    def test_chart_range_whitelist_sync_ytd(self):
        """range 화이트리스트가 두 곳(chart_data._VALID_PERIODS + dashboard_
        server._VALID_RANGES)에 중복 정의 — 한쪽에만 추가하면 그 버튼이 조용히
        1y 로 폴백하는 드리프트가 생긴다. 둘이 정확히 일치 + 둘 다 'ytd' 포함
        (YTD 버튼이 실제 동작) 영구 보장 (2026-06-07 Tier 1)."""
        import re as _re
        from bot.chart_data import _VALID_PERIODS
        assert "ytd" in _VALID_PERIODS, "chart_data._VALID_PERIODS 에 ytd 누락"
        srv = open("bot/dashboard_server.py", encoding="utf-8").read()
        m = _re.search(r"_VALID_RANGES\s*=\s*\{([^}]*)\}", srv)
        assert m, "_VALID_RANGES 리터럴 누락"
        server_ranges = set(_re.findall(r'"([a-z0-9]+)"', m.group(1)))
        assert "ytd" in server_ranges, "서버 _VALID_RANGES 에 ytd 누락"
        assert server_ranges == set(_VALID_PERIODS), (
            f"range 화이트리스트 불일치: server={server_ranges} "
            f"chart_data={set(_VALID_PERIODS)}"
        )

    def test_chart_interval_whitelist_sync_30m_1h(self):
        """interval 화이트리스트도 range 와 동일하게 두 곳(chart_data.
        _VALID_INTERVALS + dashboard_server._VALID_INTERVALS)에 중복 정의 —
        한쪽에만 추가하면 그 버튼이 서버 단에서 조용히 1d 로 폴백하는 드리프트가
        생긴다(2026-07-29 5분/30분/1시간봉 버튼 추가 시 발견 — range whitelist
        sync 테스트와 대칭, interval 쪽엔 없었음). 둘이 정확히 일치 +
        5m/30m/1h 전부 포함 영구 보장. (10분봉은 yfinance 에 없는 interval이라
        같은날 5분봉으로 교체 — resample 합성 없이 네이티브 interval 만 지원.)"""
        import re as _re
        from bot.chart_data import _VALID_INTERVALS
        assert {"5m", "30m", "1h"} <= _VALID_INTERVALS
        assert "10m" not in _VALID_INTERVALS, "10분봉은 5분봉으로 대체(제거 대상)"
        srv = open("bot/dashboard_server.py", encoding="utf-8").read()
        m = _re.search(r"_VALID_INTERVALS\s*=\s*\{([^}]*)\}", srv)
        assert m, "서버 _VALID_INTERVALS 리터럴 누락"
        server_intervals = set(_re.findall(r'"([a-z0-9]+)"', m.group(1)))
        assert server_intervals == set(_VALID_INTERVALS), (
            f"interval 화이트리스트 불일치: server={server_intervals} "
            f"chart_data={set(_VALID_INTERVALS)}"
        )

