class TestDajuEarningsPreview20260801:
    """feat: DAJU 실적 예정 알림 수집 → 블로그 대시보드 상단 섹션."""

    def test_parser_extracts_structure(self):
        from bot.daju_parse import is_daju_earnings, parse_daju
        assert is_daju_earnings(_DAJU_SAMPLE)
        assert not is_daju_earnings("그냥 잡담")
        assert parse_daju("그냥 잡담") is None
        d = parse_daju(_DAJU_SAMPLE)
        assert d["target"] == "8/5 수"
        assert d["total"] == 16 and d["picked"] == 2
        assert len(d["stocks"]) == 2
        a, b = d["stocks"]
        assert (a["rank"], a["name"], a["code"]) == (1, "롯데렌탈", "089860")
        assert (a["score"], a["score_max"]) == (52, 100)
        assert a["price"] == "39,350원" and a["when"] == "미정 · 26.2Q"
        assert a["move_1m"] == 29.4, "🔺는 양수"
        assert b["move_1m"] == -20.4, "🔻는 음수여야(부호 소실 회귀)"
        titles = [s["title"] for s in a["sections"]]
        assert "외국인·기관 순매수" in titles and "증권사 목표주가" in titles
        assert a["sections"][0]["bullets"][0].startswith("최근 5일")
        t = d["tomorrow"]
        assert t["more"] == 3 and len(t["items"]) == 2
        assert t["items"][0]["code"] == "010950"
        assert t["items"][0]["time"] == "10:00" and t["items"][0]["starred"]
        assert not t["items"][1]["starred"]
        assert t["items"][1]["note"] == "직전 -7% · 1개월 +0%"
        assert d["raw"] == _DAJU_SAMPLE, "원문 보존(파서 깨져도 화면 유지)"

    def test_only_earnings_alerts_are_ingested(self):
        """DAJU 채널의 **모든** 메시지가 아니라 실적 예정 알림만 수집한다
        (사용자 2026-08-01 확인). 옛 판정은 "📌" 가 있기만 하면 통과였는데
        DAJU **신규 기능 안내문**에도 '📌 FAQ'·'📌 문의' 가 있어, 실제로는
        헤드라인의 '후' vs 안내문의 '뒤' 한 글자로만 갈렸다 — 표현이 바뀌면
        안내문까지 수집되는 취약한 상태. 6자리 종목코드가 붙은 번호 항목을
        요구해 확실히 가른다."""
        from bot.daju_parse import is_daju_earnings
        notice = ("📣[신규 기능 안내]\n안녕하세요. DAJU(다주) 입니다.\n"
                  "📌 FAQ\nQ3. 어떻게 쓰나요?\n"
                  "└ A. 3영업일 뒤 실적 발표 예정 종목이 있고 …\n📌 문의\n")
        assert is_daju_earnings(_DAJU_SAMPLE)
        assert not is_daju_earnings(notice), "안내문이 수집됨"
        # 표현 드리프트 양방향 — 안내문은 '후' 로 바뀌어도 거부, 알림은 '뒤' 도 수집
        assert not is_daju_earnings(notice.replace("영업일 뒤", "영업일 후"))
        assert is_daju_earnings(_DAJU_SAMPLE.replace("영업일 후", "영업일 뒤"))
        # 종목코드 없는 유사 문구는 거부
        assert not is_daju_earnings("3영업일 후 실적 발표 예정\n📌 FAQ\n📌 문의")
        assert not is_daju_earnings("오늘 장 어렵네요")
        assert not is_daju_earnings("")

    def test_headline_ignores_faq_lookalike_phrase(self):
        """실제 DAJU 첫 안내 메시지(2026-08-01 사용자 제보) = 신규기능
        안내문 + 실제 알림이 한 메시지에 같이 옴. FAQ Q3 답변 줄에도 헤드라인과
        똑같은 문구('3영업일 뒤 실적 발표 예정 종목이 있고 …')가 등장해, 느슨한
        매칭으로는 안내문 문장을 헤드라인/target 으로 잘못 집는다(target 오염).
        진짜 헤드라인만 '(M/D 요일)' 날짜패턴으로 가른다."""
        from bot.daju_parse import parse_daju
        hybrid = (
            "📣[신규 기능 안내]\n안녕하세요. DAJU(다주) 입니다.\n\n"
            "📌 FAQ\nQ3. 어떻게 쓰는 건가요?\n"
            "└ A. 3영업일 뒤 실적 발표 예정 종목이 있고, 기대 스코어가 일정 "
            "이상일 경우 안내해드립니다. (알람을 받고 싶지 않다면, 알림 "
            "설정에서 꺼주시면 됩니다.)\n\n"
            "아직 부족한 점이 많지만 항상 성투하시길 바라겠습니다. "
            "+ 3영업일 후 실적 발표 예정 (8/5 수)\n\n"
            "※ 발표 예정 16곳 중 기대 상위 2곳\n\n"
            "━━━━━━━━━━━━━━\n\n"
            "📌 1. 롯데렌탈 (089860)\n - 기대점수 : 52점 / 100\n"
            " - 현재가 : 39,350원  (1개월 🔺29.4%)\n")
        d = parse_daju(hybrid)
        assert d["headline"] == "3영업일 후 실적 발표 예정 (8/5 수)", d["headline"]
        assert d["target"] == "8/5 수", d["target"]
        assert len(d["stocks"]) == 1 and d["stocks"][0]["name"] == "롯데렌탈"

    def test_archive_is_idempotent_and_isolated(self, tmp_path, monkeypatch):
        """같은 message_id 재수신(리스너 재시작·중복 push)에 카드가 늘면 안 된다.
        ⚠️ 아카이브 경로를 monkeypatch — 테스트가 실제 홈을 오염시킨 전례 있음."""
        import bot.daju_watch as dw
        monkeypatch.setattr(dw, "_ARCHIVE_DIR", tmp_path)
        rec = dw.archive_daju(_DAJU_SAMPLE, 12345)
        assert rec and len(rec["stocks"]) == 2
        assert rec["msg_id"] == "12345" and rec["source"] == "DAJU"
        dw.archive_daju(_DAJU_SAMPLE, 12345)
        assert len(list(tmp_path.rglob("*.json"))) == 1, "중복 아카이브"
        assert dw.archive_daju("무관 메시지", 999) is None
        assert len(list(tmp_path.rglob("*.json"))) == 1

    def test_push_summary_escapes_and_carries_disclaimer(self):
        """채널 push 는 원문 재게시가 아니라 요점 + 출처 고지. parse_mode=HTML
        이라 외부 텍스트의 <,>,& escape 필수(실수#7)."""
        import bot.daju_watch as dw
        from bot.daju_parse import parse_daju
        body = dw.summarize_for_push(parse_daju(_DAJU_SAMPLE))
        assert "투자 권유가 아닙니다" in body, "출처 고지 누락"
        assert "롯데렌탈" in body and "기대 52점" in body
        assert "1개월 +29.4%" in body and "1개월 -20.4%" in body
        evil = {"headline": "<b>x</b>", "stocks": [
            {"name": "<i>y</i>&z", "code": "000000", "score": 1}], "tomorrow": None}
        out = dw.summarize_for_push(evil)
        assert "<i>y</i>" not in out and "&lt;i&gt;" in out and "&amp;" in out

    def test_dashboard_section_renders_and_falls_back_to_raw(self):
        import re as _re

        import bot.dashboard as D
        from bot.daju_parse import parse_daju
        rec = parse_daju(_DAJU_SAMPLE)
        rec["ts"] = "2026-08-01T18:30:00+09:00"
        html = D._render_daju_section([rec])
        plain = " ".join(_re.sub(r"<[^>]+>", " ", html).split())
        for tok in ("롯데렌탈", "089860", "에이피알", "320,000원",
                    "투자 권유가 아닙니다", "S-Oil", "외 3곳", "외국인·기관 순매수"):
            assert tok in plain, f"섹션에 '{tok}' 누락"
        assert D._render_daju_section([]) == "", "빈 아카이브면 섹션 미표시"
        # 파싱이 깨진 건은 원문 그대로(정보 보존) + escape
        bad = D._render_daju_section([{"headline": "x", "ts": "", "stocks": [],
                                       "raw": "원문<b>보존</b>"}])
        assert "dj-raw" in bad and "&lt;b&gt;" in bad and "<b>보존" not in bad

    def test_move_1m_shows_period_label(self):
        # 사용자 2026-08-03: 원문(DAJU)이 "현재가: 93,700원 (1개월 ▼29.6%)" 처럼
        # 기간을 명시하는데 카드는 "▼29.6%" 만 보여줘 당일 등락률로 오인하기
        # 쉬웠다 — 원문과 같은 "1개월" 라벨을 등락률 옆에 붙여야 한다.
        import bot.dashboard as D
        from bot.daju_parse import parse_daju
        rec = parse_daju(_DAJU_SAMPLE)
        rec["ts"] = "2026-08-01T18:30:00+09:00"
        html = D._render_daju_section([rec])
        assert "1개월 ▲ 29.4%" in html, "롯데렌탈 1개월 등락률에 기간 라벨 누락"
        assert "1개월 ▼ 20.4%" in html, "에이피알 1개월 등락률에 기간 라벨 누락"

    def test_telethon_creds_lookup_and_no_hot_loop(self, tmp_path, monkeypatch):
        """Telethon 자격증명은 **trade 체크아웃 .env** 에만 있다 — NOAH 서비스는
        ~/stock/.env 만 읽으므로 그대로면 KeyError 로 죽고, systemd 가 15초마다
        재시작해 hot-loop 가 된다(2026-08-01 실측). 이름 후보 순회 + trade .env
        폴백 + 부재 시 exit 78(RestartPreventExitStatus)로 고정."""
        import os as _os

        import bot.daju_watch as dw
        for k in list(_os.environ):
            if "TELETHON" in k:
                monkeypatch.delenv(k, raising=False)
        env = tmp_path / ".env"
        env.write_text("# comment\nTRADE_BOT_TOKEN=secret\n"
                       'TRADE_TELETHON_API_ID = "24680"\n'
                       "TRADE_TELETHON_API_HASH='abc def'\n", encoding="utf-8")
        assert dw._env_lookup(dw._ID_KEYS, env) == "24680", "따옴표·공백 처리"
        assert dw._env_lookup(dw._HASH_KEYS, env) == "abc def"
        assert dw._env_lookup(("NOPE",), env) is None
        assert dw._env_lookup(("NOPE",), tmp_path / "missing.env") is None
        monkeypatch.setenv("DAJU_TELETHON_API_ID", "999")
        assert dw._env_lookup(dw._ID_KEYS, env) == "999", "환경변수가 파일보다 우선"
        monkeypatch.delenv("DAJU_TELETHON_API_ID")
        # 자격증명 부재 → 반드시 정수 78 (SystemExit("문자열")은 exit 1 이라
        # 재시작 루프를 못 막는다)
        monkeypatch.setattr(dw, "_TRADE_ENV", tmp_path / "missing.env")
        with pytest.raises(SystemExit) as ei:
            dw._client()
        assert ei.value.code == 78, "exit 78 이 아니면 systemd hot-loop"
        src = open("bot/daju_watch.py", encoding="utf-8").read()
        # 자격증명 검사가 telethon import 앞이어야 안내가 보인다
        assert src.index("raise SystemExit(78)") < src.index(
            "from telethon import TelegramClient\n    return TelegramClient")

    def test_unauthed_session_exits_78_not_segv(self, tmp_path, monkeypatch):
        """세션 미인증 상태로 systemd 아래서 돌면 telethon 이 대화형 input() 을
        부르고, TTY 가 없어 EOFError → **SEGV(코어덤프)** 로 죽는다. exit 11 은
        RestartPreventExitStatus=78 에 안 걸려 15초마다 재시작 루프가 된다
        (2026-08-01 실측). 세션 유무를 먼저 보고 78 로 끊는다."""
        import bot.daju_watch as dw
        monkeypatch.setenv("DAJU_TELETHON_API_ID", "1")
        monkeypatch.setenv("DAJU_TELETHON_API_HASH", "x")
        monkeypatch.setattr(dw, "_SESSION", str(tmp_path / "nosuch"))
        assert not dw._session_ready()
        with pytest.raises(SystemExit) as ei:
            dw._run()
        assert ei.value.code == 78, "78 이 아니면 systemd hot-loop"
        (tmp_path / "has.session").write_text("x")
        monkeypatch.setattr(dw, "_SESSION", str(tmp_path / "has"))
        assert dw._session_ready(), "telethon 이 붙이는 .session 접미사 인식"
        src = open("bot/daju_watch.py", encoding="utf-8").read()
        assert "except EOFError" in src, "세션 만료 2차 방어 누락"

    def test_wiring(self):
        """리스너·대시보드·systemd·help 배선 — 헬퍼만 만들고 안 쓰는 누락 방지."""
        db = open("bot/dashboard.py", encoding="utf-8").read()
        assert "{_render_daju_section(_load_daju_runs(200))}" in db, "블로그 페이지 미배선"
        assert "daju_archive" in db
        dw = open("bot/daju_watch.py", encoding="utf-8").read()
        assert "is_daju_earnings(body)" in dw, "리스너 relevance 필터 누락"
        assert "regenerate_blog_index" in dw, "대시보드 재생성 미배선"
        assert "events.NewMessage(chats=_SOURCE)" in dw
        # 세션 파일은 다른 리스너와 **별도**(상시 프로세스 락 경합 방지)
        assert ".daju-listener-session" in dw
        unit = open("deploy/daju-listener.service", encoding="utf-8").read()
        assert "-m bot.daju_watch" in unit and "RestartPreventExitStatus=78" in unit
        # user-visible 변경 → _HELP_TEXT 같은 commit 갱신(공개 spec)
        tb = open("bot/telegram_bot.py", encoding="utf-8").read()
        assert "DAJU 실적예정" in tb, "_HELP_TEXT 미갱신"


class TestDajuGroupedByMonthDay20260803:
    """사용자 2026-08-03 '블로그 업데이트 대쉬보드 반영되는거랑 똑같은
    형식으로(카드형식 및 월/일별 쌓이는 구조 등) 구현해줘' — DAJU 실적발표
    예정 섹션을 blog.html 본문 카드 스트림과 같은 month>day>card 누적
    구조로 재구성(2026-08-01 최초 구현은 최신 8건 flat 나열 — 날짜 그룹
    없었음)."""

    def _rec(self, date, headline):
        return {"headline": headline, "date": date,
                "ts": f"{date}T18:30:00+09:00",
                "stocks": [], "tomorrow": {}, "raw": ""}

    def test_groups_by_month_and_day(self):
        import bot.dashboard as D
        runs = [
            self._rec("2025-02-03", "카드A"),
            self._rec("2025-02-03", "카드B"),
            self._rec("2025-01-15", "카드C"),
        ]
        html = D._render_daju_section(runs)
        assert html.count('<details class="month"') == 2, "월 그룹 2개(2025-01·2025-02)여야"
        assert html.count('<details class="day"') == 2, "일 그룹 2개(01-15·02-03)여야"
        assert "2025년 2월" in html and "2025년 1월" in html
        assert "2025-02-03" in html and "2025-01-15" in html
        assert '<span class="count">2 건</span>' in html   # 02-03 은 2건
        assert html.index("2025년 2월") < html.index("2025년 1월"), "최신월이 먼저(내림차순)"
        assert html.count('<details class="dj-card"') == 3   # 개별 카드 스타일 유지
        assert "카드A" in html and "카드B" in html and "카드C" in html

    def test_no_cap_at_eight(self):
        # 옛 구현이 runs[:8] 로 잘랐던 것 — 회귀 방지(전부 렌더돼야).
        import bot.dashboard as D
        runs = [self._rec("2025-03-01", f"카드{i}") for i in range(12)]
        html = D._render_daju_section(runs)
        for i in range(12):
            assert f"카드{i}" in html, f"카드{i} 가 누락됨(구 cap=8 회귀)"

    def test_load_daju_runs_bumped_for_grouping(self):
        # 8개 flat 캡이 사라졌으니 로드 limit 도 그에 맞춰 늘어야(그룹 뒤에서
        # 잘리는 걸 방지) — 기존 20 → 200.
        src = open("bot/dashboard.py", encoding="utf-8").read()
        assert "_load_daju_runs(200)" in src, \
            "블로그 페이지의 _load_daju_runs 호출이 확장된 limit 을 안 씀"


