class TestDartRoicAndQuarterlyPane:
    """ROIC 추가(calc_kr_financial_ratios) + 밸류에이션 탭 분기별 재무추이
    (사용자 2026-08-19 '기업탭 ROIC 추가' + '연도별 재무추이 위에 분기별')."""

    def test_roic_uses_effective_tax_rate(self):
        from bot.dart_client import calc_kr_financial_ratios
        fin = {"영업이익": 26000, "세전이익": 40000, "법인세비용": 6000,
              "자산총계": 255300, "유동부채": 30000}
        r = calc_kr_financial_ratios(fin)
        # NOPAT = 26000*(1-6000/40000) = 22100, IC = 255300-30000 = 225300
        expected = 22100 / 225300 * 100
        assert r["ROIC"] is not None and abs(r["ROIC"] - expected) < 1e-6

    def test_roic_falls_back_to_operating_income_without_tax_data(self):
        from bot.dart_client import calc_kr_financial_ratios
        fin = {"영업이익": 26000, "자산총계": 255300, "유동부채": 30000}
        r = calc_kr_financial_ratios(fin)
        expected = 26000 / 225300 * 100
        assert abs(r["ROIC"] - expected) < 1e-6

    def test_roic_falls_back_when_effective_tax_rate_out_of_range(self):
        from bot.dart_client import calc_kr_financial_ratios
        # 세전이익이 비정상적으로 작아 실효세율이 1을 훌쩍 넘는 왜곡 케이스 —
        # 고정 세율을 창작해 보정하지 않고 영업이익 그대로 사용해야 한다.
        fin = {"영업이익": 26000, "세전이익": 100, "법인세비용": 6000,
              "자산총계": 255300, "유동부채": 30000}
        r = calc_kr_financial_ratios(fin)
        expected = 26000 / 225300 * 100
        assert abs(r["ROIC"] - expected) < 1e-6

    def test_roic_none_when_invested_capital_missing(self):
        from bot.dart_client import calc_kr_financial_ratios
        assert calc_kr_financial_ratios({"영업이익": 26000})["ROIC"] is None

    def test_roic_wired_into_company_tab_ratio_rows(self):
        src = open("bot/dashboard.py", encoding="utf-8").read()
        assert '("ROIC", "ROIC")' in src, "기업탭 K-IFRS 재무요약에 ROIC 행 누락"

    def test_kifrs_summary_left_right_table_row_counts_match(self):
        # 사용자 2026-08-19 — ROIC 추가로 우측(비율) 테이블이 7행이 됐는데
        # 좌측(금액) 테이블은 6행이라 시각적으로 어긋남. 배당수익률을 좌측
        # 루프 뒤에 추가해 7행으로 맞춤 — 루프의 (라벨,키) 튜플 개수 +
        # 루프 밖에서 수동으로 덧붙인 행 수를 세어 좌우 동일한지 고정.
        # 2026-08-16: 소스 문자열 패턴(`fin_rows += (f'<tr>` 횟수)으로 세던
        # 옛 방식은 루프 본문 포맷이 바뀌자 깨졌다. **실제 렌더된 행 수**를
        # 세도록 바꾼다 — 계약(좌우 표 행 수 일치)을 직접 검증한다.
        import re
        from bot.dashboard import _render_stock_info_html
        rec = {"ticker": "005930.KS", "stock_info": {
            "dividendYield": 2.1, "current_price": 70000,
            "kr": {"financials": {"year": 2025, "fs_div": "CFS",
                                  "매출": 3e14, "영업이익": 3e13,
                                  "당기순이익": 2e13, "자산총계": 5e14,
                                  "부채총계": 1e14, "자본총계": 4e14,
                                  "영업이익률": 10.0, "순이익률": 6.7,
                                  "ROE": 5.0, "ROA": 4.0, "ROIC": 8.0,
                                  "부채비율": 25.0, "유동비율": 200.0}}}}
        r = _render_stock_info_html(rec)
        h = ("".join(str(v) for v in r["panes"].values())
             + str(r.get("other_panes", "")))
        # ⚠️ 문자열 경계로 자르면 각주 한 줄 추가에도 슬라이스가 새 나가
        # 무관한 표를 세게 된다(2026-08-16 독립 리뷰 — 3073자 오버런).
        # 앞에서 2개만 뽑되 **정확히 2개인지** 검증해 오버런을 잡는다.
        card = h[h.index("K-IFRS 재무 요약"):]
        nxt = card.find('class="si-section-title"', 10)
        if nxt > 0:
            card = card[:nxt]
        tables = re.findall(r"<tbody>(.*?)</tbody>", card, re.S)
        assert len(tables) == 2, f"K-IFRS 요약 표가 2개가 아님({len(tables)})"
        left, right = (t.count("<tr>") for t in tables)
        assert "배당수익률" in tables[0], "좌측(금액)에 배당수익률 행 누락"
        assert left == right == 7, (left, right)

    def test_roic_wired_into_stock_snapshot_compact_dict(self):
        src = open("bot/stock_snapshot.py", encoding="utf-8").read()
        assert '"ROIC"' in src, "kr.financials(compact) 로 ROIC 값이 안 넘어감"

    def test_quarterly_pane_rendered_above_annual_trend(self):
        # render_lookup_detail 은 내부에서 실데이터를 fetch 해 독립 단위테스트가
        # 어려움(기존 관례 동일, financials_ts 쪽도 전용 테스트 없음) — 소스
        # 배치 순서로 계약 고정: 분기 섹션이 연도 섹션보다 먼저 삽입돼야 한다.
        src = open("bot/dashboard.py", encoding="utf-8").read()
        assert "kr_fin_q_html" in src and "분기별 재무추이" in src
        q_idx = src.index("{kr_fin_q_html}")
        ts_idx = src.index("{kr_fin_ts_html}")
        assert q_idx < ts_idx, "분기별 재무추이가 연도별 재무추이보다 아래에 배치됨"

    def test_stock_snapshot_quarterly_task_uses_get_quarterly_series(self):
        src = open("bot/stock_snapshot.py", encoding="utf-8").read()
        assert "get_quarterly_series" in src and "financials_q" in src

    def test_quarterly_table_renders_newest_first_but_data_stays_chronological(self):
        # ⚠️ 계약 반전 — 옛 요구(2026-08-19 "최신이 왼쪽")를 사용자가
        # 2026-08-16 에 뒤집었다("최신이 뒤쪽으로, 모든 나라 적용").
        # 이제 **표 렌더러가 항상 오래된→최신으로 정렬**하고 호출부는
        # 순서를 손대지 않는다(정렬 책임 일원화 — 소스 순서가 달라져도
        # 화면은 같다). 실제 컬럼 순서는 TestChronologicalTablesAndVol 이
        # 렌더 결과로 검증한다. 여기서는 **호출부가 다시 뒤집지 않는지**만.
        # ⚠️ 2026-08-24 개정: 옛 판은 제목 **리터럴**로 호출부를 찾아, 제목에
        # 열 수를 넣자(`최근 {n}분기`) 곧바로 깨졌다 — 표현이 바뀌어도 계약은
        # 유지되어야 한다(#19). 호출을 AST 로 찾는다.
        import ast
        src = open("bot/dashboard.py", encoding="utf-8").read()
        calls = [n for n in ast.walk(ast.parse(src))
                 if isinstance(n, ast.Call)
                 and getattr(n.func, "id", "") == "_kr_fin_trend_table"]
        assert len(calls) >= 2, len(calls)
        for c in calls:
            seg = ast.get_source_segment(src, c) or ""
            assert "reversed" not in seg, ("호출부가 다시 뒤집어 최신이 "
                                           f"왼쪽이 됨: {seg[:120]}")
        # 데이터 적재 쪽은 정렬을 건드리지 않아야 한다(시계열 자연순 보존).
        snap = open("bot/stock_snapshot.py", encoding="utf-8").read()
        q_block = snap[snap.index("get_quarterly_series"):]
        q_block = q_block[:q_block.index("financials_q")]
        assert "reversed" not in q_block and ".sort(" not in q_block, \
            "financials_q 적재 시 순서를 바꾸면 차트가 거꾸로 그려짐"


class TestQuarterlyInfographic20260819:
    """분기 실적분석 인포그래픽(2·3·4단계) — DART 공시 원문 근거 성장동력/
    리스크 요약(bot.dart_growth_risk) + 스코어카드 PNG(bot.quarterly_
    infographic) + 종목상세 '분기실적' 탭/API 배선. 핵심 계약: 숫자는 전부
    DART 실측 주입(렌더러가 만들지 않음), LLM 실패 시 정성 카드 섹션을
    통째로 생략(빈 카드 fabrication 금지), 증권사 리포트 인용 금지."""

    # ── 2단계: 공시 원문 섹션 추출 ────────────────────────────────
    def test_extract_narrative_picks_body_not_toc(self):
        from bot.dart_growth_risk import extract_business_narrative as ex
        toc = "I. 회사의 개요 II. 사업의 내용 III. 재무에 관한 사항 "
        body = ("II. 사업의 내용 " + "당사는 반도체 장비를 제조합니다. " * 20
                + "III. 재무에 관한 사항 연결재무제표")
        r = ex(toc + body)
        assert r and "반도체 장비" in r
        assert "재무에 관한 사항" not in r, "종료 마커 이후까지 포함됨"
        assert "회사의 개요" not in r, "목차(짧은 매칭)를 본문으로 오인"

    def test_extract_narrative_none_when_only_toc_or_missing(self):
        from bot.dart_growth_risk import extract_business_narrative as ex
        assert ex("I. 회사의 개요 II. 사업의 내용 III. 재무에 관한 사항") is None
        assert ex("관계없는 텍스트") is None
        assert ex("") is None and ex(None) is None

    def test_extract_narrative_absorbs_spacing_and_caps_length(self):
        from bot.dart_growth_risk import extract_business_narrative as ex
        spaced = "사 업 의 내 용 " + "가나다라마바사아자차 " * 20 + "재 무 에 관 한 사 항"
        assert ex(spaced) is not None, "공백 변형 목차를 못 잡음"
        r = ex("사업의 내용 " + "가" * 9000, max_chars=500)
        assert r is not None and len(r) <= 500

