    def test_clean_list_caps_and_drops_placeholders(self):
        from bot.dart_growth_risk import MAX_ITEMS, _clean_list
        over = [str(i) for i in range(MAX_ITEMS + 3)]
        assert _clean_list(over) == over[:MAX_ITEMS]
