    def test_valuation_table_shows_fcf_under_debt_ratio(self):
        """사용자 지정 위치 = 부채비율 **밑**. `_kr_fin_trend_table` 은
        중첩 함수라 import 가 안 된다 — AST 로 떼어 **실제 코드 그대로**
        실행한다(소스 문자열 단언은 틀린 값을 축복한다, 실수 #19)."""
        import ast
        import html as _h
        import re
        import textwrap
        src = open("bot/dashboard.py", encoding="utf-8").read()
        fn = next((n for n in ast.walk(ast.parse(src))
                   if isinstance(n, ast.FunctionDef)
                   and n.name == "_kr_fin_trend_table"), None)
        assert fn, "표 렌더러 이름이 바뀜"
        # 중첩 함수는 바깥 모듈의 헬퍼를 쓴다 — 네임스페이스에 넣어 준다
        from bot.dashboard import trend_chart_geometry
        from bot.dashboard import compact_amount
        ns = {"esc": _h.escape, "compact_amount": compact_amount,
              "currency": "USD",
              "trend_chart_geometry": trend_chart_geometry}
        exec(textwrap.dedent(ast.get_source_segment(src, fn)), ns)
        table = ns["_kr_fin_trend_table"]
        items = [{"label": "26.1Q", "매출": 1e12, "영업이익": 2e11,
                  "당기순이익": 1e11, "영업이익률": 20.0, "ROE": 30.0,
                  "부채비율": 140.0, "FCF": 1011e8, "quarter": 1},
                 {"label": "26.2Q", "매출": 1.1e12, "영업이익": 2.2e11,
                  "당기순이익": 1.2e11, "영업이익률": 20.0, "ROE": 31.0,
                  "부채비율": 143.0, "quarter": 2}]
        h = table("분기별 재무추이", items, lambda q: q["label"])
        row = re.search(r"<tr><td>FCF</td>.*?</tr>", h)
        assert row, "FCF 행이 없다"
        # FnGuide 실측값과 같은 표기(1,011억)
        assert "1,011억" in row.group(0), row.group(0)
        assert h.index("부채비율") < h.index("<tr><td>FCF"), "부채비율 위에 있다"
        assert "FCF = <b>영업활동현금흐름" in h, "산식 각주가 없다"
        # 재료가 없으면 전 칸 '—' 인 행을 만들지 않는다
        bare = [{k: v for k, v in it.items() if k != "FCF"} for it in items]
        assert "<tr><td>FCF</td>" not in table("x", bare, lambda q: q["label"])

    def test_fcf_chart_sits_under_net_income_and_is_optional(self):
        """사용자 지정 위치. 재료가 없으면 **빈 패널을 그리지 않는다**."""
        import tempfile
        import warnings
        import matplotlib
        matplotlib.use("Agg")
        from matplotlib.figure import Figure
        from bot import quarterly_infographic as qi

        def _run(with_fcf):
            qs = []
            for i, f in ((1, 7e10), (2, 9e10), (3, -2e10)):
                fin = {"매출": 1e12, "영업이익": 2e11, "당기순이익": 1e11}
                if with_fcf:
                    fin["FCF"] = f
                qs.append({"label": f"26.{i}Q", "financials": fin,
                           "ratios": {"영업이익률": 20.0, "순이익률": 10.0}})
            p = {"ticker": "005930.KS", "company": "T", "market": "KRX",
                 "market_cap": 1.2e11, "price": 45600, "quarters": qs,
                 "ttm": qi._ttm(qs), "per": 12.0, "per_forward": 9.0,
                 "per_self": True, "psr": 2.7, "currency": "KRW",
                 "currency_mismatch": False, "fiscal_note": "",
                 "anomaly_keys": [], "anomaly_labels": [],
                 "component_accounts": {}, "source_label": "DART",
                 "asof": "2026-08-21_15", "growth_risk": {"ok": False}}
            cap = {}
            orig = Figure.savefig

            def spy(self, *a, **k):
                cap["axes"] = [(round(ax.get_position().y0, 4), ax)
                               for ax in self.axes if ax.axison]
                cap["txt"] = [t.get_text() for ax in self.axes
                              for t in ax.texts]
                return orig(self, *a, **k)
            Figure.savefig = spy
            _o, qi._font_ok = qi._font_ok, lambda: True
            try:
                with tempfile.TemporaryDirectory() as d, \
                        warnings.catch_warnings():
                    warnings.simplefilter("ignore")
                    qi._render_locked(p, f"{d}/x.png", ("charts",))
            finally:
                Figure.savefig, qi._font_ok = orig, _o
            return cap

        with_ = _run(True)
        without = _run(False)
        assert any("FCF" in t for t in with_["txt"]), "FCF 차트가 없다"
        assert not any("FCF" in t for t in without["txt"]), \
            "재료가 없는데 빈 FCF 패널을 그렸다"
        assert len(with_["axes"]) == len(without["axes"]) + 1, \
            f"패널 수가 안 늘었다: {len(with_['axes'])}"
        # 당기순이익 **밑** = 그림에서 더 아래 = figure y0 가 더 작다.
        assert min(y for y, _ in with_["axes"]) < min(
            y for y, _ in without["axes"]), "FCF 가 맨 아래가 아니다"

    def test_profit_trend_chart_includes_fcf(self):
        """사용자 2026-08-21 "매출, 영익, 순이익에 FCF 로 포함해줘. 연간과
        분기 모두. 전 나라 모두."

        ⚠️ **같은 원천**(yfinance 현금흐름)을 쓴다 — KR 은 DART FCF 가 따로
        있지만 이 차트의 나머지 셋이 yfinance 라, 한 그림 안에서 기준이
        갈리면 세로로 읽는 자리에서 거짓말이 된다(실수 #33).
        `_profit_trend` 는 중첩 함수라 AST 로 떼어 **실제 코드 그대로** 돌린다."""
        import ast
        import html as _h
        import re
        import textwrap
        src = open("bot/dashboard.py", encoding="utf-8").read()
        fn = next((n for n in ast.walk(ast.parse(src))
                   if isinstance(n, ast.FunctionDef)
                   and n.name == "_profit_trend"), None)
        assert fn, "차트 함수 이름이 바뀜"
        # 중첩 함수는 바깥 모듈의 헬퍼를 쓴다 — 네임스페이스에 넣어 준다
        from bot.dashboard import trend_chart_geometry
        from bot.dashboard import compact_amount
        ns = {"esc": _h.escape, "compact_amount": compact_amount,
              "currency": "USD",
              "trend_chart_geometry": trend_chart_geometry}
        exec(textwrap.dedent(ast.get_source_segment(src, fn)), ns)
        trend = ns["_profit_trend"]
        IS = [{"period": f"2026-0{m}-30", "Total Revenue": 1000 + m,
               "Operating Income": 200 + m, "Net Income": 100 + m}
              for m in (3, 6, 9)]
        # ⚠️ 일부러 **역순**으로 준다 — 위치로 조인하면 값이 밀린다(#46).
        CF = [{"period": "2026-09-30", "Operating Cash Flow": 300,
               "Capital Expenditure": -80},
              {"period": "2026-03-30", "Free Cash Flow": 190},
              {"period": "2026-06-30", "Operating Cash Flow": 250,
               "Capital Expenditure": -50}]
        h = trend(IS, 5, lambda p: p[:7], "분기추이", "QoQ", "분기", CF)
        assert "FCF" in h, "FCF 계열이 없다"
        assert h.count("<rect") == 3 * 4, f"막대 수가 3기간×4 가 아님: {h}"
        # 기간으로 조인됐다면 FCF 는 190 → 200 → 220 으로 **오름차순**이다.
        # 위치로 매기면 CF 입력 순서(220·190·200)가 그대로 실려 순서가 깨진다.
        # (축 최대 표기는 사용자 요청으로 뺐으므로 막대 높이로 잰다.)
        svgs = re.findall(r"<svg.*?</svg>", h, re.S)
        fcf_bars = [float(x) for x in
                    re.findall(r'<rect[^>]*height="([\d.]+)"', svgs[3])]
        assert fcf_bars == sorted(fcf_bars) and len(set(fcf_bars)) == 3, fcf_bars
        head = re.search(r"<thead>.*?</thead>", h, re.S).group(0)
        assert head.index("순이익") < head.index("FCF"), "FCF 가 순이익 앞"
        body = re.search(r"<tbody>.*?</tbody>", h, re.S).group(0)
        # 2개 성장률 행 × (라벨 1 + 계열 4) = 10 셀
        assert len(re.findall(r"<td", body)) == 10, body
        # 재료가 없으면 **막대·열을 만들지 않는다**(빈 막대 = 없는 사실)
        h3 = trend(IS, 5, lambda p: p[:7], "x", "y", "분기", None)
        assert "FCF" not in h3 and h3.count("<rect") == 3 * 3

    def test_enrich_kr_pool_covers_every_task(self):
        """⚠️ 풀이 task 보다 작으면 **두 물결**로 돌아 벽시계가
        `max(1차) + max(2차)` 가 된다 — 병렬인데도 느린 이유가 여기 숨는다.
        실측(2026-08-21) `enrich:KR` 19.1초일 때 풀 8 · task 12 였다."""
        import ast
        src = open("bot/stock_snapshot.py", encoding="utf-8").read()
        fn = next((n for n in ast.walk(ast.parse(src))
                   if isinstance(n, ast.FunctionDef) and n.name == "_enrich_kr"),
                  None)
        assert fn, "_enrich_kr 이름이 바뀜"
        body = ast.get_source_segment(src, fn)
        assert "max_workers=len(tasks)" in body, (
            "풀 크기를 리터럴로 두면 task 를 더할 때 조용히 물결이 생긴다")

    def test_enrich_kr_tasks_are_named_for_timing(self):
        """이름이 없으면 '느리다'까지만 알고 무엇을 고칠지는 모른다(#69).
        프로브는 제품이 심은 계측을 **읽기만** 해야 한다(#35)."""
        # ⚠️ **동작**으로 본다 — 소스 문자열 단언은 계약을 지키는 리팩터에
        # 깨진다(#19·#89: 이번 세션에만 아홉 번째다).
        import bot.stock_snapshot as ss
        snap: dict = {}
        ss._enrich_kr("005930.KS", snap)     # 자격증명 없으면 전부 빨리 실패
        tm = ss.last_timing("005930.KS")
        kr = {k for k in tm if k.startswith("kr:")}
        assert len(kr) >= 10, f"task 별 계측이 없다: {sorted(tm)}"
        for name in ("kr:dart.financials", "kr:fnguide", "kr:fsc.dilution"):
            assert name in kr, (name, sorted(kr))
        # ⚠️ 옛 판은 프로브 소스에서 `startswith("kr:")` **개수**를 셌다 —
        # 표현이 바뀌면 깨지고, 세는 것만으론 실제 동작을 모른다(#19).
        # 판정을 순수 함수로 빼 뒀으니 **값으로** 본다.
        from bot.scripts.detail_timing_probe import slowest_parallel
        t = {"yf.info": 0.4, "재무제표": 2.1, "실적이력": 1.6,
             "total": 22.5, "enrich:KR": 19.1, "kr:fnguide": 18.9}
        # enrich 내부 값(18.9)에 밀리면 병목을 **엉뚱하게** 보고한다
        assert slowest_parallel(t) == ("재무제표", 2.1), slowest_parallel(t)
        assert slowest_parallel({}) == ("—", 0.0)

    def test_backlog_verdict_is_returned_not_only_logged(self):
        """커버리지 9/40(22%)이 "원천에 없다"인지 "파서가 못 읽는다"인지
        알 방법이 없었다 — 사유가 `_MISS_LOG` 에만 갔고 그마저 미공시류는
        건너뛴다. 감사가 개선 여지를 세려면 **미공시까지 포함한** 분포가
        필요하다(#54)."""
        from bot.dart_backlog import backlog_for, backlog_probe

        class _D:
            api_key = "K"

            def find_periodic_reports(self, *a):
                return []

            def find_periodic_report(self, *a):
                return None
        val, why = backlog_probe(_D(), "X", 2026, "11012")
        assert val is None and why == "원문미제공", (val, why)
        # 얇은 래퍼 — 수집 사다리를 복제하면 화면과 감사가 갈라진다(#35)
        assert backlog_for(_D(), "X", 2026, "11012") is None
        import ast
        src = open("bot/dart_backlog.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "backlog_for")
        body = ast.get_source_segment(src, fn)
        assert "_fetch_doc_text" not in body, "래퍼가 수집을 복제했다"

    def test_probe_separates_fixable_backlog_misses(self):
        """미공시류는 파서를 고쳐도 안 나온다 — 개선 여지에서 빼야 숫자가
        행동으로 이어진다(dart_backlog.diagnose 규약)."""
        # ⚠️ 옛 판은 `if backlog_why:` 뒤 600자에 그 낱말이 있나 보는 **소스
        # 문자열**이었다. 판정을 순수 함수로 빼는 리팩터(2026-08-21, 같은
        # 계약을 더 강하게 지킨다)에 그대로 깨졌다 — 동작으로 본다(#19).
        from bot.scripts.production_format_probe import fixable_reasons
        got = fixable_reasons({"미공시": 9, "명시적미공시": 3,
                               "미검사": 2, "형식미지원": 7})
        assert got == {"형식미지원": 7}, got
        src = open("bot/scripts/production_format_probe.py",
                   encoding="utf-8").read()
        assert "backlog_probe" in src, "프로브가 판정을 안 읽는다"
        # 프로브 버전 배너(실수 #21) — 숫자가 아니라 **찍는 행위**를(#67)
        import bot.scripts.production_format_probe as pf
        assert pf._PROBE_VER >= 8

    def test_dart_table_keeps_the_original_line_structure(self):
        """사용자 2026-08-21 농심: 사업부문 셀이 `식 품 제 조및판 매 등` 로
        떴다. DART 원문은 좁은 셀에서 한 낱말을 **여러 줄**로 쪼개 놓는데
        (`<P>식 품 제</P><P>조및판 매</P><P>등</P>`), 줄 구조를 버리면 그
        줄바꿈이 브라우저에서 **공백**이 돼 낱말이 엉뚱한 자리에서 갈린다.
        원본 재현이 목적일 때 값뿐 아니라 **줄 구조**도 원본이다(#74 의 짝)."""
        import re
        from bot.dart_production import sanitize_table
        raw = ("<TABLE><TR><TD>\n<P>식 품 제</P>\n<P>조및판 매</P>\n"
               "<P>등</P>\n</TD><TD>제품</TD></TR>"
               "<TR><TD>라 면</TD><TD>1,622,749</TD></TR></TABLE>")
        h = sanitize_table(raw)
        cells = re.findall(r"<td[^>]*>(.*?)</td>", h, re.S)
        assert cells[0] == "식 품 제<br>조및판 매<br>등", cells[0]
        # 브라우저가 보는 텍스트에 줄이 뭉개진 형태가 남으면 안 된다
        assert "식 품 제 조및판" not in h, "줄바꿈이 공백으로 뭉개졌다"
        # 셀 경계·연속 `<br>` 는 빈 줄만 만든다 — 정리돼야 한다
        assert "<td><br>" not in h and "<br></td>" not in h
        assert "<br><br>" not in h
        assert cells[1] == "제품" and cells[3] == "1,622,749"

    def test_capex_accepts_variants_but_not_components(self):
        """회사마다 표기가 갈려 하나만 두면 조용히 빈칸이 된다.
        ⚠️ 다만 `토지의 취득` 같은 **구성요소**를 넣으면 총액이 없는 회사
        에서 부분값이 CAPEX 가 되어 FCF 가 과대표시된다(재고자산과 같은 함정)."""
        from bot.dart_client import _NAME_MAP_NORM, _norm_acct_nm

        def canon(nm):
            return _NAME_MAP_NORM.get(_norm_acct_nm(nm))
        for nm in ("Ⅰ. 영업활동으로 인한 현금흐름", "영업활동순현금흐름"):
            assert canon(nm) == "영업활동현금흐름", nm
        # ⚠️ 2026-08-24 정정: `영업에서 창출된 현금흐름` 은 **이자·법인세
        # 납부 전 소계**라 영업활동현금흐름보다 크다 — 승자 규칙이 '절댓값
        # 큰 행'이라 그 줄이 이겨 FCF 가 부풀려졌다(NHN KCP 실측 +70.7억).
        assert canon("영업에서 창출된 현금흐름") is None
        for nm in ("유형자산의 취득", "유형자산의 증가", "유형자산 취득"):
            assert canon(nm) == "유형자산취득", nm
        for nm in ("무형자산의 취득", "무형자산의 증가"):
            assert canon(nm) == "무형자산취득", nm
        # 구성요소는 **매핑하지 않는다**
        for nm in ("토지의 취득", "건물의 취득", "기계장치의 취득"):
            assert canon(nm) is None, f"구성요소를 CAPEX 로 잡았다: {nm}"

    def test_financials_cache_version_tracks_the_parser(self):
        """⚠️ **이 함수에서만 세 번 겪은 실패**(v4·v5·v8): 파서를 고쳐도
        디스크 캐시가 옛 결과를 최대 7일간 서빙한다(실수 #18).

        2026-08-21 실측: CF 계정을 추가했는데 캐시 키를 안 올려, 최근
        조회분(FY2025·25.3Q~26.2Q)만 FCF 가 비고 캐시가 없던 옛 기간
        (FY2023·FY2024·25.2Q)만 값이 나왔다 — 두 종목에서 **패턴이 동일**
        해서 캐시가 범인임이 드러났다.

        규율로는 세 번 다 실패했으므로 **키 집합을 고정**한다. 새 계정을
        추가하면 이 테스트가 깨지고, 고치려면 버전을 올려야 한다."""
        from bot.dart_client import _CANONICAL_KEYS, _FIN_CACHE_VER
        expected = {
            "매출", "매출원가", "매출총이익", "판관비", "영업이익",
            "금융수익", "금융비용", "세전이익", "법인세비용", "당기순이익",
            "EPS", "재고자산", "유동자산", "비유동자산", "자산총계",
            "유동부채", "비유동부채", "부채총계", "이익잉여금", "자본총계",
            # v8 에서 추가된 현금흐름 계정 — FCF 재료
            "영업활동현금흐름", "유형자산취득", "무형자산취득",
            # v10 지배주주 귀속분 — 주당지표의 분자(FnGuide 산식, #193)
            "지배주주순이익", "지배주주자본",
            # v11 비지배지분 — 지배주주자본을 원천이 안 줄 때 빼서 만든다
            "비지배지분",
            # v13 비지배순이익 — 지배주주순이익 항등식 폴백(ROE 분자·분모를
            # 같은 급으로 유지하기 위해 필요하다, #34)
            "비지배순이익",
        }
        assert _CANONICAL_KEYS == expected, (
            "파서가 내는 계정이 바뀌었다 — `_FIN_CACHE_VER` 를 올리고 이 "
            f"목록도 갱신할 것. 차이: {_CANONICAL_KEYS ^ expected}")
        assert _FIN_CACHE_VER >= 10, "지배주주 계정 추가분을 무효화하려면 10 이상"

    def test_financials_cache_key_is_derived_not_literal(self):
        """키를 리터럴로 적으면 다음 번에도 올리는 걸 잊는다 — 실제로
        세 번 잊었다. 상수 하나에서 만들어야 한 곳만 고치면 된다."""
