        assert "2026-06-12 종가 기준" in html              # 자료 기준일 표시
        # 빈 데이터 → graceful 안내
        monkeypatch.setattr(tw, "fetch_tw_movers",
                            lambda limit=30: {"up": [], "down": [], "ts": ""})
        assert "불러올 수 없습니다" in render_tw_highlow_page()

