class TestTradeDashboardAudit20260820:
    """수출입(trade) 대시보드 감사 — 사용자 2026-08-20 "Trade 도 감사만들어줘".

    trade 는 별도 체크아웃(~/stock-trade)·별도 데이터(~/.trade)라 NOAH 의
    audit_sweep 에 넣지 않고 전용 타이머(trade-bot-dashboard-audit, 08:10
    KST)로 돈다. 여기선 순수 파서·계약을 고정한다(데이터 실측은 VM 몫)."""

    def test_header_parser_reads_the_real_render_format(self):
        # 실제 렌더는 **UTC 표기·콤마 없음**(dashboard.py:690). 처음 정규식은
        # 숫자·기호만 받아 'UTC' 글자에서 통째로 미매칭 — 픽스처를 실제 형식
        # 으로 만들지 않았으면 영원히 '파싱 0건 ❌'만 찍었다(#54).
        from trade.scripts.dashboard_audit import parse_header
        real = ("갱신 2026-08-20 06:40 UTC · 총 3036건 (최신 1054개) · "
                "수출 2000 / 수입 1036 · 잠정 1500 / 확정 1536 · 품목 88")
        h = parse_header(real)
        assert h == {"updated": "2026-08-20 06:40 UTC", "total": 3036,
                     "latest": 1054, "export": 2000, "import": 1036,
                     "prelim": 1500, "final": 1536, "items": 88}
        assert parse_header("아무 관계 없는 텍스트") is None

    def test_producer_really_writes_that_format(self):
        # 생산자 쪽도 같은 테스트에서 고정 — 한쪽만 바뀌면 감사가 눈이 먼다(#54b).
        src = open("trade/dashboard.py", encoding="utf-8").read()
        assert 'strftime("%Y-%m-%d %H:%M UTC")' in src
        assert "총 {s.get('total', 0)}건 (최신 {len(latest_ids)}개)" in src

    def test_lazy_refs_matched_by_real_markers_only(self):
        # index 의 lazy 참조 3형태(data-src / HISTORY_SRC / INDUSTRY_CSV_SRC)만
        # 잡고, 빈문자(인라인 폴백)는 요구하지 않는다 — 빈 customs.db E2E 에서
        # 파일 없음을 ❌ 로 오보하던 것을 고친 계약(#50).
        from trade.scripts.dashboard_audit import _REF_RE
        t = ('<main id="industry-view" class="view" data-src="industry_panel.html">'
             'const HISTORY_SRC="alerts_history.json";'
             'const INDUSTRY_CSV_SRC="";')
        got = sorted({a or b for a, b in _REF_RE.findall(t) if (a or b)})
        assert got == ["alerts_history.json", "industry_panel.html"], got
        src = open("trade/dashboard.py", encoding="utf-8").read()
        assert 'const HISTORY_SRC=' in src and 'const INDUSTRY_CSV_SRC=' in src

    def test_latest_count_is_distinct_dedup_keys(self):
        from trade.scripts.dashboard_audit import latest_count
        assert latest_count([{"dedup_key": "a"}, {"dedup_key": "a"},
                             {"dedup_key": "b"}, {"dedup_key": None}]) == 3

    def test_timer_units_exist_and_notify_only_on_findings(self):
        svc = open("deploy/trade-bot-dashboard-audit.service", encoding="utf-8").read()
        tmr = open("deploy/trade-bot-dashboard-audit.timer", encoding="utf-8").read()
        assert "trade.scripts.dashboard_audit --notify" in svc
        assert "OnCalendar=*-*-* 08:10:00 Asia/Seoul" in tmr
        aud = open("trade/scripts/dashboard_audit.py", encoding="utf-8").read()
        # 무음 규율: ❌ 0건이면 notify 경로 자체에 안 들어간다
        assert '"--notify" in argv' in aud
        assert aud.index("if not bad:") < aud.index('"--notify" in argv')

    def test_sibling_staleness_pure_function(self):
        """③ 형제 페이지 검증이 '존재+비어있지 않음'뿐이라 화석을 못 잡았다
        (2026-08-20 전수 감사 — cheongyak.html 이 그 상태로 두 달 산 실수 #53
        의 trade 판 방지). asof_footer 의 '페이지 생성 …KST' 줄을 파싱해
        누락/24h 초과를 ❌ 로 판정한다. 인라인 판정은 회귀가 소스 문자열만
        보게 되므로 순수 함수로 고정(#41/#19)."""
        from datetime import datetime
        from trade.scripts.dashboard_audit import _KST, sibling_staleness
        now = datetime(2026, 8, 20, 19, 0, tzinfo=_KST)
        _pg = "<!doctype html><html><body>%s</body></html>"
        fresh = _pg % "… · 페이지 생성 2026-08-20 18:14 KST"
        assert sibling_staleness(fresh, "tw.html", now) is None
        # footer 누락 = ❌ (구버전 렌더 또는 배선 이탈)
        assert "as-of 줄 없음" in sibling_staleness(_pg % "x", "tw.html", now)
        # 24h 초과 = ❌ (5분 재생성 주기가 멈춘 화석)
        stale = _pg % "… · 페이지 생성 2026-08-18 18:14 KST"
        assert "멈춘" in sibling_staleness(stale, "tw.html", now)
        # 정적 아카이브 3종은 생성 주기가 달라 면제
        assert sibling_staleness(_pg % "x", "reference.html", now) is None

    def test_lazy_fragments_are_judged_by_mtime_not_by_a_footer(self):
        """2026-08-21 이 감사가 **정상 산출물 4건을 ❌ 로 오보**했다
        (alerts_history.json · heatmap_panel.html · industry_csv.html ·
        industry_panel.html). 넷 다 index.html 에서 떼어낸 lazy 조각이라
        생성부가 footer 를 찍은 적이 없다 — 원천이 보장하는 규칙이 아니라
        내가 그럴듯하다고 생각한 규칙을 단언한 것(실수 #50).

        그렇다고 면제만 하면 화석을 놓친다(#41) — mtime 으로 같은 실패모드를
        본다. 판정 근거가 없으면 ✅ 가 아니라 ❌ 다(#54)."""
        from datetime import datetime, timedelta
        from trade.scripts.dashboard_audit import _KST, sibling_staleness
        now = datetime(2026, 8, 21, 8, 10, tzinfo=_KST)
        frag = '<div class="hm-wrap">…</div>'
        js = '{"a": 1}'
        for body in (frag, js):
            # footer 가 없어도 파일이 방금 써졌으면 정상
            assert sibling_staleness(body, "heatmap_panel.html", now,
                                     now - timedelta(hours=1)) is None
            # 오래 안 바뀌었으면 화석 ❌
            note = sibling_staleness(body, "heatmap_panel.html", now,
                                     now - timedelta(hours=40))
            assert note and "화석" in note
            # mtime 을 안 주면 '판정 불가' ❌ — 조용한 통과 금지
            assert "판정 불가" in sibling_staleness(body, "x.json", now)
        # 독립 페이지는 여전히 footer 규칙을 탄다(조각 규칙이 새면 안 됨)
        pg = "<!doctype html><html><body>no footer</body></html>"
        assert "as-of 줄 없음" in sibling_staleness(pg, "tw.html", now,
                                                    now - timedelta(hours=1))

    def test_backlog_audit_counts_the_population_the_header_renders(self):
        """감사는 eval_misses **원본 줄 수**를, 헤더는 IGNORED·JP·/ignore 를
        뺀 수를 셌다 — 두 모집단이 갈라져 정상 화면을 "53건인데 표기 없음"
        으로 오보했다(실수 #45). 화면이 쓰는 함수를 그대로 태워야 한다(#35)."""
        src = open("trade/scripts/dashboard_audit.py", encoding="utf-8").read()
        blk = src[src.index("⑤ 미파싱 백로그(eval_misses)"):]
        blk = blk[:blk.index("return bad")]
        assert "_load_eval_miss_summary" in blk, "렌더러 집계를 안 쓴다"
        # 원본 줄 수로 ❌ 를 내면 안 된다 — 판정은 표기대상 수로만
        assert "shown_n and not has_line" in blk
        assert "bad.append(f\"미파싱 백로그 {raw}" not in blk
        # 집계를 못 만들면 조용히 통과시키지 않는다(#54)
        assert "판정 불가" in blk


class TestAssetPagesContracts20260820:
    """자산·ASIA·Screener·trade 아카이브 렌더 계약 — A안 잔여 표면 감사에서
    나온 결함 3건(사용자 2026-08-20 "이어서 A 로 남은것들도 다 봐줘")."""

    def test_screener_status_restore_is_the_servers_text(self):
        # 서버 '총 N건의 Bottleneck Screener 실행' vs JS 복원 '총 N건의
        # screener 실행' — #48 이 Screener 에도 살아 있었다. 조건부 섹션도
        # 같은 하드코딩이라 함께 통일.
        import re
        import bot.dashboard as d
        html = d._render_screener_page(
            [{"_date": "2026-08-20", "_filename": "a.json", "ts": "t",
              "domain": "x", "cost_krw": 1.0, "top_3_picks": []}], {}, [])
        srv = re.search(r'id="scr-status"[^>]*>([^<]*)<', html)
        assert srv and srv.group(1) == "총 1건의 Bottleneck Screener 실행"
        assert html.count("baseStatus") >= 2        # 선언 + 사용
        assert "csBase" in html                     # 조건부 섹션도
        assert not re.search(r"textContent = '총 ' \+ \w+ \+ '건의", html)

    def test_asia_page_speaks_when_everything_is_empty(self):
        # 4개 시장 수집이 전부 실패하면 위젯이 모두 생략돼 **백지**였다(#43).
        import bot.dashboard as d
        html = d._render_asia_page({})
        assert "업종 등락 데이터가 아직" in html
        # 하나라도 있으면 안내문 없이 위젯
        html2 = d._render_asia_page({"jp_sector_movers": {
            "up": [{"name": "은행", "pct": 1.2}], "down": [],
            "ts": "08-20 15:00", "source": "ETF"}})
        assert "업종 등락 데이터가 아직" not in html2
        assert "일본 업종 등락" in html2

    def test_index_audit_counts_the_real_card_markup(self):
        # 분석 아카이브의 카드는 <div class="card"> — 피드 대시보드들의
        # <details class="card"> 가 아니다. v1 감사가 details 로 세서 VM
        # 실데이터 77건을 '카드 0'으로 오보했다(#47: 계수 패턴은 실제 렌더로
        # 검증하고 나서 믿을 것). 실제 _render_index 렌더로 고정한다.
        import re
        import bot.dashboard as d
        rec = {"ticker": "NVDA", "trade_date": "2026-08-20",
               "date": "2026-08-20", "decision": "매수", "summary": "s",
               "market": "US", "name": "NVIDIA",
               "analyzed_at": "2026-08-20T10:00:00"}
        html, frags = d._render_index([rec])
        n = len(re.findall(r'<div class="card"', html)) + sum(
            len(re.findall(r'<div class="card"', f)) for f in frags.values())
        assert n == 1                       # v2 패턴 = 정확
        assert len(re.findall(r'<details class="card"', html)) == 0  # v1 = 0 오보
        # 감사 소스도 div 패턴을 쓰는지(계약)
        aud = open("bot/scripts/asset_pages_audit.py", encoding="utf-8").read()
        assert '_IDX_CARD = re.compile(r\'<div class="card"\')' in aud

    def test_trade_archive_restore_is_not_daily_byte(self):
        # NOAH 에서 verbatim 복사한 JS 가 'Daily Byte 브리프'를 하드코딩 —
        # trade 페이지에서 검색을 지우면 남의 화면 문구가 떴다(#48 trade 판).
        import re
        from trade.archive_template import render_archive_page
        html = render_archive_page(
            [{"date": "2026-08-20", "title": "t", "body": "b"}],
            title="산업 아카이브", subtitle="s")
        srv = re.search(r'id="scr-status"[^>]*>([^<]*)<', html)
        assert srv and srv.group(1) == "총 1건"
        assert "baseStatus" in html
        assert "건의 Daily Byte 브리프" not in html


class TestAuditSweep20260820:
    """감사 4종 자동 실행 — 사용자 2026-08-20 "매번 할때마다 왜 새로운것이
    나오지?" 에 대한 구조적 답(B안). 사람이 물어봐야 도는 감사는 같은 일을
    반복하게 만든다 → 매일 08:00 KST 자동 실행, **❌ 가 있을 때만** 알림."""

    def test_silent_when_clean(self):
        # 매일 오는 '이상 없음'은 곧 무시되고, 그러면 진짜 신호도 안 읽힌다.
        import bot.audit_sweep as a
        assert a.report_text({"findings": [], "warn": 9, "errors": []}) == ""

    def test_reports_when_a_finding_exists(self):
        import bot.audit_sweep as a
        txt = a.report_text({"findings": ["📋 DART [1) DART] ❌ 날짜 2건"],
                             "warn": 5, "errors": []})
        assert "❌ 1건" in txt and "⚠️ 5건" in txt and "날짜 2건" in txt

    def test_a_crashed_audit_is_itself_a_finding(self):
        # 감사가 죽었는데 조용히 통과하면 도구가 눈이 먼 걸 아무도 모른다(#54).
        import bot.audit_sweep as a
        txt = a.report_text({"findings": [], "warn": 0,
                             "errors": ["📊 차트보드: 감사 실행 실패 — KeyError: x"]})
        assert txt and "감사 실행 실패" in txt

    def test_findings_carry_the_section_they_came_from(self):
        import bot.audit_sweep as a
        # ⚠️ 구분선을 **두 종류 다** 넣는다 — '=' 줄은 모양 규칙에서 걸러지지만
        # '─' 줄은 startswith("──") 에 걸려 제목으로 오인된다. 처음 픽스처엔
        # '=' 만 있어서 구분선 가드를 지워도 테스트가 통과했다(뮤테이션 U4).
        sep = "─" * 30
        out = ("=" * 20 + "\n1) DART 공시 대시보드\n" + "=" * 20 +
               "\n✅ 정상\n❌ 날짜 2건\n\n" + sep +
               "\n── 매크로 스냅샷 (카드)\n   ❌ 카드 0개\n" + sep +
               "\n④ 데이터 품질\n   ❌ 자기참조 3\n")
        got = a._findings(out)
        assert got == ["[1) DART 공시 대시보드] ❌ 날짜 2건",
                       "[매크로 스냅샷 (카드)] ❌ 카드 0개",
                       "[④ 데이터 품질] ❌ 자기참조 3"], got

    def test_a_failing_axis_header_still_names_its_own_section(self):
        # Market cap 축이 실패하면 헤더가 '── … ⚠️ stale' 로 마크를 달고
        # 나온다. '마크 있는 줄은 제목 아님' 가드를 뒀더니 그 줄을 건너뛰어
        # ❌ 가 **직전 섹션**(다른 축)에 붙었다 — 하필 결함이 난 그때.
        import bot.audit_sweep as a
        out = ("  ── Earnings (earnings) · 100행\n  ✅ 순위 1..100 연속\n"
               "  ── Market Cap (marketcap) · 0행 ⚠️ stale(최신 수집 실패)\n"
               "  ❌ 0행 — 수집 실패\n")
        got = a._findings(out)
        assert len(got) == 1 and "Market Cap" in got[0] and "Earnings" not in got[0], got
        # '──────' 단독 줄은 제목이 아니다 — 오인되면 '[] ❌ …' 이 된다.
        assert a._section_of("─" * 30) is None
        assert a._section_of("── 매크로 스냅샷 (카드)") == "매크로 스냅샷 (카드)"

    def test_legend_lines_are_not_findings(self):
        # 도구 끝의 '읽는 법: ❌ = …' 범례가 결함으로 집계됐다(스모크 실측).
        # 범례는 '❌ =' 꼴 — 실제 판정 줄('❌ 날짜 2건')과 모양으로 갈린다.
        import bot.audit_sweep as a
        out = ("1) DART\n❌ 날짜 2건\n"
               "읽는 법: ❌ = 화면이 사실과 다른 것 · ⚠️ = 확인\n")
        got = a._findings(out)
        assert got == ["[1) DART] ❌ 날짜 2건"], got

    def test_every_audit_script_is_registered_in_the_sweep(self):
        # 감사를 새로 만들고 등록을 잊으면 그 표면만 조용히 빠진다(#24).
        import glob
        import os
        import bot.audit_sweep as a
        found = {f"bot.scripts.{os.path.basename(p)[:-3]}"
                 for p in glob.glob("bot/scripts/*_audit.py")}
        assert found, "감사 스크립트를 못 찾음"
        registered = {m for _n, m, _c in a.AUDITS}
        assert found <= registered, f"sweep 미등록 감사: {found - registered}"
        # 시그니처가 갈린다(main() vs main(argv)) — 실행기가 둘 다 다뤄야 한다.
        # 실제로 peer_currency_audit 가 TypeError 로 죽어 '감사 실행 실패'가
        # 첫 스모크에 찍혔다.
        import importlib
        import inspect
        for m in registered:
            fn = importlib.import_module(m).main
            n = len(inspect.signature(fn).parameters)
            assert n <= 1, f"{m}.main 인자 {n}개 — 실행기가 못 부른다"
        assert {c for _n, _m, c in a.AUDITS} <= {"daily", "weekly"}
        # 무거운 것(671종목 yfinance)은 매일 돌리지 않는다
        assert dict((m, c) for _n, m, c in a.AUDITS)[
            "bot.scripts.peer_currency_audit"] == "weekly"

    def test_wired_as_a_daily_task_and_documented(self):
        tb = open("bot/telegram_bot.py", encoding="utf-8").read()
        assert "_periodic_audit_sweep" in tb and "_audit_sweep_task" in tb
        assert "if now.hour != 8:" in tb          # 08:00 KST
        assert "await asyncio.to_thread(report_text, None," in tb  # 루프 차단 금지
        assert "now.weekday() == 0" in tb                    # 주간 감사는 월요일
        assert "🔍 대시보드 감사" in tb           # _HELP_TEXT 등록(같은 commit)


class TestRegimeCardExplanations20260820:
    """매크로/크립토 레짐 카드의 설명이 **실제 계산과 일치**하는가.

    사용자 2026-08-20 "이 두개에 대해서 특히, 매크로 크로스에셋 레짐에 대해서
    설명을 추가해줘". 설명을 붙이며 두 군데가 코드와 어긋나 있는 걸 발견했다:
    ① 카드 note 가 지표쌍을 5개만 적었는데 실제 투표는 6개(XLY-XLP 누락)
    ② 크립토 note 가 '가격·ATH낙폭 컴포넌트'라고 했는데 가격은 점수에 안 들어간다
       (추세 컴포넌트가 SMA50·SMA200 을 함께 요구하는데 둘 다 None).
    설명 out-of-sync = 버그(§Help/Dashboard)."""

    @staticmethod
    def _page():
        import bot.market_timing as mt
        return mt.render_market_timing_page({
            "macro": {"regime": "Transitional", "inputs": 6, "inputs_total": 6,
                      "as_of": "2026-08-19"},
            "crypto": {"price": 69296, "ath_change_pct": -45.0, "score": 55.0,
                       "as_of": "2026-08-20 13:28 KST"},
            "markets": {}, "cot": {}})

    @classmethod
    def _panel(cls, emoji):
        """그 카드 하나만 잘라낸다. 페이지 전체를 grep 하면 ℹ️ 가이드에 같은
        단어가 있어 **카드에서 설명을 지워도 테스트가 통과한다**(2026-08-20
        뮤테이션에서 실제로 통과했다 — 실수 #19 의 범위판)."""
        html = cls._page()
        i = html.index(f'<div class="panel-title">{emoji}')
        j = html.find('<div class="panel">', i)
        return html[i:j if j > 0 else len(html)]

    def test_every_regime_the_classifier_can_return_has_a_korean_meaning(self):
        # 이름 열거는 새 국면을 못 잡는다 — 분류기가 돌려줄 수 있는 값 전부를
        # 소스에서 뽑아 라벨 존재를 확인한다(#31).
        import re
        import bot.market_timing as mt
        src = open("bot/market_timing.py", encoding="utf-8").read()
        body = src[src.index("def classify_macro_regime"):
                   src.index("def crypto_regime_score")]
        returned = set(re.findall(r'votes\.append\("(\w+)"', body))
        returned |= set(re.findall(r'return "(\w+)"', body))
        assert returned, "분류기가 돌려주는 국면을 못 찾음"
        for r in returned:
            assert mt.macro_regime_kr(r), f"{r} 의 한글 뜻이 없다"
        assert mt.macro_regime_kr("없는국면") == ""      # 지어내지 않는다

    def test_card_lists_as_many_pairs_as_the_classifier_votes_on(self):
        # note 가 5쌍만 적고 화면은 '반영 지표 6/6' 이라고 하면 세어보는
        # 사용자가 바로 어긋남을 본다(실수 #45 의 라벨판).
        import inspect
        import bot.market_timing as mt
        n_inputs = len(inspect.signature(mt.classify_macro_regime).parameters)
        card = self._panel("🌐")
        for pair in ("RSP-SPY", "IWM-SPY", "HYG-LQD", "SPY-TLT",
                     "XLY-XLP", "10Y-2Y"):
            assert pair in card, f"카드에 {pair} 설명이 없다"
        assert n_inputs == 6
        assert "반영 지표 6/6" in card

    def test_card_explains_that_transitional_is_not_a_regime(self):
        card = self._panel("🌐")
        assert "판단보류" in card          # 국면 값 아래 한 줄 뜻
        assert "과반" in card and "3개 미만" in card

    def test_crypto_card_shows_where_the_score_comes_from(self):
        # 55 가 어디서 나온 숫자인지 나란히 보여야 눈으로 검산된다(실수 #33).
        import bot.market_timing as mt
        assert mt.crypto_regime_score(69296, None, None, None, -45.0,
                                      None)["score"] == 55.0
        card = self._panel("🪙")
        assert "= 100 + (ATH 대비 -45.0)" in card
        assert "BTC 가격은 점수에 안 들어갑니다" in card

    def test_guide_covers_both_cards(self):
        html = self._page()
        for k in ("동일가중", "신용 스프레드", "국채 커브",
                  "Concentration(집중)", "Inflationary(인플레)",
                  "risk-on", "SMA50·SMA200"):
            assert k in html, f"ℹ️ 가이드에 '{k}' 설명이 없다"


class TestBoardAuditReadsRealKeys20260820:
    """board_audit 의 스냅샷 2개 섹션이 **엉뚱한 키**를 읽어 늘 통과하던 것.

    - 글로벌 스냅샷: 원천은 기준일을 `time` 으로 주는데 감사는 `date`/`asof`
      만 봐서 10행 전부 '기준 —', 게다가 ❓ 분기가 '기준일이 있을 때만' 이라
      **판정 불가가 ✅ 로 통과**했다.
    - 매크로 스냅샷: `fetch_macro_snapshot()` 은 `domestic`/`global` 로 주는데
      감사는 `indicators` 를 읽어 **한 번도 아무것도 검사하지 않았다**.
    둘 다 실수 #47(감사 계수 패턴 오류)·#41(0건 매칭을 ✅ 로)의 재발이다."""

    def test_fred_row_asof_reads_the_time_key(self):
        import bot.scripts.board_audit as B
        assert B.fred_row_asof({"value": 4.19, "time": "2026-08-18"}) == "2026-08-18"
        assert B.fred_row_asof({"value": 4.19}) == ""      # 없으면 빈 문자열
        assert B.fred_row_asof(None) == ""

    def test_the_producer_really_uses_that_key(self):
        # 원천이 키 이름을 바꾸면 감사가 다시 눈이 먼다 — 양쪽을 같이 고정.
        src = open("bot/market_overview.py", encoding="utf-8").read()
        assert '"time": latest_date' in src

    def test_macro_rows_reads_domestic_and_global(self):
        import bot.scripts.board_audit as B
        assert len(B.macro_rows({"domestic": [{"a": 1}],
                                 "global": [{"b": 2}, {"c": 3}]})) == 3
        assert B.macro_rows({"indicators": [{"a": 1}]}) == []   # 없는 키
        assert B.macro_rows(None) == []

    def test_macro_snapshot_really_returns_those_lists(self):
        src = open("bot/macro_snapshot.py", encoding="utf-8").read()
        assert '"domestic": domestic,' in src and '"global": glob,' in src

    def test_zero_rows_is_reported_as_audit_failure(self):
        # 대조 대상이 0건이면 '이상 없음'이 아니라 감사 실패다(실수 #47b).
        src = open("bot/scripts/board_audit.py", encoding="utf-8").read()
        assert src.count("대조 실패, 이상 없음 아님") == 2
        assert "❓ 기준일 없음(판정 불가)" in src


class TestSitesList20260820:
    """/sites (_SITES_TEXT) — 외부 third-party 링크 목록의 형식 계약.

    항목이 하나씩 손으로 추가되는 목록이라 불릿이 조용히 어긋난다 —
    2026-08-20 실제로 마지막 두 줄이 '?' 와 '-' 로 들어가 화면에서 홀로 튀었다
    (사용자 캡쳐로 발각). 형식을 회귀로 고정한다."""

    @staticmethod
    def _body():
        import re
        src = open("bot/telegram_bot.py", encoding="utf-8").read()
        t = re.search(r'_SITES_TEXT = """(.*?)"""', src, re.S).group(1)
        return t, [l for l in t.splitlines() if l.strip()][1:]   # [0] = 헤더

    def test_every_entry_uses_the_same_bullet(self):
        _t, body = self._body()
        assert body, "목록이 비었다"
        bad = [l for l in body if not l.startswith(" • ")]
        assert not bad, f"불릿이 다른 줄: {bad}"

    def test_every_entry_is_a_single_anchor(self):
        import re
        _t, body = self._body()
        for l in body:
            assert re.fullmatch(
                r' • <a href="https?://[^"]+">[^<]+</a>', l), f"형식 이탈: {l}"

    def test_no_duplicate_urls(self):
        import re
        t, _body = self._body()
        urls = re.findall(r'href="([^"]+)"', t)
        dups = sorted({u for u in urls if urls.count(u) > 1})
        assert not dups, f"중복 링크: {dups}"

    def test_fits_one_telegram_message(self):
        # 단일 메시지로 나가므로 4096 UTF-16 단위 상한(§Help 규칙과 같은 계약)
        t, _body = self._body()
        n = len(t.encode("utf-16-le")) // 2
        assert n < 4096, f"{n} UTF-16 units — 분할 필요"

    def test_raoni_sites_registered(self):
        # 사용자 2026-08-20 추가분
        t, _body = self._body()
        assert '<a href="https://raoni.xyz/">raoni 삼하닉</a>' in t
        assert '<a href="https://uplist.raoni.xyz/">Upbit Listing Radar</a>' in t


class TestFeedBoardsShared20260820:
    """피드형 대시보드 5종(Daily Byte·레딧·블로그·부동산·청약) 공통 계약.

    다섯 화면이 같은 뼈대(_DAILY_BYTE_JS + 월>일>카드)를 쓰므로 회귀도 한 번에
    돈다 — 한 화면만 고치고 나머지가 갈라지는 걸 막는다(실수 #38)."""

    @staticmethod
    def _mk(n, ds, hhmm, **kw):
        return dict(_date=ds, _filename=f"{hhmm.replace(':', '')}{n}.json",
                    ts=f"{ds}T{hhmm}:00", **kw)

    def _pages(self):
        import bot.dashboard as d
        m = self._mk
        db = [m(1, "2026-08-20", "19:00", body="A", cost_krw=37.0,
                elapsed_sec=9, kind="daily")]
        ri = [m(1, "2026-08-20", "05:07", title="미국 레딧 게시물 분석", body="SPCE")]
        bl = [m(1, "2026-08-20", "09:40", title="글1", desc="본문", link="http://x")]
        re_ = [m(1, "2026-08-20", "09:00", body="실거래", cost_krw=0,
                 _kind="realestate", ymd="202608")]
        return {
            "daily_byte": (d._render_daily_byte_page(db), "총 1건의 Daily Byte 브리프"),
            "reddit": (d._render_reddit_insider_page(ri)[0], "총 1건의 포워드"),
            "blog": (d._render_blog_page(bl)[0], "총 1건의 글"),
            "realestate": (d._render_realestate_page(re_), "총 1건의 부동산/청약 기록"),
        }

    def test_search_clear_restores_the_servers_own_status_label(self):
        # 검색을 지우면 JS 가 상태줄을 되돌리는데, 그 문구를 JS 안에 하드코딩하고
        # 페이지마다 _DAILY_BYTE_JS 를 .replace 로 갈아끼웠다 — 레딧·블로그는
        # replace 가 아예 없어 '총 129건의 Daily Byte 브리프'가 됐고, 부동산·
        # 청약은 문구 일부만 갈려 '기록'/'피드'가 사라졌다(실수 #24 의 JS 판).
        import re
        for name, (html, want) in self._pages().items():
            srv = re.search(r'id="scr-status"[^>]*>([^<]*)<', html)
            assert srv and srv.group(1).strip() == want, f"{name}: {srv and srv.group(1)}"
            assert "const baseStatus = (sts.textContent || '').trim();" in html, name
            assert "sts.textContent = baseStatus;" in html, name
            # 하드코딩된 복원 문구가 남아 있으면 다시 갈릴 수 있다
            assert not re.search(r"sts\.textContent = '총 ' \+ \w+ \+ '건의", html), name

    def test_every_feed_page_says_when_its_data_is_from(self):
        # "이거 최신이야?"에 화면이 답해야 한다(규칙 10b·실수 #43).
        import re
        want = {"daily_byte": "마지막 브리프 (KST)", "reddit": "마지막 포워드 (KST)",
                "blog": "마지막 새 글 (KST)", "realestate": "마지막 기록 (KST)"}
        for name, (html, _lbl) in self._pages().items():
            # 라벨엔 수집기 점검 문구가 뒤에 붙을 수 있어 prefix 로 찾는다
            stats = [(l, v) for v, l in re.findall(
                r'<div class="stat-v">([^<]*)</div>\s*<div class="stat-l">([^<]*)</div>',
                html) if l.startswith(want[name])]
            assert stats, f"{name}: 기준시각 stat 없음"
            assert stats[0][1].startswith("2026-08-20"), (name, stats[0])

    def test_asof_is_max_ts_not_first_element(self):
        # 부동산 페이지는 실거래+청약 아카이브를 **이어붙여** 받는다 —
        # runs[0] 을 쓰면 첫 리스트의 최신이 전체 최신인 척한다.
        import bot.dashboard as d
        m = self._mk
        runs = [m(1, "2026-08-19", "09:00", body="실거래", cost_krw=0,
                  _kind="realestate", ymd="202608"),
                m(2, "2026-08-20", "14:00", body="청약", cost_krw=0,
                  _kind="cheongyak", count=3)]
        assert d._feed_latest_ts(runs) == "2026-08-20 14:00"
        assert "마지막 기록 (KST)" in d._render_realestate_page(runs)
        assert "2026-08-20 14:00" in d._render_realestate_page(runs)

    def test_every_feed_page_says_when_the_collector_last_ran(self, tmp_path,
                                                             monkeypatch):
        # '마지막 새 글 08-17' 이 정상(새 글 없음)인지 장애인지 화면이 구별
        # 못 했다(2026-08-20 부동산: 3일 전 기록 + 판단 근거 없음, 실수 #43).
        import bot.feed_health as fh
        monkeypatch.setattr(fh, "_DIR", tmp_path / "fh")
        for name, (html, _l) in self._pages().items():
            if name == "daily_byte":
                continue          # Daily Byte 는 고정 스케줄(19:00/08:00)이라 제외
            assert "점검" in html, f"{name}: 수집기 점검 표기 없음"
        fh.mark("blog")
        html = __import__("bot.dashboard", fromlist=["d"])._render_blog_page(
            [dict(_date="2026-08-20", _filename="a.json",
                  ts="2026-08-20T09:40:00", title="글", desc="본문",
                  link="http://x")])[0]
        assert "점검 기록 없음" not in html and "점검 " in html

    def test_feed_health_note_states(self, tmp_path, monkeypatch):
        import datetime as _dt
        import bot.feed_health as fh
        monkeypatch.setattr(fh, "_DIR", tmp_path / "fh")
        assert fh.note("blog") == "점검 기록 없음"
        fh.mark("blog")
        assert fh.note("blog").startswith("점검 ") and "⚠️" not in fh.note("blog")
        # 상한을 넘기면 ⚠️ — 오래된 도장을 직접 써서 강제로 태운다
        old = (_dt.datetime.now(fh._KST) - _dt.timedelta(hours=9))
        fh._path("blog").write_text(old.isoformat(timespec="seconds"))
        assert "⚠️" in fh.note("blog")
        # 기준 미등록 피드는 '판정 못 함'을 밝혀야 한다(조용한 ✅ 금지, #41)
        fh.mark("nosuch")
        assert "지연 기준 미등록" in fh.note("nosuch")

    def test_every_feed_the_dashboards_show_has_a_staleness_bound(self):
        # 화면이 참조하는 피드 이름을 소스에서 뽑아 _MAX_GAP_H 와 대조 —
        # 이름 열거만 하면 새 피드가 조용히 판정 불가로 샌다(실수 #31).
        import re
        import bot.feed_health as fh
        src = open("bot/dashboard.py", encoding="utf-8").read()
        used = set(re.findall(r'_feed_note\("([a-z_]+)"\)', src))
        assert used, "대시보드가 _feed_note 를 안 쓰고 있다"
        missing = used - set(fh._MAX_GAP_H)
        assert not missing, f"지연 기준 미등록 피드: {missing}"

    def test_cheongyak_standalone_page_is_gone(self, tmp_path, monkeypatch):
        # 사용자 2026-08-20 "청약대시보드는 삭제해줘". 같은 레코드를 두 번
        # 그리던 페이지고, regenerate 가 이미 realestate 로 리다이렉트만 해서
        # **6월 이후 갱신이 멈춘 화석 파일**이었다(화면엔 '총 피드 2'로 표시).
        import bot.dashboard as d
        import bot.dashboard_server as ds
        for gone in ("_render_cheongyak_page", "regenerate_cheongyak_index",
                     "_CHEONGYAK_JS"):
            assert not hasattr(d, gone), f"{gone} 가 남아 있다"
        db = open("bot/dashboard.py", encoding="utf-8").read()
        assert 'href="cheongyak.html"' not in db, "죽은 페이지로 가는 링크가 남아 있다"
        assert "cheongyak.html" not in ds._OUR_ROOT_PAGES
        # 재생성 시 옛 파일을 지운다 — 링크가 없어도 URL 로 열리면 옛 숫자를 준다
        stale = tmp_path / "cheongyak.html"
        stale.write_text("옛 화면")
        monkeypatch.setattr(d, "ARCHIVE_ROOT", tmp_path)
        monkeypatch.setattr(d, "_load_realestate_runs", lambda: [])
        monkeypatch.setattr(d, "_load_cheongyak_runs", lambda: [])
        d.regenerate_realestate_index()
        assert not stale.exists(), "옛 cheongyak.html 이 안 지워졌다"

    def test_cheongyak_records_render_inside_the_realestate_page(self):
        # 단독 페이지를 지운 대신 **부동산 화면이 청약을 실어야** 한다.
        import bot.dashboard as d
