        import bot.finviz_client as fc
        monkeypatch.setattr("bot.twse_client.fetch_tw_industry_map", lambda: {})
        monkeypatch.setattr(fc, "_fetch_industries", lambda tickers, **k: {"2330.TW": "반도체(yf)"})
