class TestOnStartupStaticPagesBackgrounded20260803:
    """2026-08-03 실측: _on_startup(post_init) 이 screener~dart_feed 정적
    페이지 재생성 10개를 async 본문에서 동기 실행 → app.run_polling() 의
    getUpdates 시작을 그만큼 지연. dart_feed 재생성은 FSC(data.go.kr) 시총
    조회가 45초 소프트예산(dashboard._mc_deadline) + 콜당 20초(fsc_client.
    _TIMEOUT) 오버런까지 낼 수 있어, FSC 저하(429·timeout 연발) 시 watchdog
    의 180초 'bot starting' 유예(deploy/watchdog.sh)를 넘겨 polling 진입 전에
    재시작당함 — 09:07·09:11 hang 알림 실측(재시작마다 cascade 처음부터 재현,
    자기악화 루프). main() 의 _startup_regen 스레드와 동일 패턴으로 백그라운드화."""

    def test_static_pages_regen_is_backgrounded(self):
        src = open("bot/telegram_bot.py", encoding="utf-8").read()
        assert "def _static_pages_regen():" in src, \
            "static 페이지 재생성이 별도 함수로 분리돼야(백그라운드화 전제)"
        assert 'Thread(target=_static_pages_regen, name="static-pages-regen",' in src, \
            "static 페이지 재생성이 daemon 스레드로 배선돼야 (post_init 동기 " \
            "실행이면 getUpdates 시작 지연 → watchdog false-restart)"
        # 스레드 함수 정의가 스레드 기동보다 먼저 나와야 하고, 그 사이(정의부
        # 내부)에 각 regenerate_* 호출이 들어있어야 — 동기 최상위 호출로
        # 되돌아가는 회귀 방지.
        def_idx = src.index("def _static_pages_regen():")
        start_idx = src.index('name="static-pages-regen"')
        assert def_idx < start_idx
        body = src[def_idx:start_idx]
        for fn in ("regenerate_screener_index", "regenerate_daily_byte_index",
                   "regenerate_realestate_index",
                   "regenerate_gics_candidates_index", "regenerate_watchlist_index",
                   "regenerate_reddit_insider_index", "regenerate_blog_index",
                   "regenerate_valuechain_index", "regenerate_market_index",
                   "regenerate_dart_feed_index"):
            assert fn in body, f"{fn} 가 백그라운드 스레드 함수 밖(동기 경로)으로 이동함"


class TestFredCardDailyDateAndJoltsScale20260803:
    """사용자 2026-08-03 스크린샷 후속 질문("최신값 맞는거지?")에서 발견:
    (1) '핵심 지표' 카드가 국채금리 3종(일별 series)도 macro_snapshot 과 달리
    월 잘림 라벨('2026-07')을 써 실제로는 최근 며칠 값인데 한 달 지난 것처럼
    보였다 — macro_snapshot 은 2026-08-02 에 같은 문제를 _DAILY_CADENCE_KEYS
    로 이미 고쳤는데 이 카드엔 안 옮겨졌었음.
    (2) JOLTS(단위 M) 의 change 값이 헤드라인처럼 ÷1000 안 돼 원시(천단위)
    숫자가 그대로 떠 '▲9.00' 이 마치 9백만 변화처럼 보였다(실제 0.01M=1만)."""

    def test_daily_series_shows_full_date(self):
        import bot.dashboard as d
        fred_data = [{"label": "US 미국채 10년 (금리)", "unit": "%",
                      "series_id": "DGS10",
                      "data": {"value": 4.68, "change": 0.01, "time": "2026-07-31"}}]
        html = d._render_fred_card(fred_data, None)
        assert "2026-07-31" in html, "일별 series(DGS10) 가 정확한 날짜를 안 보여줌"
        assert "(2026-07)</span>" not in html, "일별 series 가 여전히 월로 잘림"

    def test_non_daily_series_still_month_truncated(self):
        # 월간/분기 series(CPI 등)는 원래대로 월 라벨 유지 — 회귀 방지.
        import bot.dashboard as d
        # ⚠️ 관측일을 **고정 문자열**로 두면 시간이 지나면서 그 값이 공표
        # 규약상 '지연'이 되어 `⚠ 지연` 배지가 붙는다(2026-08-19 실제 발생 —
        # 하드코딩한 2026-06-15 가 CPI 규약을 넘김). 이 테스트가 보려는 건
        # **월 잘림**이므로 오늘 기준 상대 날짜를 쓴다.
        from datetime import datetime, timedelta
        _t = (datetime.utcnow() + timedelta(hours=9)).date()
        fred_data = [{"label": "CPI (YoY)", "unit": "%", "series_id": "CPIAUCSL",
                      "data": {"value": 3.46, "change": -0.70,
                               "time": _t.isoformat()}}]
        html = d._render_fred_card(fred_data, None)
        assert f"({_t:%Y-%m})</span>" in html
        assert "2026-06-15" not in html

    def test_jolts_change_scaled_to_millions(self):
        import bot.dashboard as d
        # 원시(천단위) value=7600 → 7.6M, change=9(천단위) → 0.01M 로 스케일.
        fred_data = [{"label": "JOLTS (비농업 구인)", "unit": "M", "series_id": "JTSJOL",
                      "data": {"value": 7600.0, "change": 9.0, "time": "2026-05-15"}}]
        html = d._render_fred_card(fred_data, None)
        assert "7.6M" in html
        assert "▲0.01" in html, "JOLTS change 가 여전히 원시(천단위) 스케일로 표시됨"
        assert "▲9.00" not in html, "JOLTS change 가 헤드라인과 다른 스케일(원시값)로 표시됨"

    def test_fetch_all_fred_includes_series_id(self):
        src = open("bot/market_overview.py", encoding="utf-8").read()
        assert '"series_id": series_id' in src, \
            "_fetch_all_fred 결과에 series_id 미포함 — 카드 렌더가 일별/월별 구분 불가"


class TestDepositCacheSessionIndependent20260803:
    """사용자 2026-08-03 실측(TNBfolio 위젯 캡쳐 비교): TNBfolio 는 07/31
    투자자예탁금·신용융자를 이미 반영(오후 6:35)했는데 우리 대시보드는
    여전히 07/30 — KOFIA 가 KR 장마감(15:30) 이후 저녁에도 T-1 데이터를
    자체 스케줄로 공표할 수 있는데, deposit.json 캐시가 _session_fresh
    ("KR",...) 를 써서 '장 밖 = 재fetch 0' 으로 얼어붙어 다음 장 개장까지
    새 공표본을 못 받아온다(fsc_client._kofia_series 의 안쪽 3h 캐시는
    이미 하루종일 재확인하도록 돼있었는데 이 바깥 캐시가 먼저 막고 있었음).
    ttl 명시 시 세션과 무관하게 순수 경과시간으로만 신선도 판단하도록 fix."""

    def test_cached_ttl_overrides_session_freeze(self, tmp_path, monkeypatch):
        import os
        import time

        import bot.naver_sector_client as nsc
        monkeypatch.setattr(nsc, "_CACHE_DIR", tmp_path)
        f = tmp_path / "deposit.json"
        f.write_text('{"date": "old"}', encoding="utf-8")
        # 장 밖이라고 가정해도(_session_fresh 가 True 를 리턴해도) ttl 지정 시
        # 그건 무시하고 순수 경과시간만 본다 — old mtime(4시간 전)이면 stale.
        monkeypatch.setattr("bot.finviz_client._session_fresh", lambda *a, **k: True)
        old = time.time() - 4 * 3600
        os.utime(f, (old, old))
        assert nsc._cached("deposit.json", ttl=3 * 3600) is None, \
            "ttl 지정 시에도 session_fresh(장 밖 프리즈)에 여전히 의존함"
        # 세션-인지 기본 호출(ttl=None)은 옛 동작 그대로 유지(다른 캐시파일 회귀 방지).
        assert nsc._cached("deposit.json") == {"date": "old"}, \
            "ttl 미지정 기본 경로가 세션-인지 동작을 잃음(업종/테마 등 회귀 위험)"

    def test_fetch_deposit_uses_session_independent_ttl(self):
        src = open("bot/naver_sector_client.py", encoding="utf-8").read()
        assert '_cached("deposit.json", ttl=1 * 3600)' in src, \
            "fetch_deposit 가 세션-무관 TTL(1h) 로 안 바뀜(2026-08-08 시장유동성 1h 통일)"


class TestKisVkospiIndex20260808:
    """VKOSPI 재구현(2번째 시도) — pykrx/ECOS 무료소스 둘 다 데이터 없어 1차
    롤백(#835) 후, 사용자가 KIS Developers 공식문서 확인 + idxcode.mst 마스터
    파일 실측 파싱으로 지수코드 '0503'(VKOSPI) 확정. KIS 국내업종 현재지수/
    기간별시세 API 로 재구현. 코드는 추측 아님 — 실제 다운로드한 마스터파일에서
    확인."""

    def test_get_domestic_index_price_parses_bstp_nmix_prpr(self, monkeypatch):
        import bot.kis_client as k
        monkeypatch.setattr(k, "_cache_get", lambda key, ttl_hours=None: None)
        monkeypatch.setattr(k, "_cache_put", lambda key, val: None)
        seen = {}

        def _fake_get(path, tr_id, params, custtype=None):
            seen["path"] = path
            seen["tr_id"] = tr_id
            seen["params"] = params
            return {"output": {"bstp_nmix_prpr": "6258.77"}}

        monkeypatch.setattr(k, "_get", _fake_get)
        v = k.KisClient().get_domestic_index_price("0503")
        assert v == 6258.77
        assert seen["tr_id"] == "FHPUP02100000"
        assert seen["path"] == "/uapi/domestic-stock/v1/quotations/inquire-index-price"
        assert seen["params"]["FID_COND_MRKT_DIV_CODE"] == "U"
        assert seen["params"]["FID_INPUT_ISCD"] == "0503"

    def test_get_domestic_index_price_none_on_empty_output(self, monkeypatch):
        import bot.kis_client as k
        monkeypatch.setattr(k, "_cache_get", lambda key, ttl_hours=None: None)
        monkeypatch.setattr(k, "_cache_put", lambda key, val: None)
        monkeypatch.setattr(k, "_get", lambda path, tr_id, params, custtype=None: None)
        assert k.KisClient().get_domestic_index_price("0503") is None

    def test_get_domestic_index_daily_paginates_and_dedups(self, monkeypatch):
        # days=200 > 70 이므로 페이지네이션(70일 단위 청크) 여러 번 호출돼야
        # 함 — 각 호출을 서로 다른 날짜로 응답해 병합·중복제거 검증.
        import bot.kis_client as k
        monkeypatch.setattr(k, "_cache_get", lambda key, ttl_hours=None: None)
        monkeypatch.setattr(k, "_cache_put", lambda key, val: None)
        call_count = {"n": 0}

        def _fake_get(path, tr_id, params, custtype=None):
            call_count["n"] += 1
            if call_count["n"] == 1:
                return {"output2": [
                    {"stck_bsop_date": "20260805", "bstp_nmix_prpr": "21.30"},
                    {"stck_bsop_date": "20260806", "bstp_nmix_prpr": "22.70"},
                ]}
            if call_count["n"] == 2:
                return {"output2": [
                    {"stck_bsop_date": "20260806", "bstp_nmix_prpr": "22.70"},  # 중복
                    {"stck_bsop_date": "20260601", "bstp_nmix_prpr": "19.10"},
                ]}
            return {"output2": []}   # 더 과거 청크는 데이터 없음 → 루프 종료

        monkeypatch.setattr(k, "_get", _fake_get)
        bars = k.KisClient().get_domestic_index_daily("0503", days=200)
        assert bars is not None
        dates = [b["date"] for b in bars]
        assert dates == sorted(dates), "오름차순 정렬 안 됨"
        assert len(dates) == len(set(dates)), "중복 날짜 제거 안 됨"
        assert {"date": "2026-08-06", "close": 22.70} in bars
        assert call_count["n"] >= 2, "70일 초과분 페이지네이션 안 됨(1콜만 호출)"

    def test_get_domestic_index_daily_none_when_too_few_bars(self, monkeypatch):
        import bot.kis_client as k
