        import bot.dashboard as d
        two = [{"d": "2026.07.01", "v": 1}, {"d": "2026.07.02", "v": 2}]
        vser = [{"d": "2026.08.05", "v": 21.3}, {"d": "2026.08.06", "v": 22.7}]
