    def test_us_korean_names_merge_two_sources_and_reject_english(
            self, monkeypatch, tmp_path):
        """⚠️ 업종 endpoint 는 업종당 상위 300종목까지라 소형주가 빠진다 —
        실적 캘린더에서 ABHBY·ACRG·ARMP 가 티커만 떴다(사용자 2026-08-18).
        worldstock 목록을 얹되, **한글이 든 이름만** 받는다: 원천이 영문을
        주면 '한글명' 자리에 영문이 들어가 되레 헷갈린다."""
        import bot.finviz_client as fvc
        import bot.naver_ranking_client as nrc
        monkeypatch.setattr(nrc, "world_upjong_name",
                            lambda m: {"AAPL": "애플", "MSFT": "Microsoft"})
        monkeypatch.setattr(nrc, "world_name_map",
                            lambda m, **k: {"ARMP": "아르마타", "ACRG": "Acreage"})
        # ⚠️ `_cached`/`_cache_write` 는 함수 **안에서** finviz_client 로부터
        # import 된다 — nrc 에 패치하면 안 먹고 진짜 디스크 캐시를 읽는다
        # (그리고 테스트가 실 캐시를 오염시킨다).
        monkeypatch.setattr(fvc, "_cached", lambda *a, **k: None)
        monkeypatch.setattr(fvc, "_cache_write", lambda *a, **k: None)
        nrc._KOR_NAME_BUILDING.discard("US")
        # 즉시 반환분: 업종 맵 중 한글만.
        got = nrc.korean_name_map("US")
        assert got == {"AAPL": "애플"}, got
        # 백그라운드 병합 결과를 직접 검증(스레드 대기 대신 같은 로직 호출).
        merged = {k: v for k, v in nrc.world_name_map("US").items()
                  if nrc._HANGUL_RE.search(v)}
        merged.update({k: v for k, v in nrc.world_upjong_name("US").items()
                       if nrc._HANGUL_RE.search(v)})
        assert merged == {"ARMP": "아르마타", "AAPL": "애플"}
        assert "Microsoft" not in merged.values()
        assert "Acreage" not in merged.values()
        # 배선 — 실적 캘린더가 병합 맵을 쓰는지(실수 #20).
        import pathlib as _p
        dd = _p.Path("bot/dashboard.py").read_text(encoding="utf-8")
        assert "korean_name_map as _knm" in dd and '_us_kr = _knm("US")' in dd

    def test_korean_font_is_found_by_glyphs_not_by_name(self, tmp_path):
        """⚠️ 옛 판정은 `NanumGothic.ttf` 경로 3개 + 이름에 "Nanum" 이 있는지
        만 봤다 — Noto CJK 처럼 한글이 완벽한 폰트가 깔린 서버에서도 "폰트
        미설치"로 단정하고 이미지를 포기했다(사용자 2026-08-18 LPK.DE,
        실수 #24 목록형 판정). 이름이 아니라 **글리프**로 판정한다."""
        from bot import korean_font as kf
        import matplotlib, pathlib as _p
        mpl = _p.Path(matplotlib.__file__).parent / "mpl-data" / "fonts" / "ttf"
        # (a) 한글 없는 폰트는 거부.
        dejavu = mpl / "DejaVuSans.ttf"
        assert dejavu.exists()
        assert kf._has_hangul(str(dejavu)) is False

        # (b) ⚠️ **만능 폴백 폰트도 거부해야 한다.** matplotlib 동봉
        # LastResort 는 모든 코드포인트에 글리프를 주지만 실제로는 네모만
        # 그린다 — 한글 검사만 하면 통과하고 화면은 두부가 된다.
        last = next(iter(mpl.glob("LastResort*.ttf")), None)
        if last is not None:
            from matplotlib.ft2font import FT2Font
            f = FT2Font(str(last))
            assert f.get_char_index(0xAC00), "전제 확인: 한글 글리프는 있다"
            assert kf._has_hangul(str(last)) is False, "폴백 폰트를 받아들였다"

        # (c) 이름 목록이 아니라 실측이므로 Nanum 이 아니어도 통과한다.
        found = kf.find_font()
        if found:
            assert kf._has_hangul(found)
            assert "폰트 사용" in kf.diagnose()
        else:
            assert "설치" in kf.diagnose(), "없으면 설치 방법을 말해야 한다"

    def test_render_failure_states_the_actual_reason(self, monkeypatch):
        """⚠️ 옛 화면은 원인과 무관하게 늘 "서버 한글 폰트 미설치" 라고 했다
        — 폰트가 멀쩡한데 다른 이유로 실패해도 사용자를 폰트 설치로 보냈다."""
        import bot.dashboard_server as ds
        from bot import korean_font as kf
        monkeypatch.setattr(kf, "find_font", lambda: "/x/NotoSansKR.otf")
        assert "폰트는 정상" in ds._render_note()
        monkeypatch.setattr(kf, "find_font", lambda: None)
        monkeypatch.setattr(kf, "diagnose", lambda: "한글 글리프를 가진 폰트 없음 — 설치: ...")
        assert "설치" in ds._render_note()
        # 프런트가 서버 문구를 쓰는지(배선, 실수 #20).
        import pathlib as _p
        dd = _p.Path("bot/dashboard.py").read_text(encoding="utf-8")
        assert "j.render_note" in dd
        assert "서버 한글 폰트 미설치" not in dd, "하드코딩 문구 재발"

    def test_missing_quarter_is_named_not_silently_skipped(self):
        """⚠️ LPK.DE 표가 25.1Q·25.2Q·**25.4Q**·26.1Q·26.2Q 로 이어져 25.3Q 가
        통째로 없는데 화면엔 아무 표시가 없었다(사용자 2026-08-18) — 원천
        결측인지 우리가 흘린 건지 볼 방법이 없었다. 채우지 않고 밝힌다."""
        from bot.quarterly_series import missing_quarters
        from bot.quarterly_infographic import _footnotes
        qs = [{"period": "2025-03-31", "label": "25.1Q"},
              {"period": "2025-06-30", "label": "25.2Q"},
              {"period": "2025-12-31", "label": "25.4Q"},
              {"period": "2026-03-31", "label": "26.1Q"},
              {"period": "2026-06-30", "label": "26.2Q"}]
        assert missing_quarters(qs) == ["25.3Q"]
        # 연속이면 아무 말도 하지 않는다(가짜 경고 금지).
        cont = [{"period": "2026-03-31", "label": "26.1Q"},
                {"period": "2026-06-30", "label": "26.2Q"}]
        assert missing_quarters(cont) == []
        # 형식을 모르면 **판정하지 않는다**(추측 금지).
        assert missing_quarters([{"period": "2026Q1"}, {"period": "2026Q3"}]) == []
        # PNG·표가 공유하는 각주에 실제로 실린다(배선, 실수 #20).
        notes = " ".join(t for t, _c in _footnotes({"currency": "EUR"}, qs))
        assert "25.3Q" in notes and "채우지 않습니다" in notes
        assert "25.3Q" not in " ".join(
            t for t, _c in _footnotes({"currency": "EUR"}, cont))

    def test_core_indicator_rows_stay_one_line(self):
        """⚠️ 핵심 지표 카드는 300px 그리드다. 라벨이 길면 두 줄로 접혀 옆
        카드와 행 높이가 어긋난다(사용자 2026-08-18 "(금리) 같은 글자 빼서
        옆과 높이를 맞춰줘"). 라벨 길이와 줄바꿈 금지를 함께 강제한다."""
        import pathlib
        import re
        from bot.market_overview import FRED_INDICATORS
        for label, sid, _u, _lb in FRED_INDICATORS:
            assert "(금리)" not in label, f"카드 제목과 중복: {label}"
            assert len(label) <= 14, f"라벨이 너무 길다({len(label)}자): {label}"
        # 변동 칸이 실제 폭보다 넓으면 라벨 칸을 눌러 그 행만 두 줄이 된다.
        dd = pathlib.Path("bot/dashboard.py").read_text(encoding="utf-8")
        i = dd.index('".mcard td:nth-child(3)')
        w = int(re.search(r"width:(\d+)px", dd[i:i + 120]).group(1))
        assert w <= 70, f"변동 칸이 너무 넓다({w}px) — 라벨이 접힌다"

    def test_macro_note_is_collapsed_not_a_growing_paragraph(self):
        """⚠️ 안내문에 설명을 계속 덧붙이다 문단이 길어져 카드보다 눈에 띄었다
        (사용자 2026-08-18 "설명이 계속 rolling 되는데 적절하지 않다").
        접기(details)로 넣고 줄 수를 묶는다 — 다음에 또 덧붙이면 테스트가 잡는다."""
        import re
        from bot.dashboard import _render_macro_snapshot
        html = _render_macro_snapshot({
            "domestic": [{"label": "X", "value": 1, "decimals": 0,
                          "unit": "", "asof": "2026-06"}],
            "global": [], "charts": {}, "ts": "08.19"})
        m = re.search(r'<details class="macro-note".*?</details>', html, re.S)
        assert m, "안내문이 접기(details)가 아니다"
        blk = m.group(0)
        assert "<summary" in blk and "읽는 법" in blk
        assert blk.count("<li>") <= 4, "안내문 항목이 또 불어났다"
        # 안내문이 항상 펼쳐진 채로 돌아가지 않게(open 속성 금지).
        assert not re.search(r"<details[^>]*\bopen\b", blk)

    def test_component_revenue_never_produces_impossible_ratios(self):
        """⚠️ NH투자증권(2026-08-19 사용자): 화면에 영업이익률 117.7%, 매출
        5,787억 < 영업이익 6,812억. 총수익 계정을 공시하지 않는 금융사라
        '매출' 자리에 **이자수익**(구성요소)이 들어갔는데, 그걸 분모로 나눠
        불가능한 비율을 그대로 찍었다. 값은 보존하되 비율은 비운다."""
        from bot.dart_client import calc_kr_financial_ratios, revenue_label
        base = {"매출": 1.97e12, "영업이익": 1.42e12, "당기순이익": 1.03e12,
                "자본총계": 9.4e12, "자산총계": 8.3e13, "부채총계": 7.4e13,
                "매출총이익": 1.0e12}
        ok = calc_kr_financial_ratios(base)
        assert round(ok["영업이익률"], 1) == 72.1        # 총액이면 그대로 낸다
        comp = dict(base, _component_accounts={"매출": "이자수익"})
        bad = calc_kr_financial_ratios(comp)
        for k in ("영업이익률", "순이익률", "매출총이익률"):
            assert bad[k] is None, f"{k} 가 구성요소를 분모로 계산됐다"
        # 매출과 무관한 비율은 살아 있어야 한다(과잉 차단 금지).
        assert bad["ROE"] is not None and bad["부채비율"] is not None
        # 행 이름도 실제 계정으로 — '매출'이라 부르면 모순돼 보인다.
        assert revenue_label(comp) == "이자수익"
        assert revenue_label(base) == "매출"

    def test_total_revenue_wins_even_when_its_korean_name_is_unlisted(self):
        """⚠️ **근본 원인.** 우선순위를 한글 이름으로만 매겨서, 표준 태그
        (`ifrs-full_Revenue`)로 총액이 정확히 잡혀도 이름이 목록에 없으면
        최하위로 밀려 구성요소(이자수익)에게 졌다. 이름 앞 번호("Ⅰ.")만
        붙어도 같은 일이 벌어진다(2026-08-19 실측)."""
        from bot.dart_client import _account_rank, _extract_dart_financials
        # (a) 이름 앞 번호·공백은 벗기고 본다.
        assert _account_rank("매출", "Ⅰ. 영업수익") == 0
        assert _account_rank("매출", "영업수익 ") == 0
        assert _account_rank("매출", "1. 영업수익") == 0
        # (b) 이름을 몰라도 표준 총액 태그면 구성요소보다 앞선다.
        assert _account_rank("매출", "순영업손익", "ifrs-full_Revenue") < \
            _account_rank("매출", "이자수익")
        # (c) 태그도 이름도 모르면 종전대로 맨 뒤(없는 규칙을 만들지 않는다).
        assert _account_rank("매출", "순영업손익", "") == 3

        # (d) E2E — 추출기를 통째로 태워 **승자**가 바뀌는지 본다(실수 #20:
        # 헬퍼 테스트만으로는 배선 변형을 못 잡는다).
        items = [
            {"account_id": "ifrs-full_Revenue", "account_nm": "Ⅰ. 영업수익",
             "thstrm_amount": "10,000,000,000", "sj_div": "IS"},
            {"account_id": "dart_InterestIncome", "account_nm": "이자수익",
             "thstrm_amount": "1,970,000,000", "sj_div": "IS"},
        ]
        fin = _extract_dart_financials(items)
        assert fin["매출"] == 1e10, "총액이 아니라 구성요소가 이겼다"
        assert "매출" not in (fin.get("_component_accounts") or {}), \
            "총액을 잡았는데 구성요소로 표기했다"
        # 총액이 아예 없을 때만 구성요소가 승자가 되고, 그 사실이 남는다.
        only_comp = _extract_dart_financials([items[1]])
        assert only_comp["매출"] == 1.97e9
        assert (only_comp.get("_component_accounts") or {})["매출"] == "이자수익"

    def test_component_revenue_surfaces_say_so(self):
        """세 화면(요약·추이표·인포그래픽)이 **같은 이름**을 쓰고, 매출로
        나누는 지표를 만들지 않는지."""
        from bot.quarterly_infographic import _footnotes, table_html
        qs = [{"label": "26.2Q", "period": "2026-06-30",
               "financials": {"매출": 5.787e11, "영업이익": 6.812e11,
                              "당기순이익": 9.652e11,
                              "_component_accounts": {"매출": "이자수익"}},
               "ratios": {"영업이익률": None, "순이익률": None}}]
        pl = {"currency": "KRW", "quarters": qs, "psr": None,
              "component_accounts": {"매출": "이자수익"}}
        import re
        assert re.findall(r"<tr><td>([^<]+)</td>", table_html(pl))[0] == "이자수익"
        note = " ".join(t for t, _c in _footnotes(pl, qs))
        assert "이자수익(구성요소 계정)" in note
        assert "PSR 산출 제외" in note, "왜 비었는지 설명이 없다"
        # VM 프로브(2026-08-19 005940.KS)로 확정: 손익 40개 항목에 영업수익이
        # 없고 수수료수익·이자수익 등 구성요소만 있다 — 이 값은 총수익의
        # **일부**다. 각주가 그 사실을 말해야 총액으로 오해하지 않는다.
        assert "총수익의 일부" in note
        # PNG 각주는 plain text — 마크다운 별표가 그려지면 안 된다.
        assert "**" not in note
        # PSR 가드가 배선돼 있는지(실수 #20).
        import pathlib as _p
        src = _p.Path("bot/quarterly_infographic.py").read_text(encoding="utf-8")
        i = src.index("psr = mcap / _ttm_rev")
        assert "not _rev_is_comp" in src[i - 400:i]

    def test_archived_kr_financials_are_refreshed_when_schema_moves(self):
        """⚠️ **fix 를 배포해도 이미 분석한 종목은 안 바뀐다**(실수 #18).
        KR 재무는 분석 시점에 아카이브 JSON 으로 구워지고, 옛 `_e_financials`
        는 yfinance 만 다시 받았다 — NH투자증권의 영업이익률 117.7% 가
        #916 배포 후에도 화면에 그대로 남는다는 뜻이다(사용자 2026-08-19
        "비슷한 종목들도 고쳐진 거라고 봐야지?"). 스키마 버전으로 대조한다."""
        import pathlib
        from bot.stock_snapshot import _KR_FIN_SCHEMA_VER, collect_kr_financials
        assert _KR_FIN_SCHEMA_VER >= 1
        assert callable(collect_kr_financials)      # 밖에서 부를 수 있어야 한다
        src = pathlib.Path("bot/dashboard.py").read_text(encoding="utf-8")
        i = src.index("def _e_kr_financials()")
        blk = src[i:src.index("def _e_peers()", i)]
        assert "_KR_FIN_SCHEMA_VER" in blk, "버전 대조 없이 냄새만 맡고 있다"
        assert "collect_kr_financials" in blk
        # 이미 최신이면 재수집하지 않는다(매 렌더 DART 재호출 방지).
        assert 'financials_ver") or 0) >= _KR_FIN_SCHEMA_VER' in blk
        # 애초에 없던 종목에 새로 만들지 않는다(비-KR·미수집 보존).
        assert 'if not _kr.get("financials")' in blk
        # 실행 경로 둘 다에 배선돼 있어야 한다(병렬·순차).
        assert src.count("_e_kr_financials()") >= 1
        assert "_pool.submit(_e_kr_financials)" in src

        # 수집기가 버전을 실제로 찍는지 — 스텁으로 통째로 태운다(실수 #20).
        import bot.stock_snapshot as ss

        class _FakeDart:
            def get_normalized_financials(self, tk, year=None):
                return {"year": year or 2025, "fs_div": "CFS",
                        "financials": {"매출": 100.0, "영업이익": 10.0},
                        "ratios": {"영업이익률": 10.0}}

        import unittest.mock as _m
        with _m.patch("bot.dart_client.get_dart", lambda: _FakeDart()):
            out = collect_kr_financials("005930.KS")
        assert out["kr"]["financials_ver"] == _KR_FIN_SCHEMA_VER
        assert out["kr"]["financials"]["매출"] == 100.0

    def test_fnguide_fills_total_revenue_only_when_it_checks_out(self):
        """⚠️ VM 스윕(2026-08-19): 금융 27종목 중 **15개**가 DART 표준 손익에
        총액(영업수익)이 없어 이자수익이 '매출'로 올라갔다. FnGuide 에는
        총액이 있다(NH 26.1Q 8.17조 vs 이자수익 0.55조).

        다른 출처 숫자를 우리 표에 넣는 일이라 **검산 없이는 안 쓴다** —
        기간 일치 · 영업이익 교차 확인 · 총액>구성요소. 하나라도 어긋나면
        entry 를 건드리지 않는다(옛 동작 유지)."""
        from bot.kr_revenue_fallback import fill_total_revenue
        S = {"quarter": {"2026/03": {"매출액": 8.172e12, "영업이익": 6.367e11,
                                     "당기순이익": 4.757e11}}}

        def _e(**kw):
            d = {"매출": 5.532e11, "영업이익": 6.367e11, "당기순이익": 4.757e11,
                 "_component_accounts": {"매출": "이자수익"}}
            d.update(kw)
            return d

        e = _e()
        assert fill_total_revenue("005940", e, year=2026, quarter=1, summary=S)
        assert e["매출"] == 8.172e12
        assert round(e["영업이익률"], 2) == 7.79      # FnGuide 화면과 정합
        assert e["_revenue_source"] == "FnGuide"
        assert e["_revenue_component_was"] == "이자수익"
        assert "_component_accounts" not in e, "총액을 넣고도 구성요소로 표기"

        # (1) 기간이 없으면 추측하지 않는다.
        e2 = _e()
        assert not fill_total_revenue("005940", e2, year=2026, quarter=2,
                                      summary=S)
        assert e2["매출"] == 5.532e11 and "_revenue_source" not in e2
        # (2) 영업이익이 어긋나면 다른 표를 붙인 것이다.
        e3 = _e(영업이익=9.9e11)
        assert not fill_total_revenue("005940", e3, year=2026, quarter=1,
                                      summary=S)
        # (3) 총액이 구성요소 이하면 파싱 오류다.
        e4 = _e()
        assert not fill_total_revenue(
            "005940", e4, year=2026, quarter=1,
            summary={"quarter": {"2026/03": {"매출액": 1e11,
                                             "영업이익": 6.367e11}}})
        # (4) 총액이 이미 있는 회사는 손대지 않는다.
        e5 = {"매출": 1e12, "영업이익": 1e11}
        assert not fill_total_revenue("005940", e5, year=2026, quarter=1,
                                      summary=S)
        assert e5 == {"매출": 1e12, "영업이익": 1e11}

    def test_fnguide_summary_parser_reads_the_real_table_shape(self):
        """⚠️ 실제 표(2026-08-19 005940 원문 덤프)는 헤더에 **탭별 대체 컬럼
        세트가 전부** 들어 있다 — 헤더 20칸 vs 데이터 8칸, 숨김 표식 없음
        (전부 class="sub line"). 그룹 헤더가 칸 수(연간4·분기4)를 주고,
        실제 그려지는 세트는 **간격이 일정한 연속 구간**이라는 두 사실을
        합쳐야 유일하게 결정된다."""
        from bot.wisereport_financials import parse_financial_summary
        per = ["2022/12", "2023/12", "2024/12", "2025/12", "2026/12",
               "2025/03", "2025/12", "2026/03", "2025/06", "2026/06",
               "2025/06", "2025/09", "2025/12", "2026/03", "2026/06",
               "2025/03", "2025/12", "2026/03", "2025/06", "2026/06"]
        hdr = "".join(f"<th scope='col' class='sub line'>{p}<br>"
                      f"<span class='multi-row'>(IFRS연결)</span></th>"
                      for p in per)

        def _row(nm, vs):
            return ("<tr><th scope='row' class='line txt'>" + nm + "</th>"
                    + "".join(f"<td class='num line'>{v}</td>" for v in vs)
                    + "</tr>")

        html = ('<table><tr><th class="c1 line" rowspan="2">주요재무정보</th>'
                '<th scope="colgroup" class="line" colspan="4">연간</th>'
                '<th scope="colgroup" colspan="4">분기</th></tr>'
                "<tr>" + hdr + "</tr>"
                + _row("매출액", ["112,274", "103,712", "100,342", "136,989",
                                 "32,645", "26,840", "48,641", "81,720"])
                + _row("영업이익", ["5,214", "7,258", "9,011", "14,206",
                                  "3,219", "3,913", "4,183", "6,367"])
                + "</table>")
        out = parse_financial_summary(html)
        a, q = out["annual"], out["quarter"]
        # 연간 = 12개월 간격 연속 구간(2022~2025). 2026/12(추정)은 제외된다.
        assert sorted(a) == ["2022/12", "2023/12", "2024/12", "2025/12"]
        assert a["2025/12"]["매출액"] == 136989 * 1e8
        # 교차확인: 이 매핑일 때 FY2025 영업이익이 DART 값(14,206억)과 일치.
        assert a["2025/12"]["영업이익"] == 14206 * 1e8
        # 분기 = 3개월 간격 연속 구간(2025/06~2026/03). 화면과 정합.
        assert sorted(q) == ["2025/06", "2025/09", "2025/12", "2026/03"]
        assert q["2025/06"]["매출액"] == 32645 * 1e8
        assert q["2026/03"]["매출액"] == 81720 * 1e8
        # 같은 '2025/12' 라도 연간(13.70조)과 4분기(4.86조)를 구분한다.
        assert q["2025/12"]["매출액"] == 48641 * 1e8

        # 그룹 헤더 없는 단순 표(한 종류)도 그대로 읽는다.
        simple = ("<table><tr><th>주요재무정보</th><th>2024/12</th>"
                  "<th>2025/12</th></tr>"
                  "<tr><td>매출액</td><td>100</td><td>200</td></tr>"
                  "<tr><td>영업이익</td><td>10</td><td>20</td></tr></table>")
        assert parse_financial_summary(simple)["annual"]["2025/12"][
            "매출액"] == 200 * 1e8

        # ⚠️ **못 맞추면 버린다** — 틀린 매핑으로 숫자를 내보내지 않는다.
        broken = ('<table><tr><th rowspan="2">x</th>'
                  '<th colspan="4">연간</th></tr>'
                  "<tr><th>2024/12</th><th>2026/12</th></tr>"
                  "<tr><td>매출액</td><td>1</td><td>2</td></tr>"
                  "<tr><td>영업이익</td><td>1</td><td>2</td></tr></table>")
        assert parse_financial_summary(broken) == {"annual": {}, "quarter": {}}

        # Financial Summary 가 아닌 표는 무시한다(오탐 방지).
        assert parse_financial_summary(
            "<table><tr><th>a</th><th>2025/03</th><th>2025/06</th></tr>"
            "<tr><td>주가</td><td>1</td><td>2</td></tr></table>") == {
                "annual": {}, "quarter": {}}

    def test_fnguide_failure_says_which_of_three_causes(self, monkeypatch):
        """⚠️ VM 스윕(2026-08-19)에서 15종목 전부 "FnGuide 표 없음" 만 떴다 —
        (a) 요청 실패 (b) 표가 AJAX 라 HTML 에 없음 (c) 파싱 규칙 문제 중
        무엇인지 알 수 없는 메시지다(실수 #12). 셋을 갈라 말하게 한다."""
        import bot.wisereport_financials as wf

        class _R:
            status_code = 200
            encoding = "utf-8"

            def __init__(self, text):
                self.text = text

            def raise_for_status(self):
                pass

        monkeypatch.setattr(wf, "_cached", None, raising=False)
        # ⚠️ 실측: 기업현황(c1010001)은 Financial Summary 가 AJAX 라 HTML 에
        # 없고 '매출액' 은 산식 설명으로만 나온다 — 그래서 프래그먼트
        # (cF1001)를 받는다. URL 이 되돌아가면 15종목이 다시 빈다.
        # ⚠️ 주석에도 'cF1001' 이 나오므로 소스 전체를 보면 안 된다 —
        # **실제 URL 템플릿**을 확인한다(제 주석에 걸려 통과한 적 있음).
        assert "cF1001" in wf._URL_TMPL, "AJAX 페이지로 되돌아갔다"
        assert "freq_typ" in wf._URL_TMPL and wf._FREQS
        # (b) 표 자체가 없다
        monkeypatch.setattr(wf.requests, "get",
                            lambda *a, **k: _R("<html>no table here</html>"))
        assert wf.fetch_financial_summary("005940") is None
        assert "AJAX" in wf._LAST_REASON["005940"]
        # (c) '매출액' 은 있는데 우리가 못 읽었다
        monkeypatch.setattr(wf.requests, "get",
                            lambda *a, **k: _R("<html>매출액 30,068</html>"))
        assert wf.fetch_financial_summary("005940") is None
        assert "파싱 실패" in wf._LAST_REASON["005940"]
        # (a) 요청 자체가 실패
        def _boom(*a, **k):
            raise RuntimeError("nope")
        monkeypatch.setattr(wf.requests, "get", _boom)
        assert wf.fetch_financial_summary("005940") is None
        assert "요청 실패" in wf._LAST_REASON["005940"]

    def test_scraper_cache_is_invalidated_when_the_parser_changes(
            self, monkeypatch):
        """⚠️ **세 번째 재발**(실수 #18). 그룹 헤더 분리(#923)를 배포하고도
        스윕 출력이 한 글자도 안 변했다 — 12h 디스크 캐시가 옛 파싱 결과를
        그대로 서빙했기 때문이다. 파서를 고치면 캐시가 즉시 무효여야 한다."""
        import bot.finviz_client as fvc
        import bot.wisereport_financials as wf
        assert wf._PARSE_VER >= 2

        class _R:
            status_code = 200
            encoding = "utf-8"
            text = ("<table><tr><th>주요재무정보</th><th>2026/03</th>"
                    "<th>2026/06</th></tr>"
                    "<tr><td>매출액</td><td>10</td><td>20</td></tr>"
                    "<tr><td>영업이익</td><td>1</td><td>2</td></tr></table>")

            def raise_for_status(self):
                pass

        # 옛 버전 캐시는 무시하고 다시 받는다.
        monkeypatch.setattr(fvc, "_cached",
                            lambda *a, **k: {"annual": {}, "quarter": {"X": {}},
                                             "_ver": wf._PARSE_VER - 1})
        wrote = {}
        monkeypatch.setattr(fvc, "_cache_write",
                            lambda k, v: wrote.update({k: v}))
        monkeypatch.setattr(wf.requests, "get", lambda *a, **k: _R())
        got = wf.fetch_financial_summary("005940")
        assert got and "X" not in got["quarter"], "옛 버전 캐시를 그대로 썼다"
        assert got["_ver"] == wf._PARSE_VER
        assert wrote and list(wrote.values())[0]["_ver"] == wf._PARSE_VER

        # 같은 버전 캐시는 정상 재사용(매번 재수집이 아니다).
        monkeypatch.setattr(fvc, "_cached",
                            lambda *a, **k: {"annual": {}, "quarter": {"OK": {}},
                                             "_ver": wf._PARSE_VER})
        again = wf.fetch_financial_summary("005940")
        assert "OK" in again["quarter"]

    def test_move_card_gets_the_same_period_columns_as_vix(self, monkeypatch):
        """사용자 2026-08-19: "채권변동성도 VIX 처럼 기간으로 표시해줘."
        MOVE 만 패널을 따로 만들어 현재값 한 칸뿐이었고, 수집도 days=10 이라
        1달(21)·1년(252) 창 자체를 만들 수 없었다 — 렌더만 고치면 빈다."""
        import re
        import bot.market_timing as mt

        # (1) 수집 — 히스토리를 실제로 싣는지(창을 못 만들던 것이 진짜 원인).
        # ⚠️ 2026-08-20: 창 조회가 위치→**날짜** 기반이 되어 픽스처도 실제
        # 날짜여야 의미가 있다(가짜 'd0' 은 파싱 실패로 창이 통째로 빈다).
        from datetime import date, timedelta
        _b = date(2026, 8, 19)
        rows = [{"date": (_b - timedelta(days=399 - i)).isoformat(),
                 "close": 70.0 + i * 0.25} for i in range(400)]
        monkeypatch.setattr(mt, "fetch_index_history",
                            lambda t, **k: rows if t == "^MOVE" else [])
        monkeypatch.setattr(mt, "_index_quote_row", lambda t: [])
        monkeypatch.setattr(mt, "_fetch_vix_naver", lambda: None)
        monkeypatch.setattr(mt, "fetch_vkospi_rows", lambda: [])
        snap = mt.fetch_volatility_snapshot()
        hist = (snap.get("move") or {}).get("history") or {}
        for lb, _back in mt._VOL_LOOKBACKS:
            assert hist.get(lb) is not None, f"{lb} 창이 비었다 — 수집 기간 부족"

        # (2) 렌더 — VIX 와 같은 패널로 기간 칸이 붙는지.
        # ⚠️ 날짜를 하드코딩하면 시계가 지나면서 '지연' 라벨이 붙어 깨진다
        # (2026-08-19 실측 함정) — 오늘 기준 상대일로 만든다.
        from datetime import timedelta
        yday = (mt._kst_now().date() - timedelta(days=1)).isoformat()
        html = mt.render_market_timing_page({"volatility": {"move": {
            "value": 75.0, "date": yday,
            "history": {"전일": 74.1, "1주": 72.8, "1달": 80.3, "1년": 95.2}}}})
        i = html.index("채권 변동성 (MOVE)")
        blk = html[i:i + 3000]
        cells = dict(re.findall(
            r'class="k">([^<]+)</div><div class="v"[^>]*>([\d.]+)', blk))
        # '현재' 칸은 **며칠 종가인지**를 라벨에 달고 나온다(2026-08-19 —
        # ^MOVE 가 한 달 멈춘 값을 '현재'로 보여주던 것을 고치면서).
        cur = next((k for k in cells if k.startswith("현재")), None)
        assert cur is not None and cells[cur] == "75.0", cells
        assert yday[5:] in cur, cur
        for lb in ("전일", "1주", "1달", "1년"):
            assert lb in cells, f"{lb} 칸이 없다"

        # (3) 설명 — 단위 주의·읽는 법·왜 보는지가 있어야 한다.
        note = re.search(r'<div class="note">(.*?)</div>\s*</div>', blk, re.S)
        assert note, "설명이 없다"
        txt = re.sub(r"<[^>]+>", "", note.group(1))
        assert "직접 비교할 수 없" in txt, "VIX 와 단위가 다르다는 경고 누락"
        assert "읽는 법" in txt and "bp" in txt
        assert "할인율" in txt, "왜 주식 화면에 있는지 설명 누락"

        # 패널을 또 따로 만들면 기간 칸이 다시 사라진다 — 공용 함수 사용 강제.
        import pathlib as _p
        src = _p.Path("bot/market_timing.py").read_text(encoding="utf-8")
        j = src.index('if move:')
        assert "_vol_panel(" in src[j:j + 400], "MOVE 가 공용 패널을 안 쓴다"

    def test_industry_labels_are_korean_on_every_market(self, monkeypatch):
        """사용자 2026-08-19(JP/CN/HK/TW 신고저·급등락 스크린샷): 업종 칸에
        "Metal Fabrication"·"Furnishings, Fixtures & App…" 같은 영문이 섞여
        나왔다. 네이버 업종맵은 한글인데 **yfinance 폴백분만 번역이 빠져**
        있었다(TW 경로엔 있고 HK·CN/JP/US 엔 없었다)."""
        from bot.translate import _INDUSTRY_KR, industry_kr
        # 화면에서 실제로 목격된 미번역 항목들.
        for en in ("Metal Fabrication", "Furnishings, Fixtures & Appliances",
                   "Medical Distribution", "Electronics & Computer Distribution",
                   "Specialty Business Services"):
            assert en in _INDUSTRY_KR, f"{en} 번역 누락"
            assert industry_kr(en) != en
        # 이미 한글인 값은 그대로 통과(네이버 경로 무해).
        assert industry_kr("해운") == "해운"

        # 배선 — yfinance 폴백 경로에 번역이 걸려 있는지(실수 #20).
        import bot.finviz_client as fvc
        import bot.naver_ranking_client as nrc
        monkeypatch.setattr(fvc, "_fetch_industries",
                            lambda tks, **k: {t: "Metal Fabrication" for t in tks})
        monkeypatch.setattr(nrc, "world_industry_map", lambda m: {})
        for mkt in ("HK", "CN_A", "JP", "US", "KR", None):
            got = fvc._industries_for(["9999.HK"], mkt, allow_slow=False)
            assert got["9999.HK"] == "금속 가공", f"{mkt} 경로에서 미번역"

        # ⚠️ 위는 네이버 맵이 **통째로 빈** 경우다. 실제로 영문이 새던 곳은
        # 맵이 일부만 덮고 **나머지를 yfinance 로 채우는 분기**다 — 그쪽을
        # 따로 태운다(빈 맵만 시험하면 이 fix 를 지워도 통과한다).
        monkeypatch.setattr(nrc, "world_industry_map",
                            lambda m: {"0001.HK": "해운", "000001.SZ": "해운"})
        for mkt, covered, missing in (("HK", "0001.HK", "9999.HK"),
                                      ("CN_A", "000001.SZ", "999999.SZ")):
            got = fvc._industries_for([covered, missing], mkt, allow_slow=False)
            assert got[covered] == "해운"
            assert got[missing] == "금속 가공", f"{mkt} 폴백분 미번역"

    def test_liquidity_board_units_match_freds_native_units(self):
        """⚠️ TGA 가 화면에 **$963.95T**(실제 $963.95B, 1000배)로 떠 있었다
        — FRED `WTREGEN` 은 백만$ 인데 카탈로그가 십억$ 로 잡고 있었다
        (사용자 2026-08-19 유동성 대시보드 점검에서 발각). 표기값만 틀린 게
        아니라 **순유동성 = WALCL − TGA − RRP** 도 TGA 를 1000배로 빼고
        있었다. 단위는 눈으로 지키는 게 아니라 표로 못 박는다."""
        from bot.fred_boards_catalog import LIQ_SERIES
        # FRED 가 문서화한 원시 단위(경험적 확인은 VM 프로브의 상식범위 검사).
        native = {
            "M2SL": "B USD", "M1SL": "B USD", "RMFSL": "B USD",
            # ⚠️ WRESBAL·BOGMBASE 는 내가 이 표에 **틀리게 적었고** VM
            # 프로브의 상식범위 검사가 잡아냈다(2026-08-19): WRESBAL 원시
            # 2,944,060 을 십억$ 로 보면 $2.9경, BOGMBASE 5,490 을 백만$ 로
            # 보면 $5.49B — 둘 다 불가능한 값이다. 기억이 아니라 실측이 기준.
            "WALCL": "M USD", "WTREGEN": "M USD", "WRESBAL": "M USD",
            "WLCFLPCL": "M USD", "RRPONTSYD": "B USD", "BOGMBASE": "B USD",
            "JPNASSETS": "100M JPY", "ECBASSETSW": "M EUR",
            "TOTBKCR": "B USD", "BUSLOANS": "B USD", "COMPOUT": "B USD",
            "DPSACBW027SBOG": "B USD", "TRESEGCNM052N": "M USD",
            "FDHBFIN": "B USD",
        }
        got = {s["id"]: s.get("unit") for s in LIQ_SERIES}
        bad = {k: (got.get(k), v) for k, v in native.items()
               if got.get(k) != v}
        bad.pop("FDHBFIN", None)   # 2026-08-20 카탈로그에서 제거된 시리즈
        assert not bad, f"단위 불일치(카탈로그, FRED): {bad}"

    def test_net_liquidity_converts_tga_from_millions(self):
        """순유동성은 세 시리즈의 **단위가 제각각**이다(WALCL 백만$ ·
        TGA 백만$ · RRP 십억$). 하나만 안 맞춰도 조 단위로 어긋난다."""
        from bot.fred_boards import net_liquidity
        out = net_liquidity([("2026-08-13", 6_760_000.0)],      # 6.76조$
                            [("2026-08-13", 963_950.0)],        # 963.95십억$
                            [("2026-08-13", 0.155)])            # 0.155십억$
        assert len(out) == 1
        # 6760 − 964 − 0.155 ≈ 5795.9 (십억$)
        assert abs(out[0][1] - 5795.895) < 0.5, out

