# 2026-08-19 vol_probe v5 — MOVE 의 진짜 원인이 확정됐다.
#   · 캐럿 없는 `MOVE` = **Corvex, Inc. (EQUITY, $9.80)** — 사다리의 대역
#     관문이 실제로 폐기했다(그대로 썼으면 채권 변동성 자리에 주가 9.80).
#   · `^MOVE` 는 살아 있다(INDEX · regularMarketPrice 74.98 · 08-18 마감)
#     — 다만 야후가 **차트를 1봉만** 준다. 우리 차트 경로는 "선을 그으려면
#     2점" 이라 1봉을 버려서 0행이 됐다. 지수 카드는 차트가 아니라 값이
#     필요하므로 시세 메타에서 한 점을 건진다.
#   · 한 점으로는 창(전일·1주·1달·1년)을 못 만드니 관측을 디스크에 누적한다.
class TestVolQuoteFallbackAndSeries:
    def test_quote_fallback_when_chart_series_empty(self, monkeypatch):
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "fetch_index_history", lambda tk, **kw: [])
        monkeypatch.setattr(mt, "_index_quote_row",
                            lambda tk: [{"date": "2026-08-18", "close": 74.98}])
        rows, sym = mt.fetch_move_rows()
        assert sym == "^MOVE" and rows[-1]["close"] == 74.98

    def test_quote_fallback_still_obeys_the_band_gate(self, monkeypatch):
        """메타 경로가 관문을 비켜 가는 뒷문이 되면 안 된다."""
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "fetch_index_history", lambda tk, **kw: [])
        monkeypatch.setattr(mt, "_index_quote_row",
                            lambda tk: [{"date": "2026-08-18", "close": 9.80}])
        rows, sym = mt.fetch_move_rows()
        assert rows == [] and sym is None

    def test_quote_row_reads_metadata_price_and_date(self, monkeypatch):
        import sys
        import types
        fake = types.ModuleType("yfinance")

        class _T:
            def __init__(self, tk):
                pass

            history_metadata = {"regularMarketPrice": 74.9787,
                                "regularMarketTime": 1787085030}

        fake.Ticker = _T
        monkeypatch.setitem(sys.modules, "yfinance", fake)
        import bot.market_timing as mt
        assert mt._index_quote_row("^MOVE") == [
            {"date": "2026-08-18", "close": 74.9787}]   # 미 장마감 = UTC 같은 날

    def test_series_accumulates_across_runs(self, monkeypatch, tmp_path):
        """하루 한 점씩만 와도 창이 시간이 지나며 복원되는가."""
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_VOL_CACHE_DIR", tmp_path)
        for d, c in (("2026-08-17", 70.0), ("2026-08-18", 74.98)):
            got = mt._vol_series_merge("move", [{"date": d, "close": c}])
        assert [r["date"] for r in got] == ["2026-08-17", "2026-08-18"]
        assert mt.vol_history(got)["전일"] == 70.0

    def test_series_overwrites_same_date_and_keeps_order(self, monkeypatch,
                                                        tmp_path):
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_VOL_CACHE_DIR", tmp_path)
        mt._vol_series_merge("move", [{"date": "2026-08-18", "close": 70.0}])
        got = mt._vol_series_merge("move", [{"date": "2026-08-18", "close": 74.98},
                                            {"date": "2026-08-14", "close": 68.0}])
        assert got == [{"date": "2026-08-14", "close": 68.0},
                       {"date": "2026-08-18", "close": 74.98}]

    def test_value_comes_from_this_fetch_not_the_accumulation(self, monkeypatch,
                                                              tmp_path):
        """누적분을 값으로 쓰면 원천이 죽은 날 옛 값이 '최신'으로 둔갑한다 —
        값·기준일은 이번에 받은 관측, 창만 누적에서."""
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_VOL_CACHE_DIR", tmp_path)
        mt._vol_series_merge("move", [{"date": "2026-07-17", "close": 60.0},
                                      {"date": "2026-07-16", "close": 59.0}])
        monkeypatch.setattr(mt, "fetch_move_rows",
                            lambda: ([{"date": "2026-08-18", "close": 74.98}],
                                     "^MOVE"))
        monkeypatch.setattr(mt, "_vol_cache_save", lambda *a, **k: None)
        monkeypatch.setattr(mt, "fetch_index_history", lambda *a, **k: [])
        monkeypatch.setattr(mt, "_fetch_vix_naver", lambda: None)
        monkeypatch.setattr(mt, "fetch_vkospi_rows", lambda: [])
        snap = mt.fetch_volatility_snapshot()
        assert snap["move"]["value"] == 74.98
        assert snap["move"]["date"] == "2026-08-18"

    def test_series_never_resurrects_when_this_fetch_is_empty(self, monkeypatch,
                                                              tmp_path):
        """원천이 죽은 날 누적분으로 창을 채우면 화면이 거짓말한다 —
        그 경우는 '저장분' 라벨이 붙는 캐시 경로가 담당한다."""
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_VOL_CACHE_DIR", tmp_path)
        mt._vol_series_merge("move", [{"date": "2026-07-17", "close": 60.0}])
        assert mt._vol_series_merge("move", []) == []

    def test_series_trims_entries_newer_than_this_fetch(self, monkeypatch,
                                                       tmp_path):
        """창의 기준점이 화면의 '현재'보다 미래면 전일·1주가 어긋난다."""
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_VOL_CACHE_DIR", tmp_path)
        mt._vol_series_merge("move", [{"date": "2026-08-18", "close": 74.98}])
        got = mt._vol_series_merge("move", [{"date": "2026-08-14", "close": 68.0}])
        assert [r["date"] for r in got] == ["2026-08-14"], got
    def test_healthy_source_windows_are_untouched_by_accumulation(
            self, monkeypatch, tmp_path):
        """건강한 원천(최장 창을 이미 덮음)은 누적분을 섞지 않는다 —
        섞으면 얻는 것 없이 전일·1주 의 의미만 흔들린다(2026-08-19 VIX
        회귀 실측: 옛 관측이 끼어들어 '전일' 이 다른 값이 됐다)."""
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_VOL_CACHE_DIR", tmp_path)
        mt._vol_series_merge("vix", [{"date": "1990-01-01", "close": 99.0}])
        fresh = [{"date": f"2026-{1 + i // 28:02d}-{1 + i % 28:02d}",
                  "close": float(i)} for i in range(300)]
        got = mt._vol_series_merge("vix", fresh)
        assert got == fresh, "건강한 원천에 누적분이 섞였다"
        # 그래도 저장은 돼 있어야 한다(훗날 무너질 때의 보험).
        assert (tmp_path / "series_vix.json").exists()


# ─────────────────────────────────────────────────────────────────────────
# 2026-08-19 econ_actual_probe v1 실측 — 실제치가 **채워졌는데 틀렸다**:
#   CPI 2026-07-14 발표 ✅ 332.813 (2026-07-01 관측)
#   CPI 2026-08-12 발표 ✅ 332.813 (2026-07-01 관측)   ← 같은 숫자
# 7/14 는 **6월분**을 낸 발표인데, 지금 받은 시계열에서 "발표일 이전 마지막
# 관측"을 고르니 그때는 아직 없던 7월 관측이 붙었다. 시차 창을 지표마다 손으로
# 맞추는 방식은 사람이 규약을 외우는 일이라 매번 틀린다(#24·#27).
# → 원천 vintage(ALFRED `realtime_start=realtime_end=발표일`)를 먼저 묻는다.
#   그 날짜의 FRED 데이터베이스를 그대로 받으므로 추정이 0 이다.
class TestEconActualUsesVintage:
    def test_vintage_is_preferred_over_the_lag_window(self, monkeypatch):
        from bot import econ_calendar as ec
        from bot import fred_client
        monkeypatch.setattr(fred_client, "find_release_id", lambda s: 10)
        monkeypatch.setattr(fred_client, "fetch_release_dates",
                            lambda rid, a, b: ["2026-07-14", "2026-08-12",
                                               "2026-09-10"])
        # 지금 받은 시계열 — 7월 관측이 이미 들어 있다(창 방식이 속는 지점).
        monkeypatch.setattr(fred_client, "fetch_history", lambda sid, start=None:
                            [("2026-05-01", 331.0), ("2026-06-01", 332.0),
                             ("2026-07-01", 332.813)])
        vintages = {"2026-07-14": ("2026-06-01", 332.0),
                    "2026-08-12": ("2026-07-01", 332.813)}
        monkeypatch.setattr(fred_client, "fetch_observation_asof",
                            lambda sid, asof, **kw: vintages.get(asof))
        monkeypatch.setattr(ec, "_load_megatech_earnings", lambda t=None: [])
        data = ec._load_econ_calendar("2026-08-19")
        cpi = next(e for e in data["events"] if e["key"] == "cpi")
        got = {a["release_date"]: a["value"] for a in cpi["actuals"]}
        assert got == {"2026-07-14": 332.0, "2026-08-12": 332.813}, got
        assert len(set(got.values())) == 2, "인접 발표일이 같은 값 = 빈티지 오염"

    def test_falls_back_to_window_when_vintage_unavailable(self, monkeypatch):
        """키부재·API 실패로 vintage 가 없어도 실제치가 사라지면 안 된다."""
        from bot import econ_calendar as ec
        from bot import fred_client
        monkeypatch.setattr(fred_client, "find_release_id", lambda s: 10)
        monkeypatch.setattr(fred_client, "fetch_release_dates",
                            lambda rid, a, b: ["2026-07-14", "2026-08-12"])
        monkeypatch.setattr(fred_client, "fetch_history", lambda sid, start=None:
                            [("2026-06-01", 332.0), ("2026-07-01", 332.813)])
        monkeypatch.setattr(fred_client, "fetch_observation_asof",
                            lambda sid, asof, **kw: None)
        monkeypatch.setattr(ec, "_load_megatech_earnings", lambda t=None: [])
        data = ec._load_econ_calendar("2026-08-19")
        cpi = next(e for e in data["events"] if e["key"] == "cpi")
        assert cpi.get("actuals"), "vintage 실패 시 실제치가 통째로 사라졌다"

    def test_asof_query_pins_both_realtime_bounds(self, monkeypatch, tmp_path):
        """`realtime_start`·`realtime_end` 를 **둘 다** 발표일로 고정해야
        그 시점 데이터베이스가 온다 — 한쪽만 주면 현재값이 섞인다."""
        import bot.fred_client as fc
        seen = {}

        class _R:
            status_code = 200

            def raise_for_status(self):
                pass

            def json(self):
                return {"observations": [{"date": "2026-06-01", "value": "332.0"}]}

        def fake_get(url, **kw):
            seen["url"] = url
            return _R()

        monkeypatch.setattr(fc, "_env_key", lambda k: "dummy")
        monkeypatch.setattr(fc.requests, "get", fake_get)
        # ⚠️ 고정 경로를 쓰면 이 테스트가 **스스로 캐시를 남겨** 두 번째
        # 실행부터 requests 를 안 타고 통과한다(실측). tmp_path 로 격리.
        monkeypatch.setattr(fc, "_CACHE_DIR", tmp_path)
        got = fc.fetch_observation_asof("CPIAUCSL", "2026-07-14")
        assert got == ("2026-06-01", 332.0)
        assert "realtime_start=2026-07-14" in seen["url"], seen["url"]
        assert "realtime_end=2026-07-14" in seen["url"], seen["url"]


# ─────────────────────────────────────────────────────────────────────────
# 2026-08-20 사용자 4개 보드 전수 점검 요청에서 나온 것들.
#
# (1) PPI 105종·CPI 52종·한국 ECOS 행에 **공표규약이 하나도 없었다** — 전부
#     '6개월' 월수 휴리스틱이라, BLS 월간 지표가 넉 달 밀려도 화면은 조용했다.
#     개별 등록은 새 시리즈를 못 잡으므로(#24) **보드 그룹 기본값**으로.
# (2) 지수 기준일이 마지막 거래일보다 뒤처져도 표기가 없었다.
# (3) 테스트가 사용자 **실제 캐시 디렉터리**에 픽스처 값을 쓰고 있었다.
class TestBoardFreshnessGroupCadence:
    def test_every_board_row_is_judgeable(self):
        """어느 보드 행도 '규약 없음'으로 남으면 안 된다 — 판정 못 하는 행이
        가장 위험하다(조용히 낡는다). 시리즈를 열거하지 않고 카탈로그를
        통째로 훑는다."""
        from bot.fred_boards_catalog import CPI_SERIES, LIQ_SERIES, PPI_SERIES
        from bot.macro_cadence import CADENCE, BLS_MONTHLY, judge
        for label, cat, default in (("PPI", PPI_SERIES, BLS_MONTHLY),
                                    ("CPI", CPI_SERIES, BLS_MONTHLY),
                                    ("LIQ", LIQ_SERIES, None)):
            missing = [s["id"] for s in cat
                       if judge(s["id"], "2026-07", default=default) is None]
            assert not missing, (
                f"{label} 보드에 공표규약 없는 시리즈: {missing[:8]}"
                f"{' …' if len(missing) > 8 else ''} — CADENCE 등록 또는 "
                f"보드 그룹 기본값 필요")
        assert "FDHBFIN" not in {s["id"] for s in LIQ_SERIES}, \
            "원천이 ~170일 늦어 화면에 늘 반년+ 옛값이던 행 — 제거 상태 유지"

    def test_kr_rows_carry_their_own_cadence_key(self):
        """ECOS 행은 품목별로 id 가 쪼개져 있어(ECOS:반도체) 규약을 못 찾는다
        — `cadence_id` 로 한 규약을 공유한다."""
        import bot.fred_boards as fb
        from bot.macro_cadence import judge
        for loader, expect, cad in (("_load_kr_ppi", "ECOS:KRPPI",
                                     fb._KR_PPI_CADENCE),
                                    ("_load_kr_cpi", "ECOS:KRCPI",
                                     fb._KR_CPI_CADENCE)):
            src = __import__("inspect").getsource(getattr(fb, loader))
            assert f'"cadence_id": "{expect}"' in src, loader
            assert judge(expect, "2026-07", default=cad) is not None

    def test_kr_ppi_june_is_on_time_in_late_august(self):
        """사용자 2026-08-20 "한국 PPI 는 여전히 6월인데" — 한은은 익월
        하순 공표라 8/20 시점 기대치가 6월이다(정상). 값 자체가 아니라
        **규약이 그렇게 판정하는지**를 고정한다."""
        from datetime import date
        import bot.fred_boards as fb
        from bot.macro_cadence import judge
        t = date(2026, 8, 20)
        assert not judge("ECOS:KRPPI", "2026-06", today=t,
                         default=fb._KR_PPI_CADENCE)["stale"]
        # 한 달 더 밀리면 반드시 걸려야 한다(규약이 무력하지 않다는 증거).
        assert judge("ECOS:KRPPI", "2026-05", today=t,
                     default=fb._KR_PPI_CADENCE)["stale"]

    def test_index_staleness_is_labelled(self, monkeypatch):
        import bot.market_timing as mt
        monkeypatch.setattr(mt, "_expected_session", lambda m: ("2026-08-19", 0))
        assert mt._idx_stale("KR", "2026-08-19") == ""
        out = mt._idx_stale("KR", "2026-08-14")
        assert "거래일 지연" in out and "2026-08-19" in out, out

    def test_expected_session_survives_without_a_holiday_calendar(self,
                                                                 monkeypatch):
        """`exchange_calendars` 가 없어도 판정을 포기하지 않는다 —
        조용히 no-op 되면 화면이 낡아도 아무도 모른다(실수 #12)."""
        import bot.market_calendar as mc
        import bot.market_timing as mt
        monkeypatch.setattr(mc, "is_trading_day", lambda *a, **k: None)
        monkeypatch.setattr(mc, "add_trading_days", lambda *a, **k: None)
        exp, grace = mt._expected_session("KR")
        assert exp and grace >= 1, (exp, grace)

    def test_tests_do_not_write_into_the_real_vol_cache(self):
        """conftest 의 autouse 격리가 살아 있는가 — 이게 꺼지면 VM 에서
        `make test` 가 운영 last-good 캐시에 픽스처 값을 덮어쓴다."""
        from pathlib import Path
        import bot.market_timing as mt
        assert Path.home() not in Path(mt._VOL_CACHE_DIR).parents, \
            f"테스트가 실제 캐시를 가리키고 있다: {mt._VOL_CACHE_DIR}"
    def test_audit_reads_the_key_names_the_client_actually_uses(self):
        """board_audit v1 이 `ECOS_API_KEY` 로 물어 **있는 키를 '없음'** 으로
        오보했다(실제 이름은 `BOK_ECOS_API_KEY`) — 실수 #23 의 재발.
        키 이름을 손으로 적지 말고 클라이언트 소스에서 뽑아 쓴다."""
        import re
        src = open("bot/scripts/board_audit.py", encoding="utf-8").read()
        assert '"ECOS_API_KEY"' not in src, "틀린 키 이름이 되살아났다"
        assert "bok_ecos_client.py" in src, "키 이름을 다시 손으로 적고 있다"
        client = open("bot/bok_ecos_client.py", encoding="utf-8").read()
        found = set(re.findall(r'_env_key\("([A-Z0-9_]+)"\)', client))
        assert "BOK_ECOS_API_KEY" in found, (
            "클라이언트의 키 이름이 바뀌었다 — 프로브 추출 정규식도 확인할 것")

    def test_dead_fred_series_is_out_of_the_catalog(self):
        """`CUSR0000SETE`(자동차보험 CPI)는 FRED 가 400 을 준다 — 매 사이클
        실패 로그를 남기고 제외되던 죽은 시리즈(2026-08-20 감사에서 발각)."""
        from bot.fred_boards_catalog import CPI_SERIES
        assert "CUSR0000SETE" not in {s["id"] for s in CPI_SERIES}


# ─────────────────────────────────────────────────────────────────────────
# 2026-08-20 사용자(Neosem 동종비교 캡처): "여기 동종업계비교에 억지로 없는거
# 계산해서 넣지마. ＊표시된거. 더 이상해져."
#
# 화면 실물: SK하이닉스 PER 6.6＊ · 삼성전자 10.8＊ 는 우리가 시총÷순이익으로
# 만든 값이고, TSMC 27.5 · AMD 119.0 은 소스값이었다 — **같은 PER 열의 숫자가
# 서로 다른 정의**였다. ＊ 로 구분 표시를 해도 사람 눈은 열을 세로로 읽는다.
# 비교표는 소스값만 싣고, 없으면 빈칸으로 둔다.
#
# ⚠️ 단일 회사 화면(종합·밸류에이션 탭)의 자체계산은 **유지**한다 — 거기선
# 다른 회사와 나란히 놓이지 않아 기준이 섞이지 않는다.
class TestPeerTableSourceValuesOnly20260820:
    @staticmethod
    def _pane(si):
        """동종비교 pane 만 잘라 온다(기존 peer 테스트와 같은 방식)."""
        from bot.dashboard import _render_stock_info_html
        out = _render_stock_info_html({"ticker": si.get("ticker", "AAA"),
                                       "stock_info": si})
        seg = out["other_panes"]
        i = seg.index('id="si-peers"')
        return seg[i:seg.index("</div>\n</div>", i) + 13]

    def test_collector_no_longer_derives_peer_multiples(self):
        """되살리기 쉬운 자리라 **부재 자체**를 고정한다 — 헬퍼가 다시
        생기면(또는 배선이 돌아오면) 이 테스트가 막는다."""
        import bot.stock_snapshot as ss
        for gone in ("_derive_peer_multiples", "_dart_peer_multiples"):
            assert not hasattr(ss, gone), (
                f"{gone} 가 되살아났다 — 비교표 자체계산은 사용자 지시로 제거됨")
        src = __import__("inspect").getsource(ss.collect_stock_snapshot)
        assert "derived_basis" not in src, "수집기가 다시 파생값을 싣는다"

    def test_archived_derived_cells_render_blank(self):
        """이미 쌓인 분석엔 `derived` 가 남아 있다 — 재수집 없이 렌더가
        빈칸으로 내린다(실수 #18 의 반대 방향: 아카이브가 굳지 않게)."""
        si = {"ticker": "253590.KQ", "peer_comps": [
            {"ticker": "000660.KS", "name": "SK hynix", "currency": "KRW",
             "market_cap": 1.06e15, "trailingPE": 6.6, "priceToBook": 4.1,
             "priceToSalesTrailing12Months": 5.6, "enterpriseToEbitda": 6.9,
             "derived": ["PBR", "PER"],
             "derived_basis": {"PER": "DART 2025 TTM", "PBR": "DART 자본총계"}},
            {"ticker": "2330.TW", "name": "TSMC", "currency": "TWD",
             "market_cap": 6.09e13, "trailingPE": 27.5, "priceToBook": 9.5,
             "priceToSalesTrailing12Months": 13.7, "enterpriseToEbitda": 18.5},
        ]}
        pane = self._pane(si)
        assert "＊" not in pane, "자체계산 표식이 아직 찍힌다"
        assert "6.6" not in pane, "자체계산 PER 이 그대로 표시된다"
        assert "4.1" not in pane, "자체계산 PBR 이 그대로 표시된다"
        # 같은 행의 **소스값**은 살아 있어야 한다(과잉 삭제 금지).
        assert "5.6" in pane and "6.9" in pane, "소스값까지 지워졌다"
        assert "27.5" in pane and "9.5" in pane, "다른 회사 소스값이 지워졌다"

    def test_legend_explains_the_blank_instead_of_a_star(self):
        si = {"ticker": "A", "peer_comps": [
            {"ticker": "000660.KS", "name": "SK hynix", "currency": "KRW",
             "market_cap": 1e14, "trailingPE": 6.6, "derived": ["PER"]}]}
        pane = self._pane(si)
        assert "자체계산" not in pane or "넣지" in pane or "비워" in pane
        assert "소스가 그 회사 값을 주지" in pane, pane[-600:]

    def test_subject_row_is_not_backfilled_with_page_derived_values(self):
        """주체 행도 예외가 아니다 — 밸류에이션 탭의 자체계산을 비교표로
        옮기면 같은 문제가 그대로 재현된다(캡처의 Neosem 29.1＊·3.5＊)."""
        si = {"ticker": "253590.KQ", "trailingPE": 29.1, "priceToBook": 3.5,
              "priceToSalesTrailing12Months": 7.4,
              "_derived_multiples": ["trailingPE", "priceToBook"],
              "_derived_basis": {"trailingPE": "DART TTM"},
              "peer_comps": [
                  {"ticker": "253590.KQ", "name": "Neosem", "currency": "KRW",
                   "market_cap": 4.725e11, "is_subject": True,
                   "priceToSalesTrailing12Months": 7.4}]}
        pane = self._pane(si)
        assert "29.1" not in pane, "밸류에이션 탭의 자체계산 PER 이 비교표로 샜다"
        assert "3.5" not in pane, "자체계산 PBR 이 비교표로 샜다"
        assert "7.4" in pane, "주체 행의 소스값(PSR)까지 사라졌다"

    def test_subject_row_still_takes_source_values_from_the_page(self):
        """반대 방향 과잉 금지 — si 의 **소스값**은 계속 채워야 한다."""
        si = {"ticker": "AAA", "trailingPE": 12.0, "_derived_multiples": [],
              "peer_comps": [{"ticker": "AAA", "name": "A", "currency": "USD",
                              "market_cap": 1e10, "is_subject": True}]}
        assert "12.0" in self._pane(si)


# ─────────────────────────────────────────────────────────────────────────
# 2026-08-20 사용자: "제대로 돌아가는지 정말 못믿겠어. … 모두 하나씩 꼼꼼히
# 제대로 업데이트되고 제대로 가져오는지 검증해줘."
#
# 신선도 감사(board_audit)만으로는 못 잡는 두 부류가 실제로 나왔다.
#
# ① **검산 실패** — 관심종목의 `예상 PER` 이 옆 칸의 `현재가 ÷ 예상 EPS` 와
#    안 맞았다. 세 칸이 서로 다른 출처였기 때문:
#      현재가 = 네이버 실시간(KR) · 예상 EPS = forwardEps→trailingEps→
#      calendar 컨센서스 · 예상 PER = yfinance forwardPE(자기 EPS·자기 가격)
#    미국 종목은 우연히 맞아 눈에 안 보였고(SKHY 157.01÷32.14=4.9 ✓) 국내만
#    틀렸다(삼성전자 247,500÷14,227=17.4 인데 화면 3.7 · 쿠콘 10.7 인데 8.9).
# ② **교차 불일치** — 'PPI' 가 글로벌 스냅샷은 PPIACO(8.27%), 매크로 스냅샷은
#    PPIFIS(4.84%). 둘 다 맞는 값인데 이름이 같아 한쪽이 틀린 것처럼 보였다.
# ③ **어림 라벨** — 매크로 카드의 "12개월 전"은 창이 *최근 12개 관측*이라
#    실제론 11개월 전이다. 사용자가 YoY 로 검산하면 안 맞는다(#29 와 같은 병).
class TestSurfaceArithmeticAndCrossConsistency20260820:
    def test_watchlist_per_is_derivable_from_the_two_cells_beside_it(self):
        from bot.market_favorites import _per_from_shown
        # 캡처 실측값 — 미국은 원래 맞았고 국내가 틀렸다.
        for px, eps, want in ((157.01, 32.14, 4.9), (53.8, 3.34, 16.1),
                              (119.49, 5.14, 23.2), (11.05, 1.67, 6.6),
                              (20600, 1921, 10.7), (247500, 14227.34, 17.4)):
            got = _per_from_shown(px, eps)
            assert got is not None and round(got, 1) == want, (px, eps, got)

    def test_watchlist_per_is_blank_when_eps_is_missing(self):
        """'EPS 는 —인데 PER 은 6.2' 같은 설명 불가능한 행을 만들지 않는다."""
        from bot.market_favorites import _per_from_shown
        for px, eps in ((24650, None), (None, 5.0), (100, 0), (0, 5.0)):
            assert _per_from_shown(px, eps) is None, (px, eps)

    def test_watchlist_never_stores_the_sources_own_pe(self):
        """소스 PER 을 그대로 싣는 배선이 되살아나면 다시 어긋난다."""
        import inspect
        import bot.market_favorites as mf
        src = inspect.getsource(mf)
        for bad in ('f["per"] = fwd_pe', 'per_val = info.get("forwardPE")',
                    '"per": per_val'):
            assert bad not in src, f"소스 PER 배선이 되살아났다: {bad}"
        assert '_per_from_shown(f.get("current_price")' in src, "검산 배선 없음"

    def test_per_is_computed_after_the_calendar_may_replace_eps(self):
        """PER 을 EPS 확정 **전에** 만들면 이 버그의 원래 형태가 재현된다 —
        calendar 블록이 eps_estimate 를 컨센서스로 갈아끼우기 때문."""
        import re
        src = open("bot/market_favorites.py", encoding="utf-8").read()
        # ⚠️ 모듈 전체에서 찾으면 `add_favorite` 의 calendar 블록이 먼저
        # 걸려 순서가 뒤바뀐 뮤테이션도 통과한다(실측) — **갱신 함수 본문**
        # 으로 좁힌다.
        m = re.search(r"\n    def _refresh\(f: dict\) -> None:.*?"
                      r"(?=\n    with ThreadPoolExecutor)", src, re.S)
        assert m, "_refresh 본문을 못 찾았다 — 배선 확인"
        blk = m.group(0)
        i_cal = blk.index('cal.get("Earnings Average")')
        i_per = blk.index('f["per"] = _per_from_shown(')
        assert i_per > i_cal, "PER 계산이 EPS 확정(calendar 갈아끼우기)보다 앞선다"

    def test_two_screens_do_not_call_different_series_the_same_name(self):
        """PPI 처럼 다른 시리즈를 같은 이름으로 부르면 사용자는 둘 중 하나가
        틀렸다고 읽는다 — 라벨에 기준이 들어가야 한다."""
        import re
        mo = open("bot/market_overview.py", encoding="utf-8").read()
        ms = open("bot/macro_snapshot.py", encoding="utf-8").read()
        mo_ids = {lbl: sid for lbl, sid in re.findall(
            r'\("([^"]*(?:PPI|CPI|PCE)[^"]*)",\s*"([A-Z0-9]+)"', mo)
            if not re.fullmatch(r"[A-Z0-9]+", lbl)}
        ms_ids = {sid: lbl for lbl, sid in re.findall(
            r'\("[a-z_]+",\s*"([^"]+)",\s*"[^"]*",\s*"fred",\s*"([A-Z0-9]+)"', ms)}

        def topic(l):
            return next((t for t in ("PPI", "CPI", "PCE") if t in l.upper()), "")

        def qual(l, t):
            return re.sub(r"[\s()]+", "",
                          re.sub(r"\(YoY\)|미국|글로벌|US\b", "", l).replace(t, ""))

        for lbl, sid in mo_ids.items():
            if sid in ms_ids:
                continue
            t = topic(lbl)
            for rs, rl in ms_ids.items():
                if rs == sid or topic(rl) != t:
                    continue
                assert qual(lbl, t) and qual(rl, t), (
                    f"'{lbl}'({sid}) 와 '{rl}'({rs}) 가 같은 이름·다른 시리즈")

    def test_macro_card_period_label_carries_a_real_date(self):
        """"12개월 전"은 어림이다 — 창이 최근 N개 관측이라 실제론 N−1개월 전.
        실제 관측 기간을 실어 사용자가 검산할 수 있어야 한다."""
        import inspect
        import bot.macro_snapshot as ms
        assert "period_start_asof" in inspect.getsource(ms), "실제 기간 미전달"
        dash = open("bot/dashboard.py", encoding="utf-8").read()
        assert "period_start_asof" in dash, "렌더가 실제 기간을 안 쓴다"
        i = dash.index('_ps_asof = str(ind.get("period_start_asof")')
        blk = dash[i:i + 400]
        assert "대비" in blk and "f'{span} 전'" in blk, \
            "날짜가 있으면 날짜로, 없을 때만 어림 라벨이어야 한다"


# ─────────────────────────────────────────────────────────────────────────
# 2026-08-20 (2차) 사용자 전수 검증 요청에서 나온 것들. 앞선 감사가 전부 ✅
# 였는데도 화면이 틀렸던 이유가 또 나왔다 — **판정 기준 자체가 관대**했거나,
# 라벨이 계산과 무관했다.
class TestSecondSweep20260820:
    # ── ① 지수 신선도 재질의가 3년 요청에서만 걸리던 것 ────────────────
    def test_index_retry_fires_on_a_one_year_request_too(self, monkeypatch):
        """사용자: "한국일본 이미 장종료 6시간 지났을텐데 KR KOSPI 같은건
        금일 기준도 아니야." 재질의가 `period == "3y"` 에서만 걸려 있었는데
        시장타이밍은 days=120(=1년)이라 **한 번도 안 탔다**."""
        from datetime import timedelta
        import bot.chart_data as cd
        import bot.market_timing as mt
        today = mt._kst_now().date()

        def payload(n, end):
            ts = [(end - timedelta(days=i)).isoformat() for i in range(n)][::-1]
            return {"times": ts, "close": [100.0 + i for i in range(n)]}

        seen = []

        def fake(ticker, interval="1d", period="1y", prefer_period=False):
            seen.append((period, prefer_period))
            if prefer_period:
                return payload(120, today - timedelta(days=1))   # 신선
            return payload(120, today - timedelta(days=2))       # 하루 뒤처짐

        # `fetch_index_history` 는 함수 안에서 import 하므로 원본 모듈만 패치.
        monkeypatch.setattr(cd, "fetch_chart_payload", fake)
        out = mt.fetch_index_history("^KS11", days=120)
        assert len(seen) > 1, f"1년 요청에서 재질의가 안 걸렸다: {seen}"
        assert out[-1]["date"] == (today - timedelta(days=1)).isoformat()

    def test_volatility_tickers_keep_the_looser_gate(self):
        """^VIX·^MOVE 는 원천이 성겨 매번 재질의하면 야후 호출만 두 배 된다."""
        import bot.market_timing as mt
        assert mt._idx_stale_days("^KS11") == mt._IDX_RETRY_STALE_DAYS == 1
        assert mt._idx_stale_days("^MOVE") == mt._VOL_STALE_DAYS > 1

    # ── ② 유동성 보드 표기 ──────────────────────────────────────────
    def test_ratio_series_are_not_rendered_as_percent(self):
        """통화유통속도가 "1.41%" 로 떴다 — 유통속도는 배수지 퍼센트가 아니다.
        `is_rate` 가 지수·비율 계열에도 켜져 있어서 생긴 오표기."""
        from bot import fred_boards as fb
        js = fb._BOARD_JS_COMMON + open("bot/fred_boards.py", encoding="utf-8").read()
        assert "if(u==='Ratio')return v.toFixed(2);" in js, "Ratio 분기 없음"
        assert "if(r.is_rate&&(!u||u==='%'))" in js, \
            "is_rate 가 단위와 무관하게 %를 붙인다"
        # 카탈로그에 Ratio·is_rate 조합이 실재해야 이 가드가 의미 있다.
        from bot.fred_boards_catalog import LIQ_SERIES
        assert any(s.get("unit") == "Ratio" and s.get("is_rate")
                   for s in LIQ_SERIES)

    def test_windows_shorter_than_the_series_period_are_blank(self):
        """분기 시리즈의 '1M' 은 사실 직전 **분기** 비교라 "+0.00%" 가
        '변화 없음'처럼 보였다 — 계산 불가한 창은 빈칸이 낫다.
        카탈로그 플래그가 아니라 **관측 간격 실측**으로 판정한다(#24)."""
        from bot.fred_boards import _median_month_gap, series_metrics
        monthly = [(f"2025-{m:02d}-01", 100.0 + m) for m in range(1, 13)] + \
                  [(f"2026-{m:02d}-01", 112.0 + m) for m in range(1, 8)]
        quarterly = sorted(
            [(f"{y}-{m:02d}-01", 1.30 + i * 0.01)
             for i, (y, m) in enumerate([(2024, 1), (2024, 4), (2024, 7),
                                         (2024, 10), (2025, 1), (2025, 4),
                                         (2025, 7), (2025, 10), (2026, 1),
                                         (2026, 4)])])
        assert _median_month_gap(monthly) == 1
        assert _median_month_gap(quarterly) == 3
        mm, qm = series_metrics(monthly), series_metrics(quarterly)
        assert mm["mom"] is not None and mm["m3"] is not None
        assert qm["mom"] is None, "분기 시리즈에 1M 이 숫자로 남았다"
        assert qm["m3"] is not None and qm["yoy"] is not None, "과잉 삭제"

