class TestDartCellWbr20260821:
    """긴 셀의 줄바꿈 힌트 — 사용자 2026-08-21 라온피플 "화면에서만 줄 바꿈".

    DART 26.2Q 원문(접수번호 20260814002571)이 `AI비전솔루션생성형AI,
    Platform` 으로 **공백 없이** 붙어 있어 브라우저가 접을 자리를 못 찾는다.
    글자를 넣으면 원문 왜곡이므로 `<wbr>`(zero-width) 만 끼운다."""

    def _sanitize(self, inner):
        from bot.dart_production import sanitize_table
        return sanitize_table(
            "<TABLE><TR><TD>품목</TD><TD>매출액</TD></TR>"
            f"<TR><TD>{inner}</TD><TD ALIGN=RIGHT>2,663</TD></TR></TABLE>")

    def test_hangul_latin_boundary_gets_a_break_hint(self):
        h = self._sanitize("AI비전솔루션생성형AI, Platform")
        assert "AI<wbr>비전솔루션생성형<wbr>AI, Platform" in h, h

    def test_text_is_unchanged_when_tags_are_stripped(self):
        """`<wbr>` 는 표시용이다 — 텍스트가 한 글자라도 바뀌면 안 된다."""
        import re
        h = self._sanitize("AI비전솔루션생성형AI, Platform")
        plain = re.sub(r"<[^>]*>", "", h)
        assert "AI비전솔루션생성형AI, Platform" in plain, plain
        assert "wbr" not in plain

    def test_short_cells_are_left_alone(self):
        """짧은 셀은 접힐 일이 없다 — 마크업만 지저분해진다."""
        h = self._sanitize("라면A")
        assert "<wbr>" not in h, h

    def test_break_hint_survives_the_original_line_structure(self):
        """#94 로 살린 원본 `<br>` 를 그대로 두고 텍스트에만 넣는다."""
        h = self._sanitize(
            "반도체검사장비2종<BR>Monitoring Burn-In Tester 등 장비")
        assert h.count("<br>") == 1
        assert "반도체검사장비<wbr>2<wbr>종<br>Monitoring" in h, h

    def test_tags_are_never_touched(self):
        """태그 **밖의 텍스트에만** 넣는다 — 속성값에 끼면 표가 깨진다.
        (셀 속성은 지금 `class` 뿐이지만, 경계 판정을 마크업 전체에
        걸면 언제든 속성값을 물어뜯는다.)"""
        from bot.dart_production import _add_wbr
        src = ('<table><tr><td class="lft"><span data-x="검사2종">'
               '반도체검사장비2종 및 관련 부품 일체</span></td></tr></table>')
        out = _add_wbr(src)
        assert 'data-x="검사2종"' in out, out
        assert "반도체검사장비<wbr>2<wbr>종 및" in out, out

    def test_probe_dump_strips_the_break_hints(self):
        """프로브 덤프는 셀 경계를 `|` 로 찍는다 — `<wbr>` 를 남기면 원문에
        없는 칸이 있는 것처럼 보인다(#35 프로브는 화면이 쓰는 그 값을 본다)."""
        import ast
        src = open("bot/scripts/production_format_probe.py",
                   encoding="utf-8").read()
        tree = ast.parse(src)
        for node in ast.walk(tree):     # 독스트링은 검사에서 뺀다(#59b)
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef,
                                 ast.ClassDef, ast.Module)):
                if (node.body and isinstance(node.body[0], ast.Expr)
                        and isinstance(node.body[0].value, ast.Constant)
                        and isinstance(node.body[0].value.value, str)):
                    node.body[0].value.value = ""
        code = ast.unparse(tree)
        assert "wbr" in code, "덤프가 줄바꿈 힌트를 안 걷어낸다"


class TestChartEventsBudget20260821:
    """공시 마커는 **장식**이다 — 차트를 붙잡으면 안 된다.

    2026-08-21 실측: `/api/chart` 385초 중 `indicators` 가 380.451초인데 순수
    계산은 250봉에 0.02초였다 — 전부 `fetch_disclosure_events` 의 바깥 원천
    I/O. 차트 payload 캐시는 5분이라 5분마다 그 값을 다시 물었다."""

    def _iso(self, tmp_path, monkeypatch):
        import pathlib
        import bot.finviz_client as fv
        monkeypatch.setattr(fv, "_CACHE_DIR", pathlib.Path(tmp_path))

    def test_budget_returns_without_markers_and_warms_the_cache(
            self, tmp_path, monkeypatch):
        """⚠️ 시간이 아니라 **신호**로 잰다 — sleep 으로 쓰면 부하가 걸린
        전체 실행에서 흔들린다(실측: 단독 green, 전체 실행 red)."""
        import threading
        import bot.chart_events as ce
        self._iso(tmp_path, monkeypatch)
        entered, release, wrote = (threading.Event(), threading.Event(),
                                   threading.Event())

        def slow(ticker, limit=250, days=400):
            entered.set()
            release.wait(10)
            return [{"time": "2026-08-01", "title": "수주", "type": "order"}]
        monkeypatch.setattr(ce, "_fetch_events", slow)
        monkeypatch.setattr(ce, "_EV_BUDGET", 0.15)
        # ⚠️ 캐시 헬퍼는 호출 **시작 시점**에 묶인다 — 먼저 감싸 둔다
        import bot.finviz_client as fv
        orig = fv._cache_write

        def spy(name, obj):
            orig(name, obj)
            wrote.set()
        monkeypatch.setattr(fv, "_cache_write", spy)
        assert ce.fetch_disclosure_events("005930.KS", days=90) == [], \
            "원천이 안 끝났는데 기다렸다(예산 미준수)"
        assert entered.wait(5), "백그라운드가 시작조차 안 했다"
        release.set()
        assert wrote.wait(5), "백그라운드가 캐시를 안 썼다"
        got = ce.fetch_disclosure_events("005930.KS", days=90)
        assert len(got) == 1, got

    def test_one_cache_key_per_ticker_regardless_of_chart_range(
            self, tmp_path, monkeypatch):
        """차트 기간마다 창이 달라지면 캐시 키가 쪼개져 거의 안 맞는다(#61).
        비용은 창 길이가 아니라 페이지 수가 정하므로 창은 고정해도 같다."""
        import bot.chart_events as ce
        self._iso(tmp_path, monkeypatch)
        calls = []
        monkeypatch.setattr(ce, "_fetch_events",
                            lambda t, limit=250, days=400: (
                                calls.append(days),
                                [{"time": "2026-08-01", "title": "수주"}])[1])
        for rng in (30, 90, 365, 1095, 4000):
            assert len(ce.fetch_disclosure_events("005930.KS", days=rng)) == 1
        assert calls == [4000], calls

    def test_empty_result_is_only_trusted_briefly(self, tmp_path, monkeypatch):
        """빈 결과는 '원천에 없음'일 수도 **원천 실패**일 수도 있다 —
        길게 믿으면 전산장애 한 번에 12시간 마커가 사라진다."""
        import bot.chart_events as ce
        self._iso(tmp_path, monkeypatch)
        n = []
        monkeypatch.setattr(ce, "_fetch_events",
                            lambda t, limit=250, days=400: (n.append(1), [])[1])
        assert ce.fetch_disclosure_events("005930.KS") == []
        assert ce.fetch_disclosure_events("005930.KS") == []
        assert len(n) == 1, "짧은 창 안에서는 캐시가 막아야 한다"
        monkeypatch.setattr(ce, "_EV_SOFT_TTL", 0)      # 짧은 창이 지난 뒤
        assert ce.fetch_disclosure_events("005930.KS") == []
        assert len(n) == 2, "빈 결과를 영원히 믿고 있다"

    def test_fixed_window_matches_what_each_client_is_asked_for(
            self, monkeypatch):
        """`_days_for` 는 `_fetch_events` 의 시장별 캡과 **같은 값**이어야
        한다(멱등) — 아니면 캐시 키의 창과 실제 조회창이 갈린다."""
        import types
        import bot.chart_events as ce
        seen = {}

        class _C:
            def get_recent_disclosures(self, t, days_back=0, limit=0):
                seen["d"] = days_back
                return []

        def _mod(**kw):
            return types.SimpleNamespace(**kw)
        monkeypatch.setitem(__import__("sys").modules, "bot.dart_client",
                            _mod(get_dart=lambda: _C()))
        monkeypatch.setitem(__import__("sys").modules, "bot.dart_detail",
                            _mod(get_disclosure_summaries=lambda *a, **k: {}))
        monkeypatch.setitem(__import__("sys").modules, "bot.edinet_client",
                            _mod(get_edinet=lambda: _C()))
        monkeypatch.setitem(__import__("sys").modules, "bot.mops_client",
                            _mod(get_mops=lambda: _C()))
        monkeypatch.setitem(__import__("sys").modules, "bot.akshare_client",
                            _mod(get_akshare=lambda: _C()))
        monkeypatch.setitem(
            __import__("sys").modules, "bot.edgar_client",
            _mod(get_recent_8k=lambda t, days=0, top_n=0: (
                seen.__setitem__("d", days), [])[1]))
        from bot.market import detect_market
        for tkr in ("005930.KS", "AAPL", "7203.T", "2330.TW", "600519.SS"):
            seen.clear()
            mkt = detect_market(tkr)
            want = ce._days_for(mkt)
            ce._fetch_events(tkr, limit=250, days=want)
            assert seen.get("d") == want, (tkr, mkt, want, seen)

    def test_chart_guide_explains_the_budget(self):
        """동작이 바뀌면 설명도 정확히(out-of-sync = 버그) — 첫 조회에서
        마커가 비어 보일 수 있다는 걸 화면이 말해야 한다."""
        from bot.dashboard import _render_chart_section
        html = _render_chart_section({
            "ticker": "005930.KS",
            "price_chart": {"times": ["2026-08-20"], "close": [70000.0]}})
        i = html.find("공시 마커 (날짜별")
        assert i > 0, "차트 가이드에 공시 마커 섹션이 없다"
        seg = html[i:i + 2500]                  # 그 섹션만 본다(#55)
        assert "차트를 붙잡지 않습니다" in seg, seg[:400]
        assert "백그라운드로 받아" in seg, seg[:400]


class TestProbeAlignSummary20260821:
    """프로브가 **화면의 정렬 판정을 되읽어** 말해 준다 — 스크린샷 왕복 대신.

    사용자가 세 번 지적한 증상(#78 셀→표 · #97 표→열 · #115 rowspan 열번호)은
    전부 '한 열 안에서 정렬이 갈림'이다. 감사가 그걸 직접 세면 다음 라운드가
    없다(#114 감사는 무엇을 보고 말하는지 밝힐 것)."""

    _MK = ("<TABLE>"
           "<TR><TD ROWSPAN=2>사업부문</TD><TD>품 목</TD><TD>매출액</TD></TR>"
           "<TR><TD>전력기기, 전력시스템, 배전반, 변압기, 신재생에너지 등</TD>"
           "<TD ALIGN=RIGHT>3,273,963</TD></TR>"
           "<TR><TD>자동화</TD><TD>PLC, 인버터, 자동화시스템, 빌딩자동화 등</TD>"
           "<TD>283,183</TD></TR>"
           "<TR><TD COLSPAN=2>연 결 조 정 및 내부거래 제거</TD>"
           "<TD>(1,047,792)</TD></TR></TABLE>")

    def test_reports_one_class_per_column(self):
        from bot.dart_production import sanitize_table
        from bot.scripts.production_format_probe import align_summary
        cols = align_summary(sanitize_table(self._MK))
        assert not any(c["mixed"] for c in cols), cols
        # 판정 단위는 **슬롯**(시작열, span) — 걸친 셀은 자기 슬롯을 갖는다
        slots = {(c["col"], c["span"]): c for c in cols}
        assert set(slots) == {(0, 1), (0, 2), (1, 1), (2, 1)}, sorted(slots)
        assert slots[(1, 1)]["cls"] == "lft", slots[(1, 1)]
        assert slots[(0, 1)]["cls"] == "ctr", slots[(0, 1)]
        assert slots[(2, 1)]["cls"] == "ctr", slots[(2, 1)]
        assert "전력기기" in slots[(1, 1)]["sample"]
        # 걸친 셀이 span==1 슬롯의 성격을 오염시키면 안 된다
        assert slots[(0, 1)]["sample"] == "사업부문", slots[(0, 1)]

    def test_mixed_column_is_flagged(self):
        """열 번호가 밀리면(rowspan 미반영) 같은 열에 두 class 가 섞인다 —
        그때 프로브가 **⚠️ 를 찍어야** 한다. 안 찍으면 감사가 눈이 먼 것."""
        from bot.scripts.production_format_probe import align_summary
        broken = ('<table class="si-table">'
                  '<tr><td rowspan="2" class="ctr">사업부문</td>'
                  '<td class="lft">품 목</td></tr>'
                  '<tr><td class="ctr">전력기기, 전력시스템 등</td></tr>'
                  '</table>')
        cols = align_summary(broken)
        assert any(c["mixed"] for c in cols), cols

    def test_empty_input_reports_nothing_rather_than_passing(self):
        """대조 대상이 0건이면 '이상 없음'이 아니다(#54) — 호출부가 ❌ 를
        찍을 수 있게 **빈 리스트**로 답한다."""
        from bot.scripts.production_format_probe import align_summary
        assert align_summary("") == []
        assert align_summary("<table></table>") == []


class TestKeyedTiming20260822:
    """계측이 **요청별**이어야 한다 — 사용자가 탭 셋을 열면 세 종목 수집이
    겹치고, 전역 dict 하나면 로그 한 줄이 누구 것인지 알 수 없다.

    2026-08-22 실측 로그에서 302430.KQ · 005880.KS · 294870.KS 세 종목이
    같은 구간에 겹쳐 돌았다. 그 상태로 잰 값으로 병목을 짚으면 **엉뚱한
    곳을 고친다**(#35 감사가 화면과 다른 경로를 보면 거짓 안심/거짓 경보).
    """

    def test_stages_do_not_leak_between_keys(self):
        from bot.timing import Stages
        st = Stages()
        st.start("A")
        st.start("B")
        st.set("A", "yf.history", 1.0)
        st.set("B", "yf.history", 99.0)
        assert st.snapshot("A") == {"yf.history": 1.0}
        assert st.snapshot("B") == {"yf.history": 99.0}
        assert st.snapshot("C") == {}, "안 잰 키가 남의 값을 받는다"

    def test_start_clears_only_its_own_key(self):
        from bot.timing import Stages
        st = Stages()
        st.start("A")
        st.set("A", "x", 1.0)
        st.start("B")
        assert st.snapshot("A") == {"x": 1.0}, "다른 키를 지웠다"
        st.start("A")
        assert st.snapshot("A") == {}, "재시작이 옛 값을 안 지웠다"

    def test_snapshot_is_a_copy(self):
        from bot.timing import Stages
        st = Stages()
        st.start("A")
        st.set("A", "x", 1.0)
        got = st.snapshot("A")
        st.start("A")
        assert got == {"x": 1.0}, "내부 dict 를 그대로 넘겼다"

    def test_old_keys_are_evicted(self):
        """프로세스가 오래 살아도 안 자란다."""
        from bot.timing import Stages
        st = Stages(keep=3)
        for k in "abcde":
            st.start(k)
            st.set(k, "x", 1.0)
        assert st.snapshot("a") == {} and st.snapshot("b") == {}
        assert st.snapshot("e") == {"x": 1.0}

    def test_concurrent_collections_keep_their_own_stages(self):
        """실제 경로로 태운다 — 헬퍼 단위테스트는 배선 변형을 못 잡는다(#20)."""
        import threading
        import bot.stock_snapshot as ss
        ready, go = threading.Event(), threading.Event()

        def work(tk, val):
            ss._TIMING.start(tk)
            ready.set()
            go.wait(5)
            ss._TIMING.set(tk, "yf.info", val)
        t1 = threading.Thread(target=work, args=("AAA", 1.0))
        t2 = threading.Thread(target=work, args=("BBB", 9.0))
        t1.start(); t2.start()
        assert ready.wait(5)
        go.set()
        t1.join(5); t2.join(5)
        assert ss.last_timing("AAA") == {"yf.info": 1.0}
        assert ss.last_timing("BBB") == {"yf.info": 9.0}

    def test_chart_key_is_shared_by_writer_and_reader(self):
        """로그를 찍는 쪽과 재는 쪽이 **같은 문자열**을 써야 한다 — 다르면
        `chart-timing` 이 영원히 안 찍힌다(조용한 실패)."""
        import ast
        import bot.chart_data as cd
        key = cd.timing_key("005930.KS", "1d", "1y")
        cd._TIMING.start(key)
        cd._TIMING.set(key, "total", 1.0)
        assert cd.last_chart_timing(key) == {"total": 1.0}
        # 핸들러가 **읽는 키를 timing_key 로 만드는지** 구조로 본다 —
        # 리터럴을 손으로 적으면 수집기와 갈려 로그가 조용히 사라진다.
        src = open("bot/dashboard_server.py", encoding="utf-8").read()
        reads = [n for n in ast.walk(ast.parse(src))
                 if isinstance(n, ast.Call)
                 and getattr(n.func, "id", "") == "last_chart_timing"]
        assert reads, "핸들러가 계측을 안 읽는다"
        assert all(a.args and isinstance(a.args[0], ast.Call)
                   and getattr(a.args[0].func, "id", "") == "timing_key"
                   for a in reads), "키를 timing_key 로 안 만든다"


class TestColspanOnlyColumn20260822:
    """열 하나가 **전부 colspan** 이면 한 칸도 판정 안 돼 가운데로 굳었다.

    사용자 2026-08-22 IPARK현대산업개발(294870.KS) 실측: `국내/해외` 하위열
    때문에 품목 셀이 전부 `colspan=2` 였고, 긴 품목명이 가운데로 들쭉날쭉했다
    — #97(표→열)에서 고친 바로 그 증상이 축만 바꿔 **네 번째**로 재발한 것.
    판정 단위를 열 번호가 아니라 **슬롯**(시작열, span)으로 바꿔 끝낸다."""

    _MK = ("<TABLE>"
           "<TR><TD ROWSPAN=2 COLSPAN=2>사업부문</TD>"
           "<TD ROWSPAN=2 COLSPAN=2>품 목</TD>"
           "<TD COLSPAN=2>제9기 반기</TD></TR>"
           "<TR><TD>매출액</TD><TD>비율</TD></TR>"
           "<TR><TD ROWSPAN=2>건설</TD><TD>외주주택</TD>"
           "<TD COLSPAN=2>아파트, 주상복합, 오피스텔 등</TD>"
           "<TD>974,030</TD><TD>61.3</TD></TR>"
           "<TR><TD>토목</TD>"
           "<TD COLSPAN=2>도로, 항만, 공단부지 조성,일반철도, 고속철도 등</TD>"
           "<TD>110,557</TD><TD>7.0</TD></TR>"
           "<TR><TD COLSPAN=4>합 계</TD><TD>1,588,584</TD><TD>100.0</TD></TR>"
           "</TABLE>")

    def _slots(self):
        from bot.dart_production import sanitize_table
        from bot.scripts.production_format_probe import align_summary
        return {(c["col"], c["span"]): c
                for c in align_summary(sanitize_table(self._MK))}

    def test_long_colspan_column_is_left_aligned(self):
        s = self._slots()
        assert (2, 2) in s, f"품목 슬롯이 판정에서 빠졌다: {sorted(s)}"
        assert s[(2, 2)]["cls"] == "lft", s[(2, 2)]
        assert not s[(2, 2)]["mixed"], s[(2, 2)]

    def test_short_spanning_labels_stay_centered(self):
        """`합 계`(colspan=4)·`사업부문`(colspan=2) 같은 짧은 라벨은 가운데다
        — 슬롯 판정으로 바꿨다고 전부 좌측이 되면 안 된다."""
        s = self._slots()
        assert s[(0, 4)]["cls"] == "ctr", s[(0, 4)]      # 합 계
        assert s[(0, 2)]["cls"] == "ctr", s[(0, 2)]      # 사업부문
        assert s[(1, 1)]["cls"] == "ctr", s[(1, 1)]      # 외주주택·토목
        assert s[(4, 1)]["cls"] == "ctr", s[(4, 1)]      # 금액

    def test_single_spanning_label_stays_centered(self):
        """칸이 **하나뿐인** 슬롯은 어긋날 상대가 없다 — 소계·합계 라벨은
        길어도 가운데(사용자 승인된 기존 동작이 슬롯 판정에 안 깨지게)."""
        from bot.dart_production import sanitize_table
        from bot.scripts.production_format_probe import align_summary
        mk = ("<TABLE><TR><TD>구분</TD><TD>품 목</TD><TD>매출액</TD></TR>"
              "<TR><TD>반도체</TD><TD>검사장비</TD><TD>226,883</TD></TR>"
              "<TR><TD COLSPAN=2>제품 및 상품 등 소 계(내부거래 조정 전)</TD>"
              "<TD>279,651</TD></TR></TABLE>")
        got = {(c["col"], c["span"]): c["cls"]
               for c in align_summary(sanitize_table(mk))}
        assert got[(0, 2)] == "ctr", got

    def test_numbers_never_become_long_text(self):
        """숫자 칸은 아무리 길어도 '긴 글'이 아니다(자릿수·부호·%)."""
        from bot.dart_production import sanitize_table
        from bot.scripts.production_format_probe import align_summary
        mk = ("<TABLE><TR><TD>구분</TD><TD COLSPAN=2>금액</TD></TR>"
              "<TR><TD>매출</TD>"
              "<TD COLSPAN=2>(1,234,567,890,123,456,789,012)</TD></TR>"
              "</TABLE>")
        got = {(c["col"], c["span"]): c["cls"]
               for c in align_summary(sanitize_table(mk))}
        assert got[(1, 2)] == "ctr", got


class TestTablesParseCache20260822:
    """DART 원문 파싱 결과를 캐시한다 — 2.8M자를 매 요청 다시 훑고 있었다.

    2026-08-22 실측: `/api/quarterly` 213~288초. 이 파싱은 순수 CPU(정규식)라
    GIL 을 붙잡아, 같은 시각 차트의 pandas 계산까지 굶겼다(`ind.basic` 이
    로컬 0.02초 → VM 9.8초, `ind.ichimoku+disparity` 59.7초)."""

    _Q = [{"label": "26.2Q", "reprt_code": "11012", "year": 2026}]

    class _Dart:
        api_key = "k"

    def _stub(self, monkeypatch, calls):
        import sys
        import types
        import bot.dart_production as dp
        monkeypatch.setattr(dp, "_rcept_nos", lambda *a, **k: ["R1"])

        def _fetch(rn, key, max_bytes=0, raw_markup=False):
            calls.append(rn)
            return "<TABLE><TR><TD>x</TD></TR></TABLE>"
        monkeypatch.setitem(
            sys.modules, "bot.dart_feed",
            types.SimpleNamespace(_DOC_TEXT_MAX=1, _DOC_TEXT_MAX_FULL=2,
                                  _fetch_doc_text=_fetch,
                                  doc_was_truncated=lambda *a, **k: False))
        monkeypatch.setattr(dp, "_PARSERS", {
            "products": lambda mk: {"table_html": "<table></table>"}})

    def test_second_call_does_not_reparse(self, monkeypatch):
        import bot.dart_production as dp
        calls = []
        self._stub(monkeypatch, calls)
        a = dp.tables_rolling(self._Dart(), "294870.KS", self._Q)
        b = dp.tables_rolling(self._Dart(), "294870.KS", self._Q)
        assert a == b and a.get("products"), (a, b)
        assert len(calls) == 1, f"원문을 다시 받고 다시 파싱했다: {calls}"

    def test_parser_change_invalidates_the_cache(self, monkeypatch):
        """⚠️ 버전 상수를 손으로 올리는 방식은 이 레포에서 **세 번** 실패했다
        (#18 · #21b · #95). 파서 소스 지문이 키에 들어가야 한다."""
        import bot.dart_production as dp
        k1 = dp._tables_cache_key("A", self._Q, ("products",))
        monkeypatch.setattr(dp, "_PARSE_SIG", "deadbeef")
        k2 = dp._tables_cache_key("A", self._Q, ("products",))
        assert k1 != k2, (k1, k2)

    def test_new_report_gets_a_new_key(self):
        """새 분기가 나오면 옛 결과를 계속 보여주면 안 된다(#18)."""
        import bot.dart_production as dp
        k1 = dp._tables_cache_key("A", [{"label": "26.2Q",
                                         "reprt_code": "11012"}],
                                  ("products",))
        k2 = dp._tables_cache_key("A", [{"label": "26.3Q",
                                         "reprt_code": "11014"}],
                                  ("products",))
        assert k1 != k2, (k1, k2)

    def test_failure_is_not_cached(self, monkeypatch):
        """예외로 끝난 실행을 캐시하면 24시간 동안 빈 표가 굳는다."""
        import sys
        import types
        import bot.dart_production as dp
        monkeypatch.setattr(dp, "_rcept_nos", lambda *a, **k: ["R1"])
        n = []

        def _boom(*a, **k):
            n.append(1)
            raise RuntimeError("원천 장애")
        monkeypatch.setitem(
            sys.modules, "bot.dart_feed",
            types.SimpleNamespace(_DOC_TEXT_MAX=1, _DOC_TEXT_MAX_FULL=2,
                                  _fetch_doc_text=_boom,
                                  doc_was_truncated=lambda *a, **k: False))
        assert dp.tables_rolling(self._Dart(), "ZZZ.KS", self._Q) == {}
        assert dp.tables_rolling(self._Dart(), "ZZZ.KS", self._Q) == {}
        assert len(n) == 2, "실패를 캐시했다"


class TestChartLiteFirst20260822:
    """첫 화면(종합 탭)은 **기본 ON 인 것만** 계산하고 먼저 그린다.

    사용자 2026-08-22: "차트쪽 즉 종합탭은 그래도 다른것보다 빨리 나와야할것
    같아. 우선 첫화면이니까." VM 실측 CCJ: `indicators=73.093s` 중
    `ind.ichimoku+disparity=59.73s` + `ind.events=3.276s` — 전부 화면
    **기본 OFF** 오버레이다. 아무도 안 켠 계산을 기다리고 있었다(#116 의 짝)."""

    def _payload(self, **kw):
        import numpy as np
        import pandas as pd
        import bot.chart_data as cd
        n = 250
        c = pd.Series(
            np.cumsum(np.random.default_rng(1).normal(0, 1, n)) + 100,
            index=pd.date_range("2025-01-01", periods=n, freq="D"))
        return cd._series_payload(c, "KRW", 0, None, c, c * 1.01, c * 0.99,
                                  ticker=None, interval="1d", **kw)

    def test_lite_skips_the_default_off_overlays(self):
        lite = self._payload(lite=True)
        for k in ("ichimoku", "disparity", "elliott", "events"):
            assert k not in lite, f"lite 인데 {k} 를 계산했다"

    def test_lite_keeps_everything_the_first_screen_draws(self):
        """기본 ON 은 캔들·이평선·거래량 — 그건 lite 에도 다 있어야 한다."""
        full, lite = self._payload(), self._payload(lite=True)
        for k in ("times", "close", "open", "high", "low",
                  "ema21", "sma55", "sma200"):
            assert k in lite, f"첫 화면이 그리는 {k} 가 lite 에서 빠졌다"
            assert lite[k] == full[k], k

    def test_full_still_has_them(self):
        """lite 를 넣었다고 본 경로가 비면 오버레이가 영영 안 켜진다."""
        full = self._payload()
        assert "ichimoku" in full and "disparity" in full, sorted(full)

    def test_cache_and_timing_keys_separate_lite(self):
        """lite 는 **다른 payload** 다 — 같은 키에 섞으면 오버레이를 켜도
        TTL 내내 데이터가 없다."""
        import bot.chart_data as cd
        from bot.dashboard_server import chart_cache_name
        assert (chart_cache_name("A", "1d", "1y", True)
                != chart_cache_name("A", "1d", "1y"))
        assert (cd.timing_key("A", "1d", "1y", True)
                != cd.timing_key("A", "1d", "1y"))

    def test_client_asks_lite_first_then_fetches_the_rest(self):
        """배선이 빠지면 서버만 빨라지고 화면은 그대로다(#20)."""
        from bot.dashboard import _CHART_JS
        assert "&lite=1" in _CHART_JS, "첫 요청이 lite 가 아니다"
        # ⚠️ 정의만 보면 **호출을 지우는 변형이 통과한다**(실측) — 정의 1 +
        # 호출 1 이 최소다(#20 배선은 존재가 아니라 호출을 봐야 한다).
        assert _CHART_JS.count("loadRest(") >= 2, "나머지를 받아오는 호출이 없다"
        # 켜져 있는 오버레이가 있으면 합친 뒤 다시 그려야 한다
        assert "if (needsRest()) { render(lastData, true)" in _CHART_JS
        # 아직 안 온 오버레이를 켜면 **왜 비었는지** 말해야 한다(빈 화면 금지)
        assert "보조지표 준비 중" in _CHART_JS

    def test_generated_chart_js_still_parses(self):
        """생성물이 JS 면 **파서에 태운다**(#26 — 파이썬은 JS 문법을 안 본다)."""
        import os
        import shutil
        import subprocess
        import tempfile
        node = shutil.which("node") or shutil.which("nodejs")
        if not node:
            pytest.skip("node 미설치")
        from bot.dashboard import _CHART_JS
        with tempfile.NamedTemporaryFile("w", suffix=".js", encoding="utf-8",
                                         delete=False) as f:
            f.write(_CHART_JS)
            path = f.name
        try:
            r = subprocess.run([node, "--check", path],
                               capture_output=True, text=True)
            assert r.returncode == 0, r.stderr
        finally:
            os.unlink(path)


class TestQuarterlyStagesAndBacklogCache20260822:
    """`/api/quarterly` 115초 중 57초가 `get_or_render` **밖**이었다.

    2026-08-22 실측: `quarterly-timing 200710.KS build_payload=51.542s
    render_png=6.896s total=58.441s` 인데 `api-timing /api/quarterly 115381ms`.
    로그가 그 57초를 이름조차 못 붙였다(#44 '기준 미기록'의 계측판)."""

    def test_handler_stages_are_logged(self):
        """핸들러가 **직접 하는 일**(스냅샷·제품/가동률 표)도 실려야 한다."""
        import ast
        src = open("bot/dashboard_server.py", encoding="utf-8").read()
        names = {n.args[1].value for n in ast.walk(ast.parse(src))
                 if isinstance(n, ast.Call)
                 and getattr(n.func, "attr", "") == "set"
                 and len(n.args) >= 2 and isinstance(n.args[1], ast.Constant)}
        assert {"h.snapshot", "h.production_html"} <= names, sorted(names)

    def test_build_payload_stages_are_measured(self):
        """`build_payload=51.5s` 안에서 시계열인지 수주잔고인지 갈라야 한다."""
        import bot.quarterly_infographic as qi
        _k = qi.timing_key("ZZZ")
        qi._RENDER_TIMING.start(_k)
        for k in ("bp.series", "bp.backlog"):
            qi._RENDER_TIMING.set(_k, k, 1.0)
        assert set(qi.last_render_timing("ZZZ")) == {"bp.series", "bp.backlog"}
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        named = {n.args[1].value for n in ast.walk(ast.parse(src))
                 if isinstance(n, ast.Call)
                 and getattr(n.func, "attr", "") == "set"
                 and len(n.args) >= 2 and isinstance(n.args[1], ast.Constant)}
        assert {"bp.series", "bp.backlog"} <= named, sorted(named)

    # ── 수주잔고 파싱 캐시 (#119 와 같은 규약) ──────────────────────────
    class _Dart:
        api_key = "k"

        def find_periodic_reports(self, *a, **k):
            return [{"rcept_no": "R1"}]

    def _stub(self, monkeypatch, calls, text="수주잔고 없음"):
        import sys
        import types
        monkeypatch.setitem(
            sys.modules, "bot.dart_feed",
            types.SimpleNamespace(
                _DOC_TEXT_MAX_FULL=2,
                _fetch_doc_text=lambda rn, key, max_bytes=0: (
                    calls.append(rn), text)[1]))

    def test_second_call_does_not_refetch(self, monkeypatch):
        import bot.dart_backlog as bl
        calls = []
        self._stub(monkeypatch, calls)
        a = bl.backlog_probe(self._Dart(), "005930.KS", 2026, "11012")
        b = bl.backlog_probe(self._Dart(), "005930.KS", 2026, "11012")
        assert a == b, (a, b)
        assert len(calls) == 1, f"원문을 다시 받아 다시 훑었다: {calls}"

    def test_audit_path_bypasses_the_cache(self, monkeypatch):
        """`out` 을 요구하는 호출(감사·프로브)은 원문 발췌가 필요하다 —
        캐시를 태우면 진단이 낡는다(#35)."""
        import bot.dart_backlog as bl
        calls = []
        self._stub(monkeypatch, calls)
        bl.backlog_probe(self._Dart(), "005930.KS", 2026, "11012")
        out: dict = {}
        bl.backlog_probe(self._Dart(), "005930.KS", 2026, "11012", out=out)
        assert len(calls) == 2, "감사 경로가 캐시를 탔다"

    def test_parser_change_invalidates(self, monkeypatch):
        import bot.dart_backlog as bl
        k1 = bl._bl_key("A", 2026, "11012")
        monkeypatch.setattr(bl, "_BL_SIG", "deadbeef")
        assert bl._bl_key("A", 2026, "11012") != k1

    def test_missing_document_is_not_cached(self, monkeypatch):
        """원문미제공은 원천 장애일 수 있다 — 24시간 믿으면 공시하는 회사가
        하루 종일 빈칸이다(#116 의 짝)."""
        import bot.dart_backlog as bl
        calls = []
        self._stub(monkeypatch, calls, text="")
        bl.backlog_probe(self._Dart(), "005930.KS", 2026, "11012")
        bl.backlog_probe(self._Dart(), "005930.KS", 2026, "11012")
        assert len(calls) == 2, "원문미제공을 캐시했다"


class TestQuarterlyTimingKeyIsPerRequest20260822:
    """티커만으로는 부족했다 — 같은 티커의 **두 실행**이 섞였다.

    2026-08-22 VM 실측 한 줄: `051910.KS render_png=106.249s total=17.528s
    build_payload=17.514s cached=1.0s` — 캐시 히트(total 17.5초)인데 렌더
    106초가 붙어 있다. single-flight 키가 `quarterly:{ticker}:{run}` 이라
    `run` 이 다른 두 요청은 같은 티커로 **동시에** 돈다. #117 에서 단위를
    티커로 잡은 것이 여기서 부족했다 — 키는 **요청**이어야 한다."""

    def test_same_ticker_different_run_do_not_mix(self):
        import bot.quarterly_infographic as qi
        k0, k1 = qi.timing_key("A", False), qi.timing_key("A", True)
        assert k0 != k1, (k0, k1)
        qi._RENDER_TIMING.start(k0)
        qi._RENDER_TIMING.set(k0, "render_png", 106.2)
        qi._RENDER_TIMING.start(k1)
        qi._RENDER_TIMING.set(k1, "cached", 1.0)
        assert qi.last_render_timing("A", False) == {"render_png": 106.2}
        assert qi.last_render_timing("A", True) == {"cached": 1.0}

    def test_handler_reads_the_key_it_wrote(self):
        """찍는 쪽과 재는 쪽이 같은 키 생성 함수를 써야 한다 — 리터럴을
        손으로 적으면 갈려서 로그가 조용히 사라진다(#117)."""
        import ast
        src = open("bot/dashboard_server.py", encoding="utf-8").read()
        reads = [n for n in ast.walk(ast.parse(src))
                 if isinstance(n, ast.Call)
                 and getattr(n.func, "attr", "") == "last_render_timing"]
        assert reads, "핸들러가 분기실적 계측을 안 읽는다"
        assert all(len(r.args) >= 2 for r in reads), \
            "run 을 안 넘겨 다른 실행의 값을 읽는다"

    def test_build_payload_writes_under_the_same_key(self):
        """`build_payload` 안의 단계도 같은 요청 키로 들어가야 한다."""
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        for n in ast.walk(ast.parse(src)):
            if (isinstance(n, ast.Call)
                    and getattr(n.func, "attr", "") == "set"
                    and len(n.args) >= 2
                    and isinstance(n.args[1], ast.Constant)
                    and str(n.args[1].value).startswith("bp.")):
                assert isinstance(n.args[0], ast.Call) and \
                    getattr(n.args[0].func, "id", "") == "timing_key", \
                    f"{n.args[1].value} 가 요청 키를 안 쓴다"


class TestShortHistoryRefetch20260822:
    """1년을 요청했는데 한 달치만 오면 **한 번 더 묻는다**.

    사용자 2026-08-22 두산테스나(131970.KS): 푸터가 `1년 · 일봉 · 25개 봉 ·
    2026-07-16 → 2026-08-21`. 같은 화면의 LG화학은 242개 봉이었다. 야후는
    심볼·시각에 따라 `start`/`end` 질의에 **앞부분이 잘린** 데이터를 주고,
    그때 **기간 키워드**로 물으면 온전히 온다(`^MOVE` 2026-08-19 실측이
    같은 증상). 조용히 넘기면 "가끔 차트가 이상하다"로만 보인다."""

    def _hist(self, start, n):
        import numpy as np
        import pandas as pd
        idx = pd.date_range(start, periods=n, freq="D")
        return pd.DataFrame({"Open": np.arange(n) + 100.0,
                             "High": np.arange(n) + 101.0,
                             "Low": np.arange(n) + 99.0,
                             "Close": np.arange(n) + 100.0,
                             "Volume": np.arange(n) + 1000.0}, index=idx)

    def _run(self, monkeypatch, short_n=25, full_n=250):
        import sys
        import types
        import bot.chart_data as cd
        calls = []

        class _T:
            def __init__(self, tkr):
                pass

            def history(self, **kw):
                calls.append(kw)
                if "period" in kw:
                    return self_outer._hist("2025-08-22", full_n)
                return self_outer._hist("2026-07-16", short_n)
        self_outer = self
        monkeypatch.setitem(sys.modules, "yfinance",
                            types.SimpleNamespace(Ticker=_T))
        monkeypatch.setattr(cd, "_merge_today_bar",
                            lambda t, c, v, o, h, l: (c, v, o, h, l))
        return cd.fetch_chart_payload("131970.KS", "1d", "1y"), calls

    def test_short_range_is_refetched_by_period(self, monkeypatch):
        payload, calls = self._run(monkeypatch)
        assert len(calls) == 2, f"짧게 왔는데 다시 묻지 않았다: {calls}"
        assert "period" in calls[1], calls[1]
        assert len(payload["times"]) == 250, len(payload["times"])

    def test_full_range_is_not_refetched(self, monkeypatch):
        """온전히 왔으면 다시 묻지 않는다 — 야후 호출이 배로 늘면 안 된다."""
        payload, calls = self._run(monkeypatch, short_n=250)
        assert len(calls) == 1, f"불필요한 재질의: {calls}"

    def test_refetch_keeps_the_longer_one(self, monkeypatch):
        """재질의가 더 짧게 오면 원래 것을 지킨다 — 나빠지면 안 된다.

        ⚠️ 2026-08-23 부터 **세 번째로 넉넉한 창**(`period="max"`)도 묻는다 —
        그것도 짧으면 역시 원래 것을 지킨다."""
        payload, calls = self._run(monkeypatch, short_n=25, full_n=5)
        assert len(calls) >= 2
        assert any(c.get("period") == "max" for c in calls), calls
        assert len(payload["times"]) == 25, len(payload["times"])

    def test_span_is_measured_by_date_not_bar_count(self):
        """휴장·거래정지로 개수는 얼마든 적을 수 있다 — 날짜 폭으로 잰다(#29)."""
        import bot.chart_data as cd
        h = self._hist("2025-08-22", 250)
        assert cd._span_days(h) >= 240
        sparse = h.iloc[[0, -1]]           # 두 점뿐이지만 1년을 덮는다
        assert cd._span_days(sparse) >= 240


class TestMismatchDetailOnScreen20260822:
    """"DART 계정 불일치 가능" 만으로는 아무도 못 가른다.

    사용자 2026-08-22 LG화학(051910.KS) 25.4Q: "계정이 불일치한거 좀 봐줄수
    있어?" — `_diff_quarter` 는 **어느 계정끼리** 어긋났는지 이미 기록해
    두는데(`_mismatched_accounts`) 화면 각주가 그걸 안 실었다. 아는 걸
    화면이 말하게 한다(#43·#55)."""

    def test_pairs_are_collected(self):
        import bot.quarterly_infographic as qi
        qs = [{"label": "25.4Q",
               "financials": {"_mismatched_accounts": ["매출: 매출액 ↔ 영업수익"]}},
              {"label": "26.1Q", "financials": {}},
              {"label": "26.2Q",
               "financials": {"_mismatched_accounts": ["매출: 매출액 ↔ 영업수익"]}}]
        assert qi.mismatched_accounts(qs) == ["매출: 매출액 ↔ 영업수익"]
        assert qi.mismatched_accounts([]) == []

    def test_footnote_names_the_accounts(self):
        """각주 문구에 계정쌍이 실려야 한다 — 그 카드 하나를 잘라 본다(#55)."""
        import bot.quarterly_infographic as qi
        notes = qi._footnotes(
            {"anomaly_keys": ["매출"], "anomaly_labels": ["25.4Q"],
             "mismatched_accounts": ["매출: 매출액 ↔ 영업수익"]},
            [{"label": "26.2Q", "financials": {}}])
        line = next((t for t, _c in notes if "이상치 감지" in t), "")
        assert "매출액 ↔ 영업수익" in line, line

    def test_payload_carries_the_pairs(self):
        """헬퍼만 만들고 배선이 빠지면 화면은 그대로다(#20)."""
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        keys = {k.value for n in ast.walk(ast.parse(src))
                if isinstance(n, ast.Dict)
                for k in n.keys
                if isinstance(k, ast.Constant) and isinstance(k.value, str)}
        assert "mismatched_accounts" in keys, "payload 에 안 실린다"

    def test_snapshot_relay_is_not_an_enumeration(self):
        """플래그 이름을 열거하면 새 플래그가 조용히 빠진다(#24)."""
        from bot.stock_snapshot import relay_anomaly_fields
        # 미래에 생길 플래그도 자동으로 실려야 한다 — 이름 열거면 못 잡는다
        got = relay_anomaly_fields({"_anomaly_brand_new_2027": True}, {})
        assert got == {"_anomaly_brand_new_2027": True}, got


class TestRenderCacheSignature20260822:
    """PNG 캐시 키가 **렌더 코드**를 따라야 한다 — 아니면 고쳐도 안 바뀐다.

    사용자 2026-08-22 LG화학: 각주에 계정쌍을 싣도록 고쳤는데 화면은 옛
    문구 그대로였다. `_RENDER_VER` 가 **손으로 올리는 리터럴**이라 또 잊은
    것 — 같은 실패가 이 레포에서 네 번째다(#18 아카이브 · #21b 파싱 캐시 ·
    #95 재무 캐시 v4·v5 를 적어 두고도 v6 을 잊음 · 여기)."""

    def test_key_changes_when_render_code_changes(self, monkeypatch):
        import bot.quarterly_infographic as qi
        a = qi.cache_path("051910.KS", "202611012", asof="2026-08-22_07").name
        monkeypatch.setattr(qi, "_RENDER_SIG", "-deadbeef")
        b = qi.cache_path("051910.KS", "202611012", asof="2026-08-22_07").name
        assert a != b, (a, b)

    def test_signature_is_derived_not_hand_bumped(self):
        """규율로 기억할 일을 **구조로** 옮겼는지 — 지문이 실제 소스에서 온다."""
        import hashlib
        import pathlib
        import bot.quarterly_infographic as qi
        qi._RENDER_SIG = None                 # 다시 계산하게
        want = "-" + hashlib.sha1(
            pathlib.Path(qi.__file__).read_bytes()).hexdigest()[:8]
        assert qi._render_sig() == want, (qi._render_sig(), want)

    def test_same_code_same_key(self):
        """코드가 그대로면 키도 그대로여야 한다 — 매번 바뀌면 캐시가 죽는다."""
        import bot.quarterly_infographic as qi
        a = qi.cache_path("A", "k", asof="h").name
        b = qi.cache_path("A", "k", asof="h").name
        assert a == b, (a, b)

    def test_piece_suffixes_survive_purge(self):
        """조각(카드·하단)은 같은 캐시 키의 짝이다 — 지우면 화면에서 빠진다."""
        import bot.quarterly_infographic as qi
        p = qi.cache_path("A", "k", asof="h")
        for sfx in qi._PIECE_SUFFIXES:
            assert p.with_name(p.stem + sfx + p.suffix).suffix == ".png"
        assert set(qi._PIECE_SUFFIXES) >= {"_cards", "_b"}, qi._PIECE_SUFFIXES


class TestCaptionOnlyTableAndAccountClass20260822:
    """① 빈 칸으로 격자만 채운 캡션 표 ② 총액끼리 라벨만 다른 계정."""

    def test_empty_grid_caption_is_not_a_data_table(self):
        """사용자 2026-08-22 네패스: 가동률 패널에 **제목만** 떴다.
        `(2) 당해 사업년도의 가동률` + `(단위 : 장/Ton/천개)` 두 줄이 각각
        빈 칸 두 개를 달고 있어 `cells >= rows*3` 을 통과했다 — #76(POSCO
        캡션 표)에서 넣은 구조 게이트를 **빈 칸이 우회**했다."""
        from bot.dart_production import _looks_like_a_data_table as ok
        bad = ("<TABLE>"
               "<TR><TD></TD><TD>(2) 당해 사업년도의 가동률</TD><TD></TD></TR>"
               "<TR><TD></TD><TD></TD><TD>(단위 : 장/Ton/천개)</TD></TR>"
               "</TABLE>")
        assert not ok(bad), "빈 격자 캡션 표가 통과했다"

    def test_real_production_table_still_passes(self):
        """가드를 조이면 **무엇이 여전히 통과하는지**를 같이 못박는다(#57)."""
        from bot.dart_production import _looks_like_a_data_table as ok
        good = ("<TABLE><TR><TD>사업부문</TD><TD>사업장</TD>"
                "<TD>평균가동률</TD></TR>"
                "<TR><TD>전력</TD><TD>청주 1</TD><TD>96.4</TD></TR>"
                "<TR><TD>자동화</TD><TD>천안</TD><TD>76.9</TD></TR></TABLE>")
        assert ok(good)
        # 한 줄짜리 각주 표는 예전대로 거부(#57)
        assert not ok("<TABLE><TR><TD>생산능력 산출근거</TD>"
                      "<TD>월 25일</TD><TD>x</TD></TR></TABLE>")

    # ── ② 계정 급(총액 ↔ 구성요소) ────────────────────────────────────
    def test_total_accounts_with_different_labels_subtract(self):
        """사용자 2026-08-22 LG화학 25.4Q `매출: 영업수익 ↔ 매출액` — 연간과
        9개월 보고서가 **같은 총액**을 다른 라벨로 적었을 뿐이다. 그룹 인덱스가
        다르다고 막으면 멀쩡한 회사가 빈칸이 된다."""
        from bot.dart_quarterly import _diff_quarter
        out = _diff_quarter({"매출": 30e12, "_src": {"매출": 0}},
                            {"매출": 22e12, "_src": {"매출": 1}})
        assert out["매출"] == 8e12, out
        assert not out.get("_anomaly_account_mismatch"), out

    def test_component_account_is_still_blocked(self):
        """가드가 진짜로 막아야 하는 건 **총액 ↔ 구성요소**다(메리츠금융지주:
        영업수익 ↔ 이자수익을 빼서 TTM 매출이 -10.30조였다)."""
        from bot.dart_quarterly import _diff_quarter
        out = _diff_quarter({"매출": 8e12, "_src": {"매출": 0}},
                            {"매출": 21e12, "_src": {"매출": 2}})
        assert out["매출"] is None, out
        assert out.get("_anomaly_account_mismatch")
        assert out["_mismatched_accounts"] == ["매출: 영업수익 ↔ 이자수익"]

    def test_unknown_canonical_stays_conservative(self):
        """그룹 표가 없는 항목은 판정 불가 — 종전대로 막는다."""
        from bot.dart_quarterly import _compatible
        assert _compatible("매출", 0, 1)
        assert not _compatible("매출", 0, 2)
        assert _compatible("영업이익", 3, 3)


class TestTablePrefetch20260822:
    """제품·가동률 표를 수주잔고와 **동시에** 받는다.

    2026-08-22 실측 `quarterly-timing 145020.KQ … build_payload=3.181s
    render_png=39.15s total=42.331s h.production_html=76.1s` — 표를 걷는
    76초가 `build_payload` **뒤에 직렬로** 붙었다. 둘은 같은 정기보고서를
    보므로 서로 기다릴 이유가 없다(300120.KQ 는 `bp.backlog=83.065s`)."""

    class _Dart:
        api_key = "k"

    _Q = [{"label": "26.2Q", "reprt_code": "11012", "year": 2026}]

    @staticmethod
    def _drain(dp, deadline: float = 20.0) -> bool:
        """워커가 캐시를 쓸 때까지. ⚠️ 시간에 기대는 대기는 전체 실행에서
        흔들린다 — 여유를 넉넉히 두고 **상태**(`_PREFETCH`)를 본다."""
        import time
        end = time.time() + deadline
        while time.time() < end:
            if not dp._PREFETCH:
                return True
            time.sleep(0.02)
        return False

    def _stub(self, monkeypatch, calls, delay=0.0):
        import sys
        import time
        import types
        import bot.dart_production as dp
        # ⚠️ `_PREFETCH` 는 **모듈 전역**이다 — 앞 테스트의 워커가 남긴 키가
        # 남아 있으면 이 테스트의 미리받기가 "이미 돌고 있다"로 조기 반환해
        # 조용히 통과/실패한다(전체 실행에서만 나는 흔들림, 실측).
        dp._PREFETCH.clear()
        monkeypatch.setattr(dp, "_rcept_nos", lambda *a, **k: ["R1"])

        def _fetch(rn, key, max_bytes=0, raw_markup=False):
            calls.append(rn)
            if delay:
                time.sleep(delay)
            return "<TABLE><TR><TD>x</TD></TR></TABLE>"
        monkeypatch.setitem(
            sys.modules, "bot.dart_feed",
            types.SimpleNamespace(_DOC_TEXT_MAX=1, _DOC_TEXT_MAX_FULL=2,
                                  _fetch_doc_text=_fetch,
                                  doc_was_truncated=lambda *a, **k: False))
        monkeypatch.setattr(dp, "_PARSERS", {
            "products": lambda mk: {"table_html": "<table></table>"}})

    def test_prefetch_returns_immediately_and_warms_the_same_key(
            self, monkeypatch):
        """⚠️ 인자가 호출부와 다르면 캐시 키가 갈려 요청만 늘고 빨라지지
        않는데 그것도 조용하다(#104)."""
        import threading
        import time
        import bot.dart_production as dp
        calls = []
        self._stub(monkeypatch, calls, delay=0.3)
        t0 = time.time()
        dp.prefetch_tables(self._Dart(), "005930.KS", self._Q)
        assert time.time() - t0 < 0.15, "미리받기가 블로킹했다"
        assert self._drain(dp), "워커가 안 끝났다"
        got = dp.tables_rolling(self._Dart(), "005930.KS", self._Q)
        assert got.get("products"), got
        assert len(calls) == 1, f"본 호출이 다시 받았다(키 불일치): {calls}"
        del threading

    def test_no_duplicate_prefetch_threads(self, monkeypatch):
        import time
        import bot.dart_production as dp
        calls = []
        self._stub(monkeypatch, calls, delay=0.3)
        for _ in range(5):
            dp.prefetch_tables(self._Dart(), "005930.KS", self._Q)
        assert self._drain(dp), "워커가 안 끝났다"
        assert len(calls) == 1, f"같은 키로 여러 번 받았다: {calls}"

    def test_warm_cache_starts_no_thread(self, monkeypatch):
        """이미 따뜻하면 **스레드조차 띄우지 않는다** — 호출 수만 세면
        워커가 캐시에 걸려 조용히 통과해 가드가 눈이 먼다(#91b)."""
        import threading
        import bot.dart_production as dp
        calls, started = [], []
        self._stub(monkeypatch, calls)
        dp.tables_rolling(self._Dart(), "005930.KS", self._Q)   # 데운다
        real = threading.Thread

        class _Spy(real):
            def start(self):
                started.append(1)
                return super().start()
        monkeypatch.setattr(dp.threading, "Thread", _Spy)
        dp.prefetch_tables(self._Dart(), "005930.KS", self._Q)
        assert started == [], "이미 따뜻한데 워커를 띄웠다"

    def test_build_payload_wires_the_prefetch(self):
        """헬퍼만 만들고 배선이 빠지면 직렬 그대로다(#20)."""
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        n = sum(1 for x in ast.walk(ast.parse(src))
                if isinstance(x, ast.Call)
                and getattr(x.func, "id", "") == "prefetch_tables")
        assert n >= 1, "build_payload 가 미리받기를 안 부른다"

    def test_pre_render_is_not_a_copy_of_build_payload(self):
        """⚠️ `_t0` 리셋을 빠뜨려 `pre_render` 가 `build_payload` 와 **같은
        값**으로 찍혔다(2026-08-22 실측 3.181s/3.181s · 84.837s/84.837s) —
        같은 값을 두 이름으로 찍는 계측은 빈 구간을 못 본다."""
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "get_or_render")
        body = ast.get_source_segment(src, fn) or ""
        i_bp = body.index('"build_payload"')
        i_pr = body.index('"pre_render"')
        assert "_t_pre = " in body[i_bp:i_pr], "pre_render 앞에 리셋이 없다"


class TestEnrichRunsWithAux20260822:
    """시장 enrichment 가 보조 6종 **뒤에 직렬로** 돌고 있었다.

    2026-08-22 `/api/lookup_detail` 60~192초. `_enrich_*` 는 AST 로 확인한
    결과 **snap 에서 아무것도 읽지 않고 자기 시장 키만 쓴다** — 서로 기다릴
    이유가 없다(#127 표↔수주잔고와 같은 처방)."""

    def _stub(self, monkeypatch, order, lock, delay=0.4):
        import sys
        import time
        import types
        import bot.stock_snapshot as ss

        class _T:
            def __init__(self, t):
                pass

            @property
            def info(self):
                return {"quoteType": "EQUITY", "longName": "X"}

            def get_earnings_dates(self, *a, **k):
                return None

            def get_upgrades_downgrades(self, *a, **k):
                return None
        monkeypatch.setitem(sys.modules, "yfinance",
                            types.SimpleNamespace(Ticker=_T))

        def slow(name):
            def _f(*a, **k):
                with lock:
                    order.append(f"{name}:start")
                time.sleep(delay)
                with lock:
                    order.append(f"{name}:end")
                return {}
            return _f
        for n in ("_collect_earnings_history", "_collect_upgrades",
                  "_collect_holders", "_collect_news_fallback",
                  "_collect_financials", "_collect_peer_multiples"):
            if hasattr(ss, n):
                monkeypatch.setattr(ss, n, slow(n))

        def enrich(ticker, snap):
            with lock:
                order.append("enrich:start")
            time.sleep(delay)
            snap["kr"] = {"ok": True}
            with lock:
                order.append("enrich:end")
        monkeypatch.setattr(ss, "_enrich_kr", enrich)
        return ss

    def test_enrich_overlaps_the_aux_block(self, monkeypatch):
        """⚠️ 순서·시간으로 재면 흔들린다(실측: 단독 green, 전체 실행 red).
        **악수**로 잰다 — 양쪽이 서로가 도는 중임을 확인해야 통과한다."""
        import sys
        import threading
        import types
        import bot.stock_snapshot as ss

        class _T:
            def __init__(self, t):
                pass

            @property
            def info(self):
                return {"quoteType": "EQUITY", "longName": "X"}

            def get_earnings_dates(self, *a, **k):
                return None

            def get_upgrades_downgrades(self, *a, **k):
                return None
        monkeypatch.setitem(sys.modules, "yfinance",
                            types.SimpleNamespace(Ticker=_T))
        enr_up, aux_up = threading.Event(), threading.Event()
        met: list = []

        def _aux(*a, **k):
            aux_up.set()
            met.append(enr_up.wait(5.0))
            return {}
        for n in ("_collect_earnings_history", "_collect_upgrades",
                  "_collect_holders", "_collect_news_fallback",
                  "_collect_financials", "_collect_peer_multiples"):
            if hasattr(ss, n):
                monkeypatch.setattr(ss, n, _aux)

        def _enrich(ticker, snap):
            enr_up.set()
            met.append(aux_up.wait(5.0))
            snap["kr"] = {"ok": True}
        monkeypatch.setattr(ss, "_enrich_kr", _enrich)
        snap = ss.collect_stock_snapshot("005930.KS", use_cache=False)
        assert met and all(met), \
            f"한쪽이 상대를 못 만났다 = 직렬로 돌았다: {met}"
        assert (snap or {}).get("kr") == {"ok": True}

    def test_market_overlay_survives_the_none_strip(self, monkeypatch):
        """⚠️ `snap` 은 None strip 에서 **재바인딩**된다 — 앞에서 합치면
        새 dict 에 안 실려 시장 데이터가 통째로 사라진다."""
        import threading
        import time
        import bot.stock_snapshot as ss_mod
        order, lock = [], threading.Lock()
        ss = self._stub(monkeypatch, order, lock, delay=0.0)

        # ⚠️ enrich 를 **늦게** 끝내야 의미가 있다 — 보조가 끝나기 전에
        # 오버레이가 이미 차 있으면 "strip 앞에서 합치기" 변형도 통과한다
        # (실측: delay=0 픽스처에서 뮤테이션이 그대로 green).
        def slow_enrich(ticker, snap):
            time.sleep(0.5)
            snap["kr"] = {"ok": True}
        monkeypatch.setattr(ss_mod, "_enrich_kr", slow_enrich)
        snap = ss.collect_stock_snapshot("005930.KS", use_cache=False)
        assert (snap or {}).get("kr") == {"ok": True}, snap

    def test_enrich_failure_does_not_kill_the_snapshot(self, monkeypatch):
        """enrich 예외가 스냅샷 전체를 죽이면 상세가 통째로 빈다."""
        import threading
        import bot.stock_snapshot as ss
        order, lock = [], threading.Lock()
        self._stub(monkeypatch, order, lock, delay=0.0)

        def boom(ticker, snap):
            raise RuntimeError("원천 장애")
        monkeypatch.setattr(ss, "_enrich_kr", boom)
        snap = ss.collect_stock_snapshot("005930.KS", use_cache=False)
        assert snap and snap.get("long_name") == "X", snap
        tm = ss.last_timing("005930.KS")
        assert "enrich:KR" in tm, "실패해도 계측은 남아야 한다"

    def test_enrich_functions_read_nothing_from_snap(self):
        """겹치기의 **전제**를 못박는다 — 누가 snap 을 읽기 시작하면 경쟁이
        생기므로 그때는 이 테스트가 깨져야 한다."""
        import ast
        src = open("bot/stock_snapshot.py", encoding="utf-8").read()
        for fn in ast.walk(ast.parse(src)):
            if not (isinstance(fn, ast.FunctionDef)
                    and fn.name.startswith("_enrich_")):
                continue
            arg = fn.args.args[1].arg if len(fn.args.args) > 1 else None
            if not arg:
                continue
            for n in ast.walk(fn):
                if (isinstance(n, ast.Call)
                        and getattr(n.func, "attr", "") == "get"
                        and isinstance(getattr(n.func, "value", None), ast.Name)
                        and n.func.value.id == arg):
                    raise AssertionError(f"{fn.name} 이 {arg} 를 읽는다 — "
                                         "겹치기 전제가 깨졌다")
                if (isinstance(n, ast.Subscript)
                        and isinstance(n.value, ast.Name)
                        and n.value.id == arg
                        and isinstance(n.ctx, ast.Load)):
                    raise AssertionError(f"{fn.name} 이 {arg} 를 읽는다")

    def test_shared_pool_is_not_used_for_enrich(self):
        """공용 풀은 **말단 팬아웃 전용**이다 — 상위 병렬을 거기 제출하면
        슬롯끼리 기다려 교착한다(#110)."""
        import ast
        src = open("bot/stock_snapshot.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_collect_stock_snapshot_uncached")
        body = ast.get_source_segment(src, fn) or ""
        i = body.index("_run_enrich")
        assert "map_bounded" not in body[max(0, i - 1500):i + 500], \
            "enrich 를 공용 풀에 제출했다"

    def test_enrich_pool_does_not_leak_threads(self):
        """예외 경로를 포함해 어느 길로 빠져나가도 풀이 남으면 안 된다."""
        import sys
        import threading
        import time
        import types
        import bot.stock_snapshot as ss
        import pytest as _pt
        mp = _pt.MonkeyPatch()
        try:
            class _T:
                def __init__(self, t):
                    pass

                @property
                def info(self):
                    return {"quoteType": "EQUITY", "longName": "X"}

                def get_earnings_dates(self, *a, **k):
                    return None

                def get_upgrades_downgrades(self, *a, **k):
                    return None
            mp.setitem(sys.modules, "yfinance",
                       types.SimpleNamespace(Ticker=_T))
            mp.setattr(ss, "_enrich_kr",
                       lambda t, s: s.__setitem__("kr", {"ok": True}))
            base = threading.active_count()
            for i in range(15):
                ss.collect_stock_snapshot(f"00593{i % 10}.KS", use_cache=False)
            for _ in range(50):
                if threading.active_count() - base <= 2:
                    break
                time.sleep(0.05)
            assert threading.active_count() - base <= 2, \
                f"스레드가 샌다: {base} → {threading.active_count()}"
        finally:
            mp.undo()


class TestBacklogReasonsAndParallel20260822:
    """① 빈 분기의 **사유**를 화면이 말한다 ② 나머지 분기를 동시에 받는다.

    사용자 2026-08-22 인텔리안테크(011200.KS): 수주잔고가 26.2Q 하나만 뜨고
    앞 4분기가 비어 "앞 시기는 없는거야?"라고 물었다 — `backlog_probe` 는
    왜 못 냈는지 이미 알려주는데 `backlog_for` 가 **값만 꺼내 버렸다**(#123).
    같은 실측에서 `bp.backlog=42.443s` — 분기를 직렬로 걸었기 때문이다."""

    def _qs(self, n=5):
        return [{"label": f"2{i}Q", "year": 2026, "reprt_code": f"110{i}",
                 "financials": {}} for i in range(n)]

    def test_missing_quarters_carry_their_reason(self, monkeypatch):
        import bot.dart_backlog as bl
        import bot.quarterly_infographic as qi

        def probe(dart, ticker, year, code, out=None):
            if code == "1104":                       # 최신만 값이 있다
                return (304e8, "정상")
            return (None, "형식미지원 · 단위없음")
        monkeypatch.setattr(bl, "backlog_probe", probe)
        qs = self._qs()
        qi._fill_backlog(object(), "011200.KS", qs)
        meta = qs[-1]["_meta"]
        assert meta["backlog_missing"] == ["20Q", "21Q", "22Q", "23Q"], meta
        assert set(meta["backlog_why"].values()) == {"형식미지원 · 단위없음"}

    def test_footnote_names_the_reasons_not_one_guess(self):
        """옛 문구는 사유를 **하나로 단정**했다("DART 가 원문 미제공") —
        실제 사유는 분기마다 다르다(#50 내 가정 ≠ 원천의 보장)."""
        import bot.quarterly_infographic as qi
        notes = qi._footnotes(
            {"backlog_missing": ["25.2Q", "25.3Q", "25.4Q"],
             "backlog_why": {"25.2Q": "원문미제공", "25.3Q": "원문미제공",
                             "25.4Q": "형식미지원"}},
            [{"label": "26.2Q", "financials": {}}])
        line = next((t for t, _c in notes if "수주잔고 미표시" in t), "")
        assert "원문미제공" in line and "형식미지원" in line, line
        assert "25.2Q·25.3Q" in line, "같은 사유는 묶어서 말해야 한다"

    def test_payload_carries_the_reasons(self):
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        keys = {k.value for n in ast.walk(ast.parse(src))
                if isinstance(n, ast.Dict) for k in n.keys
                if isinstance(k, ast.Constant) and isinstance(k.value, str)}
        assert "backlog_why" in keys, "payload 에 사유가 안 실린다"

    def test_remaining_quarters_are_fanned_out_at_once(self, monkeypatch):
        """남은 분기를 **한 번에** 팬아웃에 넘기는가(직렬 순회 금지)."""
        import threading
        import time
        import bot.dart_backlog as bl
        import bot.quarterly_infographic as qi
        live = peak = 0
        lock = threading.Lock()

        def probe(dart, ticker, year, code, out=None):
            nonlocal live, peak
            with lock:
                live += 1
                peak = max(peak, live)
            time.sleep(0.25)
            with lock:
                live -= 1
            return (100.0, "정상")
        monkeypatch.setattr(bl, "backlog_probe", probe)
        # ⚠️ **공용 풀의 빈 슬롯에 기대지 않는다** — 전체 실행에서 앞
        # 테스트가 슬롯을 물고 있으면 큐에 밀려 동시 실행이 1 이 되고,
        # 멀쩡한 배선이 "직렬"로 오보된다(실측: peak=1, cap=24).
        # 공용 풀 자체의 동시성은 `TestSharedFetchPool20260821` 이 따로
        # 고정한다 — 여기서는 **배선**(남은 분기를 한 번에 넘기는가)과
        # 그때의 동시성만 본다.
        import bot.pool as _pool
        from concurrent.futures import ThreadPoolExecutor
        seen: list = []

        def _spy(f, items):
            items = list(items)
            seen.append(items)
            with ThreadPoolExecutor(max_workers=max(2, len(items))) as p:
                return list(p.map(f, items))
        monkeypatch.setattr(_pool, "map_bounded", _spy)
        qi._fill_backlog(object(), "011200.KS", self._qs())
        # 계약 = "남은 분기를 **한 번에** 팬아웃에 넘긴다". 직렬로 되돌리면
        # `map_bounded` 가 아예 안 불려 `seen` 이 비고, 이 단언이 발화한다
        # (뮤테이션으로 확인). ⚠️ 실행기 안에서의 동시 실행 수는 여기서
        # 재지 않는다 — 전체 실행 중엔 1 로 관측돼(실측) 멀쩡한 배선을
        # '직렬'로 오보한다. 그건 stdlib 의 몫이고, 공용 풀의 동시성은
        # `TestSharedFetchPool20260821` 이 따로 고정한다.
        assert seen == [[0, 1, 2, 3]], f"남은 분기를 한 번에 안 넘겼다: {seen}"
        assert peak >= 1, "스텁이 한 번도 안 불렸다"

    def test_non_disclosing_company_stays_cheap(self, monkeypatch):
        """미공시 회사는 대용량 다운로드가 **최대 2회**여야 한다 —
        병렬화가 그 비용 상한을 깨면 안 된다(#66)."""
        import bot.dart_backlog as bl
        import bot.quarterly_infographic as qi
        n = []

        def probe(dart, ticker, year, code, out=None):
            n.append(code)
            return (None, "명시적미공시")
        monkeypatch.setattr(bl, "backlog_probe", probe)
        qi._fill_backlog(object(), "000000.KS", self._qs())
        assert len(n) == 2, f"미공시 회사가 {len(n)}회 받았다"

    def test_parallel_failure_falls_back_not_crashes(self, monkeypatch):
        """한 분기가 던져도 나머지는 살아야 한다(`map_bounded` 는 None)."""
        import bot.dart_backlog as bl
        import bot.quarterly_infographic as qi

        def probe(dart, ticker, year, code, out=None):
            if code == "1101":
                raise RuntimeError("원천 장애")
            return (100.0, "정상")
        monkeypatch.setattr(bl, "backlog_probe", probe)
        qs = self._qs()
        qi._fill_backlog(object(), "011200.KS", qs)
        vals = [(q["financials"].get("수주잔고")) for q in qs]
        assert vals.count(100.0) >= 4, vals
        assert (qs[-1].get("_meta") or {}).get("backlog_why", {}).get("21Q")


class TestFcfMissingReason20260822:
    """FCF 빈 분기도 **왜** 비었는지 말해야 한다.

    사용자 2026-08-22 ASML "이거 맞는거야?" — 26.2Q 가 빈칸이었다. 재료가
    없으면 비우는 건 옳지만(빈칸 > 틀린 숫자), 사유를 안 말하면 사용자가
    물어야 한다. 같은 실수를 세 번째 반복했다(#123 계정 불일치 · #129
    수주잔고 · 여기)."""

    def test_reason_names_the_missing_input(self):
        from bot.fcf import missing_reason
        assert missing_reason(None) == "현금흐름표 없음"
        assert "CAPEX" in missing_reason({"Operating Cash Flow": 1e9})
        assert "영업활동현금흐름" in missing_reason(
            {"Capital Expenditure": -1e8})
        assert missing_reason(
            {"Operating Cash Flow": 1e9, "Capital Expenditure": -1e8}) == ""
        # 원천이 FCF 를 직접 주면 사유 자체가 없다
        assert missing_reason({"Free Cash Flow": 5e8}) == ""

    def test_attach_records_the_reason_per_quarter(self):
        from bot.fcf import attach_to_series
        qs = [{"period": "2026-03-31", "financials": {}},
              {"period": "2026-06-30", "financials": {}}]
        rows = [{"period": "2026-03-31", "Operating Cash Flow": 2e9,
                 "Capital Expenditure": -3e8},
                {"period": "2026-06-30", "Operating Cash Flow": 1e9}]
        assert attach_to_series(qs, rows) == 1
        assert qs[0]["financials"]["FCF"] == 1.7e9
        assert "CAPEX" in qs[1]["_meta"]["fcf_why"]
        assert "fcf_why" not in (qs[0].get("_meta") or {}), "채운 분기엔 사유 없음"

    def test_ocf_is_never_used_alone(self):
        """⚠️ CAPEX 가 없다고 OCF 를 FCF 로 쓰면 설비투자가 큰 회사가 크게
        부풀려진다 — 비우고 **이유를 밝힌다**."""
        from bot.fcf import fcf_from_parts, fcf_from_row
        assert fcf_from_parts(1e9, None) is None
        assert fcf_from_row({"Operating Cash Flow": 1e9}) is None

    def test_footnote_groups_the_reasons(self):
        import bot.quarterly_infographic as qi
        notes = qi._footnotes(
            {"fcf_why": {"25.2Q": "CAPEX 미제공", "25.3Q": "CAPEX 미제공",
                         "26.2Q": "현금흐름표 없음"}},
            [{"label": "26.2Q", "financials": {}}])
        line = next((t for t, _c in notes if "FCF 미표시" in t), "")
        assert "25.2Q·25.3Q" in line and "현금흐름표 없음" in line, line

    def test_payload_carries_it(self):
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        keys = {k.value for n in ast.walk(ast.parse(src))
                if isinstance(n, ast.Dict) for k in n.keys
                if isinstance(k, ast.Constant) and isinstance(k.value, str)}
        assert "fcf_why" in keys, "payload 에 안 실린다"


class TestFcfAuditNoFalsePass20260822:
    """감사가 **데이터 0건에 ✅** 를 찍고 있었다.

    2026-08-22 VM 실측: venv 밖 인터프리터로 돌려 `yfinance` 가 없자 스냅샷이
    통째로 비었는데 `① 재계산 ✅ 전 기간 일치` · `⑤ ✅ 누적 냄새 없음` 이
    찍혔다 — 대조 0건은 통과가 아니다(#54). 진단 도구가 제품과 **다른
    환경**에서 돌면 결과가 거짓이 된다(#23 의 인터프리터판)."""

    def _audit(self, monkeypatch, snap):
        import bot.scripts.fcf_audit as fa
        monkeypatch.setattr(fa, "collect_stock_snapshot",
                            lambda *a, **k: snap, raising=False)
        import bot.stock_snapshot as ss
        monkeypatch.setattr(ss, "collect_stock_snapshot", lambda *a, **k: snap)
        return fa.audit_one("ASML", None)

    def test_empty_snapshot_is_a_failure_not_a_pass(self, monkeypatch):
        r = self._audit(monkeypatch, {})
        body = "\n".join(r["lines"])
        assert "① 재계산 ❌ 대조 0건" in body, body
        assert "✅ 전 기간 일치" not in body, body
        assert r["bad"] >= 1, r

    def test_cumulative_check_needs_enough_quarters(self, monkeypatch):
        """`cumulative_smell` 은 3개 미만이면 판단보류를 준다 — 그걸
        "냄새 없음"으로 찍으면 빈 종목이 통과한다(#44b)."""
        snap = {"financials": {"cash_flow": {"quarterly": [
            {"period": "2026-03-31", "Operating Cash Flow": 2e9,
             "Capital Expenditure": -3e8}]}}}
        r = self._audit(monkeypatch, snap)
        body = "\n".join(r["lines"])
        assert "⑤ ❓ 판정 불가" in body, body
        assert "✅ 누적 냄새 없음" not in body, body

    def test_real_data_still_passes(self, monkeypatch):
        """가드를 조이면 **무엇이 여전히 통과하는지**도 못박는다(#57)."""
        q = [{"period": f"2026-{m:02d}-30", "Operating Cash Flow": 2e9 + i,
              "Capital Expenditure": -3e8} for i, m in enumerate((3, 6, 9, 12))]
        r = self._audit(monkeypatch, {"financials": {"cash_flow": {
            "quarterly": q}}})
        body = "\n".join(r["lines"])
        assert "① 재계산 ✅" in body, body
        assert "⑤ ✅ 누적 냄새 없음" in body, body

    def test_banner_reports_the_interpreter(self):
        """어느 파이썬으로 도는지 찍어야 환경 불일치가 드러난다."""
        # ⚠️ 문자열 검색으로 재면 **옆 문구가 대신 만족시킨다**(실측: 의존성
        # 오류 메시지에도 '인터프리터' 가 들어 있어 배너를 지워도 통과했다,
        # #75). 실행 경로를 **찍는 행위**를 구조로 본다.
        import ast
        src = open("bot/scripts/fcf_audit.py", encoding="utf-8").read()
        printed = False
        for n in ast.walk(ast.parse(src)):
            if not (isinstance(n, ast.Call)
                    and getattr(n.func, "id", "") == "print"):
                continue
            for a in n.args:
                for sub in ast.walk(a):
                    if (isinstance(sub, ast.Attribute)
                            and sub.attr == "executable"):
                        printed = True
        assert printed, "어느 파이썬으로 도는지 안 찍는다"
        lits = {n.value for n in ast.walk(ast.parse(src))
                if isinstance(n, ast.Constant) and isinstance(n.value, str)}
        assert any("필수 모듈 없음" in s for s in lits), "의존성 가드 없음"


class TestPerBand20260822:
    """외국 종목 PER 밴드 — 완제품 원천이 없어 **직접 만든다**.

    사용자 2026-08-22: "외국종목은 PER, PBR Band 를 제공해주는곳이 없나?
    … 차트 아니라 표도 괜찮아." 조사 결과 Yahoo·Finviz 는 현재값만, FnGuide
    는 `cmp_cd` 가 6자리 국내코드라 KR 전용이다. 재료(가격·EPS)는 이미
    받고 있으므로 여기서 계산한다(#32 의 경계: 단독 화면이라 허용)."""

    _EPS = [("2024-01-31", 2.0), ("2024-04-30", 2.1), ("2024-07-31", 2.2),
            ("2024-10-31", 2.3), ("2025-01-31", 2.4), ("2025-04-30", 2.5),
            ("2025-07-31", 2.6), ("2025-10-31", 2.7)]
    _PX = [("2024-10-31", 180.0), ("2025-01-31", 178.0),
           ("2025-04-30", 149.0), ("2025-07-31", 178.5),
           ("2025-10-31", 231.8)]

    def test_ttm_is_four_quarters_and_sorted(self):
        from bot.per_band import ttm_eps_series
        got = ttm_eps_series(self._EPS)
        assert got[0] == ("2024-10-31", 8.6), got[0]
        assert len(got) == 5, got
        # ⚠️ 원천이 **최신부터** 줘도 결과가 같아야 한다 — 그대로 굴리면
        # TTM 이 미래를 포함해 조용히 틀린다.
        assert ttm_eps_series(list(reversed(self._EPS))) == got

    def test_price_is_point_in_time(self):
        """미래 주가를 끌어오면 그때 존재하지 않았던 PER 이 된다(#28)."""
        from bot.per_band import per_series, ttm_eps_series
        rows = per_series(self._PX, ttm_eps_series(self._EPS))
        assert rows[0][0] == "2024-10-31" and rows[0][1] == 180.0
        # 그 기간 **이하**의 마지막 관측 — 뒤 가격이 앞 행에 새면 안 된다
        assert all(r[1] != 231.8 for r in rows[:-1]), rows

    def test_loss_quarters_make_no_per(self):
        """적자 구간 PER 은 음수/무한대로 튀어 밴드를 통째로 망친다."""
        from bot.per_band import per_series
        rows = per_series(self._PX, [("2025-01-31", -1.0),
                                     ("2025-04-30", 0.0),
                                     ("2025-07-31", 9.8)])
        assert [r[0] for r in rows] == ["2025-07-31"], rows

    def test_bands_come_from_the_observed_distribution(self):
        from bot.per_band import build
        b = build(self._PX, self._EPS)
        labels = [x["label"] for x in b["bands"]]
        assert labels == ["최고", "중상", "중하", "최저"], labels
        mults = [x["mult"] for x in b["bands"]]
        assert mults == sorted(mults, reverse=True), mults
        # '그 배수에서의 주가' = 배수 × 현재 TTM EPS
        top = b["bands"][0]
        assert abs(top["fair"] - top["mult"] * b["eps_now"]) < 0.02

    def test_too_few_points_makes_nothing(self):
        """점 두세 개로 그린 '최고/최저'는 이름값을 못 한다(#29)."""
        from bot.per_band import build
        assert build(self._PX[:2], self._EPS[:5]) is None

    def test_annual_mode_skips_ttm(self):
        from bot.per_band import build
        eps_a = [("2022-12-31", 6.0), ("2023-12-31", 7.0),
                 ("2024-12-31", 8.0), ("2025-12-31", 9.0)]
        px = [("2022-12-31", 60.0), ("2023-12-31", 84.0),
              ("2024-12-31", 96.0), ("2025-12-31", 135.0)]
        b = build(px, eps_a, annual=True)
        assert b and b["n"] == 4 and b["rows"][0]["per"] == 10.0, b


class TestEdgarEpsHistory20260822:
    """미국은 EDGAR 로 10년 — yfinance 8분기(≈2년)로는 밴드가 안 된다."""

    def _rows(self):
        return [
            # 분기(≈91일) — 같은 end 가 두 번, 나중 접수가 정본
            {"start": "2025-08-01", "end": "2025-10-31", "val": 2.5,
             "filed": "2025-11-10"},
            {"start": "2025-08-01", "end": "2025-10-31", "val": 2.7,
             "filed": "2025-12-20"},
            # 연간(≈364일)
            {"start": "2025-01-01", "end": "2025-12-31", "val": 9.9,
             "filed": "2026-02-10"},
            # 반기(≈181일) — 어느 쪽도 아니다. 섞으면 TTM 이 통째로 틀린다.
            {"start": "2025-01-01", "end": "2025-06-30", "val": 5.0,
             "filed": "2025-07-20"},
        ]

    def test_split_is_by_span_not_by_name(self, monkeypatch):
        """`fp` 는 10-K 에도 FY 로 붙고 20-F 는 규약이 또 다르다 — 이름이
        아니라 기간 길이로 가른다(#25)."""
        import bot.edgar_eps as ee
        monkeypatch.setattr(ee, "_rows", lambda cik, tag: self._rows())
        monkeypatch.setattr("bot.edgar_client._ticker_to_cik",
                            lambda t: "0000123456")
        monkeypatch.setattr("bot.edgar_client._load_cache",
                            lambda *a, **k: None)
        monkeypatch.setattr("bot.edgar_client._save_cache",
                            lambda *a, **k: None)
        h = ee.eps_history("AMAT")
        assert h["quarterly"] == [("2025-10-31", 2.7)], h
        assert h["annual"] == [("2025-12-31", 9.9)], h

    def test_half_year_is_rejected(self):
        import bot.edgar_eps as ee
        assert ee._span_days("2025-01-01", "2025-06-30") == 180
        assert not (ee._Q_DAYS[0] <= 180 <= ee._Q_DAYS[1])
        assert not (ee._A_DAYS[0] <= 180 <= ee._A_DAYS[1])


class TestPerBandSummary20260822:
    """사용자 2026-08-22: "5년 평균과 최저점, 최고점을 추가해줘. 여기 위에 …
    그리고 PER 은 주가에 따라 매일 바뀌잖아. 그게 고려된거 맞지?"

    ⚠️ 고려되고 있지 **않았다** — 표의 마지막 행 주가는 EPS 기간에 붙은 월봉
    이고 KR 은 FnGuide 밴드를 12시간 캐시로 받는다. 현재 PER 은 라이브 시세로
    다시 만들고, 못 받으면 **어느 쪽인지 밝힌다**."""

    @staticmethod
    def _rows(pairs):
        return [{"period": p, "price": px, "eps": None, "per": round(pr, 2)}
                for p, px, pr in pairs]

    def test_window_is_cut_by_date_not_position(self):
        """관측이 성기면 위치로 자른 '5년'은 거짓말이다(#29)."""
        from bot.per_band import summary
        rows = self._rows([("2010-01-01", 100, 50.0), ("2011-01-01", 100, 40.0),
                           ("2023-01-01", 100, 10.0), ("2024-01-01", 100, 12.0),
                           ("2025-01-01", 100, 14.0), ("2026-01-01", 100, 16.0)])
        sm = summary(rows, years=5)
        assert sm["n"] == 4, sm            # 2010·2011 은 창 밖
        assert sm["from"] == "2023-01-01" and sm["to"] == "2026-01-01"
        assert sm["min"] == 10.0 and sm["max"] == 16.0
        assert sm["avg"] == 13.0
        # 5년을 다 못 채웠으면 그렇게 적을 수 있어야 한다(화면 라벨의 근거)
        assert sm["span_years"] == 3.0 and sm["want_years"] == 5

    def test_current_per_follows_todays_price(self):
        """사용자 질문 그대로 — 주가가 오르면 현재 PER 도 올라야 한다."""
        from bot.per_band import summary
        rows = self._rows([("2023-01-01", 100, 10.0), ("2024-01-01", 110, 11.0),
                           ("2025-01-01", 120, 12.0), ("2026-01-01", 100, 10.0)])
        base = summary(rows, years=5)
        assert base["per_now_basis"] == "last" and base["per_now"] == 10.0
        up = summary(rows, years=5, price_now=150.0)
        assert up["per_now_basis"] == "live", up
        # k = 마지막 행의 PER ÷ 주가 = 10/100 → 150 × 0.1 = 15.0
        assert up["per_now"] == 15.0, up
        assert up["price_now"] == 150.0
        dn = summary(rows, years=5, price_now=50.0)
        assert dn["per_now"] == 5.0, dn

    def test_current_per_is_consistent_with_the_history_rows(self):
        """파생 칸은 **화면의 다른 칸**에서 만든다(#33) — 마지막 행의 주가를
        그대로 넣으면 그 행의 PER 이 나와야 한다. 원천별로 k 를 따로 적으면
        (비-KR 1÷EPS · KR 최고배수÷밴드선) 여기서 갈라진다."""
        from bot.per_band import summary
        rows = self._rows([("2023-01-01", 100, 10.0), ("2024-01-01", 110, 11.0),
                           ("2025-01-01", 120, 12.0), ("2026-01-01", 137, 18.83)])
        sm = summary(rows, years=5, price_now=137.0)
        assert sm["per_now"] == 18.83, sm

    def test_newest_first_input_still_finds_the_latest_row(self):
        """원천이 최신부터 주는 일이 잦다 — 문서 순서의 마지막을 '현재'로
        삼으면 조용히 **옛 행**의 기준으로 현재 PER 을 만든다."""
        from bot.per_band import summary
        rows = self._rows([("2026-01-01", 200, 20.0), ("2025-01-01", 100, 10.0),
                           ("2024-01-01", 100, 11.0), ("2023-01-01", 100, 12.0)])
        sm = summary(rows, years=5, price_now=400.0)
        # k = 20/200 = 0.1 → 400 × 0.1 = 40.0 (옛 행이면 0.1 이 아니라 0.1…
        # 이 아니라 10/100 = 0.1 로 우연히 같아지지 않게 마지막만 200 으로 뒀다)
        assert sm["per_now"] == 40.0, sm
        assert sm["to"] == "2026-01-01" and sm["from"] == "2023-01-01"

    def test_too_few_points_makes_no_summary(self):
        """점 두세 개짜리 '5년 평균'은 이름값을 못 한다(빈칸이 낫다)."""
        from bot.per_band import summary
        assert summary(None) is None and summary([]) is None
        assert summary(self._rows([("2025-01-01", 100, 10.0),
                                   ("2025-04-01", 100, 11.0),
                                   ("2025-07-01", 100, 12.0)])) is None

    def test_negative_and_broken_rows_are_dropped(self):
        from bot.per_band import summary
        rows = self._rows([("2023-01-01", 100, 10.0), ("2024-01-01", 100, 11.0),
                           ("2025-01-01", 100, 12.0), ("2026-01-01", 100, 13.0)])
        rows.append({"period": "bad", "price": 1, "per": 999})
        rows.append({"period": "2026-02-01", "price": 1, "per": -5})
        sm = summary(rows, years=5)
        assert sm["max"] == 13.0 and sm["n"] == 4, sm

    def test_live_price_rejects_order_of_magnitude_glitches(self):
        """통화 뒤섞임·분할 미조정을 거른다. ⚠️ 기준이 **월봉**이라 일일밴드
        (KR ±35%)를 쓰면 정당한 한 달 등락을 reject 한다 — 넓게 본다."""
        import bot.per_band as pb

        def _run(price, ref):
            orig = pb.__dict__.get("_stub")
            import sys
            import types
            mod = types.ModuleType("bot.world_quote")
            mod.fetch_world_quote = lambda t: {"price": price}
            sys.modules["bot.world_quote"] = mod
            try:
                return pb.live_price("AAPL", ref)
            finally:
                sys.modules.pop("bot.world_quote", None)
                assert orig is None
        assert _run(150.0, 100.0) == 150.0      # 한 달 +50% 는 정당하다
        assert _run(40.0, 100.0) == 40.0        # −60% 도 통과
        assert _run(100000.0, 100.0) is None    # 자릿수 사고
        assert _run(0.0, 100.0) is None and _run(None, 100.0) is None
        assert _run(150.0, None) == 150.0       # 기준이 없으면 값만 본다

    def test_both_producers_attach_a_summary(self):
        """헬퍼만 만들고 배선이 빠지면 화면은 그대로다(#20). KR 은 **실주행**
        으로, 비-KR 은 네트워크가 필요해 AST 로 본다."""
        import ast
        from bot.dashboard_server import _kr_per_table
        t = _kr_per_table(TestBandTableWiring20260822._BAND)
        assert t and t.get("summary"), "KR 표에 요약이 없다"
        src = open("bot/per_band.py", encoding="utf-8").read()
        node = next(n for n in ast.walk(ast.parse(src))
                    if isinstance(n, ast.FunctionDef) and n.name == "for_ticker")
        seg = ast.get_source_segment(src, node) or ""
        assert '"summary"' in seg, "for_ticker 가 요약을 안 붙인다"
        assert "live_price" in seg, "for_ticker 현재가 미배선"
        # KR 도 현재가를 실제로 부르는가 — 티커가 오면 조회한다
        srv = open("bot/dashboard_server.py", encoding="utf-8").read()
        node = next(n for n in ast.walk(ast.parse(srv))
                    if isinstance(n, ast.FunctionDef) and n.name == "_kr_band_tables")
        assert "_lp(" in (ast.get_source_segment(srv, node) or ""), "KR 현재가 미배선"

    def test_client_renders_summary_above_the_band_table(self):
        """사용자 지정 위치 — "여기 위에". 밴드 표보다 앞에 그려야 한다."""
        from bot.dashboard import _BAND_JS
        i = _BAND_JS.index("t.summary")
        j = _BAND_JS.index("그 배수에서의 주가")
        assert i < j, "요약이 밴드 표 아래에 있다"
        # 헤더는 지표명을 붙여 만든다(PER/PBR 공용) — 리터럴을 박지 않는다
        for lab in ("현재 '+kind", "평균", "최저", "최고"):
            assert lab in _BAND_JS[i:j], f"요약에 {lab} 이 없다"
        # 실시간이 아니면 **그렇게 말해야** 한다 — 침묵이 최악(#43)
        assert "실시간 시세를 못 받았습니다" in _BAND_JS[i:j]


class TestTruncatedChartFallback20260822:
    """사용자 2026-08-22 인텍플러스 064290.KS: "아직도 차트가 이렇게 나올때가
    있는데 대체 왜 그런거야? 근본적으로 해결이 안돼?" — 1년을 요청했는데
    `25개 봉 · 2026-07-16 → 2026-08-21`.

    ⚠️ 08-22 에 넣은 **기간 키워드 재질의**(#122)는 실제로 돌았지만, 야후가
    그 심볼을 **두 질의 모두** 잘라 주면 손쓸 방법이 없었다. 우리에겐 네이버
    일봉(키 불필요·차단 없음)이 이미 있는데 야후가 **빈 응답**일 때만 쓰고
    있었다 — 잘렸지만 비지 않은 응답이 그 폴백을 통째로 건너뛰게 했다."""

    @staticmethod
    def _stub_yf(monkeypatch, bdays):
        """야후가 `bdays` 영업일치만 주는 상황. 두 질의 다 같은 결과."""
        import datetime as _dt
        import sys
        import types
        import pandas as pd
        calls = []

        class _T:
            def __init__(self, tk):
                pass

            def history(self, **kw):
                calls.append(kw)
                idx = pd.date_range(end=_dt.datetime(2026, 8, 21),
                                    periods=bdays, freq="B")
                n = len(idx)
                return pd.DataFrame({"Open": [1.0] * n, "High": [1.0] * n,
                                     "Low": [1.0] * n, "Close": [1.0] * n,
                                     "Volume": [1] * n}, index=idx)
        mod = types.ModuleType("yfinance")
        mod.Ticker = _T
        monkeypatch.setitem(sys.modules, "yfinance", mod)
        return calls

    @staticmethod
    def _payload(days, step=3, label="네이버"):
        import datetime as _dt
        ts = [(_dt.date(2026, 8, 21) - _dt.timedelta(days=d)).isoformat()
              for d in range(days, -1, -step)]
        n = len(ts)
        return {"fallback": label, "times": ts, "close": [1.0] * n,
                "open": [1.0] * n, "high": [1.0] * n, "low": [1.0] * n,
                "volume": [1] * n}

    def test_truncated_yahoo_falls_back_to_naver(self, monkeypatch):
        import bot.chart_data as cd
        self._stub_yf(monkeypatch, 25)
        monkeypatch.setattr(cd, "_fetch_series_fallback",
                            lambda t, p: self._payload(360))
        out = cd.fetch_chart_payload("064290.KS", period="1y")
        assert out.get("fallback") == "네이버", out.get("fallback")
        assert cd._payload_span_days(out) > 300, len(out["times"])
        # 온전히 채웠으면 안내는 없다(잡음 금지)
        assert not out.get("notice"), out.get("notice")

    def test_fallback_is_ignored_when_it_covers_less(self, monkeypatch):
        """⚠️ 무조건 폴백하면 야후가 멀쩡한 날 **더 짧은** 데이터로 내려간다."""
        import bot.chart_data as cd
        self._stub_yf(monkeypatch, 25)
        monkeypatch.setattr(cd, "_fetch_series_fallback",
                            lambda t, p: self._payload(10))
        out = cd.fetch_chart_payload("064290.KS", period="1y")
        assert out.get("fallback") != "네이버", out
        assert len(out["close"]) == 25

    def test_screen_says_so_when_nothing_covers_the_range(self, monkeypatch):
        """'1년' 라벨에 한 달치를 실으면 그건 거짓말이다(#29·#43)."""
        import bot.chart_data as cd
        self._stub_yf(monkeypatch, 25)
        monkeypatch.setattr(cd, "_fetch_series_fallback", lambda t, p: None)
        out = cd.fetch_chart_payload("064290.KS", period="1y")
        assert out.get("notice"), "짧게 온 사실을 화면에 안 알린다"
        assert "1년" in out["notice"] and "32일" in out["notice"], out["notice"]

    def test_full_response_gets_no_fallback_and_no_notice(self, monkeypatch):
        """정상일 때 폴백을 부르면 요청만 늘고 조용히 느려진다."""
        import bot.chart_data as cd
        self._stub_yf(monkeypatch, 250)
        hit = []
        monkeypatch.setattr(cd, "_fetch_series_fallback",
                            lambda t, p: hit.append(t))
        out = cd.fetch_chart_payload("064290.KS", period="1y")
        assert not hit, "온전한 응답에도 폴백을 불렀다"
        assert not out.get("notice") and not out.get("fallback")

    def test_fallback_payload_keeps_live_price_and_52w(self, monkeypatch):
        """폴백은 예전엔 야후가 통째로 빈 종목에서만 탔지만 이제 잘린 응답에서도
        탄다 — 여기서 안 붙이면 오른쪽 패널의 현재가·52주가 조용히 사라진다."""
        import bot.chart_data as cd
        self._stub_yf(monkeypatch, 25)
        monkeypatch.setattr(cd, "_fetch_series_fallback",
                            lambda t, p: self._payload(360))
        monkeypatch.setattr(cd, "_live_last_price",
                            lambda t, pl, dec, tk: 32100.0)
        monkeypatch.setattr(cd, "_year_high_low", lambda t, dec: (41400.0, 21450.0))
        out = cd.fetch_chart_payload("064290.KS", period="1y")
        assert out["fallback"] == "네이버"
        assert out.get("last_price") == 32100.0, out.keys()
        assert out.get("wk52_high") == 41400.0 and out.get("wk52_low") == 21450.0

    def test_span_is_measured_in_days_not_bars(self):
        """봉 **개수**로 재면 휴장·거래정지가 잘림으로 오판된다(#29)."""
        import bot.chart_data as cd
        assert cd._payload_span_days(None) is None
        assert cd._payload_span_days({}) == 0
        # 4봉뿐이어도 1년을 덮으면 잘린 게 아니다
        wide = {"times": ["2025-08-21", "2025-12-01", "2026-04-01", "2026-08-21"]}
        assert cd._payload_span_days(wide) > 350, cd._payload_span_days(wide)
        # 봉이 많아도 한 달이면 잘린 것이다
        narrow = self._payload(30, step=1)
        assert cd._payload_span_days(narrow) <= 31

