class TestBandCoverageAndPartialSource20260822:
    """사용자 2026-08-22: (1) TSMC "이렇게 밖에 안되는거야? … 분기로는 안되는
    거야? 연단위밖에 안돼?" (2) SKC "PER Band 는 왜 이렇고 그 다음에 밑에
    History 는 왜 안나와?" """

    # ── (1) 대만: 원천이 PER 을 직접 준다 ────────────────────────────
    def test_tw_uses_source_per_history_not_four_annual_points(self, monkeypatch):
        """yfinance 는 분기 손익을 4~5개만 줘 TTM 이 1~2점뿐이고 연간도 4개년
        뿐이다 — TSMC 가 연 4점짜리 밴드였던 이유. 대만은 FinMind 가 **일별
        PER** 을 주므로 우리가 EPS 로 만들 필요가 없다."""
        import datetime as _dt
        import bot.finmind_client as fm
        import bot.per_band as pb
        raw, d, i = [], _dt.date(2020, 1, 6), 0
        while d <= _dt.date(2026, 8, 21):
            if d.weekday() < 5:
                raw.append({"date": d.isoformat(), "PER": 12.0 + 8 * ((i // 60) % 4)})
                i += 1
            d += _dt.timedelta(days=1)
        monkeypatch.setattr(fm, "fetch_per_pbr", lambda t, days=90: raw)
        px = [((_dt.date(2020, 1, 31) + _dt.timedelta(days=30 * k)).isoformat(),
               200.0 + 8 * k) for k in range(85)]
        rows = pb.tw_per_rows("2330.TW", px, 10)
        assert len(rows) > 40, len(rows)          # 연 4점이 아니라 월 단위
        t = pb.assemble(rows)
        assert t and t["n"] == len(rows)

    def test_tw_eps_cell_is_derived_from_the_displayed_price_and_per(self):
        """파생 칸은 **화면의 다른 칸**에서 만든다 — 눈으로 나눠 봐도 맞아야
        한다(#33)."""
        import bot.finmind_client as fm
        import bot.per_band as pb
        orig = fm.fetch_per_pbr
        fm.fetch_per_pbr = lambda t, days=90: [
            {"date": "2025-01-31", "PER": 20.0}, {"date": "2025-02-28", "PER": 25.0}]
        try:
            rows = pb.tw_per_rows("2330.TW", [("2025-01-31", 1000.0),
                                              ("2025-02-28", 1250.0)], 10)
        finally:
            fm.fetch_per_pbr = orig
        for _p, price, eps, per in rows:
            assert abs(price / eps - per) < 0.01, (price, eps, per)

    def test_tw_drops_periods_with_no_price(self):
        """주가를 모르는 시점은 버린다 — 억지로 채우면 그 행이 거짓이 된다."""
        import bot.finmind_client as fm
        import bot.per_band as pb
        orig = fm.fetch_per_pbr
        fm.fetch_per_pbr = lambda t, days=90: [
            {"date": "2015-01-30", "PER": 10.0}, {"date": "2025-01-31", "PER": 20.0}]
        try:
            rows = pb.tw_per_rows("2330.TW", [("2025-01-31", 1000.0)], 10)
        finally:
            fm.fetch_per_pbr = orig
        assert [r[0] for r in rows] == ["2025-01-31"], rows

    def test_month_end_sampling_keeps_the_last_observation(self):
        """일별을 월로 추릴 때 **마지막** 관측을 써야 그 달 종가 기준이 된다."""
        from bot.per_band import _month_end_samples
        got = _month_end_samples([("2025-01-02", 1.0), ("2025-01-31", 9.0),
                                  ("2025-02-14", 5.0)])
        assert got == [("2025-01-31", 9.0), ("2025-02-14", 5.0)], got

    def test_finmind_per_cache_key_includes_the_window(self):
        """90일 조회가 캐시를 먼저 채우면 3650일 조회가 그 90일치를 받아 간다."""
        import ast
        src = open("bot/finmind_client.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "fetch_per_pbr")
        seg = ast.get_source_segment(src, fn) or ""
        i = seg.index("ck = ")
        assert "days" in seg[i:i + 120], seg[i:i + 120]

    def test_for_ticker_actually_takes_the_tw_branch(self, monkeypatch):
        """⚠️ AST 로 `tw_per_rows(` 존재만 보면 **게이트를 못 잡는다**(호출은
        남아 있고 조건만 꺼진다) — 수집기를 통째로 태워 basis 를 본다(#20)."""
        import datetime as _dt
        import bot.finmind_client as fm
        import bot.per_band as pb
        raw = [{"date": (_dt.date(2021, 1, 31)
                         + _dt.timedelta(days=30 * k)).isoformat(),
                "PER": 15.0 + (k % 7)} for k in range(60)]
        monkeypatch.setattr(fm, "fetch_per_pbr", lambda t, days=90: raw)
        monkeypatch.setattr(pb, "_price_history", lambda t, y: ([
            ((_dt.date(2021, 1, 31) + _dt.timedelta(days=30 * k)).isoformat(),
             500.0 + 5 * k) for k in range(60)], [], False))
        monkeypatch.setattr(pb, "live_price", lambda t, ref=None, **kw: None)
        monkeypatch.setattr(pb, "chart_block", lambda t, p=None: None)
        tbl, why = pb.for_ticker("2330.TW", {})
        assert tbl is not None, why
        assert tbl["basis"] == "finmind", tbl["basis"]
        assert tbl["n"] > 40, tbl["n"]

    def test_assemble_is_the_single_band_source(self):
        """원천마다 rows 만드는 법은 달라도 밴드 규칙은 하나여야 한다(#38)."""
        import ast
        src = open("bot/per_band.py", encoding="utf-8").read()
        tree = ast.parse(src)
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "build")
        assert "assemble(" in (ast.get_source_segment(src, fn) or "")
        ft = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "for_ticker")
        # ⚠️ 예전엔 `"tw_per_rows(" in seg` 로 쟀는데, 디스패치 테이블로
        # 리팩터하자(`{"TW": (tw_per_rows, ...)}`) 괄호가 사라져 깨졌다 —
        # 계약은 "직접 PER 원천을 태우고 밴드는 assemble 로 만든다"이지
        # 특정 표현이 아니다(#19). **이름 참조**로 본다.
        names = {n.id for n in ast.walk(ft) if isinstance(n, ast.Name)}
        assert {"tw_per_rows", "baidu_per_rows", "assemble"} <= names, names

    # ── (2) 적자 기업: PER 이 없다고 PBR 을 죽이지 말 것 ──────────────
    @staticmethod
    def _skc_band():
        import datetime as _dt
        ts = [int(_dt.datetime(2022 + i // 12, 1 + i % 12, 1,
                               tzinfo=_dt.timezone.utc).timestamp() * 1000)
              for i in range(48)]
        return {
            # 적자라 FnGuide 가 PER 밴드선을 0(정의 불가)으로 보낸다
            "per": {"mult": [50.6, 33.7, 16.9, 0.0],
                    "price": [[t, 90000.0 + i * 500] for i, t in enumerate(ts)],
                    "bands": [[[t, (41577.0 if i < 2 else 0.0)]
                               for i, t in enumerate(ts)], [], [], []]},
            "pbr": {"mult": [4.0, 3.2, 2.4, 1.6],
                    "price": [[t, 90000.0 + i * 500] for i, t in enumerate(ts)],
                    "bands": [[[t, 218601.0 - i * 2000]
                               for i, t in enumerate(ts)], [], [], []]}}

    def test_missing_per_does_not_kill_pbr(self):
        """화면의 PBR 차트는 멀쩡한데 표만 사라져 "왜 안 나와?"가 됐다."""
        from bot.dashboard_server import _kr_band_tables
        per, pbr = _kr_band_tables(self._skc_band())
        assert per is None, "이 픽스처는 PER 이 없는 상황이어야 한다"
        assert pbr is not None and len(pbr["rows"]) == 48, pbr

    def test_live_price_still_fetched_when_only_pbr_has_rows(self):
        """PER 이 비었다고 PBR 요약이 현재가를 잃으면 안 된다."""
        import bot.per_band as pb
        from bot.dashboard_server import _kr_band_tables
        calls = []
        orig = pb.live_price
        pb.live_price = lambda t, ref=None: (calls.append(t), 83400.0)[1]
        try:
            _per, pbr = _kr_band_tables(self._skc_band(), "011790.KS")
        finally:
            pb.live_price = orig
        assert len(calls) == 1, calls
        assert pbr["summary"]["per_now_basis"] == "live", pbr["summary"]

    def test_screen_says_why_the_per_table_is_missing(self):
        """조용히 비우면 "왜 안 나와?"가 된다(#43)."""
        from bot.dashboard import _BAND_JS
        assert "PER 밴드를 만들 수 없습니다" in _BAND_JS
        # 사유는 표가 **없을 때만** — 있는데 띄우면 잡음이다
        i = _BAND_JS.index("function perTable")
        seg = _BAND_JS[i:i + 700]
        assert "if(!t){ el.innerHTML = why" in seg, seg[:400]


class TestTtmMissingReason20260822:
    """사용자 2026-08-22 603259.SS: "매출액이 비는건 왜 그런거야?"

    ⚠️ 25.3Q 매출이 원천에 없어 4분기 합이 안 되고 TTM 매출·PSR 이 통째로
    비었는데 **화면이 아무 말도 안 했다**. FCF·수주잔고는 이미 사유를 적고
    있었는데 TTM 만 침묵했다(#43·#129 — 이 세션에서 다섯 번째)."""

    @staticmethod
    def _qs(gap=None):
        out = []
        for i in range(1, 5):
            f = {"매출": 10.0, "영업이익": 2.0, "당기순이익": 1.0}
            if gap and i == gap[0]:
                f[gap[1]] = None
            out.append({"label": f"25.{i}Q", "financials": f})
        return out

    def test_reason_names_the_quarter_and_the_metric(self):
        from bot.quarterly_infographic import ttm_missing_why
        why = ttm_missing_why(self._qs((3, "매출")))
        assert set(why) == {"매출"}, why
        assert "25.3Q" in why["매출"], why["매출"]

    def test_reason_and_value_are_exact_opposites(self):
        """⚠️ 판정을 두 곳에 적으면 언젠가 갈라진다(#38) — `_ttm` 이 만든
        항목엔 사유가 없고, 안 만든 항목엔 **반드시** 있어야 한다."""
        from bot.quarterly_infographic import _TTM_KEYS, _ttm, ttm_missing_why
        anom = self._qs()
        anom[2]["financials"]["_anomaly_revenue_negative"] = True
        cases = (self._qs(), self._qs((1, "매출")), self._qs((4, "당기순이익")),
                 self._qs((2, "영업이익")), self._qs()[:3],
                 anom)          # ⚠️ 이상치 분기도 태워야 그 분기가 안 눈먼다
        assert "매출" in ttm_missing_why(anom), "이상치 픽스처가 안 걸렸다"
        for qs in cases:
            made, why = set(_ttm(qs)), set(ttm_missing_why(qs))
            assert made.isdisjoint(why), (made, why)
            assert made | why == set(_TTM_KEYS), (made, why)

    def test_short_sample_says_how_many_it_has(self):
        from bot.quarterly_infographic import ttm_missing_why
        why = ttm_missing_why(self._qs()[:2])
        assert len(why) == 3 and "2개" in why["매출"], why

    def test_footnote_is_rendered_and_mentions_psr(self):
        from bot.quarterly_infographic import _footnotes
        txt = " ".join(t for t, _c in _footnotes(
            {"ttm_why": {"매출": "25.3Q 원천 미제공(4분기 합 불가)"},
             "currency": "CNY"}, []))
        assert "TTM 매출 미표시" in txt, txt
        assert "PSR 산출 제외" in txt, txt

    def test_no_note_when_nothing_is_missing(self):
        """잡음 금지 — 뺀 게 없으면 각주도 없다.

        ⚠️ '미표시' 부재로만 재면 **빈 join** 이 단언을 우회한다(사유 없이
        각주만 붙는 뮤테이션이 통과했다) — 그 각주에만 있는 꼬리말을 집는다."""
        from bot.quarterly_infographic import _footnotes
        txt = " ".join(t for t, _c in _footnotes({"currency": "CNY"}, []))
        assert "부분합으로 대체하지 않음" not in txt, txt

    def test_payload_carries_the_reason(self):
        """헬퍼만 만들고 배선이 빠지면 화면은 그대로다(#20)."""
        import ast
        src = open("bot/quarterly_infographic.py", encoding="utf-8").read()
        assert '"ttm_why": ttm_missing_why(qs)' in src, "payload 배선 누락"
        ast.parse(src)


class TestLazyPaneTickerAndProbeArgs20260822:
    """사용자 2026-08-22: (1) SIE.DE 밴드 탭에 **"bad ticker"** 라는 원시 API
    오류가 그대로 떴다 (2) JP 프로브 v1 이 세 종목 모두 같은 사유를 냈다.

    ⚠️ (1) `NOAH_TICKER` 는 라이브 quote 뿐 아니라 **모든 지연 pane** 이 쓰는
    주소인데 full 단계에서만 방출됐다 — enrichment 가 실패해 core 만 남으면
    `tkr()` 이 빈 문자열이 되고 `/api/band?ticker=` 가 400 을 돌려줬다.
    ⚠️ (2) 프로브가 `for_ticker` 를 **스냅샷 없이** 불렀다. 비-KR EPS 는
    스냅샷에서 꺼내므로 결과가 원천이 아니라 프로브가 만든 것이었다(#35)."""

    def test_ticker_is_emitted_even_without_enrichment(self):
        """core 단계에서도 티커는 아는 값이다 — 지연 pane 이 주소를 잃으면 안 된다."""
        import ast
        src = open("bot/dashboard.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "render_lookup_detail")
        seg = ast.get_source_segment(src, fn) or ""
        i = seg.index("quote_script = ")
        blk = seg[i:i + 400]
        assert "NOAH_TICKER" in blk
        assert "and enrich" not in blk, "티커가 아직 full 단계에 묶여 있다"
        # 무거운 오버레이만 full 로 남아야 한다
        assert "_QUOTE_JS if enrich" in blk, blk

    def test_band_pane_does_not_call_with_an_empty_ticker(self):
        """빈 티커로 부르면 서버가 'bad ticker' 를 돌려주고 그 원시 문자열이
        화면에 그대로 뜬다(#43 사유는 사람 말로)."""
        from bot.dashboard import _BAND_JS
        i = _BAND_JS.index("function load()")
        seg = _BAND_JS[i:i + 700]
        assert "if(!tkr())" in seg, seg[:300]
        # 가드가 fetch **앞**에 있어야 의미가 있다
        assert seg.index("if(!tkr())") < seg.index("fetch("), seg[:400]

    def test_probe_passes_the_snapshot_like_the_screen_does(self):
        """경로만 같고 인자가 다르면 통계가 거짓이 된다(#35)."""
        import ast
        src = open("bot/scripts/fundamentals_probe.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "_current_path")
        call = next(n for n in ast.walk(fn)
                    if isinstance(n, ast.Call)
                    and getattr(n.func, "id", "") == "for_ticker")
        assert len(call.args) >= 2, "스냅샷을 안 넘긴다"
        seg = ast.get_source_segment(src, fn) or ""
        assert "collect_stock_snapshot" in seg
        # 어느 단계에서 끊기는지 보이게 — 스냅샷 EPS 개수를 찍는가
        assert "_eps_rows_from_snapshot" in seg

    def test_probe_version_was_bumped(self):
        """도구 출력이 바뀌었는데 배너가 그대로면 옛 실행과 구별이 안 된다(#21)."""
        import bot.scripts.fundamentals_probe as jp
        assert jp._PROBE_VER >= 2


class TestEmptyChartPanelsAndJpProbe20260822:
    """사용자 2026-08-22 9984.T: "일본기업은 EPS 이력이 없기에 밴드차트나,
    분기실적 서포트가 불가능한거야?"

    ⚠️ 화면 결함 하나 + 진단 도구 하나. 화면은 밴드가 **아예 없을 때** 'PER
    밴드 / PBR 밴드' 제목만 남아 수집 실패로 읽혔다 — 예전 숨김 로직이
    `draw()` 안에만 있어 `CD` 가 없으면 돌지 않았다."""

    def test_grid_is_hidden_when_there_is_no_band_at_all(self):
        from bot.dashboard import _BAND_JS
        assert "function showGrid(" in _BAND_JS, "차트 자리 숨김 배선이 없다"
        # 밴드가 없는 응답 경로에서 **호출**돼야 한다 — 정의만으론 안 돈다(#120)
        assert _BAND_JS.count("showGrid(") >= 3, _BAND_JS.count("showGrid(")
        i = _BAND_JS.index("if(!j||!j.ok||!j.band)")
        assert "showGrid(false)" in _BAND_JS[i:i + 200], _BAND_JS[i:i + 200]

    def test_probe_distinguishes_blocked_from_missing(self):
        """⚠️ yfinance 는 네트워크가 막히면 예외 대신 **빈 프레임**을 준다 —
        그걸 '원천 미제공'으로 읽으면 진단 도구가 거짓말한다(샌드박스 실측:
        AAPL 도 0열이었다, #86). 대조군이 죽었으면 **판정 불가**여야 한다."""
        import bot.scripts.fundamentals_probe as jp
        orig = jp._yf_cols
        try:
            jp._yf_cols = lambda t, a: (0, [])          # 전부 0열 = 차단 상황
            out = "\n".join(jp._yf_shape("9984.T"))
            assert "판정 불가" in out, out
            assert "원천 미제공" not in out, out

            jp._yf_cols = lambda t, a: ((5, ["Diluted EPS"]) if t == "AAPL"
                                        else (0, []))  # 대조군만 정상
            out = "\n".join(jp._yf_shape("9984.T"))
            assert "원천 미제공" in out, out
            assert "판정 불가" not in out, out
        finally:
            jp._yf_cols = orig

    def test_probe_never_prints_the_credential_value(self):
        """자격증명은 **출처와 길이만** — 값 금지(§Secrets·#82)."""
