class TestPerBandAudit20260822:
    """사용자가 다른 사이트를 뒤져 눈으로 대조해야 한다면 그건 화면의 결함이다
    (2026-08-22 "다른 사이트를 찾아본던 어떻게 해서든...너무 힘들다").
    판정을 **감사 도구가 대신**한다(#102c). 판정 로직은 순수 함수라 픽스처로
    동작을 고정한다(#41 — 스크립트에 인라인이면 소스 문자열만 재게 된다)."""

    @staticmethod
    def _tbl(rows, **kw):
        t = {"rows": [{"period": p, "price": px, "eps": e, "per": r}
                      for p, px, e, r in rows],
             "band_from": rows[0][0], "band_to": rows[-1][0],
             "price_now": None, "summary": {}}
        t.update(kw)
        return t

    def test_clean_table_passes_every_axis(self):
        import bot.scripts.per_band_audit as ab
        rows = [(f"20{y:02d}-06-30", 100.0 + y, 5.0, (100.0 + y) / 5.0)
                for y in range(18, 27)]
        marks = dict((a, m) for m, a, _d in ab.audit_rows(
            self._tbl(rows, fiscal_check=("ok", "결산 시점 9개와 일치"))))
        assert marks["산수"] == "✅" and marks["분할"] == "✅", marks
        assert marks["결산검산"] == "✅", marks

    def test_split_break_is_caught(self):
        """LRCX 형 — 주가는 연속인데 EPS 만 10배 튄다."""
        import bot.scripts.per_band_audit as ab
        rows = [("2023-03-31", 51.46, 35.91, 51.46 / 35.91),
                ("2023-06-30", 62.58, 3.32, 62.58 / 3.32),
                ("2023-09-30", 65.0, 3.4, 65.0 / 3.4)]
        got = dict((a, m) for m, a, _d in ab.audit_rows(self._tbl(rows)))
        assert got["분할"] == "❌", got

    def test_fiscal_check_reports_the_products_own_verdict(self):
        """KLAC 형 — 제품이 어긋남을 **감지하고 분기 경로를 폐기**했으면 화면은
        정상이다(✅). 어긋났다고 판정해 놓고 그 분기 경로를 그대로 실었다면
        그건 배선 결함이라 ❌ 다.

        ⚠️ 감사가 연간 대조본을 따로 만들어 재계산하던 옛 판은 제품이 분할
        환산을 되돌린 종목에서 **감사에서만** ❌ 를 냈다(2026-08-22 KLAC 실측,
        #35). 판정은 제품이 하고 감사는 읽는다.
        """
        import bot.scripts.per_band_audit as ab
        rows = [("2024-03-31", 68.55, 19.15, 68.55 / 19.15),
                ("2024-06-30", 81.08, 15.0, 81.08 / 15.0)]
        bad = ("mismatch", "2024-06-30 TTM 15.00 vs 연간 25.00")
        dropped = self._tbl(rows, fiscal_check=bad, basis="edgar-a")
        kept = self._tbl(rows, fiscal_check=bad, basis="edgar")
        assert dict((a, m) for m, a, _d in ab.audit_rows(dropped))["결산검산"] == "✅"
        assert dict((a, m) for m, a, _d in ab.audit_rows(kept))["결산검산"] == "❌"
        skip = self._tbl(rows, fiscal_check=("skipped", "기준이 달라"))
        assert dict((a, m) for m, a, _d in ab.audit_rows(skip))["결산검산"] == "❓"

    def test_audit_does_not_recompute_the_fiscal_check(self):
        """⚠️ 감사가 스스로 대조하면 제품과 다른 기준선을 비교한다(#35) —
        `ttm_annual_mismatch` 를 부르지 않는 것이 계약이다(존재가 아니라
        **호출**로 확인, #120)."""
        import bot.per_band as pb
        import bot.scripts.per_band_audit as ab
        calls = []
        orig = pb.ttm_annual_mismatch
        pb.ttm_annual_mismatch = lambda *a, **k: calls.append(a) or None
        try:
            rows = [("2024-03-31", 68.55, 19.15, 68.55 / 19.15),
                    ("2024-06-30", 81.08, 15.0, 81.08 / 15.0)]
            ab.audit_rows(self._tbl(rows, fiscal_check=("ok", "일치"),
                                    _annual_eps=[("2024-06-30", 25.0)]))
        finally:
            pb.ttm_annual_mismatch = orig
        assert calls == [], calls

    def test_arithmetic_mismatch_is_caught(self):
        """나란히 놓인 칸이 서로 안 맞으면 표가 거짓말이다(#33)."""
        import bot.scripts.per_band_audit as ab
        rows = [("2025-06-30", 100.0, 5.0, 20.0),
                ("2025-09-30", 120.0, 5.0, 99.0)]     # 24.0 이어야 한다
        got = dict((a, m) for m, a, _d in ab.audit_rows(self._tbl(rows)))
        assert got["산수"] == "❌", got

    def test_denominator_basis_is_one_of_the_axes(self):
        """⚠️ 감사에서 축을 통째로 떼면 조용히 안 재게 된다 — 축 목록을
        고정한다(#20 배선은 결과로 확인)."""
        import bot.scripts.per_band_audit as ab
        rows = [(f"2025-{m:02d}-28", 1000.0 + m, 5.0, (1000.0 + m) / 5.0)
                for m in range(1, 10)]
        axes = [a for _m, a, _d in ab.audit_rows(self._tbl(rows))]
        assert "분모 기준" in axes, axes

    def test_no_comparison_data_is_unknown_not_pass(self):
        """⚠️ 대조 0건은 ✅ 가 아니라 ❓ 다(#54) — 내 감사 도구에서 두 번
        어긴 실수다(#132)."""
        import bot.scripts.per_band_audit as ab
        rows = [("2025-06-30", 100.0, 5.0, 20.0)]
        got = dict((a, m) for m, a, _d in ab.audit_rows(self._tbl(rows)))
        assert got["결산검산"] == "❓", got     # 연간 대조본 없음
        assert got["현재값"] == "❓", got       # 실시간 시세 없음
        assert [m for m, a, _d in ab.audit_rows({"rows": []})] == ["❓"]

    def test_live_per_must_be_proportional_to_the_live_price(self):
        """현재 PER 은 이력 마지막 행 기준으로 현재가에 비례한다(#135)."""
        import bot.scripts.per_band_audit as ab
        rows = [("2025-06-30", 100.0, 5.0, 20.0)]
        ok = self._tbl(rows, price_now=110.0, summary={"per_now": 22.0})
        bad = self._tbl(rows, price_now=110.0, summary={"per_now": 20.0})
        assert dict((a, m) for m, a, _d in ab.audit_rows(ok))["현재값"] == "✅"
        assert dict((a, m) for m, a, _d in ab.audit_rows(bad))["현재값"] == "❌"

    def test_audit_uses_the_product_path(self):
        """프로브가 수집을 재구현하면 화면과 다른 걸 잰다(#35) — AST 로 실제
        호출을 센다(이름이 소스에 있는지로 재면 뮤테이션이 통과한다, #143)."""
        import ast
        src = open("bot/scripts/per_band_audit.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "audit_one")
        calls = [c.func.attr for c in ast.walk(fn)
                 if isinstance(c, ast.Call) and isinstance(c.func, ast.Attribute)]
        names = [c.func.id for c in ast.walk(fn)
                 if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)]
        # ⚠️ 2026-08-23: 화면이 국내를 FnGuide 로 그리므로 감사도 **공용
        # 해석기**를 타야 같은 걸 잰다(#176). `for_ticker` 직접 호출은 금지.
        assert "_resolve" in names, (names, calls)
        assert "for_ticker" not in calls, calls
        assert "collect_stock_snapshot" in names, names

    def test_product_publishes_its_fiscal_verdict(self):
        """제품이 판정을 payload 에 싣지 않으면 감사는 영원히 ❓ 다 — 배선을
        AST 로 못박는다(`res["fiscal_check"]` 대입이 실재하는가)."""
        import ast
        src = open("bot/per_band.py", encoding="utf-8").read()
        keys = [t.slice.value for n in ast.walk(ast.parse(src))
                if isinstance(n, ast.Assign)
                for t in n.targets
                if isinstance(t, ast.Subscript)
                and isinstance(t.slice, ast.Constant)]
        assert "fiscal_check" in keys, "제품이 결산검산 판정을 안 싣는다"


class TestWatchlistAndBandNote20260822:
    """사용자 2026-08-22 (관심종목 캡처 + 밴드 표 캡처):
      ① "관심종목이 너무 자주 꺼져 … 5분 간격으로 하면 어떨까?"
      ② "예상 EPS 를 현재 PER 로 바꿔줘"
      ③ "밴드차트 밑에 적어논 구간을 좀 더 예쁘게"
      ④ "한국은 한달단위로 계산하지만 4년 평균·최저·최고는 실제 분기발표 기준인거지?"
    """

    # ── ① 재시작해도 표가 비지 않는다 ────────────────────────────────
    def test_snapshot_survives_a_restart_and_carries_its_as_of(
            self, monkeypatch, tmp_path):
        """캐시가 **메모리 전용**이라 봇이 재시작될 때마다 139종목이 통째로
        `—` 가 됐다. 마지막 성공분을 디스크에 남기되, 낡은 값을 '현재'로
        내보내지 않도록 **기준시각을 같이** 싣는다(#43)."""
        import time
        import bot.market_favorites as mf
        monkeypatch.setattr(mf, "_FAVORITES_FILE",
                            tmp_path / "market_favorites.json")
        monkeypatch.setattr(mf, "_FAV_CACHE", None)
        monkeypatch.setattr(mf, "_kick_fav_refresh", lambda: None)
        # 목록(순서·구성)은 **디스크가 정본**이다 — 스냅샷은 휘발성 값만 채운다
        monkeypatch.setattr(mf, "_load", lambda: [
            {"ticker": "AAPL", "name": "Apple"},
            {"ticker": "MSFT", "name": "Microsoft"}])
        rows = [{"ticker": "AAPL", "current_price": 300.0, "per": 30.0},
                {"ticker": "GONE", "current_price": 1.0}]
        mf._snapshot_save(rows, time.time())
        got = mf.get_favorites_with_prices()
        assert [g["ticker"] for g in got] == ["AAPL", "MSFT"], got
        assert got[0]["current_price"] == 300.0, got
        assert got[0].get("as_of"), "기준시각을 안 실었다"
        # ⚠️ 지운 종목이 스냅샷에서 되살아나면 안 된다
        assert all(g["ticker"] != "GONE" for g in got), got
        # 스냅샷에 없는 종목은 빈칸(옛 값을 지어내지 않는다)
        assert got[1].get("current_price") is None, got[1]

    def test_a_successful_refresh_writes_the_snapshot(self):
        """스냅샷을 안 쓰면 재시작 때 또 빈다 — **쓰는 배선**을 못박는다."""
        import ast
        src = open("bot/market_favorites.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_compute_favorites_with_prices")
        calls = {c.func.id for c in ast.walk(fn)
                 if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)}
        assert "_snapshot_save" in calls, calls

    def test_stale_snapshot_is_not_served_as_current(self, monkeypatch,
                                                     tmp_path):
        """⚠️ 너무 낡은 스냅샷은 안 쓴다 — 2026-08-20 감사에서 '현재가 None
        인데 PER 은 몇 달 전 값'이던 그 사고의 재발 방지."""
        import time
        import bot.market_favorites as mf
        monkeypatch.setattr(mf, "_FAVORITES_FILE",
                            tmp_path / "market_favorites.json")
        mf._snapshot_save([{"ticker": "AAPL", "current_price": 1.0}],
                          time.time() - mf._SNAP_MAX_AGE - 60)
        assert mf._snapshot_load() == (None, 0.0)

    def test_refresh_loop_runs_every_five_minutes(self):
        """Automation-first — 운영자가 반복 명령을 칠 일이 없어야 한다."""
        import ast
        src = open("bot/telegram_bot.py", encoding="utf-8").read()
        tree = ast.parse(src)
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.AsyncFunctionDef)
                  and n.name == "_periodic_favorites_refresh")
        seg = ast.get_source_segment(src, fn) or ""
        assert "asyncio.sleep(300)" in seg, seg[:200]
        assert "_compute_favorites_with_prices" in seg, seg[:200]
        # 정의만 있고 **호출이 없으면** 루프는 안 돈다(#120 정의 1 + 호출 1)
        assert src.count("_periodic_favorites_refresh") >= 2, "배선 누락"

    # ── ② 현재 PER 열 ────────────────────────────────────────────────
    def test_trailing_per_is_derived_from_the_shown_price(self):
        """나란히 놓인 칸은 산수가 맞아야 한다(#33) — 현재 PER 도 **화면의
        현재가**에서 만든다. 소스 PER 을 쓰면 눈으로 나눠 봐서 안 맞는다."""
        import ast
        src = open("bot/market_favorites.py", encoding="utf-8").read()
        assert "per_trailing" in src and "eps_trailing" in src
        tree = ast.parse(src)
        assigns = [n for n in ast.walk(tree) if isinstance(n, ast.Assign)]
        got = [a for a in assigns
               if isinstance(a.targets[0], ast.Subscript)
               and isinstance(a.targets[0].slice, ast.Constant)
               and a.targets[0].slice.value == "per_trailing"]
        assert got, "per_trailing 을 안 만든다"
        seg = ast.get_source_segment(src, got[0]) or ""
        assert "_per_from_shown" in seg and "current_price" in seg, seg

    def test_screen_shows_trailing_per_not_forward_eps(self):
        src = open("bot/dashboard.py", encoding="utf-8").read()
        assert "'현재 PER'" in src, "열 제목이 안 바뀌었다"
        assert "'예상 EPS'" not in src, "예상 EPS 열이 남아 있다"
        assert "per_trailing" in src, "값을 안 읽는다"
        # 휘발성 필드로 등록돼야 콜드 로드에서 옛 값이 '현재'로 안 나간다
        import bot.market_favorites as mf
        assert "per_trailing" in mf._VOLATILE_FIELDS
        assert "eps_trailing" in mf._VOLATILE_FIELDS

    # ── ③④ 밴드 표 밑 구간 ──────────────────────────────────────────
    def test_band_note_is_chips_not_a_run_on_line(self):
        src = open("bot/dashboard.py", encoding="utf-8").read()
        i = src.index("var chips=[]")
        seg = src[i:i + 1600]
        for k in ("'기간'", "'기준'", "'그 배수에서의 주가'"):
            assert k in seg, (k, seg[:400])
        assert "border-radius:999px" in seg, "칩 모양이 아니다"

    def test_kr_band_says_its_basis_is_the_source_not_our_observations(self):
        """⚠️ KR 밴드 4선은 **FnGuide 가 준 값**(분기 실적 기준)이다 — 화면이
        '관측 N개 분포'라고 적으면 거짓말이다(#55). 요약(월말 관측)과 기준이
        다르므로 라벨로 구분한다(#34)."""
        import bot.dashboard_server as ds
        # ⚠️ 원천 키는 `bands`(밴드선 4계열)다 — 픽스처가 형식을 틀리면
        # 표가 안 만들어지고 테스트가 skip 되어 **아무것도 안 재게 된다**(#54).
        ts = [1590000000000 + i * 2592000000 for i in range(50)]
        blk = {"mult": [52.1, 38.3, 24.5, 10.7],
               "price": [[t_, 100000.0 + i * 1000] for i, t_ in enumerate(ts)],
               "bands": [[[t_, 200000.0] for t_ in ts]]}
        t = ds._fnguide_ratio_table(blk, kind="PER", px_now=187000.0)
        assert t is not None, "픽스처가 원천 형식과 다르다"
        assert t.get("band_basis"), "기준 라벨이 없다"
        assert "FnGuide" in t["band_basis"] and "분기" in t["band_basis"], \
            t["band_basis"]
        js = open("bot/dashboard.py", encoding="utf-8").read()
        assert "t.band_basis" in js, "화면이 그 라벨을 안 쓴다"


class TestBandDenominatorBasis20260822:
    """사용자 2026-08-22: "우리가 기준으로 삼는 이 월단위 주가에 따른 PER 나
    PBR 의 변화가 맞는걸까? … 혹시 분기단위로 하는게 맞지 않을까? 실제 FnGuide
    밴드차트나 네이버 밴드차트는 어떻게 하는지 보고 리뷰해줘."

    화면 값으로 되짚으니 EPS 가 **매달 +81~82 로 완벽히 선형**이었다 — 분기
    확정 실적이면 3개월마다 계단처럼 뛰어야 한다. 즉 원천 밴드선의 분모는
    분기 확정치가 아니다. ⚠️ 나는 그 직전 라운드에 **근거 없이** "분기 실적
    기준" 이라고 라벨을 붙였다 — 원천이 무엇을 쓰는지는 **재서** 말해야
    한다(#55·#34).
    """

    # 사용자 화면(2026-08-22)의 실제 값 — 지어내지 않는다.
    _SCREEN = [("2026-01-30", 33400, 15.28), ("2026-02-27", 34250, 15.10),
               ("2026-03-31", 27000, 11.49), ("2026-04-30", 29850, 12.28),
               ("2026-05-29", 23850, 9.49), ("2026-06-30", 19250, 7.42),
               ("2026-07-31", 16590, 6.20), ("2026-08-22", 26850, 9.74)]

    @classmethod
    def _rows(cls):
        return [{"period": d, "price": px, "per": pr}
                for d, px, pr in cls._SCREEN]

    def test_implied_eps_is_backed_out_of_the_source(self):
        from bot.per_band import implied_eps_series
        eps = implied_eps_series(self._rows())
        assert len(eps) == 8
        # 매달 +81~82 — 계단이 아니다
        diffs = [round(b - a) for (_p, a), (_q, b) in zip(eps, eps[1:])]
        assert all(80 <= d <= 83 for d in diffs), diffs

    def test_real_screen_values_are_judged_continuous(self):
        from bot.per_band import eps_cadence
        cad, why = eps_cadence(self._rows())
        assert cad == "연속형", (cad, why)
        assert "매달" in why, why

    def test_quarterly_stepped_source_is_judged_stepwise(self):
        """반대 증거도 같이 둔다 — '있다'만 묻는 검사는 눈이 먼다(#25)."""
        from bot.per_band import eps_cadence
        rows = [{"period": f"2025-{m:02d}-28", "price": 1000 + m,
                 "per": (1000 + m) / (100 if m < 5 else 110)}
                for m in range(1, 10)]
        cad, why = eps_cadence(rows)
        assert cad == "계단형", (cad, why)

    def test_too_few_points_is_unknown_not_a_guess(self):
        """⚠️ 대조 대상이 모자라면 ✅ 가 아니라 판정 불가다(#54)."""
        from bot.per_band import eps_cadence
        assert eps_cadence(self._rows()[:3])[0] is None

    def test_screen_label_is_measured_not_asserted(self):
        """라벨이 측정 결과를 따라야 한다 — 계단형·연속형에 따라 달라진다."""
        import bot.dashboard_server as ds
        cont = ds._kr_band_basis_note(self._rows())
        step_rows = [{"period": f"2025-{m:02d}-28", "price": 1000 + m,
                      "per": (1000 + m) / (100 if m < 5 else 110)}
                     for m in range(1, 10)]
        step = ds._kr_band_basis_note(step_rows)
        assert cont != step, (cont, step)
        # ⚠️ 부분문자열은 사유 설명에도 걸린다("분기 확정치가 **아니라**") —
        # **주장하는 라벨**(괄호 안)을 집어야 한다(#65 구조로 볼 것).
        # ⚠️ 부분문자열은 사유 설명에도 걸린다("분기 확정치가 **아니라**") —
        # 분모를 **주장하는 자리**(`분모 = …`)를 잘라서 본다(#65 구조로 볼 것).
        # 그리고 문구 리터럴을 박으면 다듬을 때마다 깨진다(#19) — 2026-08-23
        # 에 실제로 깨졌다. 계약은 "두 판정이 다른 분모를 말한다"이다.
        def _denom(note):
            return note.split("분모 = ", 1)[1].split(" · ")[0]
        assert "분기 확정" in _denom(step), step
        assert "분기 확정" not in _denom(cont), cont
        assert "매달 갱신" in _denom(cont), cont
        assert ds._kr_denom_label(self._rows()) != \
            ds._kr_denom_label(step_rows)

    def test_render_uses_the_source_denominator_label(self):
        """화면이 'TTM EPS' 라고 우기면 안 된다 — 원천이 정한다.

        ⚠️ 이름이 소스에 **있는지**로 재면 `if(false)` 로 죽이는 뮤테이션이
        통과한다(실측) — 조건이 그 값을 실제로 보는지까지 확인한다."""
        import re
        from bot.dashboard import _BAND_JS
        m = re.search(r"if\s*\(([^)]*)\)\s*denom\s*=\s*t\.denom_label",
                      _BAND_JS)
        assert m, "원천 분모 라벨을 안 쓴다"
        assert "denom_label" in m.group(1), m.group(1)

    def test_payload_carries_the_measured_labels(self):
        """⚠️ 헬퍼만 직접 부르면 **배선을 떼는 뮤테이션을 못 잡는다**(#20) —
        payload 에 측정 결과가 실려 나오는지 본다."""
        import bot.dashboard_server as ds
        ts = [1590000000000 + i * 2592000000 for i in range(50)]
        # 되짚은 EPS 가 매달 바뀌는(연속형) 원천을 흉내낸다
        blk = {"mult": [90.8, 63.4, 36.1, 8.7],
               "price": [[t_, 30000.0 + i * 300] for i, t_ in enumerate(ts)],
               "bands": [[[t_, 200000.0 + i * 7000] for i, t_ in enumerate(ts)]]}
        t = ds._fnguide_ratio_table(blk, kind="PER", px_now=26850.0)
        assert t is not None
        assert "매달 갱신" in (t.get("band_basis") or ""), t.get("band_basis")
        assert t.get("denom_label") == "원천 EPS(매달 갱신)", t.get("denom_label")

    def test_the_reason_travels_to_the_screen_not_just_the_label(self):
        """#188b — 사용자 2026-08-23 "이것도 이해가 잘 안가.. 특히 밴드차트
        설명": 판정 사유를 이미 계산해 두고 라벨만 싣고 있었다(#123·#129 에
        이은 세 번째). 라벨보다 길고, 화면이 툴팁으로 실어야 한다."""
        import re
        import bot.dashboard_server as ds
        from bot.dashboard import _BAND_JS
        why = ds._kr_band_basis_why(self._rows())
        assert len(why) > len(ds._kr_band_basis_note(self._rows())), why
        # 측정한 것만 말한다 — 무엇으로 갱신하는지는 재지 않았다(#165)
        assert "컨센서스" not in why, why
        ts = [1590000000000 + i * 2592000000 for i in range(50)]
        blk = {"mult": [90.8, 63.4, 36.1, 8.7],
               "price": [[t_, 30000.0 + i * 300] for i, t_ in enumerate(ts)],
               "bands": [[[t_, 200000.0 + i * 7000] for i, t_ in enumerate(ts)]]}
        t = ds._fnguide_ratio_table(blk, kind="PER", px_now=26850.0)
        assert t.get("band_basis_why"), "payload 가 사유를 안 싣는다"
        # 배선은 존재가 아니라 **쓰이는지**로(#141) — 칩에 실리고 title 로 나간다
        m = re.search(r"chips\.push\(\['기준',[^\]]*\]\)", _BAND_JS, re.S)
        assert m and "band_basis_why" in m.group(0), (m.group(0) if m else None)
        assert 'title="' in _BAND_JS, "툴팁을 안 그린다"


    def test_the_reason_is_visible_not_only_a_tooltip(self):
        """사용자 2026-08-23(삼양식품) "원천 EPS 라는게 정확히 이해가 안가"
        — 사유를 **툴팁에만** 실어 두면 캡션을 읽은 사용자는 못 본다(같은
        계열 질문 네 번째: #123 계정불일치 · #129 수주잔고 · #131 FCF 빈칸
        · #189 이 칩). 캡션 블록이 사유를 **보이는 줄**로 그리는지 본다.

        ⚠️ 소스에 이름이 **있는지**로 재면 칩의 툴팁이 대신 만족시킨다(#75)
        — `h+=` 로 화면에 나가는지, 그리고 그 값을 조건으로 보는지까지.
        ⚠️ 고정 길이 창으로 재면 옆 함수가 대신 만족시킨다(#60·#174) —
        `perTable` 본문만 중괄호로 잘라서 본다."""
        import re
        from bot.dashboard import _BAND_JS
        i = _BAND_JS.index("function perTable(")
        j = _BAND_JS.index("{", i)
        depth, body = 0, None
        for k in range(j, len(_BAND_JS)):
            if _BAND_JS[k] == "{":
                depth += 1
            elif _BAND_JS[k] == "}":
                depth -= 1
                if depth == 0:
                    body = _BAND_JS[j:k + 1]
                    break
        assert body, "perTable 본문을 못 찾았다"
        vis = re.search(r"h\s*\+=[^;]*band_basis_why[^;]*;", body)
        assert vis, "사유가 보이는 줄로 안 나간다(툴팁만이면 사용자는 못 읽는다)"
        assert "chips.push" not in vis.group(0), vis.group(0)
        # 값이 없을 때만 건너뛴다 — `if(false)` 로 죽이는 뮤테이션 차단
        assert re.search(r"if\s*\(\s*t\.band_basis_why\s*\)", body), body[:200]


class TestBandPeriodAndQ4Sanity20260822:
    """사용자 2026-08-22:
      ① "그 배수에서의 주가 옆에 그 시점도 써줘. 밑에 있는 기간에 나온거 말이야."
      ② LRCX 처럼 EPS 때문에 못 그리는 건 왜인가

    ②의 답: 전 시장 감사의 ❌ 3건이 **전부 회계연도말**이었다(LRCX 2023-06-25
    10.8배 · KLAC 2024-06-30 9.4배 · KLAC 2017-06-30 결산검산). 결산분기는
    10-Q 가 없어 `연간 − 3분기` 로 복원하는데, EDGAR **분기**는 후속 보고서의
    분할 소급조정분이 오고 **연간**은 as-reported 라 스케일이 갈릴 수 있다 —
    그걸 빼면 복원값이 쓰레기가 된다(KLAC 2.03 − 14.12 = **-12.09**).
    """

    def test_implausible_fiscal_q4_is_refused(self):
        from bot.edgar_eps import _plausible_q4
        # KLAC 실측 — 형제가 전부 양수인데 복원값이 큰 음수
        assert _plausible_q4(-12.09, [5.41, 4.28, 4.43]) is False
        # 크기가 형제의 3배를 넘어도 못 믿는다
        assert _plausible_q4(20.0, [5.41, 4.28, 4.43]) is False
        # 정상 복원은 통과
        assert _plausible_q4(10.03, [5.41, 4.28, 4.43]) is True
        # 형제에 적자가 섞였으면 음수 분기는 정당하다
        assert _plausible_q4(-2.0, [5.0, -1.0, 4.0]) is True

    def test_bad_annual_does_not_poison_the_quarterly_series(self):
        """KLAC 형 — 연간이 스케일이 다르면 그 해의 결산분기를 **안 만든다**.
        억지로 채우면 그 한 분기가 TTM 4개 시점을 연달아 오염시킨다."""
        from bot.edgar_eps import fill_fiscal_q4
        q = [("2023-09-30", 5.41, "2023-07-01"),
             ("2023-12-31", 4.28, "2023-10-01"),
             ("2024-03-31", 4.43, "2024-01-01")]
        good = fill_fiscal_q4(q, [("2024-06-30", 24.15, "2023-07-01")])
        assert dict(good)["2024-06-30"] > 0, good
        bad = fill_fiscal_q4(q, [("2024-06-30", 2.03, "2023-07-01")])
        assert "2024-06-30" not in dict(bad), bad
        assert len(bad) == 3, bad          # 나머지 분기는 그대로 남는다

    def test_every_band_multiple_is_a_real_observation(self):
        """⚠️ 선형보간 분위수를 쓰면 중상·중하가 **아무 시점에도 없던 값**이
        되어 '그 시점' 칸이 영영 빈다 — 그리고 '관측 분포'라는 라벨과도
        어긋난다(#32 없는 걸 만들지 말 것)."""
        from bot.per_band import assemble
        rows = [(f"2025-{m:02d}-28", 100.0 + m, 5.0, round((100.0 + m) / 5, 2))
                for m in range(1, 13)]
        got = assemble(rows)
        seen = {r["per"] for r in got["rows"]}
        for b in got["bands"]:
            assert b["mult"] in seen, (b, sorted(seen))
            assert b.get("at"), f"그 시점이 비었다: {b}"
            # 그 시점의 배수가 실제로 그 값이어야 한다
            row = next(r for r in got["rows"] if r["period"] == b["at"])
            assert abs(row["per"] - b["mult"]) < 0.011, (b, row)

    def test_period_is_left_blank_when_no_observation_matches(self):
        """원천이 배수를 직접 주면(KR) 우리 관측과 안 맞을 수 있다 — 멀면
        **비운다**(가까운 걸 조용히 붙이면 우리가 지어낸 시점이 된다).

        ⚠️ 2026-08-23 부터 오차 2% 안쪽은 `approx=True` 로 **밝히고** 준다 —
        비우기만 하면 KR 은 최고·중상·중하가 전부 '—' 였다(사용자 지적)."""
        from bot.per_band import band_period
        obs = [("2025-01-31", 100.0, 5.0, 20.0),
               ("2025-02-28", 110.0, 5.0, 22.0)]
        assert band_period(obs, 20.0) == {"at": "2025-01-31", "approx": False}
        assert band_period(obs, 33.3) is None
        # 같은 배수가 여러 번이면 가장 최근
        obs2 = obs + [("2025-03-31", 100.0, 5.0, 20.0)]
        assert band_period(obs2, 20.0)["at"] == "2025-03-31"

    def test_screen_shows_the_period_column(self):
        from bot.dashboard import _BAND_JS
        assert "그 시점" in _BAND_JS, "열 제목이 없다"
        i = _BAND_JS.index("그 배수에서의 주가</th>")
        assert "그 시점" in _BAND_JS[i:i + 200], _BAND_JS[i:i + 200]
        assert "b.at" in _BAND_JS, "값을 안 읽는다"

    def test_kr_bands_carry_the_period_too(self):
        """전 시장 동일 — KR 도 같은 칸을 채운다(있으면)."""
        import bot.dashboard_server as ds
        ts = [1590000000000 + i * 2592000000 for i in range(50)]
        blk = {"mult": [90.8, 63.4, 36.1, 8.7],
               "price": [[t_, 30000.0 + i * 300] for i, t_ in enumerate(ts)],
               "bands": [[[t_, 200000.0 + i * 7000] for i, t_ in enumerate(ts)]]}
        t = ds._fnguide_ratio_table(blk, kind="PER", px_now=26850.0)
        assert t is not None
        assert all("at" in b for b in t["bands"]), t["bands"]


class TestBandGapAndEdinetIdentity20260822:
    """2026-08-22 전 시장 감사 3라운드에서 남은 셋.

      ① LRCX ❌ 분할 — `2023-03-26 → 2024-06-30` 이 '인접'으로 비교됐다.
         **15개월** 떨어진 두 점인데(결산분기 복원을 폐기하니 연속 4분기
         규칙이 그 해 TTM 을 통째로 뺐다) 그 사이 EPS 변동은 실적이다.
      ② 소니 6758.T — 문서 12건이 전부 220/180/350 이고 有報(120)가 없다.
         `secCode` 만 열쇠로 쓰면 그 칸이 빈 문서를 통째로 놓치고, 목록을
         **못 받은 날**은 빈 날과 구별되지 않는다(#143).
    """

    # ── ① 간격이 벌어진 자리에서 인접을 끊는다 ──────────────────────────
    def test_typical_gap_is_the_series_median(self):
        from bot.per_band import typical_gap_days
        q = ["2024-03-31", "2024-06-30", "2024-09-30", "2024-12-31"]
        assert 85 <= typical_gap_days(q) <= 95
        assert typical_gap_days(["2024-12-31"]) is None

    def test_a_hole_in_the_series_is_not_an_adjacency(self):
        """LRCX 실측 형태 — 분기 계열에 15개월 구멍이 뚫려 있다."""
        from bot.per_band import trim_at_eps_break
        rows = [("2022-09-25", 30.0), ("2022-12-25", 32.0),
                ("2023-03-26", 35.91),
                # ← 여기 15개월 구멍(결산분기 복원 폐기로 TTM 이 안 만들어졌다)
                ("2024-06-30", 3.32), ("2024-09-29", 3.4),
                ("2024-12-29", 3.5)]
        kept, why = trim_at_eps_break(rows)
        assert why is None, why
        assert len(kept) == len(rows)

    def test_a_real_adjacent_break_is_still_cut(self):
        """⚠️ 가드를 느슨하게 할 땐 **무엇이 여전히 잡히는가**를 같이 못박는다
        (#57) — 정상 간격에서 튀면 그대로 잘라야 한다."""
        from bot.per_band import trim_at_eps_break
        rows = [("2022-09-25", 30.0), ("2022-12-25", 32.0),
                ("2023-03-26", 35.91), ("2023-06-25", 3.32),
                ("2023-09-24", 3.4), ("2023-12-24", 3.5)]
        kept, why = trim_at_eps_break(rows)
        assert why and "35.9" not in str(kept), (kept, why)
        assert [p for p, _ in kept] == ["2023-06-25", "2023-09-24",
                                        "2023-12-24"]

    # ── ② EDINET: 회사는 EDINET 코드로도 식별된다 ──────────────────────
    def test_docs_without_a_seccode_are_matched_by_edinet_code(self, monkeypatch):
        import bot.edinet_xbrl as ex

        class _Cl:
            def _fetch_day(self, day):
                if day.isoformat() == "2026-07-10":
                    return [{"secCode": "67580", "edinetCode": "E01777",
                             "docTypeCode": "220", "docID": "S1",
                             "submitDateTime": "2026-07-10 09:00"}]
                if day.isoformat() == "2026-06-20":
                    # 원천이 증권코드 칸을 안 채운 유가증권보고서
                    return [{"secCode": None, "edinetCode": "E01777",
                             "docTypeCode": "120", "docID": "S2",
                             "submitDateTime": "2026-06-20 09:00",
                             "periodEnd": "2026-03-31", "filerName": "ソニー"}]
                return []

        import datetime as _dt
        days = [_dt.date(2026, 7, 10), _dt.date(2026, 6, 20)]
        import time as _t
        got = ex._scan_days(_Cl(), "6758", days, want=2, t0=_t.time(),
                            budget_s=999.0, progress=None, label="t")
        assert [d["doc_id"] for d in got] == ["S2"], got

    def test_a_foreign_company_is_not_swept_in_by_edinet_code(self, monkeypatch):
        """⚠️ 열쇠를 넓히면 남의 문서를 잡을 수 있다 — 증권코드로 **한 번도**
        맞은 적 없는 EDINET 코드는 인정하지 않는다."""
        import bot.edinet_xbrl as ex
        import datetime as _dt

        class _Cl:
            def _fetch_day(self, day):
                return [{"secCode": None, "edinetCode": "E99999",
                         "docTypeCode": "120", "docID": "X1",
                         "submitDateTime": "2026-06-20 09:00"}]

        import time as _t
        got = ex._scan_days(_Cl(), "6758", [_dt.date(2026, 6, 20)], want=2,
                            t0=_t.time(), budget_s=999.0, progress=None,
                            label="t")
        assert got == [], got

    # ── ② 목록을 '못 받은 날'은 '빈 날'이 아니다 ───────────────────────
    def test_a_failed_day_is_recorded_not_silently_empty(self, monkeypatch, tmp_path):
        import bot.edinet_client as ec
        import datetime as _dt
        monkeypatch.setattr(ec, "_CACHE_DIR", tmp_path)
        tries = []

        def _get(url, timeout=None):
            tries.append(timeout)
            raise RuntimeError("timed out")

        monkeypatch.setattr(ec.requests, "get", _get)
        cl = ec.EdinetClient(api_key="k")
        assert cl._fetch_day(_dt.date(2026, 6, 26)) == []
        # 짧은 상한으로 한 번, 넉넉한 상한으로 한 번 — 6월 말 목록은 수 MB 다.
        assert len(tries) == 2 and tries[1] > tries[0], tries
        assert "2026-06-26" in cl.failed_days, cl.failed_days

    def test_a_retry_that_succeeds_clears_the_failure(self, monkeypatch, tmp_path):
        import bot.edinet_client as ec
        import datetime as _dt
        monkeypatch.setattr(ec, "_CACHE_DIR", tmp_path)
        seen = []

        class _R:
            def raise_for_status(self):
                pass

            def json(self):
                return {"results": [{"docID": "A"}]}

        def _get(url, timeout=None):
            seen.append(timeout)
            if len(seen) == 1:
                raise RuntimeError("timed out")
            return _R()

        monkeypatch.setattr(ec.requests, "get", _get)
        cl = ec.EdinetClient(api_key="k")
        assert cl._fetch_day(_dt.date(2026, 6, 26)) == [{"docID": "A"}]
        assert cl.failed_days == {}, cl.failed_days

    def test_zero_overlap_fiscal_check_is_unknown_not_pass(self):
        """⚠️ `ttm_annual_mismatch` 는 대조할 게 없어도 None 이다 — 그걸 '✅
        일치'로 옮기면 **대조 0건이 통과로 찍힌다**(#54). 20-F 제출사가 정확히
        그 경우다(분기 프레임이 아예 없다)."""
        import bot.per_band as pb
        import bot.scripts.per_band_audit as ab
        ann = [("2025-06-30", 5.0)]
        assert pb.ttm_annual_mismatch([], ann) is None      # 사유는 안 준다
        assert pb.ttm_annual_overlap([], ann) == 0          # 그런데 0건이다
        assert pb.ttm_annual_overlap([("2025-06-30", 5.0)], ann) == 1
        rows = [{"period": "2025-06-30", "price": 100.0, "eps": 5.0,
                 "per": 20.0}]
        t = {"rows": rows, "band_from": "2025-06-30", "band_to": "2025-06-30",
             "summary": {}, "basis": "edgar-a",
             "fiscal_check": ("none", "겹치는 결산일이 0개 — 대조 불가")}
        assert dict((a, m) for m, a, _d in ab.audit_rows(t))["결산검산"] == "❓"

    def test_a_4xx_is_not_retried(self, monkeypatch, tmp_path):
        """상한을 늘려도 안 고쳐지는 실패는 다시 묻지 않는다(#72)."""
        import bot.edinet_client as ec
        import datetime as _dt
        import requests
        monkeypatch.setattr(ec, "_CACHE_DIR", tmp_path)
        tries = []

        class _R:
            status_code = 403

            def raise_for_status(self):
                raise requests.exceptions.HTTPError(response=self)

        def _get(url, timeout=None):
            tries.append(timeout)
            return _R()

        monkeypatch.setattr(ec.requests, "get", _get)
        cl = ec.EdinetClient(api_key="k")
        assert cl._fetch_day(_dt.date(2026, 6, 26)) == []
        assert len(tries) == 1, tries
        assert "2026-06-26" in cl.failed_days, cl.failed_days


class TestBandNoteRoeAndShortDays20260823:
    """사용자 2026-08-23 (SK 캡처 4장):
      ① "첫번째 Remark 를 좀 더 다듬어줘. 간결하고 깔끔하게."
      ② "이 SK 차트는 또 왜 그러는거야?" — 1년 요청에 38일치
      ③ "한국기업에 한해서 여기 PBR 옆에 ROE 를 붙여줄수 있어?"
      ④ "그 시점을 가져오는건 어려운거야?" — 최고·중상·중하가 전부 '—'
    """

    # ── ① 기준 칩은 짧게, 근거 숫자는 그대로 ──────────────────────────
    def test_basis_note_is_short_and_keeps_the_measured_ratio(self):
        import bot.dashboard_server as ds
        # 되짚은 EPS 가 매달 바뀌는 형태(연속형) — FnGuide 실측 모양
        rows = [{"period": f"2025-{m:02d}-28", "price": 1000.0 + m * 10,
                 "per": (1000.0 + m * 10) / (100.0 + m)} for m in range(1, 13)]
        note = ds._kr_band_basis_note(rows)
        assert "매달 갱신" in note, note
        assert "/" in note, note              # 몇/몇 구간인지 남아 있다
        # ⚠️ 옛 문구는 판정과 근거를 두 번 적어 두 줄이 넘었다 — 줄인 건 말이다.
        assert len(note) <= 60, (len(note), note)

    def test_basis_note_says_so_when_it_cannot_judge(self):
        """표본이 모자라면 '분기 확정'이라고 우기지 않는다(#165)."""
        import bot.dashboard_server as ds
        note = ds._kr_band_basis_note([{"period": "2025-01-31", "price": 1.0,
                                        "per": 1.0}])
        assert "미판정" in note, note

    # ── ④ 그 시점 — 근사면 근사라고 밝힌다 ────────────────────────────
    def test_exact_match_is_not_marked_approximate(self):
        from bot.per_band import band_period
        obs = [("2024-01-31", 100.0, None, 5.00),
               ("2024-02-29", 120.0, None, 6.20)]
        assert band_period(obs, 5.00) == {"at": "2024-01-31", "approx": False}

    def test_nearest_observation_is_offered_but_flagged(self):
        """원천이 배수를 직접 주는 KR 은 관측과 딱 안 맞는다 — 가장 가까운
        관측을 주되 **근사임을 밝힌다**(조용히 붙이면 지어낸 시점이다, #32)."""
        from bot.per_band import band_period
        obs = [("2024-01-31", 100.0, None, 4.96),
               ("2024-02-29", 120.0, None, 9.00)]
        got = band_period(obs, 5.00)
        assert got == {"at": "2024-01-31", "approx": True}, got

    def test_far_observations_stay_empty(self):
        """⚠️ 아무거나 붙이면 안 된다 — 오차 밖이면 비운다."""
        from bot.per_band import band_period
        obs = [("2024-01-31", 100.0, None, 3.00),
               ("2024-02-29", 120.0, None, 9.00)]
        assert band_period(obs, 5.00) is None

    # ── ③ ROE = PBR ÷ PER (같은 시점) ─────────────────────────────────
    def test_roe_is_joined_by_period_not_by_position(self):
        """⚠️ 위치로 매기면 한쪽이 한 달 덜 올 때 전 행이 밀린다(#88)."""
        import bot.dashboard_server as ds
        per_t = {"rows": [{"period": "2026-06-30", "per": 10.0},
                          {"period": "2026-07-31", "per": 20.0}]}
        pbr_t = {"rows": [{"period": "2026-07-31", "per": 2.0}]}   # PER 한 달 더 많음
        ds._attach_roe(per_t, pbr_t)
        assert pbr_t["rows"][0]["roe"] == 10.0, pbr_t["rows"]      # 2.0/20.0
        assert pbr_t.get("roe_note")

    def test_roe_is_blank_when_per_is_missing(self):
        """적자로 PER 이 없는 달은 비운다 — 없는 걸 만들지 않는다(#32)."""
        import bot.dashboard_server as ds
        per_t = {"rows": [{"period": "2026-07-31", "per": None}]}
        pbr_t = {"rows": [{"period": "2026-07-31", "per": 2.0}]}
        ds._attach_roe(per_t, pbr_t)
        assert "roe" not in pbr_t["rows"][0], pbr_t["rows"]
        assert not pbr_t.get("roe_note")

    # ── ⑤ EDINET: 원천이 말한 건수보다 적게 오면 그 날은 못 믿는다 ────
    def test_a_truncated_day_is_recorded_and_not_cached(self, monkeypatch,
                                                        tmp_path):
        import bot.edinet_client as ec
        import datetime as _dt
        monkeypatch.setattr(ec, "_CACHE_DIR", tmp_path)

        class _R:
            def raise_for_status(self):
                pass

            def json(self):
                return {"metadata": {"resultset": {"count": 4000}},
                        "results": [{"docID": "A"}]}

        monkeypatch.setattr(ec.requests, "get", lambda url, timeout=None: _R())
        cl = ec.EdinetClient(api_key="k")
        day = _dt.date(2026, 6, 26)
        assert cl._fetch_day(day) == [{"docID": "A"}]
        assert cl.short_days[day.isoformat()] == (4000, 1), cl.short_days
        # 잘린 목록을 캐시하면 그 날은 영원히 잘린 채로 남는다(#21b)
        assert not (tmp_path / f"{day.isoformat()}.json").exists()

    def test_an_old_bare_list_cache_is_refetched(self, monkeypatch, tmp_path):
        """⚠️ 검증 규칙을 새로 넣어도 **이미 캐시된 날엔 안 돈다** — 봉투에
        버전을 찍고 옛 형식은 안 믿는다(#21b 캐시가 fix 를 가린다)."""
        import bot.edinet_client as ec
        import datetime as _dt
        import json as _json
        monkeypatch.setattr(ec, "_CACHE_DIR", tmp_path)
        day = _dt.date(2026, 6, 26)
        (tmp_path / f"{day.isoformat()}.json").write_text(
            _json.dumps([{"docID": "OLD"}]))
        hit = []

        class _R:
            def raise_for_status(self):
                pass

            def json(self):
                return {"metadata": {"resultset": {"count": 1}},
                        "results": [{"docID": "NEW"}]}

        def _get(url, timeout=None):
            hit.append(url)
            return _R()

        monkeypatch.setattr(ec.requests, "get", _get)
        cl = ec.EdinetClient(api_key="k")
        assert cl._fetch_day(day) == [{"docID": "NEW"}], "옛 캐시를 그대로 믿었다"
        assert len(hit) == 1, hit
        # 새 봉투는 다시 읽힌다(재요청 0회)
        assert cl._fetch_day(day) == [{"docID": "NEW"}]
        assert len(hit) == 1, hit

    # ── ② 두 질의가 다 짧으면 **넉넉한 창**으로 받아 잘라 쓴다 ─────────
    def test_a_wide_query_is_sliced_when_both_range_queries_are_short(
            self, monkeypatch):
        """사용자 2026-08-23 SK: 1년 요청에 38일치. 네이버 폴백은 국내 전용
        이라 그 밖의 시장엔 이게 마지막 수단이다."""
        import datetime as _dt
        import sys
        import types
        import pandas as pd
        import bot.chart_data as cd
        calls = []

        def _df(days, step=1):
            idx = pd.date_range(end=_dt.datetime(2026, 8, 21),
                                periods=days // step, freq=f"{step}D")
            n = len(idx)
            return pd.DataFrame({"Open": [1.0] * n, "High": [1.0] * n,
                                 "Low": [1.0] * n, "Close": [1.0] * n,
                                 "Volume": [1] * n}, index=idx)

        class _T:
            def __init__(self, tk):
                pass

            def history(self, **kw):
                calls.append(kw)
                if kw.get("period") == "max":
                    return _df(3650, step=5)      # 10년치를 준다
                return _df(38)                    # 구간 질의는 계속 짧다

        mod = types.ModuleType("yfinance")
        mod.Ticker = _T
        monkeypatch.setitem(sys.modules, "yfinance", mod)
        monkeypatch.setattr(cd, "_fetch_series_fallback", lambda t, p: None)
        monkeypatch.setattr(cd, "_merge_today_bar",
                            lambda t, c, v, o, h, l: (c, v, o, h, l))
        out = cd.fetch_chart_payload("SK", period="1y")
        assert any(c.get("period") == "max" for c in calls), calls
        span = cd._payload_span_days(out)
        assert 330 <= span <= 380, span      # 요청 창으로 **잘라서** 쓴다
        assert not out.get("notice"), out.get("notice")

    def test_wide_query_is_not_asked_when_the_range_query_is_fine(
            self, monkeypatch):
        """⚠️ 멀쩡한 날 야후 호출이 배로 늘면 안 된다."""
        import datetime as _dt
        import sys
        import types
        import pandas as pd
        import bot.chart_data as cd
        calls = []

        class _T:
            def __init__(self, tk):
                pass

            def history(self, **kw):
                calls.append(kw)
                idx = pd.date_range(end=_dt.datetime(2026, 8, 21),
                                    periods=250, freq="B")
                n = len(idx)
                return pd.DataFrame({"Open": [1.0] * n, "High": [1.0] * n,
                                     "Low": [1.0] * n, "Close": [1.0] * n,
                                     "Volume": [1] * n}, index=idx)

        mod = types.ModuleType("yfinance")
        mod.Ticker = _T
        monkeypatch.setitem(sys.modules, "yfinance", mod)
        monkeypatch.setattr(cd, "_merge_today_bar",
                            lambda t, c, v, o, h, l: (c, v, o, h, l))
        cd.fetch_chart_payload("SK", period="1y")
        assert not any(c.get("period") == "max" for c in calls), calls

    def test_tail_days_cuts_by_date(self):
        import pandas as pd
        import bot.chart_data as cd
        idx = pd.date_range("2020-01-01", periods=2000, freq="D")
        h = pd.DataFrame({"Close": [1.0] * 2000}, index=idx)
        assert cd._span_days(cd._tail_days(h, 365)) <= 366
        # 자를 게 없으면 원본 그대로 — 조용히 비우면 판정이 뒤집힌다
        assert len(cd._tail_days(h, 0)) == 2000


class TestBandPaneOrder20260823:
    """사용자 2026-08-23: "PBR 밴드는 여기 PBR 있는 곳 위로 옮겨줘."

    차트 둘을 나란히 놓고 표 둘을 그 아래 몰아 두면, PBR 표를 볼 때 그 차트가
    두 화면 위에 있다 — 지표마다 **차트 바로 밑에 그 지표의 표**를 둔다."""

    @staticmethod
    def _pane() -> str:
        import inspect
        import bot.dashboard as db
        src = inspect.getsource(db)
        i = src.index('id="si-band-grid"')
        return src[i - 2000:i + 3000]

    def test_each_chart_sits_directly_above_its_own_table(self):
        seg = self._pane()
        i_per_chart = seg.index('id="si-band-grid"')
        i_per_table = seg.index('id="si-band-table"')
        i_pbr_chart = seg.index('id="si-band-pbr-box"')
        i_pbr_table = seg.index('id="si-band-table-pbr"')
        assert i_per_chart < i_per_table < i_pbr_chart < i_pbr_table, \
            (i_per_chart, i_per_table, i_pbr_chart, i_pbr_table)

    def test_the_pbr_block_starts_hidden(self):
        """⚠️ 표 사이에 따로 서 있으므로, 기본이 보이면 데이터가 오기 전에
        'PBR 밴드' **제목만** 뜬다 — 수집 실패로 읽힌다(#43)."""
        seg = self._pane()
        i = seg.index('id="si-band-pbr-box"')
        assert "display:none" in seg[i:i + 120], seg[i:i + 120]

    @staticmethod
    def _js_body(src: str, head: str) -> str:
        """`head` 로 시작하는 함수의 **본문만** — 중괄호를 세어 자른다.

        ⚠️ 고정 길이 창으로 재면 옆 함수가 대신 만족시킨다 — 실제로 이 검사가
        `showGrid` 에서 hide 를 통째로 지운 뮤테이션을 **통과시켰다**(뒤따르는
        `draw()` 가 같은 id 를 쓴다, #60 창이 아니라 구조로 볼 것)."""
        i = src.index(head)
        j = src.index("{", i)
        depth = 0
        for k in range(j, len(src)):
            if src[k] == "{":
                depth += 1
            elif src[k] == "}":
                depth -= 1
                if depth == 0:
                    return src[j:k + 1]
        raise AssertionError(f"{head} 본문을 못 찾았다")

    def test_show_grid_hides_both_blocks(self):
        """밴드가 아예 없을 때 PER 만 감추면 PBR 제목이 남는다."""
        from bot.dashboard import _BAND_JS
        body = self._js_body(_BAND_JS, "function showGrid(")
        assert "si-band-grid" in body, body
        assert "si-band-pbr-box" in body, body

    def test_pbr_block_is_shown_before_it_is_drawn(self):
        """⚠️ 폭이 0 인 컨테이너에 그리면 플롯만 빈칸이 된다(#108) — 보이게
        한 **뒤에** 그린다."""
        from bot.dashboard import _BAND_JS
        i = _BAND_JS.index("if(CD.pbr&&CD.pbr.price")
        seg = _BAND_JS[i:i + 400]
        assert seg.index("pbrBox.style.display=''") < \
            seg.index("drawBand('si-band-pbr'"), seg


class TestWatchlistKrTrailingPer20260823:
    """사용자 2026-08-23 "진행해줘" — 관심종목의 **국내 종목 현재 PER 이 전부
    `—`** 였다(한텍·뉴파워프라즈마·쿠콘·삼성전자). yfinance 가 KR 종목의
    trailingEps 를 안 준다(`No fundamentals data found for symbol: 005930.KS`).

    KRX 투자지표는 전 종목 EPS 를 **한 번에** 준다 — 140종목을 종목마다 치지
    않아도 된다. PER 은 **화면의 현재가**로 만들어 눈으로 나눠 봐도 맞게(#33).
    """

    @staticmethod
    def _reset(mf):
        mf._FAV_CACHE, mf._FAV_CACHE_TS = None, 0.0
        mf._KR_EPS, mf._KR_EPS_TS = None, 0.0

    def test_zero_eps_is_dropped_not_treated_as_a_value(self, monkeypatch):
        """KRX 는 적자 종목의 EPS 를 0 으로 준다 — 0 은 '적자'와 '미제공'을
        구별하지 못하므로 값으로 쓰지 않는다(#43 모르면 비운다)."""
        import bot.market_favorites as mf
        import bot.stock_screener as ss
        self._reset(mf)
        monkeypatch.setattr(ss, "_fetch_kr_bulk", lambda: {
            "98070": {"EPS": 1200.0},        # 앞 0 이 빠져 와도 맞춘다
            "005930": {"EPS": 0.0},          # 적자/미제공
            "000660": {"EPS": -50.0}})
        got = mf._kr_eps_bulk()
        assert got == {"098070": 1200.0}, got

    def test_bulk_is_cached(self, monkeypatch):
        import bot.market_favorites as mf
        import bot.stock_screener as ss
        self._reset(mf)
        hits = []
        monkeypatch.setattr(ss, "_fetch_kr_bulk",
                            lambda: hits.append(1) or {"098070": {"EPS": 1.0}})
        mf._kr_eps_bulk()
        mf._kr_eps_bulk()
        assert len(hits) == 1, hits

    def test_a_kr_row_gets_per_from_the_shown_price(self, monkeypatch):
        """⚠️ 헬퍼만 부르는 테스트는 **배선을 못 잡는다**(#20) — 수집기를
        통째로 태운다."""
        import bot.market_favorites as mf
        self._reset(mf)
        monkeypatch.setattr(mf, "_load", lambda: [
            {"ticker": "098070.KQ", "name": "Hantech", "currency": "KRW"}])
        monkeypatch.setattr(mf, "_save", lambda x: None)
        monkeypatch.setattr(mf, "_naver_quote_for",
                            lambda t: {"price": 23650.0, "pct": 0.0,
                                       "mcap": None, "name": "한텍"})
        monkeypatch.setattr(mf, "_kr_eps_bulk", lambda: {"098070": 1200.0})
        row = mf._compute_favorites_with_prices()[0]
        assert row["eps_trailing"] == 1200.0
        assert row["eps_trailing_src"] == "KRX"
        # 화면의 현재가 ÷ 화면의 EPS 가 그대로 PER 이어야 한다(#33)
        assert abs(row["per_trailing"] - 23650.0 / 1200.0) < 0.01, row

    def test_the_bulk_is_fetched_once_not_per_ticker(self, monkeypatch):
        """⚠️ 스레드마다 부르면 같은 벌크를 종목 수만큼 두드린다 — 캐시는
        **진행 중인 중복**을 못 막는다(#113)."""
        import bot.market_favorites as mf
        self._reset(mf)
        monkeypatch.setattr(mf, "_load", lambda: [
            {"ticker": f"09807{i}.KQ", "name": f"n{i}", "currency": "KRW"}
            for i in range(5)])
        monkeypatch.setattr(mf, "_save", lambda x: None)
        monkeypatch.setattr(mf, "_naver_quote_for", lambda t: None)
        hits = []
        monkeypatch.setattr(mf, "_kr_eps_bulk", lambda: hits.append(1) or {})
        mf._compute_favorites_with_prices()
        assert len(hits) == 1, hits

    def test_the_bulk_is_not_fetched_for_a_foreign_only_list(self, monkeypatch):
        """국내 종목이 없으면 KRX 를 부를 이유가 없다."""
        import bot.market_favorites as mf
        self._reset(mf)
        monkeypatch.setattr(mf, "_load", lambda: [
            {"ticker": "AAPL", "name": "Apple", "currency": "USD"}])
        monkeypatch.setattr(mf, "_save", lambda x: None)
        monkeypatch.setattr(mf, "_naver_quote_for", lambda t: None)
        hits = []
        monkeypatch.setattr(mf, "_kr_eps_bulk", lambda: hits.append(1) or {})
        mf._compute_favorites_with_prices()
        assert hits == [], hits

    def test_yfinance_trailing_eps_wins_when_present(self, monkeypatch):
        """⚠️ KRX 로 **덮어쓰면** 해외 종목의 TTM 기준이 조용히 바뀐다 —
        비어 있을 때만 채운다."""
        import ast
        src = open("bot/market_favorites.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_compute_favorites_with_prices")
        seg = ast.get_source_segment(src, fn) or ""
        i = seg.index('f["eps_trailing_src"] = "KRX"')
        head = seg[:i]
        assert 'if f["eps_trailing"] is None' in head[-500:], head[-500:]

    def test_the_cell_says_where_the_per_came_from(self):
        """한 열에 두 원천이 섞이므로 기준을 밝히고(#34) 산식을 적는다(#33).
        ⚠️ 배선은 존재가 아니라 **호출**로 센다 — 정의 1 + 호출 1(#120)."""
        src = open("bot/dashboard.py", encoding="utf-8").read()
        assert src.count("tperTitle(") >= 2, src.count("tperTitle(")
        i = src.index("function tperTitle(")
        body = src[i:i + 700]
        assert "eps_trailing_src" in body and "KRX" in body, body


class TestBandSourceSinglePath20260823:
    """사용자 2026-08-23 "남은거 모두 끝났는지도 확인해줘" — 확인하다 드러난 것.

    감사는 `per_band.for_ticker` 만 불러 국내 종목을 `yf-a · 관측 4개` 로
    판정했는데, 화면은 FnGuide 밴드를 그린다(같은 종목이 **관측 49개**).
    감사가 **화면이 쓰지 않는 경로**를 재고 있었다(#35) — 국내 분기가
    `_handle_band_api` 안에 인라인으로만 있었던 것이 원인이다."""

    def test_kr_goes_to_fnguide_and_others_to_per_band(self, monkeypatch):
        import bot.band_source as bs
        import bot.dashboard_server as ds
        import bot.fnguide_bandchart as fg
        import bot.per_band as pb
        monkeypatch.setattr(fg, "fetch_band_chart", lambda t: {"raw": t})
        monkeypatch.setattr(ds, "_kr_band_tables",
                            lambda d, t: ({"n": 49, "kind": "PER"},
                                          {"n": 49, "kind": "PBR"}))
        monkeypatch.setattr(pb, "for_ticker",
                            lambda t, s=None: ({"n": 10, "basis": "edinet"}, None))
        kr = bs.resolve("005930.KS")
        assert kr["basis"] == "fnguide" and kr["per"]["n"] == 49, kr
        assert kr["pbr"] and kr["raw"], kr
        jp = bs.resolve("6758.T")
        assert jp["basis"] == "edinet" and jp["pbr"] is None, jp

    def test_no_fnguide_data_says_why(self):
        """조용히 비우면 '수집 실패'로 읽힌다(#43)."""
        import bot.band_source as bs
        import bot.fnguide_bandchart as fg
        orig = fg.fetch_band_chart
        fg.fetch_band_chart = lambda t: None
        try:
            got = bs.resolve("005930.KS")
        finally:
            fg.fetch_band_chart = orig
        assert got["per"] is None and got["why"], got

    def test_both_the_screen_and_the_audit_call_the_resolver(self):
        """⚠️ 한쪽만 부르면 다시 갈라진다 — **호출**을 AST 로 센다(#120)."""
        import ast
        for path, fn_name in (("bot/dashboard_server.py", "_handle_band_api"),
                              ("bot/scripts/per_band_audit.py", "audit_one")):
            src = open(path, encoding="utf-8").read()
            fn = next(n for n in ast.walk(ast.parse(src))
                      if isinstance(n, ast.FunctionDef) and n.name == fn_name)
            names = [c.func.id for c in ast.walk(fn)
                     if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)]
            attrs = [c.func.attr for c in ast.walk(fn)
                     if isinstance(c, ast.Call)
                     and isinstance(c.func, ast.Attribute)]
            assert "_resolve" in names or "resolve" in (names + attrs), \
                f"{path}:{fn_name} 이 공용 해석기를 안 부른다 — {names + attrs}"
        # 그리고 감사는 `for_ticker` 를 **직접** 부르면 안 된다(경로가 갈린다)
        src = open("bot/scripts/per_band_audit.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "audit_one")
        attrs = [c.func.attr for c in ast.walk(fn)
                 if isinstance(c, ast.Call) and isinstance(c.func, ast.Attribute)]
        assert "for_ticker" not in attrs, attrs

    def test_the_audit_covers_japan(self):
        """일본이 표본에 없으면 '일본도 되나'를 영영 못 답한다."""
        import bot.scripts.per_band_audit as ab
        jp = [t for m, t in ab._MARKET_SAMPLES if m == "JP"]
        assert len(jp) >= 3, jp
        markets = {m for m, _t in ab._MARKET_SAMPLES}
        assert {"US", "KR", "JP", "TW", "CN_A", "HK", "EU"} <= markets, markets

    def test_the_audit_also_checks_the_pbr_table(self):
        """국내는 PER·PBR 표가 같이 나온다 — 한쪽만 재면 나머지가 낡는다(#38)."""
        import ast
        src = open("bot/scripts/per_band_audit.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "audit_one")
        seg = ast.get_source_segment(src, fn) or ""
        assert seg.count("audit_rows(") >= 2, seg.count("audit_rows(")
        assert 'got.get("pbr")' in seg, seg[-600:]


class TestPartialRestatementAndStalePath20260823:
    """사용자 2026-08-23 "KLAC, LRCX 여전히 이상한것 같아".

    두 종목이 **다른 병**이었다.
      · LRCX — EDGAR 분기가 2024-06-30 부터는 이미 분할반영(후속 10-Q 에
        소급조정분이 실린다)인데 그보다 앞은 as-reported 였다. 날짜로 자르는
        환산은 이미 조정된 칸까지 10 으로 나눠 **더 나빠져** 되돌려졌고,
        결과적으로 아무것도 안 됐다(옛 PER 1.05~2.5).
      · KLAC — 결산분기 복원을 폐기하면 그 해 TTM 4점이 빠지는데 결산분기는
        매년 오므로 계열이 **영구히 멈춘다**. 이력이 2024-03-31 에서 끊긴 채
        현재 PER 96.08x 가 밴드 최고 36.48x 를 넘었다.
    """

    # ── LRCX: 기준이 갈리는 자리를 찾는다 ─────────────────────────────
    def test_partially_restated_series_is_rescaled_at_the_break(self):
        from bot.per_band import adjust_eps_for_splits
        rows = [("2022-09-25", 34.87), ("2022-12-25", 37.20),
                ("2023-03-26", 35.91),
                ("2024-06-30", 2.90), ("2024-09-29", 3.09),
                ("2024-12-29", 3.29), ("2026-06-28", 5.76)]
        out = dict(adjust_eps_for_splits(rows, [("2024-10-03", 10.0)]))
        assert abs(out["2023-03-26"] - 3.591) < 1e-6, out
        assert abs(out["2024-06-30"] - 2.90) < 1e-9, out   # 이미 조정된 칸은 그대로
        assert abs(out["2026-06-28"] - 5.76) < 1e-9, out

    def test_a_moderate_earnings_drop_is_not_rescaled(self):
        """⚠️ 실적 변동을 분할로 오인해 깎으면 안 된다 — 급변이 문턱 아래면
        경계 탐색을 **아예 시작하지 않는다**(#146 증상이 아니라 원인으로).

        (2.5배 감익은 실적이다. 문턱을 낮추면 ÷2 경계가 그걸 '고쳐' 버린다.)
        """
        from bot.per_band import adjust_eps_for_splits
        rows = [("2023-03-31", 2.8), ("2023-06-30", 2.8),
                ("2023-09-30", 1.0), ("2023-12-31", 1.0)]
        out = adjust_eps_for_splits(rows, [("2020-01-01", 2.0)])
        assert out == rows, out

    def test_a_split_inside_the_window_is_applied_even_without_a_big_jump(self):
        """⚠️ 경계 탐색은 급변이 클 때만 돈다 — 그 아래에서도 **날짜 기준**은
        적용돼야 한다(분할은 원천이 알려준 사실이지 우리 추정이 아니다)."""
        from bot.per_band import adjust_eps_for_splits
        rows = [("2023-03-31", 2.5), ("2023-06-30", 2.5),
                ("2023-09-30", 1.0), ("2023-12-31", 1.0)]
        out = dict(adjust_eps_for_splits(rows, [("2023-08-01", 2.0)]))
        assert abs(out["2023-03-31"] - 1.25) < 1e-9, out   # 분할 전 → ÷2
        assert abs(out["2023-12-31"] - 1.0) < 1e-9, out    # 분할 후 → 그대로

    def test_cum_split_factors_multiplies_backwards(self):
        from bot.per_band import cum_split_factors
        # 최신 분할부터 거슬러 곱한다 — 2024 이전 행은 ÷10, 2020 이전은 ÷20
        assert cum_split_factors([("2020-01-01", 2.0),
                                  ("2024-01-01", 10.0)]) == [10.0, 20.0]
        assert cum_split_factors([]) == []

    def test_a_marginal_gain_is_refused(self):
        """어중간한 개선은 실적 변동을 깎은 것이다 — 극적일 때만 인정한다.

        (환산하면 최대 급변이 4.0 → 2.7 로 **줄기는 한다**. 기준이 실제로
        갈렸으면 개선이 극적이므로 이 정도는 인정하지 않는다.)
        """
        from bot.per_band import adjust_eps_for_splits
        rows = [("2023-03-31", 8.0), ("2023-06-30", 2.0), ("2023-09-30", 5.4)]
        out = adjust_eps_for_splits(rows, [("2023-08-01", 2.0)])
        assert out == rows, out

    # ── KLAC: 멈춘 계열은 쓰지 않는다 ─────────────────────────────────
    def test_a_stalled_quarterly_series_falls_back_to_annual(self):
        from bot.per_band import staler_than
        q = [("2023-06-30", 1.9), ("2024-03-31", 1.92)]
        a = [("2024-06-30", 2.0), ("2025-06-30", 2.4), ("2026-06-30", 2.9)]
        assert staler_than(q, a), "멈춘 분기 계열을 그대로 쓴다"
        assert staler_than(a, a) is None          # 같은 끝이면 바꿀 이유 없다
        # 한 분기 늦은 정도로는 경로를 바꾸지 않는다
        assert staler_than([("2026-03-31", 1.0)], [("2026-06-30", 1.0)]) is None

    def test_for_ticker_consults_the_staleness_gate(self):
        """⚠️ 헬퍼만 있고 배선이 없으면 화면은 그대로다 — **호출**을 센다(#120)."""
        import ast
        src = open("bot/per_band.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "for_ticker")
        names = [c.func.id for c in ast.walk(fn)
                 if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)]
        assert "staler_than" in names, names

    def test_the_screen_says_the_path_changed(self):
        """조용히 다른 계열로 내려가면 왜 점이 적은지 알 수 없다(#43)."""
        from bot.dashboard import _BAND_JS
        assert "path_note" in _BAND_JS, "경로 변경 사유를 안 그린다"

    # ── 감사가 그 증상을 잡는가 ───────────────────────────────────────
    def test_the_audit_flags_a_stale_history(self):
        """⚠️ KLAC 은 산수·창·상식성이 전부 ✅ 라 감사가 그냥 통과시켰다."""
        import bot.scripts.per_band_audit as ab
        stale = {"rows": [{"period": "2024-03-31", "price": 69.86,
                           "eps": 1.92, "per": 36.39}],
                 "band_from": "2024-03-31", "band_to": "2024-03-31",
                 "summary": {}, "basis": "edgar"}
        got = dict((a, m) for m, a, _d in ab.audit_rows(stale))
        assert got["최신성"] == "❌", got

    def test_the_audit_passes_a_fresh_history(self):
        """⚠️ 늘 ❌ 를 찍는 축은 아무것도 안 재는 것이다 — 통과도 확인한다."""
        import datetime as _dt
        import bot.scripts.per_band_audit as ab
        today = _dt.datetime.now(_dt.timezone(_dt.timedelta(hours=9))).date()
        fresh = {"rows": [{"period": today.isoformat(), "price": 100.0,
                           "eps": 5.0, "per": 20.0}],
                 "band_from": today.isoformat(), "band_to": today.isoformat(),
                 "summary": {}, "basis": "edgar"}
        got = dict((a, m) for m, a, _d in ab.audit_rows(fresh))
        assert got["최신성"] == "✅", got

    # ── 연차로 내려간 **사유**는 경우마다 다르다 ─────────────────────
    def test_the_annual_fallback_reason_is_not_asserted_by_the_label(self):
        """⚠️ 2026-08-23 KLAC 실측: 출처가 "연차 희석 EPS — **20-F 등 분기
        미제출**" 인데 KLAC 은 10-Q 를 낸다 — 분기 계열이 멈춰서 내려간
        것이지 미제출이 아니다. 라벨이 원인을 단정하면 거짓말이 된다(#55).
        """
        from bot.per_band import _SRC_LABEL, edgar_annual_reason
        assert "20-F" not in _SRC_LABEL["edgar-a"], _SRC_LABEL["edgar-a"]
        q = [("2024-03-31", 1.9)]
        t = [("2024-03-31", 1.92)]
        a = [("2025-06-30", 2.4), ("2026-06-30", 2.9)]
        assert "20-F" in edgar_annual_reason(None, None, a)      # 진짜 미제출
        assert "결산검산" in edgar_annual_reason(q, t, a, "어긋")
        assert "멈춰" in edgar_annual_reason(q, t, a)            # 계열이 멈춤
        # 셋 다 아니면 단정하지 않는다
        assert edgar_annual_reason(q, a, a)

    def test_the_annual_path_carries_the_reason(self):
        """헬퍼만 있고 배선이 없으면 화면은 그대로다 — **호출**을 센다(#120)."""
        import ast
        src = open("bot/per_band.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "for_ticker")
        names = [c.func.id for c in ast.walk(fn)
                 if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)]
        assert "edgar_annual_reason" in names, names


class TestAuditCountsWhatItChecked20260823:
    """사용자 2026-08-23 "전체 감사를 꼼꼼히 한 번 더 돌려보고 수정할 건
    수정해줘" — 감사 자체를 훑다가 나온 **거짓 초록** 둘.

      ① 국내(FnGuide)는 분모를 안 줘서 `eps` 가 전 행 None 인데, 산수 축이
         "49/49 행에서 주가÷EPS=PER ✅" 라고 찍었다 — **한 행도 안 재고**
         통과시킨 것이다(#54). 감사가 국내 경로를 타게 만든 바로 그 커밋에서
         생긴 거짓 초록이다.
      ② PBR 표의 분모는 **BPS** 인데 화면·감사가 'EPS' 라고 적고 있었다(#34).
    """

    @staticmethod
    def _kr(kind="PBR"):
        return {"rows": [{"period": f"2025-{m:02d}-28", "price": 1000.0 + m,
                          "eps": None, "per": (1000.0 + m) / 100.0}
                         for m in range(1, 13)],
                "kind": kind, "basis": "fnguide", "band_from": "2025-01-28",
                "band_to": "2025-12-28", "summary": {}}

    def test_zero_checkable_rows_is_unknown_not_pass(self):
        import bot.scripts.per_band_audit as ab
        got = dict((a, m) for m, a, _d in ab.audit_rows(self._kr()))
        assert got["산수"] == "❓", got

    def test_the_split_axis_does_not_pass_on_nothing_either(self):
        """⚠️ 같은 함정이 옆 축에도 있다 — 원천이 배수를 직접 주지 않는
        경로에서 EPS 가 없으면 ❓ 여야 한다."""
        import bot.scripts.per_band_audit as ab
        t = self._kr(kind="PER")
        t["basis"] = "edgar"            # 직접 PER 경로가 아니다
        got = dict((a, m) for m, a, _d in ab.audit_rows(t))
        assert got["분할"] == "❓", got

    def test_a_checkable_table_still_reports_the_count(self):
        """⚠️ 늘 ❓ 를 찍는 축은 아무것도 안 재는 것이다 — 통과도 확인한다."""
        import bot.scripts.per_band_audit as ab
        t = {"rows": [{"period": "2025-06-30", "price": 100.0, "eps": 5.0,
                       "per": 20.0}],
             "kind": "PER", "basis": "edgar", "band_from": "2025-06-30",
             "band_to": "2025-06-30", "summary": {}}
        got = [(m, d) for m, a, d in ab.audit_rows(t) if a == "산수"]
        assert got[0][0] == "✅", got
        assert "1/1" in got[0][1] and "주가÷EPS=PER" in got[0][1], got

    def test_the_pbr_denominator_is_bps_everywhere(self):
        """PER 의 분모는 EPS, PBR 의 분모는 BPS — 지표 이름을 섞으면 화면이
        거짓말한다(2026-08-23 캡처: "PBR = 주가 ÷ 원천 EPS(매달 갱신)")."""
        import bot.dashboard_server as ds
        import bot.scripts.per_band_audit as ab
        rows = [{"period": f"2025-{m:02d}-28", "price": 1000.0 + m * 10,
                 "per": (1000.0 + m * 10) / (100.0 + m)} for m in range(1, 13)]
        assert "BPS" in ds._kr_denom_label(rows, "PBR")
        assert "EPS" not in ds._kr_denom_label(rows, "PBR")
        assert "EPS" in ds._kr_denom_label(rows, "PER")
        assert "BPS" in ds._kr_band_basis_note(rows, "PBR")
        assert "EPS" in ds._kr_band_basis_note(rows, "PER")
        # 감사 ⑥ 도 표의 지표를 따라간다
        msg = [d for m, a, d in ab.audit_rows(self._kr()) if a == "분모 기준"][0]
        assert "BPS" in msg and "되짚은 EPS" not in msg, msg

    def test_the_table_passes_its_kind_to_the_labels(self):
        """⚠️ 헬퍼만 kind 를 받고 호출부가 안 넘기면 화면은 그대로다(#20)."""
        import ast
        src = open("bot/dashboard_server.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_fnguide_ratio_table")
        for call in ("_kr_band_basis_note", "_kr_denom_label"):
            node = next(c for c in ast.walk(fn)
                        if isinstance(c, ast.Call)
                        and isinstance(c.func, ast.Name)
                        and c.func.id == call)
            assert len(node.args) >= 2, f"{call} 에 kind 를 안 넘긴다"


class TestPerMetricTrendCharts20260823:
    """사용자 2026-08-23: "매출액은 매출액끼리, 영익은 영익끼리, 순이익은
    순익끼리, FCF 는 FCF 끼리 차트로 보여주는게 더 보기 편할 것 같은데…
    너무 헷갈려."

    한 그림에 겹쳐 그리면 축이 하나뿐이라 **매출이 나머지를 눌러 버린다**.
    지표마다 자기 축을 가진 작은 차트로 나눈다 — 대신 높이를 지표끼리
    비교할 수 없게 되므로 **각 차트가 자기 축 최대값을 밝힌다**(#34)."""

    @staticmethod
    def _trend(**kw):
        import ast
        import html as _h
        import textwrap
        from bot.dashboard import compact_amount, trend_chart_geometry
        src = open("bot/dashboard.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_profit_trend")
        ns = {"esc": _h.escape, "compact_amount": compact_amount,
              "currency": kw.get("currency", "KRW"),
              "trend_chart_geometry": trend_chart_geometry}
        exec(textwrap.dedent(ast.get_source_segment(src, fn)), ns)
        return ns["_profit_trend"]

    @staticmethod
    def _data(fcf=True):
        IS = [{"period": f"2026-0{m}-30", "Total Revenue": 1e12 + m * 1e10,
               "Operating Income": 2e11 + m * 1e9,
               "Net Income": 1e11 + m * 1e9} for m in (3, 6, 9)]
        CF = ([{"period": f"2026-0{m}-30", "Operating Cash Flow": 3e11,
                "Capital Expenditure": -8e10} for m in (3, 6, 9)]
              if fcf else None)
        return IS, CF

    def test_one_chart_per_metric(self):
        IS, CF = self._data()
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", CF)
        assert h.count("<svg") == 4, f"지표별 차트가 아니다: {h.count('<svg')}"
        # 지표 이름이 각 차트의 제목이다(공용 범례 하나가 아니라)
        for nm in ("매출", "영업이익", "순이익", "FCF"):
            assert nm in h, nm

    def test_each_chart_has_its_own_axis(self):
        """⚠️ 축을 공유하면 고치려던 그 문제(매출이 나머지를 누름)가 그대로다.

        축이 갈렸는지는 **막대 높이**로 잰다 — 매출이 순이익의 10배인데 축을
        공유하면 순이익 막대가 바닥에 붙고, 자기 축이면 둘 다 꽉 찬다."""
        import re
        IS, CF = self._data()
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", CF)
        bars = [float(x) for x in
                re.findall(r'<rect[^>]*height="([\d.]+)"', h)]
        assert len(bars) == 12, bars
        assert min(bars) >= 100.0, f"축을 공유해 눌렸다: {bars}"

    def test_the_group_says_axes_differ(self):
        """높이를 지표끼리 비교할 수 없게 됐으므로 **기준을 밝혀야** 한다(#34).
        ⚠️ 차트마다 적던 '축 최대'는 사용자 요청으로 뺐다(2026-08-23) —
        대신 그룹 아래 한 줄로 남긴다. 아무 말도 안 하면 "영업이익이 매출만큼
        크다"로 읽힌다."""
        IS, CF = self._data()
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", CF)
        assert "축 최대" not in h, "차트마다 축 설명이 남아 있다"
        assert "축이 다릅니다" in h, "축이 다르다는 사실을 아무 데서도 안 말한다"

    def test_the_four_charts_share_one_canvas(self):
        """⚠️ 지표마다 음수 깊이가 달라 도화지를 따로 잡으면 기간 라벨이
        차트마다 다른 높이에 찍히고, 가장 깊은 차트만 아래 설명과 붙는다
        (사용자 2026-08-23 "너무 붙어있는 것 같아"). 좌표계를 공유한다(#62)."""
        import re
        IS, _ = self._data(fcf=False)
        # 순이익만 크게 음수 — 옛 판이면 이 차트만 도화지가 길어진다
        for r in IS:
            r["Net Income"] = -9e11
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", None)
        hs = set(re.findall(r'viewBox="0 0 260 ([\d.]+)"', h))
        ys = set(re.findall(r'<text x="[\d.]+" y="(\d+)" font-size="11"', h))
        assert len(hs) == 1, f"도화지 높이가 갈렸다: {hs}"
        assert len(ys) == 1, f"기간 라벨 높이가 갈렸다: {ys}"

    def test_a_missing_period_is_marked_not_drawn_as_zero(self):
        """값이 없는 기간에 0 짜리 막대를 그리면 '현금흐름 0' 이라는 **없는
        사실**을 그린 것이다 — 그렇다고 조용히 비우면 0 으로 읽힌다(#43)."""
        IS, CF = self._data()
        CF = [r for r in CF if not r["period"].startswith("2026-06")]
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", CF)
        assert h.count("<rect") == 3 * 3 + 2, h.count("<rect")
        # ⚠️ 표에도 '—' 가 있다 — **차트 안**을 봐야 한다(#75 옆 칸이 대신
        # 만족시키면 가드를 지워도 통과한다).
        import re
        svgs = "".join(re.findall(r"<svg.*?</svg>", h, re.S))
        assert ">—<" in svgs, "차트가 빈 기간을 표시하지 않는다"

    def test_a_metric_with_no_data_gets_no_chart(self):
        """FCF 재료가 없으면 FCF 차트를 아예 만들지 않는다(빈 축은 거짓말)."""
        IS, _ = self._data(fcf=False)
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", None)
        assert h.count("<svg") == 3 and "FCF" not in h, h.count("<svg")

    def test_an_all_zero_metric_gets_no_chart_either(self):
        """⚠️ 값이 **있는데 전부 0** 이면 `_has_fcf` 가 True 라 계열에는
        들어온다 — 축이 0 인 차트를 그리면 안 된다(그리면 나눗셈부터 터진다).
        """
        IS, _ = self._data(fcf=False)
        CF = [{"period": f"2026-0{m}-30", "Operating Cash Flow": 0.0,
               "Capital Expenditure": 0.0} for m in (3, 6, 9)]
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", CF)
        assert h.count("<svg") == 3, h.count("<svg")

    def test_charts_reflow_on_narrow_screens(self):
        """네 차트를 가로로 못 넣는 폭에서도 읽혀야 한다 — 고정 폭 금지."""
        IS, CF = self._data()
        h = self._trend()(IS, 5, lambda p: p[:7], "t", "g", "분기", CF)
        assert "auto-fit" in h and "minmax(" in h, h[:300]
        assert 'width="100%"' in h, "차트가 고정 폭이다"

    def test_table_and_chart_share_one_formatter(self):
        """⚠️ 축약을 두 벌 두면 같은 값이 표와 차트에서 달리 읽힌다(#38).
        `_fin_table` 이 자기 축약을 다시 만들면 안 된다."""
        import ast
        src = open("bot/dashboard.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "_fin_table")
        seg = ast.get_source_segment(src, fn) or ""
        assert "compact_amount(" in seg, "표가 공용 축약 함수를 안 쓴다"
        for lit in ("조\"", "억\"", "兆\"", "億\""):
            assert lit not in seg, f"표에 축약 리터럴이 남아 있다: {lit}"


class TestFullAuditFindings20260823:
    """사용자 2026-08-23 전 시장 감사(v9) 실측에서 나온 셋.

      ① 소니 6758.T ❌ 최신성 — FY2026 이 **순손실**이라 PER 이 정의되지 않아
         이력이 2025-03-31 에서 멈추는데, 화면이 그 사실을 **한 마디도** 안
         했다. 낡음 자체가 죄가 아니라 말 안 하는 것이 죄다(#43·#131).
      ② 국내 2종목 ❓ 창 — `assemble` 이 싣는 `band_from/to` 를 FnGuide 경로만
         빠뜨려 감사가 창을 못 쟀다.
      ③ SIE.DE ❓ 현재값 — "현재 PER **또는** 실시간 시세 없음" 은 다음
         라운드를 낭비한다. 어느 것이 없는지 말해야 한다(#82).
    """

    # ── ① 적자로 끊긴 계열은 그렇다고 말한다 ──────────────────────────
    def test_a_loss_year_that_ends_the_series_is_explained(self):
        from bot.per_band import loss_tail_reason
        eps = [("2025-03-31", 187.92), ("2026-03-31", -54.36)]
        why = loss_tail_reason(eps, [{"period": "2025-03-31"}])
        assert why and "적자" in why and "2026-03-31" in why, why
        # 최신 기간이 흑자면 할 말이 없다
        assert loss_tail_reason([("2026-03-31", 10.0)],
                                [{"period": "2026-03-31"}]) is None
        # 밴드가 최신까지 왔으면(빠진 게 없으면) 역시 없다
        assert loss_tail_reason(eps, [{"period": "2026-03-31"}]) is None

    def test_build_attaches_the_reason(self):
        """⚠️ 헬퍼만 있고 배선이 없으면 화면은 그대로다(#20) — `build` 를
        실제로 태운다."""
        from bot.per_band import build
        px = [(f"20{y}-03-31", 100.0) for y in range(20, 27)]
        eps = [(f"20{y}-03-31", 10.0 + y) for y in range(20, 26)]
        eps.append(("2026-03-31", -5.0))
        got = build(px, eps, annual=True)
        assert got and got.get("gap_note"), got

    def test_the_screen_renders_the_reason(self):
        """⚠️ 존재가 아니라 **몇 번** 그리는지 센다 — 편집 중에 같은 블록을
        두 번 넣어 화면에 사유가 두 줄로 뜰 뻔했고, '있는지'만 보는 검사는
        하나를 지워도 통과했다(#59 중복 정의 · #120 배선은 호출로)."""
        from bot.dashboard import _BAND_JS
        for name in ("t.gap_note", "t.path_note", "t.trim_note"):
            assert _BAND_JS.count(f"if({name})") == 1, \
                f"{name} 렌더가 {_BAND_JS.count(f'if({name})')}번"

    def test_the_audit_separates_explained_staleness_from_silence(self):
        """설명된 낡음은 ✅, **조용한** 낡음은 ❌ — 감사는 침묵을 잡는다."""
        import bot.scripts.per_band_audit as ab
        base = {"rows": [{"period": "2025-03-31", "price": 100.0,
                          "eps": 5.0, "per": 20.0}],
                "basis": "edinet", "band_from": "2025-03-31",
                "band_to": "2025-03-31", "summary": {}, "kind": "PER"}
        silent = dict(base)
        assert dict((a, m) for m, a, _d in ab.audit_rows(silent))["최신성"] == "❌"
        told = dict(base, gap_note="최근 회계연도(2026-03-31)는 적자라 …")
        assert dict((a, m) for m, a, _d in ab.audit_rows(told))["최신성"] == "✅"

    # ── ② 국내 표에도 밴드 창 ─────────────────────────────────────────
    def test_the_kr_table_carries_its_band_window(self):
        import bot.dashboard_server as ds
        import bot.scripts.per_band_audit as ab
        ts = [1590000000000 + i * 2592000000 for i in range(50)]
        blk = {"mult": [90.8, 63.4, 36.1, 8.7],
               "price": [[t, 30000.0 + i * 300] for i, t in enumerate(ts)],
               "bands": [[[t, 200000.0 + i * 7000] for i, t in enumerate(ts)]]}
        t = ds._fnguide_ratio_table(blk, kind="PER", px_now=26850.0)
        assert t and t.get("band_from") and t.get("band_to"), t
        got = dict((a, m) for m, a, _d in ab.audit_rows(t))
        assert got["창"] == "✅", got

    # ── ③ 어느 입력이 없는지 말한다 ───────────────────────────────────
    def test_the_missing_input_is_named(self):
        import bot.scripts.per_band_audit as ab
        t = {"rows": [{"period": "2026-06-30", "price": 100.0, "eps": 5.0,
                       "per": 20.0}],
             "basis": "yf-a", "band_from": "2026-06-30",
             "band_to": "2026-06-30", "summary": {"per_now": 21.0},
             "price_now": None, "kind": "PER"}
        msg = [d for m, a, d in ab.audit_rows(t) if a == "현재값"][0]
        assert "실시간 시세" in msg and "또는" not in msg, msg


class TestBandLivePriceFallback20260823:
    """사용자 2026-08-23 JBL: "현재 PER 부분은 없어. 이거 적용하기로 하지
    않았어?"

    화면 헤더는 **$313.21** 을 띄우는데 밴드 표만 "현재 PER = 마지막 관측
    기준 — 실시간 시세를 못 받았습니다" 라며 마지막 **월봉** 364.56 으로
    45.74x 를 만들었다(같은 화면 밸류에이션 탭은 39.20x). 한 사실(현재가)에
    두 경로를 두면 갈라진다(#38) — 전용 호출이 실패하면 **화면이 이미 아는
    값**으로 되돌아간다."""

    @staticmethod
    def _stub(monkeypatch, ret):
        import bot.world_quote as wq
        monkeypatch.setattr(wq, "fetch_world_quote", lambda t: ret)

    def test_snapshot_price_is_used_when_the_live_call_fails(self, monkeypatch):
        from bot.per_band import live_price
        self._stub(monkeypatch, None)
        assert live_price("JBL", 364.56, hint=313.21) == 313.21

    def test_the_live_call_still_wins(self, monkeypatch):
        """폴백이 라이브를 밀어내면 안 된다 — 순서가 뒤집히면 더 낡은 값이 된다."""
        from bot.per_band import live_price
        self._stub(monkeypatch, {"price": 313.0})
        assert live_price("JBL", 364.56, hint=999.0) == 313.0

    def test_an_implausible_hint_is_refused(self, monkeypatch):
        """⚠️ 폴백에도 같은 자릿수 가드를 건다 — 통화 뒤섞임·분할 미조정."""
        from bot.per_band import live_price
        self._stub(monkeypatch, None)
        assert live_price("JBL", 364.56, hint=5.0) is None
        assert live_price("JBL", 364.56, hint=None) is None

    def test_for_ticker_passes_the_snapshot_price(self):
        """⚠️ 헬퍼만 받고 호출부가 안 넘기면 화면은 그대로다(#20) — 인자를
        AST 로 못박는다."""
        import ast
        src = open("bot/per_band.py", encoding="utf-8").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "for_ticker")
        call = next(c for c in ast.walk(fn)
                    if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)
                    and c.func.id == "live_price")
        assert any(k.arg == "hint" for k in call.keywords), \
            "현재가 폴백을 안 넘긴다"


class TestBandChartZeroWidth20260823:
    """사용자 2026-08-23 COP: "왜 갑자기 차트그래픽이 이상하게 변했지?
    이런게 나왔다가 안나왔다가 하는데."

    밴드 SVG 는 높이가 고정이라 `preserveAspectRatio="none"` 인데, viewBox
    폭이 실제 렌더 폭과 다르면 그 비율만큼 **가로로만** 늘어난다. 탭이 아직
    숨겨져 있으면 `clientWidth` 가 0 이라 폴백 340 으로 그려지고, 그게
    전폭(≈1900px)으로 펴지면 5.6배 늘어난 글씨가 된다 — 폭이 잡힌 뒤 다시
    그리면 멀쩡하므로 "나왔다가 안나왔다가" 로 보인다. 밴드 pane 이 2열에서
    1열이 되며(2026-08-23) 늘어나는 비율이 커져 눈에 띄기 시작했다.
    가격 차트가 같은 병을 앓았다(#108) — 같은 처방을 쓴다."""

    @staticmethod
    def _body(head: str) -> str:
        """중괄호를 세어 **그 함수 본문만** — 고정 길이 창은 옆 함수가 대신
        만족시킨다(#174 에서 실제로 그렇게 눈이 멀었다)."""
        from bot.dashboard import _BAND_JS as js
        i = js.index(head)
        j = js.index("{", i)
        depth = 0
        for k in range(j, len(js)):
            if js[k] == "{":
                depth += 1
            elif js[k] == "}":
                depth -= 1
                if depth == 0:
                    return js[j:k + 1]
        raise AssertionError(f"{head} 본문을 못 찾았다")

    def test_zero_width_render_is_deferred(self):
        body = self._body("function drawBand(")
        assert "clientWidth<1" in body, "폭 0 가드가 없다"
        assert "requestAnimationFrame" in body, "다음 프레임으로 미루지 않는다"

    def test_the_retry_is_bounded(self):
        """⚠️ 무한 재시도는 숨은 탭에서 프레임을 계속 먹는다(#108)."""
        import re
        body = self._body("function drawBand(")
        # ⚠️ `n<60` 을 `n\s*<\s*\d+` 로 찾으면 **`ymin<0` 이 대신 만족**시킨다
        # (#75 옆 칸이 대신 만족시키면 가드를 지워도 통과한다) — 단어 경계로.
        assert "_bandRetry" in body, body[:300]
        assert re.search(r"\bn\s*<\s*\d+", body), f"재시도 상한이 없다: {body[:400]}"

    def test_the_container_is_watched_not_just_the_window(self):
        """폰트 로딩·탭 전환처럼 **컨테이너만** 바뀌면 window.resize 는 안 온다."""
        from bot.dashboard import _BAND_JS
        body = self._body("function watchBandWidth(")
        assert "ResizeObserver" in body, body[:200]
        for holder in ("si-band-per", "si-band-pbr"):
            assert holder in body, f"{holder} 를 안 본다"
        # 그리고 그 감시가 **실제로 켜져야** 한다 — 정의만 있으면 안 된다(#120)
        assert _BAND_JS.count("watchBandWidth(") >= 2, "감시를 켜지 않는다"

    def test_the_redraw_uses_the_same_payload(self):
        """다시 그릴 때 재료를 기억하지 못하면 빈 차트가 된다."""
        body = self._body("function drawBand(")
        assert "_bandLast[holderId]" in body, "재료를 기억하지 않는다"


class TestPerBasisAcrossTabs20260823:
    """사용자 2026-08-23 SK텔레콤 017670.KS: "왜 현재 PER 가 안맞는거야?
    두개의 탭에서?"

    밸류에이션 탭 **30.55x**(= 102,200 ÷ TTM 실적 EPS 3,344.90) vs 밴드차트 탭
    **21.30x**(= 102,200 ÷ FnGuide 가 쓰는 매달 갱신 EPS ≈ 4,798). 둘 다 맞는
    값인데 **분모가 다르다** — 이름이 같으면 사용자는 "한쪽이 틀렸다"고
    읽는다(#34 같은 주제어에 다른 시리즈면 라벨에 기준을 박을 것).

    ⚠️ 같은 캡처의 짝: `PER (선행) 16.04x` 인데 `EPS (선행)` 은 '—' 였다 —
    화면의 분모로 **눈으로 나눠 볼 수 없는 행**이다(#33)."""

    @staticmethod
    def _per_mark_fn(si: dict):
        import ast
        import textwrap
        src = open("bot/dashboard.py", encoding="utf-8").read()
        i = src.index("    def _per_mark(per_key: str, eps_key: str) -> str:")
        j = src.index('    val_multiples = ""', i)
        ns = {"si": si}
        exec(textwrap.dedent(src[i:j]), ns)
        return ns["_per_mark"]

    def test_a_verifiable_row_gets_no_marker(self):
        """⚠️ 늘 표시를 다는 축은 아무것도 안 재는 것이다 — 통과도 확인한다."""
        f = self._per_mark_fn({"trailingPE": 30.55, "trailingEps": 3344.90,
                               "current_price": 102200})
        assert f("trailingPE", "trailingEps") == ""

    def test_a_row_without_its_denominator_says_so(self):
        f = self._per_mark_fn({"forwardPE": 16.04, "forwardEps": None,
                               "current_price": 102200})
        assert "검산 불가" in f("forwardPE", "forwardEps")

    def test_a_row_that_does_not_divide_shows_the_recomputed_value(self):
        """2026-08-20 삼성전자 형: 화면은 3.7x 인데 247,500÷14,227 = 17.4x."""
        f = self._per_mark_fn({"trailingPE": 3.7, "trailingEps": 14227.0,
                               "current_price": 247500})
        assert "17.40x" in f("trailingPE", "trailingEps")

    def test_both_surfaces_state_their_denominator(self):
        """한쪽만 밝히면 사용자는 여전히 어느 쪽이 틀렸는지 모른다.

        ⚠️ 2026-08-24 계약 변경(사용자 "이거 다 빼줘. 알아들었으니"): 밸류에이션
        탭의 'ℹ️ 밴드차트 탭은 분모가 달라 값이 다릅니다' 줄은 **뺐다**. 밴드 탭
        캡션이 이미 두 분모를 **숫자로** 나란히 놓기 때문이다(#202) — 상호참조를
        양쪽에 두면 읽을 것만 는다. 그래도 밸류에이션 탭은 **자기 분모**를
        밝혀야 하고, 밴드 탭은 반대 방향을 계속 가리킨다."""
        import bot.dashboard as db
        import bot.dashboard_server as ds
        from bot.dashboard import per_basis_lines
        note = " ".join(per_basis_lines(True, "네이버(FnGuide) 추정 EPS"))
        assert "TTM 실적 EPS" in note, note      # 자기 분모는 계속 밝힌다
        assert "밴드차트" not in note, note      # 상호참조는 뺐다
        # 밴드 표의 출처 줄도 반대 방향을 밝힌다
        ts = [1590000000000 + k * 2592000000 for k in range(50)]
        blk = {"mult": [90.8, 63.4, 36.1, 8.7],
               "price": [[t, 30000.0 + k * 300] for k, t in enumerate(ts)],
               "bands": [[[t, 200000.0 + k * 7000] for k, t in enumerate(ts)]]}
        t = ds._fnguide_ratio_table(blk, kind="PER", px_now=26850.0)
        assert "밸류에이션 탭" in (t or {}).get("source", ""), (t or {}).get("source")
        assert db  # 렌더 모듈이 임포트되는지(문법 회귀)

    def test_the_note_is_rendered_once(self):
        """⚠️ '있는지'만 보는 검사는 중복을 못 잡는다(#59) — 몇 번인지 센다."""
        src = open("bot/dashboard.py", encoding="utf-8").read()
        assert src.count("{_per_basis_note}") == 1, src.count("{_per_basis_note}")


class TestAuditLogFindings20260823:
    """2026-08-23 전 시장 감사 로그(❌ 0건)에 섞여 있던 **조용한 결함** 셋.

      ① `akshare: HK disclosures … (after 2 retries): module 'akshare' has
         no attribute 'stock_zh_h_disclosure_em'` — 영원히 없을 이름에
         재시도 예산을 쓰고, 종목마다 WARNING 을 찍었다(#151·#25).
      ② 그 메시지의 '2 retries' 는 **상수**였다 — 실제로는 첫 시도에서 끊긴
         영구 실패다. 안 한 일을 했다고 말하는 로그(#12 의 로그판).
      ③ `krx_alert: … 400 Bad Request … body=LOGOUT` ×6 — 파라미터 문제가
         아니라 **로그인 세션 문제**다. 사유를 잘못 적으면 payload 를
         고치려 들게 된다(#82).
    """

    def test_a_missing_akshare_function_is_not_called(self, monkeypatch):
        """`hasattr` 로 **먼저 재고** 없으면 부르지 않는다 — 재시도 예산까지
        쓰면 안 된다(#151 이름이 아니라 실측)."""
        import types
        import bot.akshare_client as ac
        calls = []
        monkeypatch.setattr(ac, "_fetch_with_retry",
                            lambda fn, label: calls.append(label))
        monkeypatch.setattr(ac, "_import_akshare",
                            lambda: types.SimpleNamespace())   # 그 함수 없음
        monkeypatch.setattr(ac, "_cache_get", lambda k: None)
        monkeypatch.setattr(ac, "_cache_put", lambda k, v: None)
        out = ac.AkshareClient().get_recent_disclosures("0700.HK")
        assert out == [], out
        assert calls == [], f"없는 함수를 불렀다: {calls}"

    def test_the_function_is_called_when_present(self, monkeypatch):
        """⚠️ 늘 건너뛰면 기능이 죽는다 — 있으면 부르는지도 확인한다."""
        import types
        import bot.akshare_client as ac
        calls = []
        monkeypatch.setattr(ac, "_fetch_with_retry",
                            lambda fn, label: calls.append(label))
        monkeypatch.setattr(ac, "_import_akshare", lambda: types.SimpleNamespace(
            **{ac._HK_DISCLOSURE_FN: lambda symbol=None: None}))
        monkeypatch.setattr(ac, "_cache_get", lambda k: None)
        monkeypatch.setattr(ac, "_cache_put", lambda k, v: None)
        ac.AkshareClient().get_recent_disclosures("0700.HK")
        assert calls and "HK disclosures" in calls[0], calls

    def test_the_retry_log_counts_actual_attempts(self, caplog):
        """상수를 찍으면 **안 한 일을 했다고** 말한다."""
        import logging
        import bot.akshare_client as ac

        def _boom():
            raise AttributeError("module 'akshare' has no attribute 'x'")

        with caplog.at_level(logging.WARNING, logger="bot.akshare"):
            assert ac._fetch_with_retry(_boom, label="t") is None
        msg = " ".join(r.getMessage() for r in caplog.records)
        assert "1회 시도" in msg, msg
        assert "2 retries" not in msg, msg

    def test_a_krx_logout_body_is_named_as_a_session_problem(self, monkeypatch,
                                                             caplog):
        """'400 Bad Request' 라고만 적으면 payload 를 고치려 든다(#82)."""
        import logging
        import bot.krx_alert_client as kc

        class _R:
            status_code = 400
            text = "LOGOUT"

        monkeypatch.setattr(kc.requests, "post",
                            lambda *a, **k: _R())
        with caplog.at_level(logging.WARNING, logger="bot.krx_alert"):
            assert kc._fetch_krx_json("dbms/X", {"mktId": "STK"}) is None
        msg = " ".join(r.getMessage() for r in caplog.records)
        assert "로그인" in msg, msg


class TestShareCountIdentity:
    """#188 — 발행주식수는 EPS·BPS 의 분모다. 화면이 자기 산수를 못 맞추면
    주당지표가 통째로 그만큼 밀린다.

    VM 실측(서희건설 035890.KQ 2026-08-23):
      · yfinance  주식수 185,368,615 · 시총 3,967억  → **자기들끼리는 맞는다**
      · KRX/네이버 상장주식수 207,588,536 · 진짜 시총 4,442억
      · BPS 6,680.92(낡은 수) → 5,965.80(등록 수) · FnGuide 5,856 (1.9% 차)
    """

    PX = 2140.0
    YF, KRX = 185368615.0, 207588536.0
    YF_MC, TRUE_MC = 396688818176.0, 444239467040.0
    EQUITY = 1238432454403.0

    def test_the_identity_is_three_state(self):
        from bot.share_count import reconcile
        assert reconcile(self.PX, self.TRUE_MC, self.YF)["ok"] is False
        assert reconcile(self.PX, self.TRUE_MC, self.KRX)["ok"] is True
        # 재료가 없으면 **통과가 아니라 판정 불가**(#54)
