    def test_the_derived_note_groups_by_basis(self):
        """사용자 2026-08-23 "이것도 깔끔하게 잘 정리해주고" — 항목마다 기준을
        반복하면 한 줄이 길어져 아무도 안 읽는다. 옛 판은 같은 괄호가 여섯 번
        나왔다(`BPS(최근분기말), EPS(선행)(네이버 추정), …`)."""
        from bot.dashboard import _derived_desc
        si = {"_derived_multiples": ["bookValue", "forwardEps", "forwardPE",
                                     "priceToBook", "trailingEps", "trailingPE"],
              "_derived_basis": {"bookValue": "최근분기말",
                                 "forwardEps": "네이버 추정",
                                 "forwardPE": "네이버 추정",
                                 "priceToBook": "최근분기말",
                                 "trailingEps": "TTM 25.3Q~26.2Q",
                                 "trailingPE": "TTM 25.3Q~26.2Q"},
              "_derived_scope": "연결 총액(비지배지분 포함)"}
        out = _derived_desc(si)
        # 기준이 **한 번씩만** 나온다
        for b in ("최근분기말", "네이버 추정", "TTM 25.3Q~26.2Q"):
            assert out.count(b) == 1, (b, out.count(b))
        assert "BPS · PBR" in out and "EPS(선행) · PER(선행)" in out, out
        # 3그룹 + 분모 한 줄. 수정평균으로 나눈 경우에만 근거 줄이 하나 더
        # 붙는다(2026-08-23) — 그건 아래 EPS 분모 회귀가 따로 고정한다.
        assert out.count("<br>") == 3, out.count("<br>")
        assert "분모 = " in out and "분자 = DART" in out, out

    def test_the_derived_block_is_not_glued_to_the_source_line(self):
        """우측정렬 한 줄에 긴 문단을 이어 붙이면 줄바꿈이 제멋대로 생긴다
        (사용자 "왜 줄 바꿈했는지도 모르겠네") — 좌측정렬 블록으로 뺀다."""
        import ast
        src = open("bot/dashboard.py").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_render_stock_info_html")
        seg = ast.get_source_segment(src, fn) or ""
        assert '_val_src += ((" · ⚙️' not in seg, "아직 출처 줄에 붙인다"
        assert "_derived_block = (" in seg and "{_derived_block}" in seg
        assert seg.count("{_derived_block}") == 1

    def test_the_per_note_is_parallel_short_lines(self):
        """각주는 **짧은 평행 줄**이어야 한다 — 한 줄이 길면 브라우저가 아무
        데서나 접는다(#211).

        ⚠️ 2026-08-24 개정: 옛 판은 `_per_basis_note` 대입식의 **AST 문자열
        상수**를 조건부(IfExp) 안팎으로 갈라 셌다. 사용자가 한 줄('밴드차트
        탭은 분모가 달라…')을 빼 달라고 해서 줄을 리스트로 모으자 그 검사가
        통째로 눈이 멀었다(무조건 ℹ️ 0개) — 표현이 바뀌어도 계약은 유지되어야
        한다(#19·#89·#117). 이제 순수 함수의 **값**으로 잰다.

        계약: 무조건 2줄(후행·선행) · 조건부 2줄(사유 · 네이버 창) ·
        각 줄은 `ℹ️` 하나로 시작하고 `<br>` 를 품지 않는다(잇는 건 렌더다)."""
        from bot.dashboard import per_basis_lines
        base = per_basis_lines(True, "yfinance 컨센서스 EPS")
        assert len(base) == 2, base
        assert "후행 PER" in base[0] and "선행 PER" in base[1], base
        full = per_basis_lines(True, "(없음)", "사유줄", "창줄")
        assert len(full) == 4, full
        for ln in full:
            assert ln.count("ℹ️") == 1, ln
            assert "<br>" not in ln, ln            # 구분자는 렌더가 붙인다
            assert len(ln) < 90, ln                # 짧은 평행 줄
        # 조건부 줄은 **조건이 있을 때만** — 상수로 한 줄 더 넣는 변형 차단
        assert per_basis_lines(True, "x", None, "창줄")[-1].endswith("창줄")
        assert len(per_basis_lines(True, "x", None, None)) == 2
        # 렌더는 `<br>` 로 잇기만 한다 — 마지막 줄이 없어도 구분자가 안 남는다
        assert not "<br>".join(base).endswith("<br>")

    def test_derived_scope_is_per_item_not_one_label_for_two_accounts(self):
        """2026-08-23 스모크에서 드러남: 지배주주 **순이익**은 주는데 지배주주
        **자본**은 안 주는 회사가 있다(DART 실제). 옛 코드는 둘 중 하나만
        총액이면 `_derived_scope` 를 통째로 '연결 총액'으로 덮어, EPS 는
        지배주주 귀속분으로 만들어 놓고 화면은 총액이라고 말했다 — 한 라벨이
        두 계정을 대표하면 한쪽은 반드시 거짓말이다(#34·#55).
        그리고 **파생되지 않은 항목**의 기준은 아예 말하지 않는다."""
        from bot.dashboard import _derive_missing_multiples as d

        def _si(**over):
            q = {"year": 2026, "quarter": 2, "매출": 5e11}
            q.update(over)
            qs = [dict(q, year=y, quarter=n)
                  for y, n in ((2025, 3), (2025, 4), (2026, 1), (2026, 2))]
            return d({"market_cap": 4.4e11, "shares_outstanding": 2.07e8,
                      "current_price": 2140.0, "kr": {"financials_q": qs}})

        mixed = _si(당기순이익=1e11, 지배주주순이익=9.8e10, 자본총계=3e13)
        sc = mixed["_derived_scope"]
        assert "순이익 지배주주 귀속분" in sc and "자본 연결 총액" in sc, sc

        both_own = _si(지배주주순이익=9.8e10, 지배주주자본=2.9e13)
        assert both_own["_derived_scope"] == "지배주주 귀속분", both_own["_derived_scope"]

        both_tot = _si(당기순이익=1e11, 자본총계=3e13)
        assert both_tot["_derived_scope"] == "연결 총액(비지배지분 포함)"

        # 순이익이 없어 EPS·PER 이 안 만들어지면 그 기준은 말하지 않는다
        only_bps = _si(자본총계=3e13)
        assert "trailingEps" not in (only_bps.get("_derived_multiples") or [])
        assert "순이익" not in only_bps["_derived_scope"], only_bps["_derived_scope"]

        # 순이익도 자본도 안 썼으면(PSR 만) 계정 기준을 **아예 말하지 않는다** —
        # 매출에는 지배주주/비지배 개념이 없다(#55).
        from bot.dashboard import _derived_desc
        psr_only = _si()
        assert psr_only.get("_derived_multiples") == \
            ["priceToSalesTrailing12Months"], psr_only.get("_derived_multiples")
        assert "_derived_scope" not in psr_only, psr_only.get("_derived_scope")
        txt = _derived_desc(psr_only)
        assert "분자 = DART" not in txt and "자사주" not in txt, txt
        assert "PSR" in txt

    def test_the_ttm_window_label_is_shared_by_revenue_and_profit(self):
        """같은 4분기인데 PSR 만 'TTM', EPS·PER 은 'TTM 25.3Q~26.2Q' 이면
        기준별로 묶는 각주(#211)가 **두 그룹**으로 그려 창이 둘인 것처럼
        보인다 — 같은 창은 같은 문자열이어야 한다(#34)."""
        from bot.dashboard import _derive_missing_multiples as d, _derived_desc
        qs = [{"year": y, "quarter": n, "매출": 5e11, "당기순이익": 1e11,
               "자본총계": 3e13}
              for y, n in ((2025, 3), (2025, 4), (2026, 1), (2026, 2))]
        out = d({"market_cap": 4.4e11, "shares_outstanding": 2.07e8,
                 "current_price": 2140.0, "kr": {"financials_q": qs}})
        b = out["_derived_basis"]
        assert b["priceToSalesTrailing12Months"] == b["trailingPE"] \
            == "TTM 25.3Q~26.2Q", b
        txt = _derived_desc(out)
        assert txt.count("TTM 25.3Q~26.2Q") == 1, txt
        assert "PSR · EPS(후행) · PER(후행)" in txt, txt

    def test_hankyung_target_never_reads_the_ticker_code(self):
        """사용자 2026-08-23 쿠콘 294570.KQ: 화면이 `목표가 ₩294,570
        (+997.1%)` 을 띄웠다 — **목표가가 티커와 정확히 같았다**. 한경 행
        파서가 '≥1000 인 첫 정수'를 목표가로 집는데 목표가 없는 행에서
        6자리 종목코드가 잡힌 것이다. 값이 티커와 같으면 그건 값이 아니다."""
        from datetime import date
        from bot.hk_consensus_client import _parse_report_rows
        row = ('<tr><td>2026-08-20</td><td>294570</td><td>쿠콘</td>'
               '<td>유진투자증권</td><td>실적 개선</td></tr>')
        got = _parse_report_rows(row, date(2026, 1, 1), "294570")
        assert got and got[0]["target"] is None, got
        # 픽스처가 진짜 버그를 재현하는지 — code 를 안 주면 옛 증상이 난다
        assert _parse_report_rows(row, date(2026, 1, 1))[0]["target"] == 294570.0
        # 진짜 목표가는 그대로 읽는다
        row2 = ('<tr><td>2026-08-20</td><td>294570</td>'
                '<td>유진투자증권</td><td>35,000</td></tr>')
        assert _parse_report_rows(row2, date(2026, 1, 1), "294570")[0]["target"] \
            == 35000.0
        # 파서를 고쳐도 오늘치 캐시가 옛 값을 서빙한다(#21b) — 키에 버전
        import ast
        src = open("bot/hk_consensus_client.py").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "fetch_consensus")
        seg = ast.get_source_segment(src, fn) or ""
        assert "_PARSE_VER" in seg, "캐시 키에 파서 버전이 없다"

    def test_kr_consensus_source_label_names_the_real_source(self):
        """쿠콘 실측: 컨센서스 탭은 '출처 Naver Finance', 같은 값을 싣는
        리서치 탭은 '출처 한경 컨센서스' 였다 — `src` 가 리터럴이라 한경
        폴백으로 내려온 결과에도 네이버라고 적었다(#55)."""
        import ast
        src = open("bot/dashboard.py").read()
        i = src.index('src = ("한경 컨센서스"')
        seg = src[i:i + 200]
        assert "_hk_used" in seg, seg
        assert src.count('_hk_used = _hk') == 2, "폴백 경로 둘 다 기록해야 한다"
        assert 'src = "Naver Finance"' not in src, "옛 리터럴이 남아 있다"

    def test_share_card_shows_only_the_count_but_keeps_warnings(self):
        """사용자 2026-08-23 "주식수만 보이게 해줘. 다른 설명은 빼고" —
        출처 라벨은 툴팁으로. 단 **어긋난 사실은 숨기지 않는다**(#43)."""
        from bot.dashboard import _render_stock_info_html
        ok = _render_stock_info_html({"ticker": "005490.KS", "stock_info": {
            "currency": "KRW", "current_price": 310000.0,
            "market_cap": 2.456e13, "shares_outstanding": 79241527,
            "shares_source": "KRX 상장주식수(2026-08-24) · 시총 재계산"}})
        import re

        def _sub(html):
            """발행주식수 카드의 **보이는** 서브텍스트만 — 속성(title)은
            눈에 안 보이므로 세면 안 된다(#91b 재는 대상이 맞나)."""
            i = html.index("발행주식수")
            m = re.search(r'<span class="si-sub"[^>]*>(.*?)</span>',
                          html[i:i + 800], re.S)
            return m.group(1) if m else ""

        h = ok["header"] if isinstance(ok, dict) and "header" in ok else str(ok)
        assert _sub(h) == "79,241,527주", _sub(h)
        assert 'title="KRX 상장주식수(2026-08-24) · 시총 재계산"' in h
        # ⚠️ 2026-08-27 두 번째 계약 변경(#256, #222 로 다시 씀): #254 는
        # 어긋나는 순간 현재가 × 발행주식수로 재계산했지만, 같은 날 사용자
        # "야후나 구글도 전 클래스로 보여주지? 맞으면 미국도 전 클래스로
        # 해줘" 로 반전 — 렌더 파생부는 시총을 **재계산하지 않는다**(원천
        # 전 클래스가 표준, 모집단 판정은 수집부). 침묵 금지 계약은 그대로다
        # — 어긋남은 발행주식수 카드의 경고가 **비교한 시총을 카드와 같은
        # 문자열로**(#219) 말한다.
        bad = _render_stock_info_html({"ticker": "005490.KS", "stock_info": {
            "currency": "KRW", "current_price": 310000.0,
            "market_cap": 3.9e13, "shares_outstanding": 79241527}})
        hb = bad["header"] if isinstance(bad, dict) and "header" in bad else str(bad)
        i = hb.index("시가총액")
        seg = hb[i:i + 600]
        assert "₩39.00조" in seg, seg[:300]              # 원천 값 유지(#256)
        assert "재계산했습니다" not in seg, seg[:300]
        j = hb.index("발행주식수")
        seg2 = hb[j:j + 900]
        assert "⚠️" in seg2 and "₩39.00조" in seg2, seg2[:300]

    def test_bps_denominator_deducts_treasury_and_pbr_follows_bps(self):
        """사용자 2026-08-23 POSCO홀딩스 005490.KS: 우리 BPS 809,716 vs
        네이버 759,917(+6.6%). FnGuide 산식은 BPS 분모가 **자사주 차감
        유통주식수**다(사용자 제공). 그리고 PBR 은 화면의 BPS 에서 만들어야
        `현재가 ÷ BPS` 와 맞는다(#33) — 시총÷자본으로 만들면 어긋난다."""
        from bot.dart_client import _pick_share_totals
        from bot.dashboard import _derive_missing_multiples as d
        # ① 행 선택 — 합계 행이 있으면 그것, 없으면 종류주를 **더한다**
        # ⚠️ 픽스처는 **원천이 실제로 주는 필드명**이어야 한다(#155).
        # `isu_stock_totqy` 는 발행할 주식의 총수(수권)이고 실제 발행분은
        # `istc_totqy` 다 — POSCO홀딩스 실측: 전자 200,000,000 · 후자
        # 79,241,527. 이름이 그럴듯해 그걸 쓰면 자사주 차감이 통째로 틀린다.
        assert _pick_share_totals(
            [{"se": "보통주", "isu_stock_totqy": "200,000,000",
              "istc_totqy": "79,241,527", "tesstk_co": "3,620,748",
              "distb_stock_co": "75,620,779"}]
        ) == {"issued": 79241527, "treasury": 3620748,
              "distributed": 75620779}
        # 유통주식수를 안 주면 발행 − 자기주식 — 수권주식수를 쓰면 안 된다
        assert _pick_share_totals(
            [{"se": "보통주", "isu_stock_totqy": "200,000,000",
              "istc_totqy": "79,241,527", "tesstk_co": "3,620,748",
              "distb_stock_co": "-"}])["distributed"] == 75620779
        assert _pick_share_totals(
            [{"se": "보통주", "istc_totqy": "80", "tesstk_co": "5",
              "distb_stock_co": "-"},
             {"se": "우선주", "istc_totqy": "20", "tesstk_co": "0",
              "distb_stock_co": "-"}])["distributed"] == 95
        assert _pick_share_totals([{"se": "합계", "istc_totqy": "-"}]) == {}

        qs = [{"year": y, "quarter": q, "당기순이익": 1e11,
               "지배주주순이익": 9.8e10, "지배주주자본": 5.672e13, "매출": 5e11}
              for y, q in ((2025, 3), (2025, 4), (2026, 1), (2026, 2))]
        base = {"market_cap": 2.456e13, "shares_outstanding": 79241527,
                "current_price": 310000.0}
        out = d({**base, "kr": {
            "financials_q": qs,
            "share_totals": {"issued": 79241527, "treasury": 4600000,
                             "distributed": 74641527}}})
        # ② 유통주식수로 나눈다
        assert abs(out["bookValue"] - 5.672e13 / 74641527) < 1.0, out["bookValue"]
        # ③ PBR 은 화면의 BPS 에서 — 눈으로 나눠 봤을 때 맞는다
        assert abs(out["priceToBook"] - 310000.0 / out["bookValue"]) < 1e-9
        assert "자사주" in out["_derived_basis"]["bookValue"]
        # ④ 자사주 자료가 없으면 상장주식수로 떨어지고 라벨도 그렇게
        out2 = d({**base, "kr": {"financials_q": qs}})
        assert abs(out2["bookValue"] - 5.672e13 / 79241527) < 1.0
        assert "자사주" not in out2["_derived_basis"]["bookValue"]
        # ⑤ 새 필드는 **아카이브엔 없다** — 상세 보강이 같이 채워야 한다(#198)
        import ast
        src = open("bot/dashboard.py").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_ensure_detail_enrichment")
        seg = ast.get_source_segment(src, fn) or ""
        assert "get_share_totals" in seg, "아카이브 보강에 배선이 없다"

    def test_kr_dividend_yield_comes_from_naver_and_survives_the_overlay(self):
        """POSCO홀딩스 실측: 우리 2.58%(yfinance dividendRate 약 8,000) vs
        네이버 3.23%(DPS 10,000). FnGuide 산식은 수정DPS/기말주가이고
        국내는 그 값이 원천이다. 규칙은 한 곳(#38)이고 라이브 오버레이도
        그걸 써야 서버가 그린 값을 되돌리지 않는다(#199)."""
        import ast
        from bot.dashboard import dividend_yield_pct
        v, src = dividend_yield_pct(
            {"kr": {"naver_val": {"dvr": 3.23, "dvr_asof": "2026.02"}},
             "dividendYield": 2.58, "dividendRate": 8000,
             "current_price": 310000.0})
        assert (round(v, 2), "네이버" in src) == (3.23, True), (v, src)
        assert "2026.02" in src, src
        # 네이버가 없으면 계산 폴백
        v2, src2 = dividend_yield_pct({"dividendRate": 8000,
                                       "current_price": 310000.0})
        assert round(v2, 2) == 2.58 and src2 == "yfinance"
        # 오버레이가 서버 값을 덮지 않는다 — 배선을 AST 로
        src_txt = open("bot/dashboard.py").read()
        fn = next(n for n in ast.walk(ast.parse(src_txt))
                  if isinstance(n, ast.FunctionDef) and n.name == "build_live_quote")
        seg = ast.get_source_segment(src_txt, fn) or ""
        assert "_kr_dvr" in seg and "_kr_dvr if _kr_dvr is not None" in seg, \
            "라이브 오버레이가 국내 배당수익률을 다시 yfinance 로 덮는다"

    def test_naver_dividend_parser_does_not_grab_the_as_of_date(self):
        """라벨 뒤 **첫 숫자**를 집으면 기준시점(`2026.02`)이 잡힌다(실측) —
        값은 `%` 가 따라붙는 숫자다. 픽스처는 원천이 실제로 보내는 모양을
        흉내내야 이 버그를 잡는다(#155)."""
        from bot.naver_finance_client import _DVR_FALLBACK_RE as R
        for html, want in (
            ('<th>배당수익률</th><td class="v">2026.02</td>'
             '<td><span>3.23</span>%</td>', "3.23"),
            ('<th>배당수익률<em>2026.02</em></th>'
             '<td><em id="_dvr">3.23</em>%</td>', "3.23"),
            ('<td>배당수익률</td><td>3.23%</td>', "3.23"),
            ('<td>배당수익률</td><td>N/A</td>', None),
        ):
            got = R.search(html)
            assert (got.group(1) if got else None) == want, (html, got)

    def test_roe_note_does_not_claim_fnguide_basis_on_the_total_equity(self):
        """사용자 2026-08-23 "네이버랑 비교하면 ROE 가 우리가 좀 적게 나오는게
        계산식의 차이 같은데" — 원천이 지배주주 자본총계를 안 주면 분모가
        **연결 자본총계**(비지배지분 포함)로 떨어져 ROE 가 체계적으로 낮게
        나온다. 그런데 각주는 그때도 'FnGuide 산식과 같은 기준'이라고 적고
        있었다(#55). 분모 계정에 따라 문구가 갈려야 한다.

        ⚠️ 2026-08-24 개정: 옛 판은 `IfExp` 를 **정확히 1개**로 세어, 원천이
        늘면서(비-KR 은 yfinance) 조건이 하나 더 붙자 깨졌다 — 표현이 아니라
        **화면에 찍힌 문구**로 잰다(#19). 세 갈래를 전부 렌더해 확인한다."""
        import bot.dashboard as d

        def _html(basis, market="019210.KQ", cur="KRW"):
            qs = [{"label": f"2{i}.1Q", "year": 2020 + i, "quarter": 1,
                   "매출": 1e11, "영업이익": 2e10, "당기순이익": 1e10,
                   "영업이익률": 20.0, "ROE": 12.0, "부채비율": 50.0,
                   "FCF": 5e9, "_returns_basis": basis} for i in range(5)]
            si = {"currency": cur, "current_price": 100.0,
                  "kr": {"financials_q": qs}}
            p = d._render_stock_info_html({"ticker": market, "stock_info": si})
            return "".join(str(v) for v in p.values())

        owner = {"numerator": "지배주주순이익", "denominator": "지배주주자본",
                 "averaged": True}
        total = {"numerator": "당기순이익(연결 총액)", "denominator": "자본총계",
                 "averaged": True}
        kr_owner = _html(owner)
        assert "FnGuide 산식과 같은 기준입니다" in kr_owner
        kr_total = _html(total)
        assert "FnGuide 산식과 같은 기준입니다" not in kr_total, \
            "연결 자본총계로 나눠 놓고 FnGuide 와 같다고 주장한다"
        assert "연결 자본총계" in kr_total, kr_total[:200]

    def test_non_kr_roe_note_does_not_invoke_fnguide(self):
        """FnGuide 는 **국내** 기준이다 — 비-KR 표(yfinance 원천)가 그 이름을
        대면 화면이 거짓말한다(#55·#34). 사용자 2026-08-24 로 같은 렌더러를
        전 시장이 쓰게 되면서 생긴 갈래."""
        import bot.dashboard as d

        def _fin(n_q=8, n_y=5):
            qs = [f"202{4 + i // 4}-{3 * (i % 4) + 3:02d}-30" for i in range(n_q)]
            ys = [f"{2021 + i}-12-31" for i in range(n_y)]

            def isr(p):
                return {"period": p, "Total Revenue": 1e9,
                        "Operating Income": 2e8, "Net Income": 1.5e8,
                        "Net Income Common Stockholders": 1.5e8}

            def bsr(p):
                return {"period": p, "Total Assets": 9e9,
                        "Total Liabilities Net Minority Interest": 4e9,
                        "Stockholders Equity": 5e9,
                        "Total Equity Gross Minority Interest": 5e9}

            def cfr(p):
                return {"period": p, "Operating Cash Flow": 3e8,
                        "Capital Expenditure": -1e8}
            return {"income_statement": {"quarterly": [isr(p) for p in qs],
                                         "annual": [isr(p) for p in ys]},
                    "balance_sheet": {"quarterly": [bsr(p) for p in qs],
                                      "annual": [bsr(p) for p in ys]},
                    "cash_flow": {"quarterly": [cfr(p) for p in qs],
                                  "annual": [cfr(p) for p in ys]}}

        si = {"currency": "USD", "current_price": 100.0, "financials": _fin()}
        p = d._render_stock_info_html({"ticker": "TEST", "stock_info": si})
        html = "".join(str(v) for v in p.values())
        assert "분기별 재무추이 (최근 5분기)" in html, "비-KR 분기 표가 없다"
        assert "재무 추이 (연간, 최근 5년)" in html, "비-KR 연간 표가 없다"
        # ⚠️ **페이지 전체 grep 은 눈이 먼다** — 밴드 탭 ℹ️ 가이드에도
        # 'FnGuide' 가 있어, 표에서 지워도 통과한다(#55 실측). 그 **표
        # 하나를 잘라내서** 본다.
        i = html.index("분기별 재무추이 (최근 5분기)")
        seg = html[i:html.index("</div>", html.index("</table>", i))]
        assert "ℹ️ ROE = <b>" in seg, "ROE 각주가 없다"
        assert "FnGuide" not in seg, "비-KR 표가 FnGuide 를 근거로 댄다"
        assert "DART" not in seg, "비-KR 표가 DART 를 원천이라고 적는다"
        assert "yfinance" in seg, "원천을 안 밝힌다"
        # 금액은 **거래 통화 관례**로 — 원화 '억' 이 미국 종목에 붙으면 안 된다
        assert "억</td>" not in seg, "비-KR 표가 원화 단위로 찍힌다"

    def test_quarterly_forward_per_uses_naver_for_kr(self):
        """사용자 2026-08-23 "분기실적탭에 Forward per 는 밸류에이션탭에
        PER (선행) 과 맞춰져. 한국꺼는" — 야후는 국내 forwardEps 를 안 줘서
        밸류에이션 탭은 네이버 추정 EPS 로 만든다(#206). 여기만 야후
        forwardPE 를 쓰면 같은 종목의 선행 PER 이 탭마다 갈린다(#38·#147)."""
        import ast
        src = open("bot/quarterly_infographic.py").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef) and n.name == "build_payload")
        seg = ast.get_source_segment(src, fn) or ""
        # ⚠️ 고정 길이 창으로 재면 주석 한 줄에 무너진다(#60) — 함수 전체로.
        assert "kr_forward_from_naver" in seg, "규칙을 복제했다"
        # ⚠️ 2026-08-24: 국내는 `forwardEps` 가 **있을 때만** yfinance 를 쓴다
        # (`_live_per` 경로). 분모 없이 배수만 만드는 뒤 두 폴백은 국내에서
        # 막혀 있어야 한다 — 밸류에이션 탭과 같은 규칙(#38).
        assert seg.count("if per_fwd is None and not is_kr:") == 2, \
            seg.count("if per_fwd is None and not is_kr:")
        assert seg.count("if per_fwd is None:") == 1, \
            seg.count("if per_fwd is None:")

    def test_no_dict_literal_has_duplicate_keys(self):
        """중복 키는 파이썬이 조용히 **마지막 것만** 남긴다 — 앞의 매핑이
        통째로 죽는다. 2026-08-23 실측: `_DART_CODE_MAP` 에
        `ifrs-full_EquityAttributableToOwnersOfParent` 가 두 번 있어
        (지배주주자본 → 자본총계) **`지배주주자본` 이 전 종목에서 한 번도
        안 채워졌다**. 그 결과 BPS·ROE 분모가 연결 총액(비지배 포함)으로
        떨어져 FnGuide 보다 체계적으로 어긋났다(POSCO홀딩스 프로브 확인).

        옛 가드는 `bot/translate.py` **한 파일만** 봤다 — 목록형은 새 파일을
        못 잡는다(#24). 디렉터리 전체를 AST 로 훑는다."""
        import ast, pathlib
        from collections import Counter
        bad, scanned = [], 0
        for root in ("bot", "trade"):
            for p in sorted(pathlib.Path(root).rglob("*.py")):
                tree = ast.parse(p.read_text(encoding="utf-8"))
                scanned += 1
                for n in ast.walk(tree):
                    if not isinstance(n, ast.Dict):
                        continue
                    ks = [k.value for k in n.keys
                          if isinstance(k, ast.Constant)
                          and isinstance(k.value, (str, int))]
                    for k, c in Counter(ks).items():
                        if c > 1:
                            bad.append(f"{p}:{n.lineno} {k!r}×{c}")
        assert scanned > 300, f"훑은 모듈 {scanned}개 — 스캔이 안 돌았다"
        assert not bad, "중복 키: " + ", ".join(bad)

    def test_owner_equity_is_filled_from_the_identity_when_missing(self):
        """`지배주주자본` 은 BPS·ROE 의 분모다. 원천이 그 계정을 안 주면
        분모가 연결 총액으로 떨어져 두 지표가 **같은 방향으로** 낮아진다.
        계정 이름 열거로는 새 표기를 못 잡으므로(#24) `자본총계 − 비지배지분`
        이라는 항등식을 최종 그물로 둔다. 그리고 만든 값은 그렇게 밝힌다(#43)."""
        import ast
        from bot.dart_client import _fill_equity_fallbacks as f
        d = {"자본총계": 64.16e12, "비지배지분": 6.7e12}
        f(d)
        assert round(d["지배주주자본"]) == round(57.46e12), d
        assert "자본총계" in d["_derived_from"]["지배주주자본"]
        # 반대 방향 — 자본을 지배주주분으로만 주는 회사
        d2 = {"지배주주자본": 5.76e12}
        f(d2)
        assert d2["자본총계"] == 5.76e12 and d2["_derived_from"]["자본총계"]
        # 원천이 준 값은 **덮지 않는다**
        d3 = {"자본총계": 100.0, "지배주주자본": 90.0, "비지배지분": 5.0}
        f(d3)
        assert d3["지배주주자본"] == 90.0 and "_derived_from" not in d3
        f({})                                   # 재료 없음 → 아무 일 없음
        # 배선 — 정규화 재무가 이 함수를 부른다(#20 배선은 태워야 보인다)
        src = open("bot/dart_client.py").read()
        fn = next(n for n in ast.walk(ast.parse(src))
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "get_normalized_financials")
        seg = ast.get_source_segment(src, fn) or ""
        i, j = seg.index("_fill_equity_fallbacks("), seg.index("calc_kr_financial_ratios(")
        assert i < j, "비율 계산 **전에** 채워야 ROE 분모가 지배주주자본이 된다"
        # 릴레이 목록에도 실려야 화면까지 온다
        from bot.stock_snapshot import _KR_FIN_RELAY_KEYS
        assert "비지배지분" in _KR_FIN_RELAY_KEYS
        assert "지배주주자본" in _KR_FIN_RELAY_KEYS
        # 분모를 빼서 만들었으면 **화면이 그렇게 말한다**(#43·#123) —
        # 계산해 놓고 안 실으면 사용자가 매번 물어야 한다.
        from bot.dart_client import apply_ttm_returns, apply_annual_returns
        for fn_ in (apply_ttm_returns, apply_annual_returns):
            e = [{"financials": {"당기순이익": 10.0, "지배주주순이익": 9.0,
                                 "자본총계": 100.0, "비지배지분": 10.0,
                                 "지배주주자본": 90.0, "자산총계": 200.0,
                                 "_derived_from": {"지배주주자본": "자본총계 − 비지배지분"}},
                  "ratios": {}} for _ in range(5)]
            fn_(e)
            rb = e[-1]["ratios"]["_returns_basis"]
            assert rb["denominator"] == "지배주주자본", rb
            assert rb["denominator_derived"] == "자본총계 − 비지배지분", rb
        src2 = open("bot/dashboard.py").read()
        assert src2.count('_rb["denominator_derived"]') == 1, "화면이 안 싣는다"

